  #define COMP1_ICFR_CC2IF_MSK       UINT32_C(0x00020000)   /** @brief Clear COMP channel 2 interrupt flag. */
  #define COMP1_OR_AFOP_MSK          UINT32_C(0x000007FF)   /** @brief Selection of source for alternate function of output ports. */
  #define COMP1_OR_OR_MSK            UINT32_C(0xFFFFF800)   /** @brief Option register. */
  #define COMP1_CFGR1_EN_MSK         UINT32_C(0x00000001)   /** @brief COMP channel 1 enable bit. */
  #define COMP1_CFGR1_BRGEN_MSK      UINT32_C(0x00000002)   /** @brief Scaler bridge enable. */
  #define COMP1_CFGR1_SCALEN_MSK     UINT32_C(0x00000004)   /** @brief Voltage scaler enable bit. */
  #define COMP1_CFGR1_POLARITY_MSK   UINT32_C(0x00000008)   /** @brief COMP channel 1 polarity selection bit. */
  #define COMP1_CFGR1_ITEN_MSK       UINT32_C(0x00000040)   /** @brief COMP channel 1 interrupt enable. */
  #define COMP1_CFGR1_HYST_MSK       UINT32_C(0x00000300)   /** @brief COMP channel 1 hysteresis selection bits. */
  #define COMP1_CFGR1_PWRMODE_MSK    UINT32_C(0x00003000)   /** @brief Power mode of the COMP channel 1. */
  #define COMP1_CFGR1_INMSEL_MSK     UINT32_C(0x00070000)   /** @brief COMP channel 1 inverting input selection field. */
  #define COMP1_CFGR1_INPSEL_MSK     UINT32_C(0x00100000)   /** @brief COMP channel 1 non-inverting input selection bit. */
  #define COMP1_CFGR1_BLANKING_MSK   UINT32_C(0x0F000000)   /** @brief COMP channel 1 blanking source selection bits. */
  #define COMP1_CFGR1_LOCK_MSK       UINT32_C(0x80000000)   /** @brief Lock bit. */
  #define COMP1_CFGR2_EN_MSK         UINT32_C(0x00000001)   /** @brief COMP channel 1 enable bit. */
  #define COMP1_CFGR2_BRGEN_MSK      UINT32_C(0x00000002)   /** @brief Scaler bridge enable. */
  #define COMP1_CFGR2_SCALEN_MSK     UINT32_C(0x00000004)   /** @brief Voltage scaler enable bit. */
  #define COMP1_CFGR2_POLARITY_MSK   UINT32_C(0x00000008)   /** @brief COMP channel 1 polarity selection bit. */
  #define COMP1_CFGR2_WINMODE_MSK    UINT32_C(0x00000010)   /** @brief Window comparator mode selection bit. */
  #define COMP1_CFGR2_ITEN_MSK       UINT32_C(0x00000040)   /** @brief COMP channel 1 interrupt enable. */
  #define COMP1_CFGR2_HYST_MSK       UINT32_C(0x00000300)   /** @brief COMP channel 1 hysteresis selection bits. */
  #define COMP1_CFGR2_PWRMODE_MSK    UINT32_C(0x00003000)   /** @brief Power mode of the COMP channel 1. */
  #define COMP1_CFGR2_INMSEL_MSK     UINT32_C(0x00070000)   /** @brief COMP channel 1 inverting input selection field. */
  #define COMP1_CFGR2_INPSEL_MSK     UINT32_C(0x00100000)   /** @brief COMP channel 1 non-inverting input selection bit. */
  #define COMP1_CFGR2_BLANKING_MSK   UINT32_C(0x0F000000)   /** @brief COMP channel 1 blanking source selection bits. */
  #define COMP1_CFGR2_LOCK_MSK       UINT32_C(0x80000000)   /** @brief Lock bit. */

  /**** @subsection Field Position Definitions ****/

  #define COMP1_SR_C1VAL_POS         INT32_C(0)    /** @brief COMP channel 1 output status bit. */
  #define COMP1_SR_C2VAL_POS         INT32_C(1)    /** @brief COMP channel 2 output status bit. */
  #define COMP1_SR_C1IF_POS          INT32_C(16)   /** @brief COMP channel 1 interrupt flag. */
  #define COMP1_SR_C2IF_POS          INT32_C(17)   /** @brief COMP channel 2 interrupt flag. */
  #define COMP1_ICFR_CC1IF_POS       INT32_C(16)   /** @brief Clear COMP channel 1 interrupt flag. */
  #define COMP1_ICFR_CC2IF_POS       INT32_C(17)   /** @brief Clear COMP channel 2 interrupt flag. */
  #define COMP1_OR_AFOP_POS          INT32_C(0)    /** @brief Selection of source for alternate function of output ports. */
  #define COMP1_OR_OR_POS            INT32_C(11)   /** @brief Option register. */
  #define COMP1_CFGR1_EN_POS         INT32_C(0)    /** @brief COMP channel 1 enable bit. */
  #define COMP1_CFGR1_BRGEN_POS      INT32_C(1)    /** @brief Scaler bridge enable. */
  #define COMP1_CFGR1_SCALEN_POS     INT32_C(2)    /** @brief Voltage scaler enable bit. */
  #define COMP1_CFGR1_POLARITY_POS   INT32_C(3)    /** @brief COMP channel 1 polarity selection bit. */
  #define COMP1_CFGR1_ITEN_POS       INT32_C(6)    /** @brief COMP channel 1 interrupt enable. */
  #define COMP1_CFGR1_HYST_POS       INT32_C(8)    /** @brief COMP channel 1 hysteresis selection bits. */
  #define COMP1_CFGR1_PWRMODE_POS    INT32_C(12)   /** @brief Power mode of the COMP channel 1. */
  #define COMP1_CFGR1_INMSEL_POS     INT32_C(16)   /** @brief COMP channel 1 inverting input selection field. */
  #define COMP1_CFGR1_INPSEL_POS     INT32_C(20)   /** @brief COMP channel 1 non-inverting input selection bit. */
  #define COMP1_CFGR1_BLANKING_POS   INT32_C(24)   /** @brief COMP channel 1 blanking source selection bits. */
  #define COMP1_CFGR1_LOCK_POS       INT32_C(31)   /** @brief Lock bit. */
  #define COMP1_CFGR2_EN_POS         INT32_C(0)    /** @brief COMP channel 1 enable bit. */
  #define COMP1_CFGR2_BRGEN_POS      INT32_C(1)    /** @brief Scaler bridge enable. */
  #define COMP1_CFGR2_SCALEN_POS     INT32_C(2)    /** @brief Voltage scaler enable bit. */
  #define COMP1_CFGR2_POLARITY_POS   INT32_C(3)    /** @brief COMP channel 1 polarity selection bit. */
  #define COMP1_CFGR2_WINMODE_POS    INT32_C(4)    /** @brief Window comparator mode selection bit. */
  #define COMP1_CFGR2_ITEN_POS       INT32_C(6)    /** @brief COMP channel 1 interrupt enable. */
  #define COMP1_CFGR2_HYST_POS       INT32_C(8)    /** @brief COMP channel 1 hysteresis selection bits. */
  #define COMP1_CFGR2_PWRMODE_POS    INT32_C(12)   /** @brief Power mode of the COMP channel 1. */
