  #define COMP1_CFGR2_INPSEL_POS     INT32_C(20)   /** @brief COMP channel 1 non-inverting input selection bit. */
  #define COMP1_CFGR2_BLANKING_POS   INT32_C(24)   /** @brief COMP channel 1 blanking source selection bits. */
