  /**** @subsection Field Mask Definitions ****/

  #define DAC_CR_EN1_MSK              UINT32_C(0x00000001)   /** @brief DAC channel1 enable this bit is set and cleared by software to enable/disable DAC channel1.. */
  #define DAC_CR_TEN1_MSK             UINT32_C(0x00000002)   /** @brief DAC channel1 trigger enable. */
  #define DAC_CR_TSEL1_MSK            UINT32_C(0x0000001C)   /** @brief DAC channel1 trigger selection these bits select the external event used to trigger DAC channel1. Note: only used if bit TEN1 = 1 (DAC channel1 trigger enabled).. */
  #define DAC_CR_WAVE1_MSK            UINT32_C(0x000000C0)   /** @brief DAC channel1 noise/triangle wave generation enable these bits are set and cleared by software. Note: only used if bit TEN1 = 1 (DAC channel1 trigger enabled).. */
  #define DAC_CR_MAMP1_MSK            UINT32_C(0x00000F00)   /** @brief DAC channel1 mask/amplitude selector these bits are written by software to select mask in wave generation mode or amplitude in triangle generation mode. = 1011: unmask bits[11:0] of LFSR/ triangle amplitude equal to 4095. */
  #define DAC_CR_DMAEN1_MSK           UINT32_C(0x00001000)   /** @brief DAC channel1 DMA enable this bit is set and cleared by software.. */
  #define DAC_CR_DMAUDRIE1_MSK        UINT32_C(0x00002000)   /** @brief DAC channel1 DMA underrun interrupt enable this bit is set and cleared by software.. */
  #define DAC_CR_CEN1_MSK             UINT32_C(0x00004000)   /** @brief DAC channel 1 calibration enable this bit is set and cleared by software to enable/disable DAC channel 1 calibration, it can be written only if bit EN1=0 into DAC_CR (the calibration mode can be entered/exit only when the DAC channel is disabled) otherwise, the write operation is ignored.. */
  #define DAC_CR_EN2_MSK              UINT32_C(0x00010000)   /** @brief DAC channel2 enable this bit is set and cleared by software to enable/disable DAC channel2.. */
  #define DAC_CR_TEN2_MSK             UINT32_C(0x00020000)   /** @brief DAC channel2 trigger enable. */
  #define DAC_CR_TSEL2_MSK            UINT32_C(0x001C0000)   /** @brief DAC channel2 trigger selection these bits select the external event used to trigger DAC channel2 note: only used if bit TEN2 = 1 (DAC channel2 trigger enabled).. */
  #define DAC_CR_WAVE2_MSK            UINT32_C(0x00C00000)   /** @brief DAC channel2 noise/triangle wave generation enable these bits are set/reset by software. 1x: triangle wave generation enabled note: only used if bit TEN2 = 1 (DAC channel2 trigger enabled). */
  #define DAC_CR_MAMP2_MSK            UINT32_C(0x0F000000)   /** @brief DAC channel2 mask/amplitude selector these bits are written by software to select mask in wave generation mode or amplitude in triangle generation mode. = 1011: unmask bits[11:0] of LFSR/ triangle amplitude equal to 4095. */
  #define DAC_CR_DMAEN2_MSK           UINT32_C(0x10000000)   /** @brief DAC channel2 DMA enable this bit is set and cleared by software.. */
  #define DAC_CR_DMAUDRIE2_MSK        UINT32_C(0x20000000)   /** @brief DAC channel2 DMA underrun interrupt enable this bit is set and cleared by software.. */
  #define DAC_CR_CEN2_MSK             UINT32_C(0x40000000)   /** @brief DAC channel 2 calibration enable this bit is set and cleared by software to enable/disable DAC channel 2 calibration, it can be written only if bit EN2=0 into DAC_CR (the calibration mode can be entered/exit only when the DAC channel is disabled) otherwise, the write operation is ignored.. */
  #define DAC_SWTRGR_SWTRIG1_MSK      UINT32_C(0x00000001)   /** @brief DAC channel1 software trigger this bit is set by software to trigger the DAC in software trigger mode. Note: this bit is cleared by hardware (one APB1 clock cycle later) once the DAC_DHR1 register value has been loaded into the DAC_DOR1 register.. */
  #define DAC_SWTRGR_SWTRIG2_MSK      UINT32_C(0x00000002)   /** @brief DAC channel2 software trigger this bit is set by software to trigger the DAC in software trigger mode. Note: this bit is cleared by hardware (one APB1 clock cycle later) once the DAC_DHR2 register value has been loaded into the DAC_DOR2 register.. */
  #define DAC_DHR12R1_DACC1DHR_MSK    UINT32_C(0x00000FFF)   /** @brief DAC channel1 12-bit right-aligned data these bits are written by software which specifies 12-bit data for DAC channel1.. */
  #define DAC_DHR12L1_DACC1DHR_MSK    UINT32_C(0x0000FFF0)   /** @brief DAC channel1 12-bit left-aligned data these bits are written by software which specifies 12-bit data for DAC channel1.. */
  #define DAC_DHR8R1_DACC1DHR_MSK     UINT32_C(0x000000FF)   /** @brief DAC channel1 8-bit right-aligned data these bits are written by software which specifies 8-bit data for DAC channel1.. */
  #define DAC_DHR12R2_DACC2DHR_MSK    UINT32_C(0x00000FFF)   /** @brief DAC channel2 12-bit right-aligned data these bits are written by software which specifies 12-bit data for DAC channel2.. */
  #define DAC_DHR12L2_DACC2DHR_MSK    UINT32_C(0x0000FFF0)   /** @brief DAC channel2 12-bit left-aligned data these bits are written by software which specify 12-bit data for DAC channel2.. */
  #define DAC_DHR8R2_DACC2DHR_MSK     UINT32_C(0x000000FF)   /** @brief DAC channel2 8-bit right-aligned data these bits are written by software which specifies 8-bit data for DAC channel2.. */
  #define DAC_DHR12RD_DACC1DHR_MSK    UINT32_C(0x00000FFF)   /** @brief DAC channel1 12-bit right-aligned data these bits are written by software which specifies 12-bit data for DAC channel1.. */
  #define DAC_DHR12RD_DACC2DHR_MSK    UINT32_C(0x0FFF0000)   /** @brief DAC channel2 12-bit right-aligned data these bits are written by software which specifies 12-bit data for DAC channel2.. */
  #define DAC_DHR12LD_DACC1DHR_MSK    UINT32_C(0x0000FFF0)   /** @brief DAC channel1 12-bit left-aligned data these bits are written by software which specifies 12-bit data for DAC channel1.. */
  #define DAC_DHR12LD_DACC2DHR_MSK    UINT32_C(0xFFF00000)   /** @brief DAC channel2 12-bit left-aligned data these bits are written by software which specifies 12-bit data for DAC channel2.. */
  #define DAC_DHR8RD_DACC1DHR_MSK     UINT32_C(0x000000FF)   /** @brief DAC channel1 8-bit right-aligned data these bits are written by software which specifies 8-bit data for DAC channel1.. */
  #define DAC_DHR8RD_DACC2DHR_MSK     UINT32_C(0x0000FF00)   /** @brief DAC channel2 8-bit right-aligned data these bits are written by software which specifies 8-bit data for DAC channel2.. */
  #define DAC_DOR1_DACC1DOR_MSK       UINT32_C(0x00000FFF)   /** @brief DAC channel1 data output these bits are read-only, they contain data output for DAC channel1.. */
  #define DAC_DOR2_DACC2DOR_MSK       UINT32_C(0x00000FFF)   /** @brief DAC channel2 data output these bits are read-only, they contain data output for DAC channel2.. */
  #define DAC_SR_DMAUDR1_MSK          UINT32_C(0x00002000)   /** @brief DAC channel1 DMA underrun flag this bit is set by hardware and cleared by software (by writing it to 1).. */
  #define DAC_SR_CAL_FLAG1_MSK        UINT32_C(0x00004000)   /** @brief DAC channel 1 calibration offset status this bit is set and cleared by hardware. */
  #define DAC_SR_BWST1_MSK            UINT32_C(0x00008000)   /** @brief DAC channel 1 busy writing sample time flag this bit is systematically set just after sample & hold mode enable and is set each time the software writes the register DAC_SHSR1, it is cleared by hardware when the write operation of DAC_SHSR1 is complete. (It takes about 3LSI periods of synchronization).. */
  #define DAC_SR_DMAUDR2_MSK          UINT32_C(0x20000000)   /** @brief DAC channel2 DMA underrun flag this bit is set by hardware and cleared by software (by writing it to 1).. */
  #define DAC_SR_CAL_FLAG2_MSK        UINT32_C(0x40000000)   /** @brief DAC channel 2 calibration offset status this bit is set and cleared by hardware. */
  #define DAC_SR_BWST2_MSK            UINT32_C(0x80000000)   /** @brief DAC channel 2 busy writing sample time flag this bit is systematically set just after sample & hold mode enable and is set each time the software writes the register DAC_SHSR2, it is cleared by hardware when the write operation of DAC_SHSR2 is complete. (It takes about 3 LSI periods of synchronization).. */
  #define DAC_CCR_OTRIM1_MSK          UINT32_C(0x0000001F)   /** @brief DAC channel 1 offset trimming value. */
  #define DAC_CCR_OTRIM2_MSK          UINT32_C(0x001F0000)   /** @brief DAC channel 2 offset trimming value. */
  #define DAC_MCR_MODE1_MSK           UINT32_C(0x00000007)   /** @brief DAC channel 1 mode these bits can be written only when the DAC is disabled and not in the calibration mode (when bit EN1=0 and bit CEN1 =0 in the DAC_CR register). If EN1=1 or CEN1 =1 the write operation is ignored. They can be set and cleared by software to select the DAC channel 1 mode: DAC channel 1 in normal mode DAC channel 1 in sample &amp; hold mode. */
  #define DAC_MCR_MODE2_MSK           UINT32_C(0x00070000)   /** @brief DAC channel 2 mode these bits can be written only when the DAC is disabled and not in the calibration mode (when bit EN2=0 and bit CEN2 =0 in the DAC_CR register). If EN2=1 or CEN2 =1 the write operation is ignored. They can be set and cleared by software to select the DAC channel 2 mode: DAC channel 2 in normal mode DAC channel 2 in sample &amp; hold mode. */
  #define DAC_SHSR1_TSAMPLE1_MSK      UINT32_C(0x000003FF)   /** @brief DAC channel 1 sample time (only valid in sample &amp; hold mode) these bits can be written when the DAC channel1 is disabled or also during normal operation. In the latter case, the write can be done only when bwstx of DAC_SR register is low, if bwstx=1, the write operation is ignored.. */
  #define DAC_SHSR2_TSAMPLE2_MSK      UINT32_C(0x000003FF)   /** @brief DAC channel 2 sample time (only valid in sample &amp; hold mode) these bits can be written when the DAC channel2 is disabled or also during normal operation. In the latter case, the write can be done only when bwstx of DAC_SR register is low, if bwstx=1, the write operation is ignored.. */
  #define DAC_SHHR_THOLD1_MSK         UINT32_C(0x000003FF)   /** @brief DAC channel 1 hold time (only valid in sample &amp; hold mode) hold time= (THOLD[9:0]) x T LSI. */
  #define DAC_SHHR_THOLD2_MSK         UINT32_C(0x03FF0000)   /** @brief DAC channel 2 hold time (only valid in sample &amp; hold mode). Hold time= (THOLD[9:0]) x T LSI. */
  #define DAC_SHRR_TREFRESH1_MSK      UINT32_C(0x000000FF)   /** @brief DAC channel 1 refresh time (only valid in sample &amp; hold mode) refresh time= (TREFRESH[7:0]) x T LSI. */
  #define DAC_SHRR_TREFRESH2_MSK      UINT32_C(0x00FF0000)   /** @brief DAC channel 2 refresh time (only valid in sample &amp; hold mode) refresh time= (TREFRESH[7:0]) x T LSI. */

