  /*************************************************************************************************
   * @section DMA2D Definitions
   *************************************************************************************************/

  /**** @subsection Register Definitions ****/

  #define DMA2D_CR_PTR        (*(RW_ uint32_t*)UINT32_C(0x52001000))   /** @brief DMA2D control register. */
  #define DMA2D_ISR_PTR       (*(RO_ uint32_t*)UINT32_C(0x52001004))   /** @brief DMA2D interrupt status register. */
  #define DMA2D_IFCR_PTR      (*(RW_ uint32_t*)UINT32_C(0x52001008))   /** @brief DMA2D interrupt flag clear register. */
  #define DMA2D_FGMAR_PTR     (*(RW_ uint32_t*)UINT32_C(0x5200100C))   /** @brief DMA2D foreground memory address register. */
  #define DMA2D_FGOR_PTR      (*(RW_ uint32_t*)UINT32_C(0x52001010))   /** @brief DMA2D foreground offset register. */
  #define DMA2D_BGMAR_PTR     (*(RW_ uint32_t*)UINT32_C(0x52001014))   /** @brief DMA2D background memory address register. */
  #define DMA2D_BGOR_PTR      (*(RW_ uint32_t*)UINT32_C(0x52001018))   /** @brief DMA2D background offset register. */
  #define DMA2D_FGPFCCR_PTR   (*(RW_ uint32_t*)UINT32_C(0x5200101C))   /** @brief DMA2D foreground PFC control register. */
  #define DMA2D_FGCOLR_PTR    (*(RW_ uint32_t*)UINT32_C(0x52001020))   /** @brief DMA2D foreground color register. */
  #define DMA2D_BGPFCCR_PTR   (*(RW_ uint32_t*)UINT32_C(0x52001024))   /** @brief DMA2D background PFC control register. */
  #define DMA2D_BGCOLR_PTR    (*(RW_ uint32_t*)UINT32_C(0x52001028))   /** @brief DMA2D background color register. */
  #define DMA2D_FGCMAR_PTR    (*(RW_ uint32_t*)UINT32_C(0x5200102C))   /** @brief DMA2D foreground CLUT memory address register. */
  #define DMA2D_BGCMAR_PTR    (*(RW_ uint32_t*)UINT32_C(0x52001030))   /** @brief DMA2D background CLUT memory address register. */
  #define DMA2D_OPFCCR_PTR    (*(RW_ uint32_t*)UINT32_C(0x52001034))   /** @brief DMA2D output PFC control register. */
  #define DMA2D_OCOLR_PTR     (*(RW_ uint32_t*)UINT32_C(0x52001038))   /** @brief DMA2D output color register. */
  #define DMA2D_OMAR_PTR      (*(RW_ uint32_t*)UINT32_C(0x5200103C))   /** @brief DMA2D output memory address register. */
  #define DMA2D_OOR_PTR       (*(RW_ uint32_t*)UINT32_C(0x52001040))   /** @brief DMA2D output offset register. */
  #define DMA2D_NLR_PTR       (*(RW_ uint32_t*)UINT32_C(0x52001044))   /** @brief DMA2D number of line register. */
  #define DMA2D_LWR_PTR       (*(RW_ uint32_t*)UINT32_C(0x52001048))   /** @brief DMA2D line watermark register. */
  #define DMA2D_AMTCR_PTR     (*(RW_ uint32_t*)UINT32_C(0x5200104C))   /** @brief DMA2D AXI master timer configuration register. */

  /**** @subsection Field Mask Definitions ****/

  #define DMA2D_CR_START_MSK         UINT32_C(0x00000001)   /** @brief Start this bit can be used to launch the DMA2D according to the parameters loaded in the various configuration registers. */
  #define DMA2D_CR_SUSP_MSK          UINT32_C(0x00000002)   /** @brief Suspend this bit can be used to suspend the current transfer. This bit is set and reset by software. It is automatically reset by hardware when the START bit is reset.. */
  #define DMA2D_CR_ABORT_MSK         UINT32_C(0x00000004)   /** @brief Abort this bit can be used to abort the current transfer. This bit is set by software and is automatically reset by hardware when the START bit is reset.. */
  #define DMA2D_CR_TEIE_MSK          UINT32_C(0x00000100)   /** @brief Transfer error interrupt enable this bit is set and cleared by software.. */
  #define DMA2D_CR_TCIE_MSK          UINT32_C(0x00000200)   /** @brief Transfer complete interrupt enable this bit is set and cleared by software.. */
  #define DMA2D_CR_TWIE_MSK          UINT32_C(0x00000400)   /** @brief Transfer watermark interrupt enable this bit is set and cleared by software.. */
  #define DMA2D_CR_CAEIE_MSK         UINT32_C(0x00000800)   /** @brief CLUT access error interrupt enable this bit is set and cleared by software.. */
  #define DMA2D_CR_CTCIE_MSK         UINT32_C(0x00001000)   /** @brief CLUT transfer complete interrupt enable this bit is set and cleared by software.. */
  #define DMA2D_CR_CEIE_MSK          UINT32_C(0x00002000)   /** @brief Configuration error interrupt enable this bit is set and cleared by software.. */
  #define DMA2D_CR_MODE_MSK          UINT32_C(0x00030000)   /** @brief DMA2D mode this bit is set and cleared by software. It cannot be modified while a transfer is ongoing.. */
  #define DMA2D_ISR_TEIF_MSK         UINT32_C(0x00000001)   /** @brief Transfer error interrupt flag this bit is set when an error occurs during a DMA transfer (data transfer or automatic CLUT loading).. */
  #define DMA2D_ISR_TCIF_MSK         UINT32_C(0x00000002)   /** @brief Transfer complete interrupt flag this bit is set when a DMA2D transfer operation is complete (data transfer only).. */
  #define DMA2D_ISR_TWIF_MSK         UINT32_C(0x00000004)   /** @brief Transfer watermark interrupt flag this bit is set when the last pixel of the watermarked line has been transferred.. */
  #define DMA2D_ISR_CAEIF_MSK        UINT32_C(0x00000008)   /** @brief CLUT access error interrupt flag this bit is set when the CPU accesses the CLUT while the CLUT is being automatically copied from a system memory to the internal DMA2D.. */
  #define DMA2D_ISR_CTCIF_MSK        UINT32_C(0x00000010)   /** @brief CLUT transfer complete interrupt flag this bit is set when the CLUT copy from a system memory area to the internal DMA2D memory is complete.. */
  #define DMA2D_ISR_CEIF_MSK         UINT32_C(0x00000020)   /** @brief Configuration error interrupt flag this bit is set when the START bit of DMA2D_CR, DMA2DFGPFCCR or DMA2D_BGPFCCR is set and a wrong configuration has been programmed.. */
  #define DMA2D_IFCR_CTEIF_MSK       UINT32_C(0x00000001)   /** @brief Clear transfer error interrupt flag programming this bit to 1 clears the TEIF flag in the DMA2D_ISR register. */
  #define DMA2D_IFCR_CTCIF_MSK       UINT32_C(0x00000002)   /** @brief Clear transfer complete interrupt flag programming this bit to 1 clears the TCIF flag in the DMA2D_ISR register. */
  #define DMA2D_IFCR_CTWIF_MSK       UINT32_C(0x00000004)   /** @brief Clear transfer watermark interrupt flag programming this bit to 1 clears the TWIF flag in the DMA2D_ISR register. */
  #define DMA2D_IFCR_CAECIF_MSK      UINT32_C(0x00000008)   /** @brief Clear CLUT access error interrupt flag programming this bit to 1 clears the CAEIF flag in the DMA2D_ISR register. */
  #define DMA2D_IFCR_CCTCIF_MSK      UINT32_C(0x00000010)   /** @brief Clear CLUT transfer complete interrupt flag programming this bit to 1 clears the CTCIF flag in the DMA2D_ISR register. */
  #define DMA2D_IFCR_CCEIF_MSK       UINT32_C(0x00000020)   /** @brief Clear configuration error interrupt flag programming this bit to 1 clears the CEIF flag in the DMA2D_ISR register. */
  #define DMA2D_FGMAR_MA_MSK         UINT32_C(0xFFFFFFFF)   /** @brief Memory address address of the data used for the foreground image. This register can only be written when data transfers are disabled. Once the data transfer has started, this register is read-only. The address alignment must match the image format selected e.g. A 32-bit per pixel format must be 32-bit aligned, a 16-bit per pixel format must be 16-bit aligned and a 4-bit per pixel format must be 8-bit aligned.. */
  #define DMA2D_FGOR_LO_MSK          UINT32_C(0x00003FFF)   /** @brief Line offset line offset used for the foreground expressed in pixel. This value is used to generate the address. It is added at the end of each line to determine the starting address of the next line. These bits can only be written when data transfers are disabled. Once a data transfer has started, they become read-only. If the image format is 4-bit per pixel, the line offset must be even.. */
