  #define FMC_SDCR1_NR_POS          INT32_C(2)    /** @brief Number of row address bits these bits define the number of bits of a row address.. */
  #define FMC_SDCR1_MWID_POS        INT32_C(4)    /** @brief Memory data bus width. These bits define the memory device width.. */
  #define FMC_SDCR1_NB_POS          INT32_C(6)    /** @brief Number of internal banks this bit sets the number of internal banks.. */
  #define FMC_SDCR1_CAS_POS         INT32_C(7)    /** @brief CAS latency this bits sets the SDRAM CAS latency in number of memory clock cycles. */
  #define FMC_SDCR1_WP_POS          INT32_C(9)    /** @brief Write protection this bit enables write mode access to the SDRAM bank.. */
  #define FMC_SDCR1_SDCLK_POS       INT32_C(10)   /** @brief SDRAM clock configuration these bits define the SDRAM clock period for both SDRAM banks and allow disabling the clock before changing the frequency. In this case the SDRAM must be re-initialized. Note: the corresponding bits in the FMC_SDCR2 register is read only.. */
  #define FMC_SDCR1_RBURST_POS      INT32_C(12)   /** @brief Burst read this bit enables burst read mode. The SDRAM controller anticipates the next read commands during the CAS latency and stores data in the read FIFO. Note: the corresponding bit in the FMC_SDCR2 register is read only.. */
  #define FMC_SDCR1_RPIPE_POS       INT32_C(13)   /** @brief Read pipe these bits define the delay, in KCK_FMC clock cycles, for reading data after CAS latency. Note: the corresponding bits in the FMC_SDCR2 register is read only.. */
  #define FMC_SDCR2_NC_POS          INT32_C(0)    /** @brief Number of column address bits these bits define the number of bits of a column address.. */
  #define FMC_SDCR2_NR_POS          INT32_C(2)    /** @brief Number of row address bits these bits define the number of bits of a row address.. */
  #define FMC_SDCR2_MWID_POS        INT32_C(4)    /** @brief Memory data bus width. These bits define the memory device width.. */
  #define FMC_SDCR2_NB_POS          INT32_C(6)    /** @brief Number of internal banks this bit sets the number of internal banks.. */
  #define FMC_SDCR2_CAS_POS         INT32_C(7)    /** @brief CAS latency this bits sets the SDRAM CAS latency in number of memory clock cycles. */
  #define FMC_SDCR2_WP_POS          INT32_C(9)    /** @brief Write protection this bit enables write mode access to the SDRAM bank.. */
  #define FMC_SDCR2_SDCLK_POS       INT32_C(10)   /** @brief SDRAM clock configuration these bits define the SDRAM clock period for both SDRAM banks and allow disabling the clock before changing the frequency. In this case the SDRAM must be re-initialized. Note: the corresponding bits in the FMC_SDCR2 register is read only.. */
  #define FMC_SDCR2_RBURST_POS      INT32_C(12)   /** @brief Burst read this bit enables burst read mode. The SDRAM controller anticipates the next read commands during the CAS latency and stores data in the read FIFO. Note: the corresponding bit in the FMC_SDCR2 register is read only.. */
  #define FMC_SDCR2_RPIPE_POS       INT32_C(13)   /** @brief Read pipe these bits define the delay, in KCK_FMC clock cycles, for reading data after CAS latency. Note: the corresponding bits in the FMC_SDCR2 register is read only.. */
  #define FMC_SDTR1_TMRD_POS        INT32_C(0)    /** @brief Load mode register to active these bits define the delay between a load mode register command and an active or refresh command in number of memory clock cycles. ..... */
  #define FMC_SDTR1_TXSR_POS        INT32_C(4)    /** @brief Exit self-refresh delay these bits define the delay from releasing the self-refresh command to issuing the activate command in number of memory clock cycles. .... Note: if two SDRAM devices are used, the FMC_SDTR1 and FMC_SDTR2 must be programmed with the same TXSR timing corresponding to the slowest SDRAM device.. */
  #define FMC_SDTR1_TRAS_POS        INT32_C(8)    /** @brief Self refresh time these bits define the minimum self-refresh period in number of memory clock cycles. ..... */
  #define FMC_SDTR1_TRC_POS         INT32_C(12)   /** @brief Row cycle delay these bits define the delay between the refresh command and the activate command, as well as the delay between two consecutive refresh commands. It is expressed in number of memory clock cycles. The TRC timing is only configured in the FMC_SDTR1 register. If two SDRAM devices are used, the TRC must be programmed with the timings of the slowest device. .... Note: TRC must match the TRC and TRFC (auto refresh period) timings defined in the SDRAM device datasheet. Note: the corresponding bits in the FMC_SDTR2 register are dont care.. */
  #define FMC_SDTR1_TWR_POS         INT32_C(16)   /** @brief Recovery delay these bits define the delay between a write and a precharge command in number of memory clock cycles. .... Note: TWR must be programmed to match the write recovery time (twr) defined in the SDRAM datasheet, and to guarantee that: TWR &#8805; TRAS - TRCD and TWR &#8805;TRC - TRCD - TRP example: TRAS= 4 cycles, TRCD= 2 cycles. So, TWR &gt;= 2 cycles. TWR must be programmed to 0x1. If two SDRAM devices are used, the FMC_SDTR1 and FMC_SDTR2 must be programmed with the same TWR timing corresponding to the slowest SDRAM device.. */
  #define FMC_SDTR1_TRP_POS         INT32_C(20)   /** @brief Row precharge delay these bits define the delay between a precharge command and another command in number of memory clock cycles. The TRP timing is only configured in the FMC_SDTR1 register. If two SDRAM devices are used, the TRP must be programmed with the timing of the slowest device. .... Note: the corresponding bits in the FMC_SDTR2 register are dont care.. */
  #define FMC_SDTR1_TRCD_POS        INT32_C(24)   /** @brief Row to column delay these bits define the delay between the activate command and a read/write command in number of memory clock cycles. ..... */
  #define FMC_SDTR2_TMRD_POS        INT32_C(0)    /** @brief Load mode register to active these bits define the delay between a load mode register command and an active or refresh command in number of memory clock cycles. ..... */
  #define FMC_SDTR2_TXSR_POS        INT32_C(4)    /** @brief Exit self-refresh delay these bits define the delay from releasing the self-refresh command to issuing the activate command in number of memory clock cycles. .... Note: if two SDRAM devices are used, the FMC_SDTR1 and FMC_SDTR2 must be programmed with the same TXSR timing corresponding to the slowest SDRAM device.. */
  #define FMC_SDTR2_TRAS_POS        INT32_C(8)    /** @brief Self refresh time these bits define the minimum self-refresh period in number of memory clock cycles. ..... */
  #define FMC_SDTR2_TRC_POS         INT32_C(12)   /** @brief Row cycle delay these bits define the delay between the refresh command and the activate command, as well as the delay between two consecutive refresh commands. It is expressed in number of memory clock cycles. The TRC timing is only configured in the FMC_SDTR1 register. If two SDRAM devices are used, the TRC must be programmed with the timings of the slowest device. .... Note: TRC must match the TRC and TRFC (auto refresh period) timings defined in the SDRAM device datasheet. Note: the corresponding bits in the FMC_SDTR2 register are dont care.. */
  #define FMC_SDTR2_TWR_POS         INT32_C(16)   /** @brief Recovery delay these bits define the delay between a write and a precharge command in number of memory clock cycles. .... Note: TWR must be programmed to match the write recovery time (twr) defined in the SDRAM datasheet, and to guarantee that: TWR &#8805; TRAS - TRCD and TWR &#8805;TRC - TRCD - TRP example: TRAS= 4 cycles, TRCD= 2 cycles. So, TWR &gt;= 2 cycles. TWR must be programmed to 0x1. If two SDRAM devices are used, the FMC_SDTR1 and FMC_SDTR2 must be programmed with the same TWR timing corresponding to the slowest SDRAM device.. */
  #define FMC_SDTR2_TRP_POS         INT32_C(20)   /** @brief Row precharge delay these bits define the delay between a precharge command and another command in number of memory clock cycles. The TRP timing is only configured in the FMC_SDTR1 register. If two SDRAM devices are used, the TRP must be programmed with the timing of the slowest device. .... Note: the corresponding bits in the FMC_SDTR2 register are dont care.. */
  #define FMC_SDTR2_TRCD_POS        INT32_C(24)   /** @brief Row to column delay these bits define the delay between the activate command and a read/write command in number of memory clock cycles. ..... */
  #define FMC_SDCMR_MODE_POS        INT32_C(0)    /** @brief Command mode these bits define the command issued to the SDRAM device. Note: when a command is issued, at least one command target bank bit ( CTB1 or CTB2) must be set otherwise the command will be ignored. Note: if two SDRAM banks are used, the auto-refresh and PALL command must be issued simultaneously to the two devices with CTB1 and CTB2 bits set otherwise the command will be ignored. Note: if only one SDRAM bank is used and a command is issued with its associated CTB bit set, the other CTB bit of the unused bank must be kept to 0.. */
  #define FMC_SDCMR_CTB2_POS        INT32_C(3)    /** @brief Command target bank 2 this bit indicates whether the command will be issued to SDRAM bank 2 or not.. */
  #define FMC_SDCMR_CTB1_POS        INT32_C(4)    /** @brief Command target bank 1 this bit indicates whether the command will be issued to SDRAM bank 1 or not.. */
  #define FMC_SDCMR_NRFS_POS        INT32_C(5)    /** @brief Number of auto-refresh these bits define the number of consecutive auto-refresh commands issued when MODE = 011. ..... */
  #define FMC_SDCMR_MRD_POS         INT32_C(9)    /** @brief Mode register definition this 14-bit field defines the SDRAM mode register content. The mode register is programmed using the load mode register command. The MRD[13:0] bits are also used to program the extended mode register for mobile SDRAM.. */
  #define FMC_SDRTR_CRE_POS         INT32_C(0)    /** @brief Clear refresh error flag this bit is used to clear the refresh error flag (RE) in the status register.. */
  #define FMC_SDRTR_COUNT_POS       INT32_C(1)    /** @brief Refresh timer count this 13-bit field defines the refresh rate of the SDRAM device. It is expressed in number of memory clock cycles. It must be set at least to 41 SDRAM clock cycles (0x29). Refresh rate = (COUNT + 1) x SDRAM frequency clock COUNT = (SDRAM refresh period / number of rows) - 20. */
  #define FMC_SDRTR_REIE_POS        INT32_C(14)   /** @brief RES interrupt enable. */
  #define FMC_SDSR_RE_POS           INT32_C(0)    /** @brief Refresh error flag an interrupt is generated if REIE = 1 and RE = 1. */
  #define FMC_SDSR_MODES1_POS       INT32_C(1)    /** @brief Status mode for bank 1 these bits define the status mode of SDRAM bank 1.. */
  #define FMC_SDSR_MODES2_POS       INT32_C(3)    /** @brief Status mode for bank 2 these bits define the status mode of SDRAM bank 2.. */

  /*************************************************************************************************
   * @section CEC Definitions
   *************************************************************************************************/

  /**** @subsection Register Definitions ****/

  #define CEC_CR_PTR     (*(RW_ uint32_t*)UINT32_C(0x40006C00))   /** @brief CEC control register. */
  #define CEC_CFGR_PTR   (*(RW_ uint32_t*)UINT32_C(0x40006C04))   /** @brief This register is used to configure the HDMI-CEC controller. It is mandatory to write CEC_CFGR only when CECEN=0.. */
  #define CEC_TXDR_PTR   (*(WO_ uint32_t*)UINT32_C(0x40006C08))   /** @brief CEC tx data register. */
  #define CEC_RXDR_PTR   (*(RO_ uint32_t*)UINT32_C(0x40006C0C))   /** @brief CEC rx data register. */
  #define CEC_ISR_PTR    (*(RW_ uint32_t*)UINT32_C(0x40006C10))   /** @brief CEC interrupt and status register. */
  #define CEC_IER_PTR    (*(RW_ uint32_t*)UINT32_C(0x40006C14))   /** @brief CEC interrupt enable register. */

  /**** @subsection Field Mask Definitions ****/

  #define CEC_CR_CECEN_MSK        UINT32_C(0x00000001)   /** @brief CEC enable the CECEN bit is set and cleared by software. CECEN=1 starts message reception and enables the TXSOM control. CECEN=0 disables the CEC peripheral, clears all bits of CEC_CR register and aborts any on-going reception or transmission.. */
  #define CEC_CR_TXSOM_MSK        UINT32_C(0x00000002)   /** @brief Tx start of message TXSOM is set by software to command transmission of the first byte of a CEC message. If the CEC message consists of only one byte, TXEOM must be set before of TXSOM. Start-Bit is effectively started on the CEC line after SFT is counted. If TXSOM is set while a message reception is ongoing, transmission will start after the end of reception. TXSOM is cleared by hardware after the last byte of the message is sent with a positive acknowledge (TXEND=1), in case of transmission underrun (TXUDR=1), negative acknowledge (TXACKE=1), and transmission error (TXERR=1). It is also cleared by CECEN=0. It is not cleared and transmission is automatically retried in case of arbitration lost (ARBLST=1). TXSOM can be also used as a status bit informing application whether any transmission request is pending or under execution. The application can abort a transmission request at any time by clearing the CECEN bit. Note: TXSOM must be set when CECEN=1 TXSOM must be set when transmission data is available into TXDR headers first four bits containing own peripheral address are taken from TXDR[7:4], not from CEC_CFGR.OAR which is used only for reception. */
  #define CEC_CR_TXEOM_MSK        UINT32_C(0x00000004)   /** @brief Tx end of message the TXEOM bit is set by software to command transmission of the last byte of a CEC message. TXEOM is cleared by hardware at the same time and under the same conditions as for TXSOM. Note: TXEOM must be set when CECEN=1 TXEOM must be set before writing transmission data to TXDR if TXEOM is set when TXSOM=0, transmitted message will consist of 1 byte (HEADER) only (PING message). */
  #define CEC_CFGR_SFT_MSK        UINT32_C(0x00000007)   /** @brief Signal free time SFT bits are set by software. In the sft=0x0 configuration the number of nominal data bit periods waited before transmission is ruled by hardware according to the transmission history. In all the other configurations the SFT number is determined by software. * 0x0 ** 2.5 data-bit periods if CEC is the last bus initiator with unsuccessful transmission (ARBLST=1, TXERR=1, TXUDR=1 or TXACKE= 1) ** 4 data-bit periods if CEC is the new bus initiator ** 6 data-bit periods if CEC is the last bus initiator with successful transmission (TXEOM=1) * 0x1: 0.5 nominal data bit periods * 0x2: 1.5 nominal data bit periods * 0x3: 2.5 nominal data bit periods * 0x4: 3.5 nominal data bit periods * 0x5: 4.5 nominal data bit periods * 0x6: 5.5 nominal data bit periods * 0x7: 6.5 nominal data bit periods. */
  #define CEC_CFGR_RXTOL_MSK      UINT32_C(0x00000008)   /** @brief Rx-Tolerance the RXTOL bit is set and cleared by software. ** start-bit, +/- 200 s rise, +/- 200 s fall. ** data-bit: +/- 200 s rise. +/- 350 s fall. ** start-bit: +/- 400 s rise, +/- 400 s fall ** data-bit: +/-300 s rise, +/- 500 s fall. */
  #define CEC_CFGR_BRESTP_MSK     UINT32_C(0x00000010)   /** @brief Rx-Stop on bit rising error the BRESTP bit is set and cleared by software.. */
  #define CEC_CFGR_BREGEN_MSK     UINT32_C(0x00000020)   /** @brief Generate error-bit on bit rising error the BREGEN bit is set and cleared by software. Note: if BRDNOGEN=0, an error-bit is generated upon BRE detection with BRESTP=1 in broadcast even if BREGEN=0. */
  #define CEC_CFGR_LBPEGEN_MSK    UINT32_C(0x00000040)   /** @brief Generate error-bit on long bit period error the LBPEGEN bit is set and cleared by software. Note: if BRDNOGEN=0, an error-bit is generated upon LBPE detection in broadcast even if LBPEGEN=0. */
  #define CEC_CFGR_BRDNOGEN_MSK   UINT32_C(0x00000080)   /** @brief Avoid error-bit generation in broadcast the BRDNOGEN bit is set and cleared by software.. */
  #define CEC_CFGR_SFTOPT_MSK     UINT32_C(0x00000100)   /** @brief SFT option bit the SFTOPT bit is set and cleared by software.. */
  #define CEC_CFGR_OAR_MSK        UINT32_C(0x7FFF0000)   /** @brief Own addresses configuration the OAR bits are set by software to select which destination logical addresses has to be considered in receive mode. Each bit, when set, enables the CEC logical address identified by the given bit position. At the end of HEADER reception, the received destination address is compared with the enabled addresses. In case of matching address, the incoming message is acknowledged and received. In case of non-matching address, the incoming message is received only in listen mode (LSTN=1), but without acknowledge sent. Broadcast messages are always received. Example: OAR = 0b000 0000 0010 0001 means that CEC acknowledges addresses 0x0 and 0x5. Consequently, each message directed to one of these addresses is received.. */
  #define CEC_CFGR_LSTN_MSK       UINT32_C(0x80000000)   /** @brief Listen mode LSTN bit is set and cleared by software.. */
  #define CEC_TXDR_TXD_MSK        UINT32_C(0x000000FF)   /** @brief Tx data register. TXD is a write-only register containing the data byte to be transmitted. Note: TXD must be written when TXSTART=1. */
  #define CEC_RXDR_RXD_MSK        UINT32_C(0x000000FF)   /** @brief Rx data register. RXD is read-only and contains the last data byte which has been received from the CEC line.. */
  #define CEC_ISR_RXBR_MSK        UINT32_C(0x00000001)   /** @brief Rx-Byte received the RXBR bit is set by hardware to inform application that a new byte has been received from the CEC line and stored into the RXD buffer. RXBR is cleared by software write at 1.. */
  #define CEC_ISR_RXEND_MSK       UINT32_C(0x00000002)   /** @brief End of reception RXEND is set by hardware to inform application that the last byte of a CEC message is received from the CEC line and stored into the RXD buffer. RXEND is set at the same time of RXBR. RXEND is cleared by software write at 1.. */
  #define CEC_ISR_RXOVR_MSK       UINT32_C(0x00000004)   /** @brief Rx-Overrun RXOVR is set by hardware if RXBR is not yet cleared at the time a new byte is received on the CEC line and stored into RXD. RXOVR assertion stops message reception so that no acknowledge is sent. In case of broadcast, a negative acknowledge is sent. RXOVR is cleared by software write at 1.. */
  #define CEC_ISR_BRE_MSK         UINT32_C(0x00000008)   /** @brief Rx-Bit rising error BRE is set by hardware in case a data-bit waveform is detected with bit rising error. BRE is set either at the time the misplaced rising edge occurs, or at the end of the maximum BRE tolerance allowed by RXTOL, in case rising edge is still longing. BRE stops message reception if BRESTP=1. BRE generates an error-bit on the CEC line if BREGEN=1. BRE is cleared by software write at 1.. */
  #define CEC_ISR_SBPE_MSK        UINT32_C(0x00000010)   /** @brief Rx-Short bit period error SBPE is set by hardware in case a data-bit waveform is detected with short bit period error. SBPE is set at the time the anticipated falling edge occurs. SBPE generates an error-bit on the CEC line. SBPE is cleared by software write at 1.. */
  #define CEC_ISR_LBPE_MSK        UINT32_C(0x00000020)   /** @brief Rx-Long bit period error LBPE is set by hardware in case a data-bit waveform is detected with long bit period error. LBPE is set at the end of the maximum bit-extension tolerance allowed by RXTOL, in case falling edge is still longing. LBPE always stops reception of the CEC message. LBPE generates an error-bit on the CEC line if LBPEGEN=1. In case of broadcast, error-bit is generated even in case of LBPEGEN=0. LBPE is cleared by software write at 1.. */
  #define CEC_ISR_RXACKE_MSK      UINT32_C(0x00000040)   /** @brief Rx-Missing acknowledge in receive mode, RXACKE is set by hardware to inform application that no acknowledge was seen on the CEC line. RXACKE applies only for broadcast messages and in listen mode also for not directly addressed messages (destination address not enabled in OAR). RXACKE aborts message reception. RXACKE is cleared by software write at 1.. */
  #define CEC_ISR_ARBLST_MSK      UINT32_C(0x00000080)   /** @brief Arbitration lost ARBLST is set by hardware to inform application that CEC device is switching to reception due to arbitration lost event following the TXSOM command. ARBLST can be due either to a contending CEC device starting earlier or starting at the same time but with higher HEADER priority. After ARBLST assertion TXSOM bit keeps pending for next transmission attempt. ARBLST is cleared by software write at 1.. */
  #define CEC_ISR_TXBR_MSK        UINT32_C(0x00000100)   /** @brief Tx-Byte request TXBR is set by hardware to inform application that the next transmission data has to be written to TXDR. TXBR is set when the 4th bit of currently transmitted byte is sent. Application must write the next byte to TXDR within 6 nominal data-bit periods before transmission underrun error occurs (TXUDR). TXBR is cleared by software write at 1.. */
  #define CEC_ISR_TXEND_MSK       UINT32_C(0x00000200)   /** @brief End of transmission TXEND is set by hardware to inform application that the last byte of the CEC message has been successfully transmitted. TXEND clears the TXSOM and TXEOM control bits. TXEND is cleared by software write at 1.. */
  #define CEC_ISR_TXUDR_MSK       UINT32_C(0x00000400)   /** @brief Tx-Buffer underrun in transmission mode, TXUDR is set by hardware if application was not in time to load TXDR before of next byte transmission. TXUDR aborts message transmission and clears TXSOM and TXEOM control bits. TXUDR is cleared by software write at 1. */
  #define CEC_ISR_TXERR_MSK       UINT32_C(0x00000800)   /** @brief Tx-Error in transmission mode, TXERR is set by hardware if the CEC initiator detects low impedance on the CEC line while it is released. TXERR aborts message transmission and clears TXSOM and TXEOM controls. TXERR is cleared by software write at 1.. */
  #define CEC_ISR_TXACKE_MSK      UINT32_C(0x00001000)   /** @brief Tx-Missing acknowledge error in transmission mode, TXACKE is set by hardware to inform application that no acknowledge was received. In case of broadcast transmission, TXACKE informs application that a negative acknowledge was received. TXACKE aborts message transmission and clears TXSOM and TXEOM controls. TXACKE is cleared by software write at 1.. */
  #define CEC_IER_RXBRIE_MSK      UINT32_C(0x00000001)   /** @brief Rx-Byte received interrupt enable the RXBRIE bit is set and cleared by software.. */
  #define CEC_IER_RXENDIE_MSK     UINT32_C(0x00000002)   /** @brief End of reception interrupt enable the RXENDIE bit is set and cleared by software.. */
  #define CEC_IER_RXOVRIE_MSK     UINT32_C(0x00000004)   /** @brief Rx-Buffer overrun interrupt enable the RXOVRIE bit is set and cleared by software.. */
  #define CEC_IER_BREIE_MSK       UINT32_C(0x00000008)   /** @brief Bit rising error interrupt enable the BREIE bit is set and cleared by software.. */
  #define CEC_IER_SBPEIE_MSK      UINT32_C(0x00000010)   /** @brief Short bit period error interrupt enable the SBPEIE bit is set and cleared by software.. */
  #define CEC_IER_LBPEIE_MSK      UINT32_C(0x00000020)   /** @brief Long bit period error interrupt enable the LBPEIE bit is set and cleared by software.. */
  #define CEC_IER_RXACKIE_MSK     UINT32_C(0x00000040)   /** @brief Rx-Missing acknowledge error interrupt enable the RXACKIE bit is set and cleared by software.. */
  #define CEC_IER_ARBLSTIE_MSK    UINT32_C(0x00000080)   /** @brief Arbitration lost interrupt enable the ARBLSTIE bit is set and cleared by software.. */
  #define CEC_IER_TXBRIE_MSK      UINT32_C(0x00000100)   /** @brief Tx-Byte request interrupt enable the TXBRIE bit is set and cleared by software.. */
  #define CEC_IER_TXENDIE_MSK     UINT32_C(0x00000200)   /** @brief Tx-End of message interrupt enable the TXENDIE bit is set and cleared by software.. */
  #define CEC_IER_TXUDRIE_MSK     UINT32_C(0x00000400)   /** @brief Tx-Underrun interrupt enable the TXUDRIE bit is set and cleared by software.. */
  #define CEC_IER_TXERRIE_MSK     UINT32_C(0x00000800)   /** @brief Tx-Error interrupt enable the TXERRIE bit is set and cleared by software.. */
  #define CEC_IER_TXACKIE_MSK     UINT32_C(0x00001000)   /** @brief Tx-Missing acknowledge error interrupt enable the TXACKEIE bit is set and cleared by software.. */

  /**** @subsection Field Position Definitions ****/

  #define CEC_CR_CECEN_POS        INT32_C(0)    /** @brief CEC enable the CECEN bit is set and cleared by software. CECEN=1 starts message reception and enables the TXSOM control. CECEN=0 disables the CEC peripheral, clears all bits of CEC_CR register and aborts any on-going reception or transmission.. */
  #define CEC_CR_TXSOM_POS        INT32_C(1)    /** @brief Tx start of message TXSOM is set by software to command transmission of the first byte of a CEC message. If the CEC message consists of only one byte, TXEOM must be set before of TXSOM. Start-Bit is effectively started on the CEC line after SFT is counted. If TXSOM is set while a message reception is ongoing, transmission will start after the end of reception. TXSOM is cleared by hardware after the last byte of the message is sent with a positive acknowledge (TXEND=1), in case of transmission underrun (TXUDR=1), negative acknowledge (TXACKE=1), and transmission error (TXERR=1). It is also cleared by CECEN=0. It is not cleared and transmission is automatically retried in case of arbitration lost (ARBLST=1). TXSOM can be also used as a status bit informing application whether any transmission request is pending or under execution. The application can abort a transmission request at any time by clearing the CECEN bit. Note: TXSOM must be set when CECEN=1 TXSOM must be set when transmission data is available into TXDR headers first four bits containing own peripheral address are taken from TXDR[7:4], not from CEC_CFGR.OAR which is used only for reception. */
  #define CEC_CR_TXEOM_POS        INT32_C(2)    /** @brief Tx end of message the TXEOM bit is set by software to command transmission of the last byte of a CEC message. TXEOM is cleared by hardware at the same time and under the same conditions as for TXSOM. Note: TXEOM must be set when CECEN=1 TXEOM must be set before writing transmission data to TXDR if TXEOM is set when TXSOM=0, transmitted message will consist of 1 byte (HEADER) only (PING message). */
  #define CEC_CFGR_SFT_POS        INT32_C(0)    /** @brief Signal free time SFT bits are set by software. In the sft=0x0 configuration the number of nominal data bit periods waited before transmission is ruled by hardware according to the transmission history. In all the other configurations the SFT number is determined by software. * 0x0 ** 2.5 data-bit periods if CEC is the last bus initiator with unsuccessful transmission (ARBLST=1, TXERR=1, TXUDR=1 or TXACKE= 1) ** 4 data-bit periods if CEC is the new bus initiator ** 6 data-bit periods if CEC is the last bus initiator with successful transmission (TXEOM=1) * 0x1: 0.5 nominal data bit periods * 0x2: 1.5 nominal data bit periods * 0x3: 2.5 nominal data bit periods * 0x4: 3.5 nominal data bit periods * 0x5: 4.5 nominal data bit periods * 0x6: 5.5 nominal data bit periods * 0x7: 6.5 nominal data bit periods. */
  #define CEC_CFGR_RXTOL_POS      INT32_C(3)    /** @brief Rx-Tolerance the RXTOL bit is set and cleared by software. ** start-bit, +/- 200 s rise, +/- 200 s fall. ** data-bit: +/- 200 s rise. +/- 350 s fall. ** start-bit: +/- 400 s rise, +/- 400 s fall ** data-bit: +/-300 s rise, +/- 500 s fall. */
  #define CEC_CFGR_BRESTP_POS     INT32_C(4)    /** @brief Rx-Stop on bit rising error the BRESTP bit is set and cleared by software.. */
  #define CEC_CFGR_BREGEN_POS     INT32_C(5)    /** @brief Generate error-bit on bit rising error the BREGEN bit is set and cleared by software. Note: if BRDNOGEN=0, an error-bit is generated upon BRE detection with BRESTP=1 in broadcast even if BREGEN=0. */
  #define CEC_CFGR_LBPEGEN_POS    INT32_C(6)    /** @brief Generate error-bit on long bit period error the LBPEGEN bit is set and cleared by software. Note: if BRDNOGEN=0, an error-bit is generated upon LBPE detection in broadcast even if LBPEGEN=0. */
  #define CEC_CFGR_BRDNOGEN_POS   INT32_C(7)    /** @brief Avoid error-bit generation in broadcast the BRDNOGEN bit is set and cleared by software.. */
  #define CEC_CFGR_SFTOPT_POS     INT32_C(8)    /** @brief SFT option bit the SFTOPT bit is set and cleared by software.. */
  #define CEC_CFGR_OAR_POS        INT32_C(16)   /** @brief Own addresses configuration the OAR bits are set by software to select which destination logical addresses has to be considered in receive mode. Each bit, when set, enables the CEC logical address identified by the given bit position. At the end of HEADER reception, the received destination address is compared with the enabled addresses. In case of matching address, the incoming message is acknowledged and received. In case of non-matching address, the incoming message is received only in listen mode (LSTN=1), but without acknowledge sent. Broadcast messages are always received. Example: OAR = 0b000 0000 0010 0001 means that CEC acknowledges addresses 0x0 and 0x5. Consequently, each message directed to one of these addresses is received.. */
  #define CEC_CFGR_LSTN_POS       INT32_C(31)   /** @brief Listen mode LSTN bit is set and cleared by software.. */
  #define CEC_TXDR_TXD_POS        INT32_C(0)    /** @brief Tx data register. TXD is a write-only register containing the data byte to be transmitted. Note: TXD must be written when TXSTART=1. */
  #define CEC_RXDR_RXD_POS        INT32_C(0)    /** @brief Rx data register. RXD is read-only and contains the last data byte which has been received from the CEC line.. */
  #define CEC_ISR_RXBR_POS        INT32_C(0)    /** @brief Rx-Byte received the RXBR bit is set by hardware to inform application that a new byte has been received from the CEC line and stored into the RXD buffer. RXBR is cleared by software write at 1.. */
  #define CEC_ISR_RXEND_POS       INT32_C(1)    /** @brief End of reception RXEND is set by hardware to inform application that the last byte of a CEC message is received from the CEC line and stored into the RXD buffer. RXEND is set at the same time of RXBR. RXEND is cleared by software write at 1.. */
  #define CEC_ISR_RXOVR_POS       INT32_C(2)    /** @brief Rx-Overrun RXOVR is set by hardware if RXBR is not yet cleared at the time a new byte is received on the CEC line and stored into RXD. RXOVR assertion stops message reception so that no acknowledge is sent. In case of broadcast, a negative acknowledge is sent. RXOVR is cleared by software write at 1.. */
  #define CEC_ISR_BRE_POS         INT32_C(3)    /** @brief Rx-Bit rising error BRE is set by hardware in case a data-bit waveform is detected with bit rising error. BRE is set either at the time the misplaced rising edge occurs, or at the end of the maximum BRE tolerance allowed by RXTOL, in case rising edge is still longing. BRE stops message reception if BRESTP=1. BRE generates an error-bit on the CEC line if BREGEN=1. BRE is cleared by software write at 1.. */
  #define CEC_ISR_SBPE_POS        INT32_C(4)    /** @brief Rx-Short bit period error SBPE is set by hardware in case a data-bit waveform is detected with short bit period error. SBPE is set at the time the anticipated falling edge occurs. SBPE generates an error-bit on the CEC line. SBPE is cleared by software write at 1.. */
  #define CEC_ISR_LBPE_POS        INT32_C(5)    /** @brief Rx-Long bit period error LBPE is set by hardware in case a data-bit waveform is detected with long bit period error. LBPE is set at the end of the maximum bit-extension tolerance allowed by RXTOL, in case falling edge is still longing. LBPE always stops reception of the CEC message. LBPE generates an error-bit on the CEC line if LBPEGEN=1. In case of broadcast, error-bit is generated even in case of LBPEGEN=0. LBPE is cleared by software write at 1.. */
  #define CEC_ISR_RXACKE_POS      INT32_C(6)    /** @brief Rx-Missing acknowledge in receive mode, RXACKE is set by hardware to inform application that no acknowledge was seen on the CEC line. RXACKE applies only for broadcast messages and in listen mode also for not directly addressed messages (destination address not enabled in OAR). RXACKE aborts message reception. RXACKE is cleared by software write at 1.. */
  #define CEC_ISR_ARBLST_POS      INT32_C(7)    /** @brief Arbitration lost ARBLST is set by hardware to inform application that CEC device is switching to reception due to arbitration lost event following the TXSOM command. ARBLST can be due either to a contending CEC device starting earlier or starting at the same time but with higher HEADER priority. After ARBLST assertion TXSOM bit keeps pending for next transmission attempt. ARBLST is cleared by software write at 1.. */
  #define CEC_ISR_TXBR_POS        INT32_C(8)    /** @brief Tx-Byte request TXBR is set by hardware to inform application that the next transmission data has to be written to TXDR. TXBR is set when the 4th bit of currently transmitted byte is sent. Application must write the next byte to TXDR within 6 nominal data-bit periods before transmission underrun error occurs (TXUDR). TXBR is cleared by software write at 1.. */
  #define CEC_ISR_TXEND_POS       INT32_C(9)    /** @brief End of transmission TXEND is set by hardware to inform application that the last byte of the CEC message has been successfully transmitted. TXEND clears the TXSOM and TXEOM control bits. TXEND is cleared by software write at 1.. */
  #define CEC_ISR_TXUDR_POS       INT32_C(10)   /** @brief Tx-Buffer underrun in transmission mode, TXUDR is set by hardware if application was not in time to load TXDR before of next byte transmission. TXUDR aborts message transmission and clears TXSOM and TXEOM control bits. TXUDR is cleared by software write at 1. */
  #define CEC_ISR_TXERR_POS       INT32_C(11)   /** @brief Tx-Error in transmission mode, TXERR is set by hardware if the CEC initiator detects low impedance on the CEC line while it is released. TXERR aborts message transmission and clears TXSOM and TXEOM controls. TXERR is cleared by software write at 1.. */
  #define CEC_ISR_TXACKE_POS      INT32_C(12)   /** @brief Tx-Missing acknowledge error in transmission mode, TXACKE is set by hardware to inform application that no acknowledge was received. In case of broadcast transmission, TXACKE informs application that a negative acknowledge was received. TXACKE aborts message transmission and clears TXSOM and TXEOM controls. TXACKE is cleared by software write at 1.. */
  #define CEC_IER_RXBRIE_POS      INT32_C(0)    /** @brief Rx-Byte received interrupt enable the RXBRIE bit is set and cleared by software.. */
  #define CEC_IER_RXENDIE_POS     INT32_C(1)    /** @brief End of reception interrupt enable the RXENDIE bit is set and cleared by software.. */
  #define CEC_IER_RXOVRIE_POS     INT32_C(2)    /** @brief Rx-Buffer overrun interrupt enable the RXOVRIE bit is set and cleared by software.. */
  #define CEC_IER_BREIE_POS       INT32_C(3)    /** @brief Bit rising error interrupt enable the BREIE bit is set and cleared by software.. */
  #define CEC_IER_SBPEIE_POS      INT32_C(4)    /** @brief Short bit period error interrupt enable the SBPEIE bit is set and cleared by software.. */
  #define CEC_IER_LBPEIE_POS      INT32_C(5)    /** @brief Long bit period error interrupt enable the LBPEIE bit is set and cleared by software.. */
  #define CEC_IER_RXACKIE_POS     INT32_C(6)    /** @brief Rx-Missing acknowledge error interrupt enable the RXACKIE bit is set and cleared by software.. */
  #define CEC_IER_ARBLSTIE_POS    INT32_C(7)    /** @brief Arbitration lost interrupt enable the ARBLSTIE bit is set and cleared by software.. */
  #define CEC_IER_TXBRIE_POS      INT32_C(8)    /** @brief Tx-Byte request interrupt enable the TXBRIE bit is set and cleared by software.. */
  #define CEC_IER_TXENDIE_POS     INT32_C(9)    /** @brief Tx-End of message interrupt enable the TXENDIE bit is set and cleared by software.. */
  #define CEC_IER_TXUDRIE_POS     INT32_C(10)   /** @brief Tx-Underrun interrupt enable the TXUDRIE bit is set and cleared by software.. */
  #define CEC_IER_TXERRIE_POS     INT32_C(11)   /** @brief Tx-Error interrupt enable the TXERRIE bit is set and cleared by software.. */
  #define CEC_IER_TXACKIE_POS     INT32_C(12)   /** @brief Tx-Missing acknowledge error interrupt enable the TXACKEIE bit is set and cleared by software.. */

