  #define HSEM_HSEM_MISR_ISEM16_POS      INT32_C(16)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM17_POS      INT32_C(17)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM18_POS      INT32_C(18)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM19_POS      INT32_C(19)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM20_POS      INT32_C(20)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM21_POS      INT32_C(21)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM22_POS      INT32_C(22)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM23_POS      INT32_C(23)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM24_POS      INT32_C(24)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM25_POS      INT32_C(25)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM26_POS      INT32_C(26)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM27_POS      INT32_C(27)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM28_POS      INT32_C(28)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM29_POS      INT32_C(29)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM30_POS      INT32_C(30)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_MISR_ISEM31_POS      INT32_C(31)   /** @brief Masked interrupt(n) semaphore n status bit after enable (mask). */
  #define HSEM_HSEM_CR_MASTERID_POS      INT32_C(8)    /** @brief MasterID of semaphores to be cleared. */
  #define HSEM_HSEM_CR_KEY_POS           INT32_C(16)   /** @brief Semaphore clear key. */
