  /*************************************************************************************************
   * @section I2C1 Definitions
   *************************************************************************************************/

  /**** @subsection Register Definitions ****/

  #define I2C1_CR1_PTR        (*(RW_ uint32_t*)UINT32_C(0x40005400))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C1_CR2_PTR        (*(RW_ uint32_t*)UINT32_C(0x40005404))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C1_OAR1_PTR       (*(RW_ uint32_t*)UINT32_C(0x40005408))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C1_OAR2_PTR       (*(RW_ uint32_t*)UINT32_C(0x4000540C))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C1_TIMINGR_PTR    (*(RW_ uint32_t*)UINT32_C(0x40005410))   /** @brief Access: no wait states. */
  #define I2C1_TIMEOUTR_PTR   (*(RW_ uint32_t*)UINT32_C(0x40005414))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C1_ISR_PTR        (*(RW_ uint32_t*)UINT32_C(0x40005418))   /** @brief Access: no wait states. */
  #define I2C1_ICR_PTR        (*(WO_ uint32_t*)UINT32_C(0x4000541C))   /** @brief Access: no wait states. */
  #define I2C1_PECR_PTR       (*(RO_ uint32_t*)UINT32_C(0x40005420))   /** @brief Access: no wait states. */
  #define I2C1_RXDR_PTR       (*(RO_ uint32_t*)UINT32_C(0x40005424))   /** @brief Access: no wait states. */
  #define I2C1_TXDR_PTR       (*(RW_ uint32_t*)UINT32_C(0x40005428))   /** @brief Access: no wait states. */

  /**** @subsection Field Mask Definitions ****/

  #define I2C1_CR1_PE_MSK               UINT32_C(0x00000001)   /** @brief Peripheral enable note: when PE=0, the I2C SCL and SDA lines are released. Internal state machines and status bits are put back to their reset value. When cleared, PE must be kept low for at least 3 APB clock cycles.. */
  #define I2C1_CR1_TXIE_MSK             UINT32_C(0x00000002)   /** @brief TX interrupt enable. */
  #define I2C1_CR1_RXIE_MSK             UINT32_C(0x00000004)   /** @brief RX interrupt enable. */
  #define I2C1_CR1_ADDRIE_MSK           UINT32_C(0x00000008)   /** @brief Address match interrupt enable (slave only). */
  #define I2C1_CR1_NACKIE_MSK           UINT32_C(0x00000010)   /** @brief Not acknowledge received interrupt enable. */
  #define I2C1_CR1_STOPIE_MSK           UINT32_C(0x00000020)   /** @brief STOP detection interrupt enable. */
  #define I2C1_CR1_TCIE_MSK             UINT32_C(0x00000040)   /** @brief Transfer complete interrupt enable note: any of these events will generate an interrupt: transfer complete (TC) transfer complete reload (TCR). */
  #define I2C1_CR1_ERRIE_MSK            UINT32_C(0x00000080)   /** @brief Error interrupts enable note: any of these errors generate an interrupt: arbitration loss (ARLO) bus error detection (BERR) overrun/underrun (OVR) timeout detection (TIMEOUT) PEC error detection (PECERR) alert pin event detection (ALERT). */
  #define I2C1_CR1_DNF_MSK              UINT32_C(0x00000F00)   /** @brief Digital noise filter these bits are used to configure the digital noise filter on SDA and SCL input. The digital filter will filter spikes with a length of up to DNF[3:0] * ti2cclk ... Note: if the analog filter is also enabled, the digital filter is added to the analog filter. This filter can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C1_CR1_ANFOFF_MSK           UINT32_C(0x00001000)   /** @brief Analog noise filter OFF note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C1_CR1_TXDMAEN_MSK          UINT32_C(0x00004000)   /** @brief DMA transmission requests enable. */
  #define I2C1_CR1_RXDMAEN_MSK          UINT32_C(0x00008000)   /** @brief DMA reception requests enable. */
  #define I2C1_CR1_SBC_MSK              UINT32_C(0x00010000)   /** @brief Slave byte control this bit is used to enable hardware byte control in slave mode.. */
  #define I2C1_CR1_NOSTRETCH_MSK        UINT32_C(0x00020000)   /** @brief Clock stretching disable this bit is used to disable clock stretching in slave mode. It must be kept cleared in master mode. Note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C1_CR1_WUPEN_MSK            UINT32_C(0x00040000)   /** @brief Wakeup from stop mode enable note: if the wakeup from stop mode feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation. Note: WUPEN can be set only when DNF = 0000. */
  #define I2C1_CR1_GCEN_MSK             UINT32_C(0x00080000)   /** @brief General call enable. */
  #define I2C1_CR1_SMBHEN_MSK           UINT32_C(0x00100000)   /** @brief SMBus host address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_CR1_SMBDEN_MSK           UINT32_C(0x00200000)   /** @brief SMBus device default address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_CR1_ALERTEN_MSK          UINT32_C(0x00400000)   /** @brief SMBus alert enable device mode (SMBHEN=0): host mode (SMBHEN=1): note: when ALERTEN=0, the SMBA pin can be used as a standard GPIO. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_CR1_PECEN_MSK            UINT32_C(0x00800000)   /** @brief PEC enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_CR2_SADD0_MSK            UINT32_C(0x00000001)   /** @brief Slave address bit 0 (master mode) in 7-bit addressing mode (ADD10 = 0): this bit is dont care in 10-bit addressing mode (ADD10 = 1): this bit should be written with bit 0 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD1_MSK            UINT32_C(0x00000002)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD2_MSK            UINT32_C(0x00000004)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD3_MSK            UINT32_C(0x00000008)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD4_MSK            UINT32_C(0x00000010)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD5_MSK            UINT32_C(0x00000020)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD6_MSK            UINT32_C(0x00000040)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD7_MSK            UINT32_C(0x00000080)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD8_MSK            UINT32_C(0x00000100)   /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD9_MSK            UINT32_C(0x00000200)   /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_RD_WRN_MSK           UINT32_C(0x00000400)   /** @brief Transfer direction (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C1_CR2_ADD10_MSK            UINT32_C(0x00000800)   /** @brief 10-bit addressing mode (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C1_CR2_HEAD10R_MSK          UINT32_C(0x00001000)   /** @brief 10-bit address header only read direction (master receiver mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C1_CR2_START_MSK            UINT32_C(0x00002000)   /** @brief Start generation this bit is set by software, and cleared by hardware after the start followed by the address sequence is sent, by an arbitration loss, by a timeout error detection, or when PE = 0. It can also be cleared by software by writing 1 to the ADDRCF bit in the I2C_ICR register. If the I2C is already in master mode with AUTOEND = 0, setting this bit generates a repeated start condition when RELOAD=0, after the end of the NBYTES transfer. Otherwise setting this bit will generate a START condition once the bus is free. Note: writing 0 to this bit has no effect. The START bit can be set even if the bus is BUSY or I2C is in slave mode. This bit has no effect when RELOAD is set.. */
  #define I2C1_CR2_STOP_MSK             UINT32_C(0x00004000)   /** @brief Stop generation (master mode) the bit is set by software, cleared by hardware when a stop condition is detected, or when PE = 0. In master mode: note: writing 0 to this bit has no effect.. */
  #define I2C1_CR2_NACK_MSK             UINT32_C(0x00008000)   /** @brief NACK generation (slave mode) the bit is set by software, cleared by hardware when the NACK is sent, or when a STOP condition or an address matched is received, or when PE=0. Note: writing 0 to this bit has no effect. This bit is used in slave mode only: in master receiver mode, NACK is automatically generated after last byte preceding STOP or RESTART condition, whatever the NACK bit value. When an overrun occurs in slave receiver NOSTRETCH mode, a NACK is automatically generated whatever the NACK bit value. When hardware PEC checking is enabled (PECBYTE=1), the PEC acknowledge value does not depend on the NACK value.. */
  #define I2C1_CR2_NBYTES_MSK           UINT32_C(0x00FF0000)   /** @brief Number of bytes the number of bytes to be transmitted/received is programmed there. This field is dont care in slave mode with SBC=0. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_RELOAD_MSK           UINT32_C(0x01000000)   /** @brief NBYTES reload mode this bit is set and cleared by software.. */
  #define I2C1_CR2_AUTOEND_MSK          UINT32_C(0x02000000)   /** @brief Automatic end mode (master mode) this bit is set and cleared by software. Note: this bit has no effect in slave mode or when the RELOAD bit is set.. */
  #define I2C1_CR2_PECBYTE_MSK          UINT32_C(0x04000000)   /** @brief Packet error checking byte this bit is set by software, and cleared by hardware when the PEC is transferred, or when a STOP condition or an address matched is received, also when PE=0. Note: writing 0 to this bit has no effect. This bit has no effect when RELOAD is set. This bit has no effect is slave mode when SBC=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_OAR1_OA1_MSK             UINT32_C(0x000003FF)   /** @brief Interface address 7-bit addressing mode: dont care 10-bit addressing mode: bits 9:8 of address note: these bits can be written only when OA1EN=0. OA1[7:1]: interface address bits 7:1 of address note: these bits can be written only when OA1EN=0. OA1[0]: interface address 7-bit addressing mode: dont care 10-bit addressing mode: bit 0 of address note: this bit can be written only when OA1EN=0.. */
  #define I2C1_OAR1_OA1MODE_MSK         UINT32_C(0x00000400)   /** @brief Own address 1 10-bit mode note: this bit can be written only when OA1EN=0.. */
  #define I2C1_OAR1_OA1EN_MSK           UINT32_C(0x00008000)   /** @brief Own address 1 enable. */
  #define I2C1_OAR2_OA2_MSK             UINT32_C(0x000000FE)   /** @brief Interface address bits 7:1 of address note: these bits can be written only when OA2EN=0.. */
  #define I2C1_OAR2_OA2MSK_MSK          UINT32_C(0x00000700)   /** @brief Own address 2 masks note: these bits can be written only when OA2EN=0. As soon as OA2MSK is not equal to 0, the reserved I2C addresses (0b0000xxx and 0b1111xxx) are not acknowledged even if the comparison matches.. */
  #define I2C1_OAR2_OA2EN_MSK           UINT32_C(0x00008000)   /** @brief Own address 2 enable. */
  #define I2C1_TIMINGR_SCLL_MSK         UINT32_C(0x000000FF)   /** @brief SCL low period (master mode) this field is used to generate the SCL low period in master mode. TSCLL = (SCLL+1) x tpresc note: SCLL is also used to generate tbuf and tsu:sta timings.. */
  #define I2C1_TIMINGR_SCLH_MSK         UINT32_C(0x0000FF00)   /** @brief SCL high period (master mode) this field is used to generate the SCL high period in master mode. TSCLH = (SCLH+1) x tpresc note: SCLH is also used to generate tsu:sto and thd:sta timing.. */
  #define I2C1_TIMINGR_SDADEL_MSK       UINT32_C(0x000F0000)   /** @brief Data hold time this field is used to generate the delay tsdadel between SCL falling edge and SDA edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tsdadel. TSDADEL= SDADEL x tpresc note: SDADEL is used to generate thd:dat timing.. */
  #define I2C1_TIMINGR_SCLDEL_MSK       UINT32_C(0x00F00000)   /** @brief Data setup time this field is used to generate a delay tscldel between SDA edge and SCL rising edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tscldel. TSCLDEL = (SCLDEL+1) x tpresc note: tscldel is used to generate tsu:dat timing.. */
  #define I2C1_TIMINGR_PRESC_MSK        UINT32_C(0xF0000000)   /** @brief Timing prescaler this field is used to prescale I2CCLK in order to generate the clock period tpresc used for data setup and hold counters (refer to I2C timings on page9) and for SCL high and low level counters (refer to I2C master initialization on page24). TPRESC = (PRESC+1) x ti2cclk. */
  #define I2C1_TIMEOUTR_TIMEOUTA_MSK    UINT32_C(0x00000FFF)   /** @brief Bus timeout A this field is used to configure: the SCL low timeout condition ttimeout when TIDLE=0 ttimeout= (TIMEOUTA+1) x 2048 x ti2cclk the bus idle condition (both SCL and SDA high) when TIDLE=1 tidle= (TIMEOUTA+1) x 4 x ti2cclk note: these bits can be written only when TIMOUTEN=0.. */
  #define I2C1_TIMEOUTR_TIDLE_MSK       UINT32_C(0x00001000)   /** @brief Idle clock timeout detection note: this bit can be written only when TIMOUTEN=0.. */
  #define I2C1_TIMEOUTR_TIMOUTEN_MSK    UINT32_C(0x00008000)   /** @brief Clock timeout enable. */
  #define I2C1_TIMEOUTR_TIMEOUTB_MSK    UINT32_C(0x0FFF0000)   /** @brief Bus timeout B this field is used to configure the cumulative clock extension timeout: in master mode, the master cumulative clock low extend time (tlow:mext) is detected in slave mode, the slave cumulative clock low extend time (tlow:sext) is detected tlow:ext= (TIMEOUTB+1) x 2048 x ti2cclk note: these bits can be written only when TEXTEN=0.. */
  #define I2C1_TIMEOUTR_TEXTEN_MSK      UINT32_C(0x80000000)   /** @brief Extended clock timeout enable. */
  #define I2C1_ISR_TXE_MSK              UINT32_C(0x00000001)   /** @brief Transmit data register empty (transmitters) this bit is set by hardware when the I2C_TXDR register is empty. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software in order to flush the transmit data register I2C_TXDR. Note: this bit is set by hardware when PE=0.. */
  #define I2C1_ISR_TXIS_MSK             UINT32_C(0x00000002)   /** @brief Transmit interrupt status (transmitters) this bit is set by hardware when the I2C_TXDR register is empty and the data to be transmitted must be written in the I2C_TXDR register. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software when NOSTRETCH=1 only, in order to generate a TXIS event (interrupt if TXIE=1 or DMA request if TXDMAEN=1). Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_RXNE_MSK             UINT32_C(0x00000004)   /** @brief Receive data register not empty (receivers) this bit is set by hardware when the received data is copied into the I2C_RXDR register, and is ready to be read. It is cleared when I2C_RXDR is read. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_ADDR_MSK             UINT32_C(0x00000008)   /** @brief Address matched (slave mode) this bit is set by hardware as soon as the received slave address matched with one of the enabled slave addresses. It is cleared by software by setting ADDRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_NACKF_MSK            UINT32_C(0x00000010)   /** @brief Not acknowledge received flag this flag is set by hardware when a NACK is received after a byte transmission. It is cleared by software by setting the NACKCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_STOPF_MSK            UINT32_C(0x00000020)   /** @brief Stop detection flag this flag is set by hardware when a stop condition is detected on the bus and the peripheral is involved in this transfer: either as a master, provided that the STOP condition is generated by the peripheral. Or as a slave, provided that the peripheral has been addressed previously during this transfer. It is cleared by software by setting the STOPCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_TC_MSK               UINT32_C(0x00000040)   /** @brief Transfer complete (master mode) this flag is set by hardware when RELOAD=0, AUTOEND=0 and NBYTES data have been transferred. It is cleared by software when START bit or STOP bit is set. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_TCR_MSK              UINT32_C(0x00000080)   /** @brief Transfer complete reload this flag is set by hardware when RELOAD=1 and NBYTES data have been transferred. It is cleared by software when NBYTES is written to a non-zero value. Note: this bit is cleared by hardware when PE=0. This flag is only for master mode, or for slave mode when the SBC bit is set.. */
  #define I2C1_ISR_BERR_MSK             UINT32_C(0x00000100)   /** @brief Bus error this flag is set by hardware when a misplaced start or stop condition is detected whereas the peripheral is involved in the transfer. The flag is not set during the address phase in slave mode. It is cleared by software by setting BERRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_ARLO_MSK             UINT32_C(0x00000200)   /** @brief Arbitration lost this flag is set by hardware in case of arbitration loss. It is cleared by software by setting the ARLOCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_OVR_MSK              UINT32_C(0x00000400)   /** @brief Overrun/Underrun (slave mode) this flag is set by hardware in slave mode with NOSTRETCH=1, when an overrun/underrun error occurs. It is cleared by software by setting the OVRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_PECERR_MSK           UINT32_C(0x00000800)   /** @brief PEC error in reception this flag is set by hardware when the received PEC does not match with the PEC register content. A NACK is automatically sent after the wrong PEC reception. It is cleared by software by setting the PECCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_ISR_TIMEOUT_MSK          UINT32_C(0x00001000)   /** @brief Timeout or tlow detection flag this flag is set by hardware when a timeout or extended clock timeout occurred. It is cleared by software by setting the TIMEOUTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_ISR_ALERT_MSK            UINT32_C(0x00002000)   /** @brief SMBus alert this flag is set by hardware when SMBHEN=1 (smbus host configuration), ALERTEN=1 and a SMBALERT event (falling edge) is detected on SMBA pin. It is cleared by software by setting the ALERTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_ISR_BUSY_MSK             UINT32_C(0x00008000)   /** @brief Bus busy this flag indicates that a communication is in progress on the bus. It is set by hardware when a START condition is detected. It is cleared by hardware when a stop condition is detected, or when PE=0.. */
  #define I2C1_ISR_DIR_MSK              UINT32_C(0x00010000)   /** @brief Transfer direction (slave mode) this flag is updated when an address match event occurs (ADDR=1).. */
  #define I2C1_ISR_ADDCODE_MSK          UINT32_C(0x00FE0000)   /** @brief Address match code (slave mode) these bits are updated with the received address when an address match event occurs (ADDR = 1). In the case of a 10-bit address, ADDCODE provides the 10-bit header followed by the 2 msbs of the address.. */
  #define I2C1_ICR_ADDRCF_MSK           UINT32_C(0x00000008)   /** @brief Address matched flag clear writing 1 to this bit clears the ADDR flag in the I2C_ISR register. Writing 1 to this bit also clears the START bit in the I2C_CR2 register.. */
  #define I2C1_ICR_NACKCF_MSK           UINT32_C(0x00000010)   /** @brief Not acknowledge flag clear writing 1 to this bit clears the ACKF flag in I2C_ISR register.. */
  #define I2C1_ICR_STOPCF_MSK           UINT32_C(0x00000020)   /** @brief Stop detection flag clear writing 1 to this bit clears the STOPF flag in the I2C_ISR register.. */
  #define I2C1_ICR_BERRCF_MSK           UINT32_C(0x00000100)   /** @brief Bus error flag clear writing 1 to this bit clears the BERRF flag in the I2C_ISR register.. */
  #define I2C1_ICR_ARLOCF_MSK           UINT32_C(0x00000200)   /** @brief Arbitration lost flag clear writing 1 to this bit clears the ARLO flag in the I2C_ISR register.. */
  #define I2C1_ICR_OVRCF_MSK            UINT32_C(0x00000400)   /** @brief Overrun/Underrun flag clear writing 1 to this bit clears the OVR flag in the I2C_ISR register.. */
  #define I2C1_ICR_PECCF_MSK            UINT32_C(0x00000800)   /** @brief PEC error flag clear writing 1 to this bit clears the PECERR flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_ICR_TIMOUTCF_MSK         UINT32_C(0x00001000)   /** @brief Timeout detection flag clear writing 1 to this bit clears the TIMEOUT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_ICR_ALERTCF_MSK          UINT32_C(0x00002000)   /** @brief Alert flag clear writing 1 to this bit clears the ALERT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_PECR_PEC_MSK             UINT32_C(0x000000FF)   /** @brief Packet error checking register this field contains the internal PEC when PECEN=1. The PEC is cleared by hardware when PE=0.. */
  #define I2C1_RXDR_RXDATA_MSK          UINT32_C(0x000000FF)   /** @brief 8-bit receive data data byte received from the I2C bus.. */
  #define I2C1_TXDR_TXDATA_MSK          UINT32_C(0x000000FF)   /** @brief 8-bit transmit data data byte to be transmitted to the I2C bus. Note: these bits can be written only when TXE=1.. */

  /**** @subsection Field Position Definitions ****/

  #define I2C1_CR1_PE_POS               INT32_C(0)    /** @brief Peripheral enable note: when PE=0, the I2C SCL and SDA lines are released. Internal state machines and status bits are put back to their reset value. When cleared, PE must be kept low for at least 3 APB clock cycles.. */
  #define I2C1_CR1_TXIE_POS             INT32_C(1)    /** @brief TX interrupt enable. */
  #define I2C1_CR1_RXIE_POS             INT32_C(2)    /** @brief RX interrupt enable. */
  #define I2C1_CR1_ADDRIE_POS           INT32_C(3)    /** @brief Address match interrupt enable (slave only). */
  #define I2C1_CR1_NACKIE_POS           INT32_C(4)    /** @brief Not acknowledge received interrupt enable. */
  #define I2C1_CR1_STOPIE_POS           INT32_C(5)    /** @brief STOP detection interrupt enable. */
  #define I2C1_CR1_TCIE_POS             INT32_C(6)    /** @brief Transfer complete interrupt enable note: any of these events will generate an interrupt: transfer complete (TC) transfer complete reload (TCR). */
  #define I2C1_CR1_ERRIE_POS            INT32_C(7)    /** @brief Error interrupts enable note: any of these errors generate an interrupt: arbitration loss (ARLO) bus error detection (BERR) overrun/underrun (OVR) timeout detection (TIMEOUT) PEC error detection (PECERR) alert pin event detection (ALERT). */
  #define I2C1_CR1_DNF_POS              INT32_C(8)    /** @brief Digital noise filter these bits are used to configure the digital noise filter on SDA and SCL input. The digital filter will filter spikes with a length of up to DNF[3:0] * ti2cclk ... Note: if the analog filter is also enabled, the digital filter is added to the analog filter. This filter can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C1_CR1_ANFOFF_POS           INT32_C(12)   /** @brief Analog noise filter OFF note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C1_CR1_TXDMAEN_POS          INT32_C(14)   /** @brief DMA transmission requests enable. */
  #define I2C1_CR1_RXDMAEN_POS          INT32_C(15)   /** @brief DMA reception requests enable. */
  #define I2C1_CR1_SBC_POS              INT32_C(16)   /** @brief Slave byte control this bit is used to enable hardware byte control in slave mode.. */
  #define I2C1_CR1_NOSTRETCH_POS        INT32_C(17)   /** @brief Clock stretching disable this bit is used to disable clock stretching in slave mode. It must be kept cleared in master mode. Note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C1_CR1_WUPEN_POS            INT32_C(18)   /** @brief Wakeup from stop mode enable note: if the wakeup from stop mode feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation. Note: WUPEN can be set only when DNF = 0000. */
  #define I2C1_CR1_GCEN_POS             INT32_C(19)   /** @brief General call enable. */
  #define I2C1_CR1_SMBHEN_POS           INT32_C(20)   /** @brief SMBus host address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_CR1_SMBDEN_POS           INT32_C(21)   /** @brief SMBus device default address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_CR1_ALERTEN_POS          INT32_C(22)   /** @brief SMBus alert enable device mode (SMBHEN=0): host mode (SMBHEN=1): note: when ALERTEN=0, the SMBA pin can be used as a standard GPIO. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_CR1_PECEN_POS            INT32_C(23)   /** @brief PEC enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_CR2_SADD0_POS            INT32_C(0)    /** @brief Slave address bit 0 (master mode) in 7-bit addressing mode (ADD10 = 0): this bit is dont care in 10-bit addressing mode (ADD10 = 1): this bit should be written with bit 0 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD1_POS            INT32_C(1)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD2_POS            INT32_C(2)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD3_POS            INT32_C(3)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD4_POS            INT32_C(4)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD5_POS            INT32_C(5)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD6_POS            INT32_C(6)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD7_POS            INT32_C(7)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD8_POS            INT32_C(8)    /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_SADD9_POS            INT32_C(9)    /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_RD_WRN_POS           INT32_C(10)   /** @brief Transfer direction (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C1_CR2_ADD10_POS            INT32_C(11)   /** @brief 10-bit addressing mode (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C1_CR2_HEAD10R_POS          INT32_C(12)   /** @brief 10-bit address header only read direction (master receiver mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C1_CR2_START_POS            INT32_C(13)   /** @brief Start generation this bit is set by software, and cleared by hardware after the start followed by the address sequence is sent, by an arbitration loss, by a timeout error detection, or when PE = 0. It can also be cleared by software by writing 1 to the ADDRCF bit in the I2C_ICR register. If the I2C is already in master mode with AUTOEND = 0, setting this bit generates a repeated start condition when RELOAD=0, after the end of the NBYTES transfer. Otherwise setting this bit will generate a START condition once the bus is free. Note: writing 0 to this bit has no effect. The START bit can be set even if the bus is BUSY or I2C is in slave mode. This bit has no effect when RELOAD is set.. */
  #define I2C1_CR2_STOP_POS             INT32_C(14)   /** @brief Stop generation (master mode) the bit is set by software, cleared by hardware when a stop condition is detected, or when PE = 0. In master mode: note: writing 0 to this bit has no effect.. */
  #define I2C1_CR2_NACK_POS             INT32_C(15)   /** @brief NACK generation (slave mode) the bit is set by software, cleared by hardware when the NACK is sent, or when a STOP condition or an address matched is received, or when PE=0. Note: writing 0 to this bit has no effect. This bit is used in slave mode only: in master receiver mode, NACK is automatically generated after last byte preceding STOP or RESTART condition, whatever the NACK bit value. When an overrun occurs in slave receiver NOSTRETCH mode, a NACK is automatically generated whatever the NACK bit value. When hardware PEC checking is enabled (PECBYTE=1), the PEC acknowledge value does not depend on the NACK value.. */
  #define I2C1_CR2_NBYTES_POS           INT32_C(16)   /** @brief Number of bytes the number of bytes to be transmitted/received is programmed there. This field is dont care in slave mode with SBC=0. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C1_CR2_RELOAD_POS           INT32_C(24)   /** @brief NBYTES reload mode this bit is set and cleared by software.. */
  #define I2C1_CR2_AUTOEND_POS          INT32_C(25)   /** @brief Automatic end mode (master mode) this bit is set and cleared by software. Note: this bit has no effect in slave mode or when the RELOAD bit is set.. */
  #define I2C1_CR2_PECBYTE_POS          INT32_C(26)   /** @brief Packet error checking byte this bit is set by software, and cleared by hardware when the PEC is transferred, or when a STOP condition or an address matched is received, also when PE=0. Note: writing 0 to this bit has no effect. This bit has no effect when RELOAD is set. This bit has no effect is slave mode when SBC=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_OAR1_OA1_POS             INT32_C(0)    /** @brief Interface address 7-bit addressing mode: dont care 10-bit addressing mode: bits 9:8 of address note: these bits can be written only when OA1EN=0. OA1[7:1]: interface address bits 7:1 of address note: these bits can be written only when OA1EN=0. OA1[0]: interface address 7-bit addressing mode: dont care 10-bit addressing mode: bit 0 of address note: this bit can be written only when OA1EN=0.. */
  #define I2C1_OAR1_OA1MODE_POS         INT32_C(10)   /** @brief Own address 1 10-bit mode note: this bit can be written only when OA1EN=0.. */
  #define I2C1_OAR1_OA1EN_POS           INT32_C(15)   /** @brief Own address 1 enable. */
  #define I2C1_OAR2_OA2_POS             INT32_C(1)    /** @brief Interface address bits 7:1 of address note: these bits can be written only when OA2EN=0.. */
  #define I2C1_OAR2_OA2MSK_POS          INT32_C(8)    /** @brief Own address 2 masks note: these bits can be written only when OA2EN=0. As soon as OA2MSK is not equal to 0, the reserved I2C addresses (0b0000xxx and 0b1111xxx) are not acknowledged even if the comparison matches.. */
  #define I2C1_OAR2_OA2EN_POS           INT32_C(15)   /** @brief Own address 2 enable. */
  #define I2C1_TIMINGR_SCLL_POS         INT32_C(0)    /** @brief SCL low period (master mode) this field is used to generate the SCL low period in master mode. TSCLL = (SCLL+1) x tpresc note: SCLL is also used to generate tbuf and tsu:sta timings.. */
  #define I2C1_TIMINGR_SCLH_POS         INT32_C(8)    /** @brief SCL high period (master mode) this field is used to generate the SCL high period in master mode. TSCLH = (SCLH+1) x tpresc note: SCLH is also used to generate tsu:sto and thd:sta timing.. */
  #define I2C1_TIMINGR_SDADEL_POS       INT32_C(16)   /** @brief Data hold time this field is used to generate the delay tsdadel between SCL falling edge and SDA edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tsdadel. TSDADEL= SDADEL x tpresc note: SDADEL is used to generate thd:dat timing.. */
  #define I2C1_TIMINGR_SCLDEL_POS       INT32_C(20)   /** @brief Data setup time this field is used to generate a delay tscldel between SDA edge and SCL rising edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tscldel. TSCLDEL = (SCLDEL+1) x tpresc note: tscldel is used to generate tsu:dat timing.. */
  #define I2C1_TIMINGR_PRESC_POS        INT32_C(28)   /** @brief Timing prescaler this field is used to prescale I2CCLK in order to generate the clock period tpresc used for data setup and hold counters (refer to I2C timings on page9) and for SCL high and low level counters (refer to I2C master initialization on page24). TPRESC = (PRESC+1) x ti2cclk. */
  #define I2C1_TIMEOUTR_TIMEOUTA_POS    INT32_C(0)    /** @brief Bus timeout A this field is used to configure: the SCL low timeout condition ttimeout when TIDLE=0 ttimeout= (TIMEOUTA+1) x 2048 x ti2cclk the bus idle condition (both SCL and SDA high) when TIDLE=1 tidle= (TIMEOUTA+1) x 4 x ti2cclk note: these bits can be written only when TIMOUTEN=0.. */
  #define I2C1_TIMEOUTR_TIDLE_POS       INT32_C(12)   /** @brief Idle clock timeout detection note: this bit can be written only when TIMOUTEN=0.. */
  #define I2C1_TIMEOUTR_TIMOUTEN_POS    INT32_C(15)   /** @brief Clock timeout enable. */
  #define I2C1_TIMEOUTR_TIMEOUTB_POS    INT32_C(16)   /** @brief Bus timeout B this field is used to configure the cumulative clock extension timeout: in master mode, the master cumulative clock low extend time (tlow:mext) is detected in slave mode, the slave cumulative clock low extend time (tlow:sext) is detected tlow:ext= (TIMEOUTB+1) x 2048 x ti2cclk note: these bits can be written only when TEXTEN=0.. */
  #define I2C1_TIMEOUTR_TEXTEN_POS      INT32_C(31)   /** @brief Extended clock timeout enable. */
  #define I2C1_ISR_TXE_POS              INT32_C(0)    /** @brief Transmit data register empty (transmitters) this bit is set by hardware when the I2C_TXDR register is empty. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software in order to flush the transmit data register I2C_TXDR. Note: this bit is set by hardware when PE=0.. */
  #define I2C1_ISR_TXIS_POS             INT32_C(1)    /** @brief Transmit interrupt status (transmitters) this bit is set by hardware when the I2C_TXDR register is empty and the data to be transmitted must be written in the I2C_TXDR register. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software when NOSTRETCH=1 only, in order to generate a TXIS event (interrupt if TXIE=1 or DMA request if TXDMAEN=1). Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_RXNE_POS             INT32_C(2)    /** @brief Receive data register not empty (receivers) this bit is set by hardware when the received data is copied into the I2C_RXDR register, and is ready to be read. It is cleared when I2C_RXDR is read. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_ADDR_POS             INT32_C(3)    /** @brief Address matched (slave mode) this bit is set by hardware as soon as the received slave address matched with one of the enabled slave addresses. It is cleared by software by setting ADDRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_NACKF_POS            INT32_C(4)    /** @brief Not acknowledge received flag this flag is set by hardware when a NACK is received after a byte transmission. It is cleared by software by setting the NACKCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_STOPF_POS            INT32_C(5)    /** @brief Stop detection flag this flag is set by hardware when a stop condition is detected on the bus and the peripheral is involved in this transfer: either as a master, provided that the STOP condition is generated by the peripheral. Or as a slave, provided that the peripheral has been addressed previously during this transfer. It is cleared by software by setting the STOPCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_TC_POS               INT32_C(6)    /** @brief Transfer complete (master mode) this flag is set by hardware when RELOAD=0, AUTOEND=0 and NBYTES data have been transferred. It is cleared by software when START bit or STOP bit is set. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_TCR_POS              INT32_C(7)    /** @brief Transfer complete reload this flag is set by hardware when RELOAD=1 and NBYTES data have been transferred. It is cleared by software when NBYTES is written to a non-zero value. Note: this bit is cleared by hardware when PE=0. This flag is only for master mode, or for slave mode when the SBC bit is set.. */
  #define I2C1_ISR_BERR_POS             INT32_C(8)    /** @brief Bus error this flag is set by hardware when a misplaced start or stop condition is detected whereas the peripheral is involved in the transfer. The flag is not set during the address phase in slave mode. It is cleared by software by setting BERRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_ARLO_POS             INT32_C(9)    /** @brief Arbitration lost this flag is set by hardware in case of arbitration loss. It is cleared by software by setting the ARLOCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_OVR_POS              INT32_C(10)   /** @brief Overrun/Underrun (slave mode) this flag is set by hardware in slave mode with NOSTRETCH=1, when an overrun/underrun error occurs. It is cleared by software by setting the OVRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C1_ISR_PECERR_POS           INT32_C(11)   /** @brief PEC error in reception this flag is set by hardware when the received PEC does not match with the PEC register content. A NACK is automatically sent after the wrong PEC reception. It is cleared by software by setting the PECCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_ISR_TIMEOUT_POS          INT32_C(12)   /** @brief Timeout or tlow detection flag this flag is set by hardware when a timeout or extended clock timeout occurred. It is cleared by software by setting the TIMEOUTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_ISR_ALERT_POS            INT32_C(13)   /** @brief SMBus alert this flag is set by hardware when SMBHEN=1 (smbus host configuration), ALERTEN=1 and a SMBALERT event (falling edge) is detected on SMBA pin. It is cleared by software by setting the ALERTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_ISR_BUSY_POS             INT32_C(15)   /** @brief Bus busy this flag indicates that a communication is in progress on the bus. It is set by hardware when a START condition is detected. It is cleared by hardware when a stop condition is detected, or when PE=0.. */
  #define I2C1_ISR_DIR_POS              INT32_C(16)   /** @brief Transfer direction (slave mode) this flag is updated when an address match event occurs (ADDR=1).. */
  #define I2C1_ISR_ADDCODE_POS          INT32_C(17)   /** @brief Address match code (slave mode) these bits are updated with the received address when an address match event occurs (ADDR = 1). In the case of a 10-bit address, ADDCODE provides the 10-bit header followed by the 2 msbs of the address.. */
  #define I2C1_ICR_ADDRCF_POS           INT32_C(3)    /** @brief Address matched flag clear writing 1 to this bit clears the ADDR flag in the I2C_ISR register. Writing 1 to this bit also clears the START bit in the I2C_CR2 register.. */
  #define I2C1_ICR_NACKCF_POS           INT32_C(4)    /** @brief Not acknowledge flag clear writing 1 to this bit clears the ACKF flag in I2C_ISR register.. */
  #define I2C1_ICR_STOPCF_POS           INT32_C(5)    /** @brief Stop detection flag clear writing 1 to this bit clears the STOPF flag in the I2C_ISR register.. */
  #define I2C1_ICR_BERRCF_POS           INT32_C(8)    /** @brief Bus error flag clear writing 1 to this bit clears the BERRF flag in the I2C_ISR register.. */
  #define I2C1_ICR_ARLOCF_POS           INT32_C(9)    /** @brief Arbitration lost flag clear writing 1 to this bit clears the ARLO flag in the I2C_ISR register.. */
  #define I2C1_ICR_OVRCF_POS            INT32_C(10)   /** @brief Overrun/Underrun flag clear writing 1 to this bit clears the OVR flag in the I2C_ISR register.. */
  #define I2C1_ICR_PECCF_POS            INT32_C(11)   /** @brief PEC error flag clear writing 1 to this bit clears the PECERR flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_ICR_TIMOUTCF_POS         INT32_C(12)   /** @brief Timeout detection flag clear writing 1 to this bit clears the TIMEOUT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_ICR_ALERTCF_POS          INT32_C(13)   /** @brief Alert flag clear writing 1 to this bit clears the ALERT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C1_PECR_PEC_POS             INT32_C(0)    /** @brief Packet error checking register this field contains the internal PEC when PECEN=1. The PEC is cleared by hardware when PE=0.. */
  #define I2C1_RXDR_RXDATA_POS          INT32_C(0)    /** @brief 8-bit receive data data byte received from the I2C bus.. */
  #define I2C1_TXDR_TXDATA_POS          INT32_C(0)    /** @brief 8-bit transmit data data byte to be transmitted to the I2C bus. Note: these bits can be written only when TXE=1.. */

  /*************************************************************************************************
   * @section I2C2 Definitions
   *************************************************************************************************/

  /**** @subsection Register Definitions ****/

  #define I2C2_CR1_PTR        (*(RW_ uint32_t*)UINT32_C(0x40005800))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C2_CR2_PTR        (*(RW_ uint32_t*)UINT32_C(0x40005804))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C2_OAR1_PTR       (*(RW_ uint32_t*)UINT32_C(0x40005808))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C2_OAR2_PTR       (*(RW_ uint32_t*)UINT32_C(0x4000580C))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C2_TIMINGR_PTR    (*(RW_ uint32_t*)UINT32_C(0x40005810))   /** @brief Access: no wait states. */
  #define I2C2_TIMEOUTR_PTR   (*(RW_ uint32_t*)UINT32_C(0x40005814))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C2_ISR_PTR        (*(RW_ uint32_t*)UINT32_C(0x40005818))   /** @brief Access: no wait states. */
  #define I2C2_ICR_PTR        (*(WO_ uint32_t*)UINT32_C(0x4000581C))   /** @brief Access: no wait states. */
  #define I2C2_PECR_PTR       (*(RO_ uint32_t*)UINT32_C(0x40005820))   /** @brief Access: no wait states. */
  #define I2C2_RXDR_PTR       (*(RO_ uint32_t*)UINT32_C(0x40005824))   /** @brief Access: no wait states. */
  #define I2C2_TXDR_PTR       (*(RW_ uint32_t*)UINT32_C(0x40005828))   /** @brief Access: no wait states. */

  /**** @subsection Field Mask Definitions ****/

  #define I2C2_CR1_PE_MSK               UINT32_C(0x00000001)   /** @brief Peripheral enable note: when PE=0, the I2C SCL and SDA lines are released. Internal state machines and status bits are put back to their reset value. When cleared, PE must be kept low for at least 3 APB clock cycles.. */
  #define I2C2_CR1_TXIE_MSK             UINT32_C(0x00000002)   /** @brief TX interrupt enable. */
  #define I2C2_CR1_RXIE_MSK             UINT32_C(0x00000004)   /** @brief RX interrupt enable. */
  #define I2C2_CR1_ADDRIE_MSK           UINT32_C(0x00000008)   /** @brief Address match interrupt enable (slave only). */
  #define I2C2_CR1_NACKIE_MSK           UINT32_C(0x00000010)   /** @brief Not acknowledge received interrupt enable. */
  #define I2C2_CR1_STOPIE_MSK           UINT32_C(0x00000020)   /** @brief STOP detection interrupt enable. */
  #define I2C2_CR1_TCIE_MSK             UINT32_C(0x00000040)   /** @brief Transfer complete interrupt enable note: any of these events will generate an interrupt: transfer complete (TC) transfer complete reload (TCR). */
  #define I2C2_CR1_ERRIE_MSK            UINT32_C(0x00000080)   /** @brief Error interrupts enable note: any of these errors generate an interrupt: arbitration loss (ARLO) bus error detection (BERR) overrun/underrun (OVR) timeout detection (TIMEOUT) PEC error detection (PECERR) alert pin event detection (ALERT). */
  #define I2C2_CR1_DNF_MSK              UINT32_C(0x00000F00)   /** @brief Digital noise filter these bits are used to configure the digital noise filter on SDA and SCL input. The digital filter will filter spikes with a length of up to DNF[3:0] * ti2cclk ... Note: if the analog filter is also enabled, the digital filter is added to the analog filter. This filter can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C2_CR1_ANFOFF_MSK           UINT32_C(0x00001000)   /** @brief Analog noise filter OFF note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C2_CR1_TXDMAEN_MSK          UINT32_C(0x00004000)   /** @brief DMA transmission requests enable. */
  #define I2C2_CR1_RXDMAEN_MSK          UINT32_C(0x00008000)   /** @brief DMA reception requests enable. */
  #define I2C2_CR1_SBC_MSK              UINT32_C(0x00010000)   /** @brief Slave byte control this bit is used to enable hardware byte control in slave mode.. */
  #define I2C2_CR1_NOSTRETCH_MSK        UINT32_C(0x00020000)   /** @brief Clock stretching disable this bit is used to disable clock stretching in slave mode. It must be kept cleared in master mode. Note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C2_CR1_WUPEN_MSK            UINT32_C(0x00040000)   /** @brief Wakeup from stop mode enable note: if the wakeup from stop mode feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation. Note: WUPEN can be set only when DNF = 0000. */
  #define I2C2_CR1_GCEN_MSK             UINT32_C(0x00080000)   /** @brief General call enable. */
  #define I2C2_CR1_SMBHEN_MSK           UINT32_C(0x00100000)   /** @brief SMBus host address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_CR1_SMBDEN_MSK           UINT32_C(0x00200000)   /** @brief SMBus device default address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_CR1_ALERTEN_MSK          UINT32_C(0x00400000)   /** @brief SMBus alert enable device mode (SMBHEN=0): host mode (SMBHEN=1): note: when ALERTEN=0, the SMBA pin can be used as a standard GPIO. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_CR1_PECEN_MSK            UINT32_C(0x00800000)   /** @brief PEC enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_CR2_SADD0_MSK            UINT32_C(0x00000001)   /** @brief Slave address bit 0 (master mode) in 7-bit addressing mode (ADD10 = 0): this bit is dont care in 10-bit addressing mode (ADD10 = 1): this bit should be written with bit 0 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD1_MSK            UINT32_C(0x00000002)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD2_MSK            UINT32_C(0x00000004)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD3_MSK            UINT32_C(0x00000008)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD4_MSK            UINT32_C(0x00000010)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD5_MSK            UINT32_C(0x00000020)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD6_MSK            UINT32_C(0x00000040)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD7_MSK            UINT32_C(0x00000080)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD8_MSK            UINT32_C(0x00000100)   /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD9_MSK            UINT32_C(0x00000200)   /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_RD_WRN_MSK           UINT32_C(0x00000400)   /** @brief Transfer direction (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C2_CR2_ADD10_MSK            UINT32_C(0x00000800)   /** @brief 10-bit addressing mode (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C2_CR2_HEAD10R_MSK          UINT32_C(0x00001000)   /** @brief 10-bit address header only read direction (master receiver mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C2_CR2_START_MSK            UINT32_C(0x00002000)   /** @brief Start generation this bit is set by software, and cleared by hardware after the start followed by the address sequence is sent, by an arbitration loss, by a timeout error detection, or when PE = 0. It can also be cleared by software by writing 1 to the ADDRCF bit in the I2C_ICR register. If the I2C is already in master mode with AUTOEND = 0, setting this bit generates a repeated start condition when RELOAD=0, after the end of the NBYTES transfer. Otherwise setting this bit will generate a START condition once the bus is free. Note: writing 0 to this bit has no effect. The START bit can be set even if the bus is BUSY or I2C is in slave mode. This bit has no effect when RELOAD is set.. */
  #define I2C2_CR2_STOP_MSK             UINT32_C(0x00004000)   /** @brief Stop generation (master mode) the bit is set by software, cleared by hardware when a stop condition is detected, or when PE = 0. In master mode: note: writing 0 to this bit has no effect.. */
  #define I2C2_CR2_NACK_MSK             UINT32_C(0x00008000)   /** @brief NACK generation (slave mode) the bit is set by software, cleared by hardware when the NACK is sent, or when a STOP condition or an address matched is received, or when PE=0. Note: writing 0 to this bit has no effect. This bit is used in slave mode only: in master receiver mode, NACK is automatically generated after last byte preceding STOP or RESTART condition, whatever the NACK bit value. When an overrun occurs in slave receiver NOSTRETCH mode, a NACK is automatically generated whatever the NACK bit value. When hardware PEC checking is enabled (PECBYTE=1), the PEC acknowledge value does not depend on the NACK value.. */
  #define I2C2_CR2_NBYTES_MSK           UINT32_C(0x00FF0000)   /** @brief Number of bytes the number of bytes to be transmitted/received is programmed there. This field is dont care in slave mode with SBC=0. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_RELOAD_MSK           UINT32_C(0x01000000)   /** @brief NBYTES reload mode this bit is set and cleared by software.. */
  #define I2C2_CR2_AUTOEND_MSK          UINT32_C(0x02000000)   /** @brief Automatic end mode (master mode) this bit is set and cleared by software. Note: this bit has no effect in slave mode or when the RELOAD bit is set.. */
  #define I2C2_CR2_PECBYTE_MSK          UINT32_C(0x04000000)   /** @brief Packet error checking byte this bit is set by software, and cleared by hardware when the PEC is transferred, or when a STOP condition or an address matched is received, also when PE=0. Note: writing 0 to this bit has no effect. This bit has no effect when RELOAD is set. This bit has no effect is slave mode when SBC=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_OAR1_OA1_MSK             UINT32_C(0x000003FF)   /** @brief Interface address 7-bit addressing mode: dont care 10-bit addressing mode: bits 9:8 of address note: these bits can be written only when OA1EN=0. OA1[7:1]: interface address bits 7:1 of address note: these bits can be written only when OA1EN=0. OA1[0]: interface address 7-bit addressing mode: dont care 10-bit addressing mode: bit 0 of address note: this bit can be written only when OA1EN=0.. */
  #define I2C2_OAR1_OA1MODE_MSK         UINT32_C(0x00000400)   /** @brief Own address 1 10-bit mode note: this bit can be written only when OA1EN=0.. */
  #define I2C2_OAR1_OA1EN_MSK           UINT32_C(0x00008000)   /** @brief Own address 1 enable. */
  #define I2C2_OAR2_OA2_MSK             UINT32_C(0x000000FE)   /** @brief Interface address bits 7:1 of address note: these bits can be written only when OA2EN=0.. */
  #define I2C2_OAR2_OA2MSK_MSK          UINT32_C(0x00000700)   /** @brief Own address 2 masks note: these bits can be written only when OA2EN=0. As soon as OA2MSK is not equal to 0, the reserved I2C addresses (0b0000xxx and 0b1111xxx) are not acknowledged even if the comparison matches.. */
  #define I2C2_OAR2_OA2EN_MSK           UINT32_C(0x00008000)   /** @brief Own address 2 enable. */
  #define I2C2_TIMINGR_SCLL_MSK         UINT32_C(0x000000FF)   /** @brief SCL low period (master mode) this field is used to generate the SCL low period in master mode. TSCLL = (SCLL+1) x tpresc note: SCLL is also used to generate tbuf and tsu:sta timings.. */
  #define I2C2_TIMINGR_SCLH_MSK         UINT32_C(0x0000FF00)   /** @brief SCL high period (master mode) this field is used to generate the SCL high period in master mode. TSCLH = (SCLH+1) x tpresc note: SCLH is also used to generate tsu:sto and thd:sta timing.. */
  #define I2C2_TIMINGR_SDADEL_MSK       UINT32_C(0x000F0000)   /** @brief Data hold time this field is used to generate the delay tsdadel between SCL falling edge and SDA edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tsdadel. TSDADEL= SDADEL x tpresc note: SDADEL is used to generate thd:dat timing.. */
  #define I2C2_TIMINGR_SCLDEL_MSK       UINT32_C(0x00F00000)   /** @brief Data setup time this field is used to generate a delay tscldel between SDA edge and SCL rising edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tscldel. TSCLDEL = (SCLDEL+1) x tpresc note: tscldel is used to generate tsu:dat timing.. */
  #define I2C2_TIMINGR_PRESC_MSK        UINT32_C(0xF0000000)   /** @brief Timing prescaler this field is used to prescale I2CCLK in order to generate the clock period tpresc used for data setup and hold counters (refer to I2C timings on page9) and for SCL high and low level counters (refer to I2C master initialization on page24). TPRESC = (PRESC+1) x ti2cclk. */
  #define I2C2_TIMEOUTR_TIMEOUTA_MSK    UINT32_C(0x00000FFF)   /** @brief Bus timeout A this field is used to configure: the SCL low timeout condition ttimeout when TIDLE=0 ttimeout= (TIMEOUTA+1) x 2048 x ti2cclk the bus idle condition (both SCL and SDA high) when TIDLE=1 tidle= (TIMEOUTA+1) x 4 x ti2cclk note: these bits can be written only when TIMOUTEN=0.. */
  #define I2C2_TIMEOUTR_TIDLE_MSK       UINT32_C(0x00001000)   /** @brief Idle clock timeout detection note: this bit can be written only when TIMOUTEN=0.. */
  #define I2C2_TIMEOUTR_TIMOUTEN_MSK    UINT32_C(0x00008000)   /** @brief Clock timeout enable. */
  #define I2C2_TIMEOUTR_TIMEOUTB_MSK    UINT32_C(0x0FFF0000)   /** @brief Bus timeout B this field is used to configure the cumulative clock extension timeout: in master mode, the master cumulative clock low extend time (tlow:mext) is detected in slave mode, the slave cumulative clock low extend time (tlow:sext) is detected tlow:ext= (TIMEOUTB+1) x 2048 x ti2cclk note: these bits can be written only when TEXTEN=0.. */
  #define I2C2_TIMEOUTR_TEXTEN_MSK      UINT32_C(0x80000000)   /** @brief Extended clock timeout enable. */
  #define I2C2_ISR_TXE_MSK              UINT32_C(0x00000001)   /** @brief Transmit data register empty (transmitters) this bit is set by hardware when the I2C_TXDR register is empty. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software in order to flush the transmit data register I2C_TXDR. Note: this bit is set by hardware when PE=0.. */
  #define I2C2_ISR_TXIS_MSK             UINT32_C(0x00000002)   /** @brief Transmit interrupt status (transmitters) this bit is set by hardware when the I2C_TXDR register is empty and the data to be transmitted must be written in the I2C_TXDR register. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software when NOSTRETCH=1 only, in order to generate a TXIS event (interrupt if TXIE=1 or DMA request if TXDMAEN=1). Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_RXNE_MSK             UINT32_C(0x00000004)   /** @brief Receive data register not empty (receivers) this bit is set by hardware when the received data is copied into the I2C_RXDR register, and is ready to be read. It is cleared when I2C_RXDR is read. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_ADDR_MSK             UINT32_C(0x00000008)   /** @brief Address matched (slave mode) this bit is set by hardware as soon as the received slave address matched with one of the enabled slave addresses. It is cleared by software by setting ADDRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_NACKF_MSK            UINT32_C(0x00000010)   /** @brief Not acknowledge received flag this flag is set by hardware when a NACK is received after a byte transmission. It is cleared by software by setting the NACKCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_STOPF_MSK            UINT32_C(0x00000020)   /** @brief Stop detection flag this flag is set by hardware when a stop condition is detected on the bus and the peripheral is involved in this transfer: either as a master, provided that the STOP condition is generated by the peripheral. Or as a slave, provided that the peripheral has been addressed previously during this transfer. It is cleared by software by setting the STOPCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_TC_MSK               UINT32_C(0x00000040)   /** @brief Transfer complete (master mode) this flag is set by hardware when RELOAD=0, AUTOEND=0 and NBYTES data have been transferred. It is cleared by software when START bit or STOP bit is set. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_TCR_MSK              UINT32_C(0x00000080)   /** @brief Transfer complete reload this flag is set by hardware when RELOAD=1 and NBYTES data have been transferred. It is cleared by software when NBYTES is written to a non-zero value. Note: this bit is cleared by hardware when PE=0. This flag is only for master mode, or for slave mode when the SBC bit is set.. */
  #define I2C2_ISR_BERR_MSK             UINT32_C(0x00000100)   /** @brief Bus error this flag is set by hardware when a misplaced start or stop condition is detected whereas the peripheral is involved in the transfer. The flag is not set during the address phase in slave mode. It is cleared by software by setting BERRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_ARLO_MSK             UINT32_C(0x00000200)   /** @brief Arbitration lost this flag is set by hardware in case of arbitration loss. It is cleared by software by setting the ARLOCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_OVR_MSK              UINT32_C(0x00000400)   /** @brief Overrun/Underrun (slave mode) this flag is set by hardware in slave mode with NOSTRETCH=1, when an overrun/underrun error occurs. It is cleared by software by setting the OVRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_PECERR_MSK           UINT32_C(0x00000800)   /** @brief PEC error in reception this flag is set by hardware when the received PEC does not match with the PEC register content. A NACK is automatically sent after the wrong PEC reception. It is cleared by software by setting the PECCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_ISR_TIMEOUT_MSK          UINT32_C(0x00001000)   /** @brief Timeout or tlow detection flag this flag is set by hardware when a timeout or extended clock timeout occurred. It is cleared by software by setting the TIMEOUTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_ISR_ALERT_MSK            UINT32_C(0x00002000)   /** @brief SMBus alert this flag is set by hardware when SMBHEN=1 (smbus host configuration), ALERTEN=1 and a SMBALERT event (falling edge) is detected on SMBA pin. It is cleared by software by setting the ALERTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_ISR_BUSY_MSK             UINT32_C(0x00008000)   /** @brief Bus busy this flag indicates that a communication is in progress on the bus. It is set by hardware when a START condition is detected. It is cleared by hardware when a stop condition is detected, or when PE=0.. */
  #define I2C2_ISR_DIR_MSK              UINT32_C(0x00010000)   /** @brief Transfer direction (slave mode) this flag is updated when an address match event occurs (ADDR=1).. */
  #define I2C2_ISR_ADDCODE_MSK          UINT32_C(0x00FE0000)   /** @brief Address match code (slave mode) these bits are updated with the received address when an address match event occurs (ADDR = 1). In the case of a 10-bit address, ADDCODE provides the 10-bit header followed by the 2 msbs of the address.. */
  #define I2C2_ICR_ADDRCF_MSK           UINT32_C(0x00000008)   /** @brief Address matched flag clear writing 1 to this bit clears the ADDR flag in the I2C_ISR register. Writing 1 to this bit also clears the START bit in the I2C_CR2 register.. */
  #define I2C2_ICR_NACKCF_MSK           UINT32_C(0x00000010)   /** @brief Not acknowledge flag clear writing 1 to this bit clears the ACKF flag in I2C_ISR register.. */
  #define I2C2_ICR_STOPCF_MSK           UINT32_C(0x00000020)   /** @brief Stop detection flag clear writing 1 to this bit clears the STOPF flag in the I2C_ISR register.. */
  #define I2C2_ICR_BERRCF_MSK           UINT32_C(0x00000100)   /** @brief Bus error flag clear writing 1 to this bit clears the BERRF flag in the I2C_ISR register.. */
  #define I2C2_ICR_ARLOCF_MSK           UINT32_C(0x00000200)   /** @brief Arbitration lost flag clear writing 1 to this bit clears the ARLO flag in the I2C_ISR register.. */
  #define I2C2_ICR_OVRCF_MSK            UINT32_C(0x00000400)   /** @brief Overrun/Underrun flag clear writing 1 to this bit clears the OVR flag in the I2C_ISR register.. */
  #define I2C2_ICR_PECCF_MSK            UINT32_C(0x00000800)   /** @brief PEC error flag clear writing 1 to this bit clears the PECERR flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_ICR_TIMOUTCF_MSK         UINT32_C(0x00001000)   /** @brief Timeout detection flag clear writing 1 to this bit clears the TIMEOUT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_ICR_ALERTCF_MSK          UINT32_C(0x00002000)   /** @brief Alert flag clear writing 1 to this bit clears the ALERT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_PECR_PEC_MSK             UINT32_C(0x000000FF)   /** @brief Packet error checking register this field contains the internal PEC when PECEN=1. The PEC is cleared by hardware when PE=0.. */
  #define I2C2_RXDR_RXDATA_MSK          UINT32_C(0x000000FF)   /** @brief 8-bit receive data data byte received from the I2C bus.. */
  #define I2C2_TXDR_TXDATA_MSK          UINT32_C(0x000000FF)   /** @brief 8-bit transmit data data byte to be transmitted to the I2C bus. Note: these bits can be written only when TXE=1.. */

  /**** @subsection Field Position Definitions ****/

  #define I2C2_CR1_PE_POS               INT32_C(0)    /** @brief Peripheral enable note: when PE=0, the I2C SCL and SDA lines are released. Internal state machines and status bits are put back to their reset value. When cleared, PE must be kept low for at least 3 APB clock cycles.. */
  #define I2C2_CR1_TXIE_POS             INT32_C(1)    /** @brief TX interrupt enable. */
  #define I2C2_CR1_RXIE_POS             INT32_C(2)    /** @brief RX interrupt enable. */
  #define I2C2_CR1_ADDRIE_POS           INT32_C(3)    /** @brief Address match interrupt enable (slave only). */
  #define I2C2_CR1_NACKIE_POS           INT32_C(4)    /** @brief Not acknowledge received interrupt enable. */
  #define I2C2_CR1_STOPIE_POS           INT32_C(5)    /** @brief STOP detection interrupt enable. */
  #define I2C2_CR1_TCIE_POS             INT32_C(6)    /** @brief Transfer complete interrupt enable note: any of these events will generate an interrupt: transfer complete (TC) transfer complete reload (TCR). */
  #define I2C2_CR1_ERRIE_POS            INT32_C(7)    /** @brief Error interrupts enable note: any of these errors generate an interrupt: arbitration loss (ARLO) bus error detection (BERR) overrun/underrun (OVR) timeout detection (TIMEOUT) PEC error detection (PECERR) alert pin event detection (ALERT). */
  #define I2C2_CR1_DNF_POS              INT32_C(8)    /** @brief Digital noise filter these bits are used to configure the digital noise filter on SDA and SCL input. The digital filter will filter spikes with a length of up to DNF[3:0] * ti2cclk ... Note: if the analog filter is also enabled, the digital filter is added to the analog filter. This filter can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C2_CR1_ANFOFF_POS           INT32_C(12)   /** @brief Analog noise filter OFF note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C2_CR1_TXDMAEN_POS          INT32_C(14)   /** @brief DMA transmission requests enable. */
  #define I2C2_CR1_RXDMAEN_POS          INT32_C(15)   /** @brief DMA reception requests enable. */
  #define I2C2_CR1_SBC_POS              INT32_C(16)   /** @brief Slave byte control this bit is used to enable hardware byte control in slave mode.. */
  #define I2C2_CR1_NOSTRETCH_POS        INT32_C(17)   /** @brief Clock stretching disable this bit is used to disable clock stretching in slave mode. It must be kept cleared in master mode. Note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C2_CR1_WUPEN_POS            INT32_C(18)   /** @brief Wakeup from stop mode enable note: if the wakeup from stop mode feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation. Note: WUPEN can be set only when DNF = 0000. */
  #define I2C2_CR1_GCEN_POS             INT32_C(19)   /** @brief General call enable. */
  #define I2C2_CR1_SMBHEN_POS           INT32_C(20)   /** @brief SMBus host address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_CR1_SMBDEN_POS           INT32_C(21)   /** @brief SMBus device default address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_CR1_ALERTEN_POS          INT32_C(22)   /** @brief SMBus alert enable device mode (SMBHEN=0): host mode (SMBHEN=1): note: when ALERTEN=0, the SMBA pin can be used as a standard GPIO. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_CR1_PECEN_POS            INT32_C(23)   /** @brief PEC enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_CR2_SADD0_POS            INT32_C(0)    /** @brief Slave address bit 0 (master mode) in 7-bit addressing mode (ADD10 = 0): this bit is dont care in 10-bit addressing mode (ADD10 = 1): this bit should be written with bit 0 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD1_POS            INT32_C(1)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD2_POS            INT32_C(2)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD3_POS            INT32_C(3)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD4_POS            INT32_C(4)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD5_POS            INT32_C(5)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD6_POS            INT32_C(6)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD7_POS            INT32_C(7)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD8_POS            INT32_C(8)    /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_SADD9_POS            INT32_C(9)    /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_RD_WRN_POS           INT32_C(10)   /** @brief Transfer direction (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C2_CR2_ADD10_POS            INT32_C(11)   /** @brief 10-bit addressing mode (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C2_CR2_HEAD10R_POS          INT32_C(12)   /** @brief 10-bit address header only read direction (master receiver mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C2_CR2_START_POS            INT32_C(13)   /** @brief Start generation this bit is set by software, and cleared by hardware after the start followed by the address sequence is sent, by an arbitration loss, by a timeout error detection, or when PE = 0. It can also be cleared by software by writing 1 to the ADDRCF bit in the I2C_ICR register. If the I2C is already in master mode with AUTOEND = 0, setting this bit generates a repeated start condition when RELOAD=0, after the end of the NBYTES transfer. Otherwise setting this bit will generate a START condition once the bus is free. Note: writing 0 to this bit has no effect. The START bit can be set even if the bus is BUSY or I2C is in slave mode. This bit has no effect when RELOAD is set.. */
  #define I2C2_CR2_STOP_POS             INT32_C(14)   /** @brief Stop generation (master mode) the bit is set by software, cleared by hardware when a stop condition is detected, or when PE = 0. In master mode: note: writing 0 to this bit has no effect.. */
  #define I2C2_CR2_NACK_POS             INT32_C(15)   /** @brief NACK generation (slave mode) the bit is set by software, cleared by hardware when the NACK is sent, or when a STOP condition or an address matched is received, or when PE=0. Note: writing 0 to this bit has no effect. This bit is used in slave mode only: in master receiver mode, NACK is automatically generated after last byte preceding STOP or RESTART condition, whatever the NACK bit value. When an overrun occurs in slave receiver NOSTRETCH mode, a NACK is automatically generated whatever the NACK bit value. When hardware PEC checking is enabled (PECBYTE=1), the PEC acknowledge value does not depend on the NACK value.. */
  #define I2C2_CR2_NBYTES_POS           INT32_C(16)   /** @brief Number of bytes the number of bytes to be transmitted/received is programmed there. This field is dont care in slave mode with SBC=0. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C2_CR2_RELOAD_POS           INT32_C(24)   /** @brief NBYTES reload mode this bit is set and cleared by software.. */
  #define I2C2_CR2_AUTOEND_POS          INT32_C(25)   /** @brief Automatic end mode (master mode) this bit is set and cleared by software. Note: this bit has no effect in slave mode or when the RELOAD bit is set.. */
  #define I2C2_CR2_PECBYTE_POS          INT32_C(26)   /** @brief Packet error checking byte this bit is set by software, and cleared by hardware when the PEC is transferred, or when a STOP condition or an address matched is received, also when PE=0. Note: writing 0 to this bit has no effect. This bit has no effect when RELOAD is set. This bit has no effect is slave mode when SBC=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_OAR1_OA1_POS             INT32_C(0)    /** @brief Interface address 7-bit addressing mode: dont care 10-bit addressing mode: bits 9:8 of address note: these bits can be written only when OA1EN=0. OA1[7:1]: interface address bits 7:1 of address note: these bits can be written only when OA1EN=0. OA1[0]: interface address 7-bit addressing mode: dont care 10-bit addressing mode: bit 0 of address note: this bit can be written only when OA1EN=0.. */
  #define I2C2_OAR1_OA1MODE_POS         INT32_C(10)   /** @brief Own address 1 10-bit mode note: this bit can be written only when OA1EN=0.. */
  #define I2C2_OAR1_OA1EN_POS           INT32_C(15)   /** @brief Own address 1 enable. */
  #define I2C2_OAR2_OA2_POS             INT32_C(1)    /** @brief Interface address bits 7:1 of address note: these bits can be written only when OA2EN=0.. */
  #define I2C2_OAR2_OA2MSK_POS          INT32_C(8)    /** @brief Own address 2 masks note: these bits can be written only when OA2EN=0. As soon as OA2MSK is not equal to 0, the reserved I2C addresses (0b0000xxx and 0b1111xxx) are not acknowledged even if the comparison matches.. */
  #define I2C2_OAR2_OA2EN_POS           INT32_C(15)   /** @brief Own address 2 enable. */
  #define I2C2_TIMINGR_SCLL_POS         INT32_C(0)    /** @brief SCL low period (master mode) this field is used to generate the SCL low period in master mode. TSCLL = (SCLL+1) x tpresc note: SCLL is also used to generate tbuf and tsu:sta timings.. */
  #define I2C2_TIMINGR_SCLH_POS         INT32_C(8)    /** @brief SCL high period (master mode) this field is used to generate the SCL high period in master mode. TSCLH = (SCLH+1) x tpresc note: SCLH is also used to generate tsu:sto and thd:sta timing.. */
  #define I2C2_TIMINGR_SDADEL_POS       INT32_C(16)   /** @brief Data hold time this field is used to generate the delay tsdadel between SCL falling edge and SDA edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tsdadel. TSDADEL= SDADEL x tpresc note: SDADEL is used to generate thd:dat timing.. */
  #define I2C2_TIMINGR_SCLDEL_POS       INT32_C(20)   /** @brief Data setup time this field is used to generate a delay tscldel between SDA edge and SCL rising edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tscldel. TSCLDEL = (SCLDEL+1) x tpresc note: tscldel is used to generate tsu:dat timing.. */
  #define I2C2_TIMINGR_PRESC_POS        INT32_C(28)   /** @brief Timing prescaler this field is used to prescale I2CCLK in order to generate the clock period tpresc used for data setup and hold counters (refer to I2C timings on page9) and for SCL high and low level counters (refer to I2C master initialization on page24). TPRESC = (PRESC+1) x ti2cclk. */
  #define I2C2_TIMEOUTR_TIMEOUTA_POS    INT32_C(0)    /** @brief Bus timeout A this field is used to configure: the SCL low timeout condition ttimeout when TIDLE=0 ttimeout= (TIMEOUTA+1) x 2048 x ti2cclk the bus idle condition (both SCL and SDA high) when TIDLE=1 tidle= (TIMEOUTA+1) x 4 x ti2cclk note: these bits can be written only when TIMOUTEN=0.. */
  #define I2C2_TIMEOUTR_TIDLE_POS       INT32_C(12)   /** @brief Idle clock timeout detection note: this bit can be written only when TIMOUTEN=0.. */
  #define I2C2_TIMEOUTR_TIMOUTEN_POS    INT32_C(15)   /** @brief Clock timeout enable. */
  #define I2C2_TIMEOUTR_TIMEOUTB_POS    INT32_C(16)   /** @brief Bus timeout B this field is used to configure the cumulative clock extension timeout: in master mode, the master cumulative clock low extend time (tlow:mext) is detected in slave mode, the slave cumulative clock low extend time (tlow:sext) is detected tlow:ext= (TIMEOUTB+1) x 2048 x ti2cclk note: these bits can be written only when TEXTEN=0.. */
  #define I2C2_TIMEOUTR_TEXTEN_POS      INT32_C(31)   /** @brief Extended clock timeout enable. */
  #define I2C2_ISR_TXE_POS              INT32_C(0)    /** @brief Transmit data register empty (transmitters) this bit is set by hardware when the I2C_TXDR register is empty. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software in order to flush the transmit data register I2C_TXDR. Note: this bit is set by hardware when PE=0.. */
  #define I2C2_ISR_TXIS_POS             INT32_C(1)    /** @brief Transmit interrupt status (transmitters) this bit is set by hardware when the I2C_TXDR register is empty and the data to be transmitted must be written in the I2C_TXDR register. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software when NOSTRETCH=1 only, in order to generate a TXIS event (interrupt if TXIE=1 or DMA request if TXDMAEN=1). Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_RXNE_POS             INT32_C(2)    /** @brief Receive data register not empty (receivers) this bit is set by hardware when the received data is copied into the I2C_RXDR register, and is ready to be read. It is cleared when I2C_RXDR is read. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_ADDR_POS             INT32_C(3)    /** @brief Address matched (slave mode) this bit is set by hardware as soon as the received slave address matched with one of the enabled slave addresses. It is cleared by software by setting ADDRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_NACKF_POS            INT32_C(4)    /** @brief Not acknowledge received flag this flag is set by hardware when a NACK is received after a byte transmission. It is cleared by software by setting the NACKCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_STOPF_POS            INT32_C(5)    /** @brief Stop detection flag this flag is set by hardware when a stop condition is detected on the bus and the peripheral is involved in this transfer: either as a master, provided that the STOP condition is generated by the peripheral. Or as a slave, provided that the peripheral has been addressed previously during this transfer. It is cleared by software by setting the STOPCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_TC_POS               INT32_C(6)    /** @brief Transfer complete (master mode) this flag is set by hardware when RELOAD=0, AUTOEND=0 and NBYTES data have been transferred. It is cleared by software when START bit or STOP bit is set. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_TCR_POS              INT32_C(7)    /** @brief Transfer complete reload this flag is set by hardware when RELOAD=1 and NBYTES data have been transferred. It is cleared by software when NBYTES is written to a non-zero value. Note: this bit is cleared by hardware when PE=0. This flag is only for master mode, or for slave mode when the SBC bit is set.. */
  #define I2C2_ISR_BERR_POS             INT32_C(8)    /** @brief Bus error this flag is set by hardware when a misplaced start or stop condition is detected whereas the peripheral is involved in the transfer. The flag is not set during the address phase in slave mode. It is cleared by software by setting BERRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_ARLO_POS             INT32_C(9)    /** @brief Arbitration lost this flag is set by hardware in case of arbitration loss. It is cleared by software by setting the ARLOCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_OVR_POS              INT32_C(10)   /** @brief Overrun/Underrun (slave mode) this flag is set by hardware in slave mode with NOSTRETCH=1, when an overrun/underrun error occurs. It is cleared by software by setting the OVRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C2_ISR_PECERR_POS           INT32_C(11)   /** @brief PEC error in reception this flag is set by hardware when the received PEC does not match with the PEC register content. A NACK is automatically sent after the wrong PEC reception. It is cleared by software by setting the PECCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_ISR_TIMEOUT_POS          INT32_C(12)   /** @brief Timeout or tlow detection flag this flag is set by hardware when a timeout or extended clock timeout occurred. It is cleared by software by setting the TIMEOUTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_ISR_ALERT_POS            INT32_C(13)   /** @brief SMBus alert this flag is set by hardware when SMBHEN=1 (smbus host configuration), ALERTEN=1 and a SMBALERT event (falling edge) is detected on SMBA pin. It is cleared by software by setting the ALERTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_ISR_BUSY_POS             INT32_C(15)   /** @brief Bus busy this flag indicates that a communication is in progress on the bus. It is set by hardware when a START condition is detected. It is cleared by hardware when a stop condition is detected, or when PE=0.. */
  #define I2C2_ISR_DIR_POS              INT32_C(16)   /** @brief Transfer direction (slave mode) this flag is updated when an address match event occurs (ADDR=1).. */
  #define I2C2_ISR_ADDCODE_POS          INT32_C(17)   /** @brief Address match code (slave mode) these bits are updated with the received address when an address match event occurs (ADDR = 1). In the case of a 10-bit address, ADDCODE provides the 10-bit header followed by the 2 msbs of the address.. */
  #define I2C2_ICR_ADDRCF_POS           INT32_C(3)    /** @brief Address matched flag clear writing 1 to this bit clears the ADDR flag in the I2C_ISR register. Writing 1 to this bit also clears the START bit in the I2C_CR2 register.. */
  #define I2C2_ICR_NACKCF_POS           INT32_C(4)    /** @brief Not acknowledge flag clear writing 1 to this bit clears the ACKF flag in I2C_ISR register.. */
  #define I2C2_ICR_STOPCF_POS           INT32_C(5)    /** @brief Stop detection flag clear writing 1 to this bit clears the STOPF flag in the I2C_ISR register.. */
  #define I2C2_ICR_BERRCF_POS           INT32_C(8)    /** @brief Bus error flag clear writing 1 to this bit clears the BERRF flag in the I2C_ISR register.. */
  #define I2C2_ICR_ARLOCF_POS           INT32_C(9)    /** @brief Arbitration lost flag clear writing 1 to this bit clears the ARLO flag in the I2C_ISR register.. */
  #define I2C2_ICR_OVRCF_POS            INT32_C(10)   /** @brief Overrun/Underrun flag clear writing 1 to this bit clears the OVR flag in the I2C_ISR register.. */
  #define I2C2_ICR_PECCF_POS            INT32_C(11)   /** @brief PEC error flag clear writing 1 to this bit clears the PECERR flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_ICR_TIMOUTCF_POS         INT32_C(12)   /** @brief Timeout detection flag clear writing 1 to this bit clears the TIMEOUT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_ICR_ALERTCF_POS          INT32_C(13)   /** @brief Alert flag clear writing 1 to this bit clears the ALERT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C2_PECR_PEC_POS             INT32_C(0)    /** @brief Packet error checking register this field contains the internal PEC when PECEN=1. The PEC is cleared by hardware when PE=0.. */
  #define I2C2_RXDR_RXDATA_POS          INT32_C(0)    /** @brief 8-bit receive data data byte received from the I2C bus.. */
  #define I2C2_TXDR_TXDATA_POS          INT32_C(0)    /** @brief 8-bit transmit data data byte to be transmitted to the I2C bus. Note: these bits can be written only when TXE=1.. */

  /*************************************************************************************************
   * @section I2C3 Definitions
   *************************************************************************************************/

  /**** @subsection Register Definitions ****/

  #define I2C3_CR1_PTR        (*(RW_ uint32_t*)UINT32_C(0x40005C00))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C3_CR2_PTR        (*(RW_ uint32_t*)UINT32_C(0x40005C04))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C3_OAR1_PTR       (*(RW_ uint32_t*)UINT32_C(0x40005C08))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C3_OAR2_PTR       (*(RW_ uint32_t*)UINT32_C(0x40005C0C))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C3_TIMINGR_PTR    (*(RW_ uint32_t*)UINT32_C(0x40005C10))   /** @brief Access: no wait states. */
  #define I2C3_TIMEOUTR_PTR   (*(RW_ uint32_t*)UINT32_C(0x40005C14))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C3_ISR_PTR        (*(RW_ uint32_t*)UINT32_C(0x40005C18))   /** @brief Access: no wait states. */
  #define I2C3_ICR_PTR        (*(WO_ uint32_t*)UINT32_C(0x40005C1C))   /** @brief Access: no wait states. */
  #define I2C3_PECR_PTR       (*(RO_ uint32_t*)UINT32_C(0x40005C20))   /** @brief Access: no wait states. */
  #define I2C3_RXDR_PTR       (*(RO_ uint32_t*)UINT32_C(0x40005C24))   /** @brief Access: no wait states. */
  #define I2C3_TXDR_PTR       (*(RW_ uint32_t*)UINT32_C(0x40005C28))   /** @brief Access: no wait states. */

  /**** @subsection Field Mask Definitions ****/

  #define I2C3_CR1_PE_MSK               UINT32_C(0x00000001)   /** @brief Peripheral enable note: when PE=0, the I2C SCL and SDA lines are released. Internal state machines and status bits are put back to their reset value. When cleared, PE must be kept low for at least 3 APB clock cycles.. */
  #define I2C3_CR1_TXIE_MSK             UINT32_C(0x00000002)   /** @brief TX interrupt enable. */
  #define I2C3_CR1_RXIE_MSK             UINT32_C(0x00000004)   /** @brief RX interrupt enable. */
  #define I2C3_CR1_ADDRIE_MSK           UINT32_C(0x00000008)   /** @brief Address match interrupt enable (slave only). */
  #define I2C3_CR1_NACKIE_MSK           UINT32_C(0x00000010)   /** @brief Not acknowledge received interrupt enable. */
  #define I2C3_CR1_STOPIE_MSK           UINT32_C(0x00000020)   /** @brief STOP detection interrupt enable. */
  #define I2C3_CR1_TCIE_MSK             UINT32_C(0x00000040)   /** @brief Transfer complete interrupt enable note: any of these events will generate an interrupt: transfer complete (TC) transfer complete reload (TCR). */
  #define I2C3_CR1_ERRIE_MSK            UINT32_C(0x00000080)   /** @brief Error interrupts enable note: any of these errors generate an interrupt: arbitration loss (ARLO) bus error detection (BERR) overrun/underrun (OVR) timeout detection (TIMEOUT) PEC error detection (PECERR) alert pin event detection (ALERT). */
  #define I2C3_CR1_DNF_MSK              UINT32_C(0x00000F00)   /** @brief Digital noise filter these bits are used to configure the digital noise filter on SDA and SCL input. The digital filter will filter spikes with a length of up to DNF[3:0] * ti2cclk ... Note: if the analog filter is also enabled, the digital filter is added to the analog filter. This filter can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C3_CR1_ANFOFF_MSK           UINT32_C(0x00001000)   /** @brief Analog noise filter OFF note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C3_CR1_TXDMAEN_MSK          UINT32_C(0x00004000)   /** @brief DMA transmission requests enable. */
  #define I2C3_CR1_RXDMAEN_MSK          UINT32_C(0x00008000)   /** @brief DMA reception requests enable. */
  #define I2C3_CR1_SBC_MSK              UINT32_C(0x00010000)   /** @brief Slave byte control this bit is used to enable hardware byte control in slave mode.. */
  #define I2C3_CR1_NOSTRETCH_MSK        UINT32_C(0x00020000)   /** @brief Clock stretching disable this bit is used to disable clock stretching in slave mode. It must be kept cleared in master mode. Note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C3_CR1_WUPEN_MSK            UINT32_C(0x00040000)   /** @brief Wakeup from stop mode enable note: if the wakeup from stop mode feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation. Note: WUPEN can be set only when DNF = 0000. */
  #define I2C3_CR1_GCEN_MSK             UINT32_C(0x00080000)   /** @brief General call enable. */
  #define I2C3_CR1_SMBHEN_MSK           UINT32_C(0x00100000)   /** @brief SMBus host address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_CR1_SMBDEN_MSK           UINT32_C(0x00200000)   /** @brief SMBus device default address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_CR1_ALERTEN_MSK          UINT32_C(0x00400000)   /** @brief SMBus alert enable device mode (SMBHEN=0): host mode (SMBHEN=1): note: when ALERTEN=0, the SMBA pin can be used as a standard GPIO. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_CR1_PECEN_MSK            UINT32_C(0x00800000)   /** @brief PEC enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_CR2_SADD0_MSK            UINT32_C(0x00000001)   /** @brief Slave address bit 0 (master mode) in 7-bit addressing mode (ADD10 = 0): this bit is dont care in 10-bit addressing mode (ADD10 = 1): this bit should be written with bit 0 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD1_MSK            UINT32_C(0x00000002)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD2_MSK            UINT32_C(0x00000004)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD3_MSK            UINT32_C(0x00000008)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD4_MSK            UINT32_C(0x00000010)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD5_MSK            UINT32_C(0x00000020)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD6_MSK            UINT32_C(0x00000040)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD7_MSK            UINT32_C(0x00000080)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD8_MSK            UINT32_C(0x00000100)   /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD9_MSK            UINT32_C(0x00000200)   /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_RD_WRN_MSK           UINT32_C(0x00000400)   /** @brief Transfer direction (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C3_CR2_ADD10_MSK            UINT32_C(0x00000800)   /** @brief 10-bit addressing mode (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C3_CR2_HEAD10R_MSK          UINT32_C(0x00001000)   /** @brief 10-bit address header only read direction (master receiver mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C3_CR2_START_MSK            UINT32_C(0x00002000)   /** @brief Start generation this bit is set by software, and cleared by hardware after the start followed by the address sequence is sent, by an arbitration loss, by a timeout error detection, or when PE = 0. It can also be cleared by software by writing 1 to the ADDRCF bit in the I2C_ICR register. If the I2C is already in master mode with AUTOEND = 0, setting this bit generates a repeated start condition when RELOAD=0, after the end of the NBYTES transfer. Otherwise setting this bit will generate a START condition once the bus is free. Note: writing 0 to this bit has no effect. The START bit can be set even if the bus is BUSY or I2C is in slave mode. This bit has no effect when RELOAD is set.. */
  #define I2C3_CR2_STOP_MSK             UINT32_C(0x00004000)   /** @brief Stop generation (master mode) the bit is set by software, cleared by hardware when a stop condition is detected, or when PE = 0. In master mode: note: writing 0 to this bit has no effect.. */
  #define I2C3_CR2_NACK_MSK             UINT32_C(0x00008000)   /** @brief NACK generation (slave mode) the bit is set by software, cleared by hardware when the NACK is sent, or when a STOP condition or an address matched is received, or when PE=0. Note: writing 0 to this bit has no effect. This bit is used in slave mode only: in master receiver mode, NACK is automatically generated after last byte preceding STOP or RESTART condition, whatever the NACK bit value. When an overrun occurs in slave receiver NOSTRETCH mode, a NACK is automatically generated whatever the NACK bit value. When hardware PEC checking is enabled (PECBYTE=1), the PEC acknowledge value does not depend on the NACK value.. */
  #define I2C3_CR2_NBYTES_MSK           UINT32_C(0x00FF0000)   /** @brief Number of bytes the number of bytes to be transmitted/received is programmed there. This field is dont care in slave mode with SBC=0. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_RELOAD_MSK           UINT32_C(0x01000000)   /** @brief NBYTES reload mode this bit is set and cleared by software.. */
  #define I2C3_CR2_AUTOEND_MSK          UINT32_C(0x02000000)   /** @brief Automatic end mode (master mode) this bit is set and cleared by software. Note: this bit has no effect in slave mode or when the RELOAD bit is set.. */
  #define I2C3_CR2_PECBYTE_MSK          UINT32_C(0x04000000)   /** @brief Packet error checking byte this bit is set by software, and cleared by hardware when the PEC is transferred, or when a STOP condition or an address matched is received, also when PE=0. Note: writing 0 to this bit has no effect. This bit has no effect when RELOAD is set. This bit has no effect is slave mode when SBC=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_OAR1_OA1_MSK             UINT32_C(0x000003FF)   /** @brief Interface address 7-bit addressing mode: dont care 10-bit addressing mode: bits 9:8 of address note: these bits can be written only when OA1EN=0. OA1[7:1]: interface address bits 7:1 of address note: these bits can be written only when OA1EN=0. OA1[0]: interface address 7-bit addressing mode: dont care 10-bit addressing mode: bit 0 of address note: this bit can be written only when OA1EN=0.. */
  #define I2C3_OAR1_OA1MODE_MSK         UINT32_C(0x00000400)   /** @brief Own address 1 10-bit mode note: this bit can be written only when OA1EN=0.. */
  #define I2C3_OAR1_OA1EN_MSK           UINT32_C(0x00008000)   /** @brief Own address 1 enable. */
  #define I2C3_OAR2_OA2_MSK             UINT32_C(0x000000FE)   /** @brief Interface address bits 7:1 of address note: these bits can be written only when OA2EN=0.. */
  #define I2C3_OAR2_OA2MSK_MSK          UINT32_C(0x00000700)   /** @brief Own address 2 masks note: these bits can be written only when OA2EN=0. As soon as OA2MSK is not equal to 0, the reserved I2C addresses (0b0000xxx and 0b1111xxx) are not acknowledged even if the comparison matches.. */
  #define I2C3_OAR2_OA2EN_MSK           UINT32_C(0x00008000)   /** @brief Own address 2 enable. */
  #define I2C3_TIMINGR_SCLL_MSK         UINT32_C(0x000000FF)   /** @brief SCL low period (master mode) this field is used to generate the SCL low period in master mode. TSCLL = (SCLL+1) x tpresc note: SCLL is also used to generate tbuf and tsu:sta timings.. */
  #define I2C3_TIMINGR_SCLH_MSK         UINT32_C(0x0000FF00)   /** @brief SCL high period (master mode) this field is used to generate the SCL high period in master mode. TSCLH = (SCLH+1) x tpresc note: SCLH is also used to generate tsu:sto and thd:sta timing.. */
  #define I2C3_TIMINGR_SDADEL_MSK       UINT32_C(0x000F0000)   /** @brief Data hold time this field is used to generate the delay tsdadel between SCL falling edge and SDA edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tsdadel. TSDADEL= SDADEL x tpresc note: SDADEL is used to generate thd:dat timing.. */
  #define I2C3_TIMINGR_SCLDEL_MSK       UINT32_C(0x00F00000)   /** @brief Data setup time this field is used to generate a delay tscldel between SDA edge and SCL rising edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tscldel. TSCLDEL = (SCLDEL+1) x tpresc note: tscldel is used to generate tsu:dat timing.. */
  #define I2C3_TIMINGR_PRESC_MSK        UINT32_C(0xF0000000)   /** @brief Timing prescaler this field is used to prescale I2CCLK in order to generate the clock period tpresc used for data setup and hold counters (refer to I2C timings on page9) and for SCL high and low level counters (refer to I2C master initialization on page24). TPRESC = (PRESC+1) x ti2cclk. */
  #define I2C3_TIMEOUTR_TIMEOUTA_MSK    UINT32_C(0x00000FFF)   /** @brief Bus timeout A this field is used to configure: the SCL low timeout condition ttimeout when TIDLE=0 ttimeout= (TIMEOUTA+1) x 2048 x ti2cclk the bus idle condition (both SCL and SDA high) when TIDLE=1 tidle= (TIMEOUTA+1) x 4 x ti2cclk note: these bits can be written only when TIMOUTEN=0.. */
  #define I2C3_TIMEOUTR_TIDLE_MSK       UINT32_C(0x00001000)   /** @brief Idle clock timeout detection note: this bit can be written only when TIMOUTEN=0.. */
  #define I2C3_TIMEOUTR_TIMOUTEN_MSK    UINT32_C(0x00008000)   /** @brief Clock timeout enable. */
  #define I2C3_TIMEOUTR_TIMEOUTB_MSK    UINT32_C(0x0FFF0000)   /** @brief Bus timeout B this field is used to configure the cumulative clock extension timeout: in master mode, the master cumulative clock low extend time (tlow:mext) is detected in slave mode, the slave cumulative clock low extend time (tlow:sext) is detected tlow:ext= (TIMEOUTB+1) x 2048 x ti2cclk note: these bits can be written only when TEXTEN=0.. */
  #define I2C3_TIMEOUTR_TEXTEN_MSK      UINT32_C(0x80000000)   /** @brief Extended clock timeout enable. */
  #define I2C3_ISR_TXE_MSK              UINT32_C(0x00000001)   /** @brief Transmit data register empty (transmitters) this bit is set by hardware when the I2C_TXDR register is empty. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software in order to flush the transmit data register I2C_TXDR. Note: this bit is set by hardware when PE=0.. */
  #define I2C3_ISR_TXIS_MSK             UINT32_C(0x00000002)   /** @brief Transmit interrupt status (transmitters) this bit is set by hardware when the I2C_TXDR register is empty and the data to be transmitted must be written in the I2C_TXDR register. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software when NOSTRETCH=1 only, in order to generate a TXIS event (interrupt if TXIE=1 or DMA request if TXDMAEN=1). Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_RXNE_MSK             UINT32_C(0x00000004)   /** @brief Receive data register not empty (receivers) this bit is set by hardware when the received data is copied into the I2C_RXDR register, and is ready to be read. It is cleared when I2C_RXDR is read. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_ADDR_MSK             UINT32_C(0x00000008)   /** @brief Address matched (slave mode) this bit is set by hardware as soon as the received slave address matched with one of the enabled slave addresses. It is cleared by software by setting ADDRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_NACKF_MSK            UINT32_C(0x00000010)   /** @brief Not acknowledge received flag this flag is set by hardware when a NACK is received after a byte transmission. It is cleared by software by setting the NACKCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_STOPF_MSK            UINT32_C(0x00000020)   /** @brief Stop detection flag this flag is set by hardware when a stop condition is detected on the bus and the peripheral is involved in this transfer: either as a master, provided that the STOP condition is generated by the peripheral. Or as a slave, provided that the peripheral has been addressed previously during this transfer. It is cleared by software by setting the STOPCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_TC_MSK               UINT32_C(0x00000040)   /** @brief Transfer complete (master mode) this flag is set by hardware when RELOAD=0, AUTOEND=0 and NBYTES data have been transferred. It is cleared by software when START bit or STOP bit is set. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_TCR_MSK              UINT32_C(0x00000080)   /** @brief Transfer complete reload this flag is set by hardware when RELOAD=1 and NBYTES data have been transferred. It is cleared by software when NBYTES is written to a non-zero value. Note: this bit is cleared by hardware when PE=0. This flag is only for master mode, or for slave mode when the SBC bit is set.. */
  #define I2C3_ISR_BERR_MSK             UINT32_C(0x00000100)   /** @brief Bus error this flag is set by hardware when a misplaced start or stop condition is detected whereas the peripheral is involved in the transfer. The flag is not set during the address phase in slave mode. It is cleared by software by setting BERRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_ARLO_MSK             UINT32_C(0x00000200)   /** @brief Arbitration lost this flag is set by hardware in case of arbitration loss. It is cleared by software by setting the ARLOCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_OVR_MSK              UINT32_C(0x00000400)   /** @brief Overrun/Underrun (slave mode) this flag is set by hardware in slave mode with NOSTRETCH=1, when an overrun/underrun error occurs. It is cleared by software by setting the OVRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_PECERR_MSK           UINT32_C(0x00000800)   /** @brief PEC error in reception this flag is set by hardware when the received PEC does not match with the PEC register content. A NACK is automatically sent after the wrong PEC reception. It is cleared by software by setting the PECCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_ISR_TIMEOUT_MSK          UINT32_C(0x00001000)   /** @brief Timeout or tlow detection flag this flag is set by hardware when a timeout or extended clock timeout occurred. It is cleared by software by setting the TIMEOUTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_ISR_ALERT_MSK            UINT32_C(0x00002000)   /** @brief SMBus alert this flag is set by hardware when SMBHEN=1 (smbus host configuration), ALERTEN=1 and a SMBALERT event (falling edge) is detected on SMBA pin. It is cleared by software by setting the ALERTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_ISR_BUSY_MSK             UINT32_C(0x00008000)   /** @brief Bus busy this flag indicates that a communication is in progress on the bus. It is set by hardware when a START condition is detected. It is cleared by hardware when a stop condition is detected, or when PE=0.. */
  #define I2C3_ISR_DIR_MSK              UINT32_C(0x00010000)   /** @brief Transfer direction (slave mode) this flag is updated when an address match event occurs (ADDR=1).. */
  #define I2C3_ISR_ADDCODE_MSK          UINT32_C(0x00FE0000)   /** @brief Address match code (slave mode) these bits are updated with the received address when an address match event occurs (ADDR = 1). In the case of a 10-bit address, ADDCODE provides the 10-bit header followed by the 2 msbs of the address.. */
  #define I2C3_ICR_ADDRCF_MSK           UINT32_C(0x00000008)   /** @brief Address matched flag clear writing 1 to this bit clears the ADDR flag in the I2C_ISR register. Writing 1 to this bit also clears the START bit in the I2C_CR2 register.. */
  #define I2C3_ICR_NACKCF_MSK           UINT32_C(0x00000010)   /** @brief Not acknowledge flag clear writing 1 to this bit clears the ACKF flag in I2C_ISR register.. */
  #define I2C3_ICR_STOPCF_MSK           UINT32_C(0x00000020)   /** @brief Stop detection flag clear writing 1 to this bit clears the STOPF flag in the I2C_ISR register.. */
  #define I2C3_ICR_BERRCF_MSK           UINT32_C(0x00000100)   /** @brief Bus error flag clear writing 1 to this bit clears the BERRF flag in the I2C_ISR register.. */
  #define I2C3_ICR_ARLOCF_MSK           UINT32_C(0x00000200)   /** @brief Arbitration lost flag clear writing 1 to this bit clears the ARLO flag in the I2C_ISR register.. */
  #define I2C3_ICR_OVRCF_MSK            UINT32_C(0x00000400)   /** @brief Overrun/Underrun flag clear writing 1 to this bit clears the OVR flag in the I2C_ISR register.. */
  #define I2C3_ICR_PECCF_MSK            UINT32_C(0x00000800)   /** @brief PEC error flag clear writing 1 to this bit clears the PECERR flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_ICR_TIMOUTCF_MSK         UINT32_C(0x00001000)   /** @brief Timeout detection flag clear writing 1 to this bit clears the TIMEOUT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_ICR_ALERTCF_MSK          UINT32_C(0x00002000)   /** @brief Alert flag clear writing 1 to this bit clears the ALERT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_PECR_PEC_MSK             UINT32_C(0x000000FF)   /** @brief Packet error checking register this field contains the internal PEC when PECEN=1. The PEC is cleared by hardware when PE=0.. */
  #define I2C3_RXDR_RXDATA_MSK          UINT32_C(0x000000FF)   /** @brief 8-bit receive data data byte received from the I2C bus.. */
  #define I2C3_TXDR_TXDATA_MSK          UINT32_C(0x000000FF)   /** @brief 8-bit transmit data data byte to be transmitted to the I2C bus. Note: these bits can be written only when TXE=1.. */

  /**** @subsection Field Position Definitions ****/

  #define I2C3_CR1_PE_POS               INT32_C(0)    /** @brief Peripheral enable note: when PE=0, the I2C SCL and SDA lines are released. Internal state machines and status bits are put back to their reset value. When cleared, PE must be kept low for at least 3 APB clock cycles.. */
  #define I2C3_CR1_TXIE_POS             INT32_C(1)    /** @brief TX interrupt enable. */
  #define I2C3_CR1_RXIE_POS             INT32_C(2)    /** @brief RX interrupt enable. */
  #define I2C3_CR1_ADDRIE_POS           INT32_C(3)    /** @brief Address match interrupt enable (slave only). */
  #define I2C3_CR1_NACKIE_POS           INT32_C(4)    /** @brief Not acknowledge received interrupt enable. */
  #define I2C3_CR1_STOPIE_POS           INT32_C(5)    /** @brief STOP detection interrupt enable. */
  #define I2C3_CR1_TCIE_POS             INT32_C(6)    /** @brief Transfer complete interrupt enable note: any of these events will generate an interrupt: transfer complete (TC) transfer complete reload (TCR). */
  #define I2C3_CR1_ERRIE_POS            INT32_C(7)    /** @brief Error interrupts enable note: any of these errors generate an interrupt: arbitration loss (ARLO) bus error detection (BERR) overrun/underrun (OVR) timeout detection (TIMEOUT) PEC error detection (PECERR) alert pin event detection (ALERT). */
  #define I2C3_CR1_DNF_POS              INT32_C(8)    /** @brief Digital noise filter these bits are used to configure the digital noise filter on SDA and SCL input. The digital filter will filter spikes with a length of up to DNF[3:0] * ti2cclk ... Note: if the analog filter is also enabled, the digital filter is added to the analog filter. This filter can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C3_CR1_ANFOFF_POS           INT32_C(12)   /** @brief Analog noise filter OFF note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C3_CR1_TXDMAEN_POS          INT32_C(14)   /** @brief DMA transmission requests enable. */
  #define I2C3_CR1_RXDMAEN_POS          INT32_C(15)   /** @brief DMA reception requests enable. */
  #define I2C3_CR1_SBC_POS              INT32_C(16)   /** @brief Slave byte control this bit is used to enable hardware byte control in slave mode.. */
  #define I2C3_CR1_NOSTRETCH_POS        INT32_C(17)   /** @brief Clock stretching disable this bit is used to disable clock stretching in slave mode. It must be kept cleared in master mode. Note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C3_CR1_WUPEN_POS            INT32_C(18)   /** @brief Wakeup from stop mode enable note: if the wakeup from stop mode feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation. Note: WUPEN can be set only when DNF = 0000. */
  #define I2C3_CR1_GCEN_POS             INT32_C(19)   /** @brief General call enable. */
  #define I2C3_CR1_SMBHEN_POS           INT32_C(20)   /** @brief SMBus host address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_CR1_SMBDEN_POS           INT32_C(21)   /** @brief SMBus device default address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_CR1_ALERTEN_POS          INT32_C(22)   /** @brief SMBus alert enable device mode (SMBHEN=0): host mode (SMBHEN=1): note: when ALERTEN=0, the SMBA pin can be used as a standard GPIO. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_CR1_PECEN_POS            INT32_C(23)   /** @brief PEC enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_CR2_SADD0_POS            INT32_C(0)    /** @brief Slave address bit 0 (master mode) in 7-bit addressing mode (ADD10 = 0): this bit is dont care in 10-bit addressing mode (ADD10 = 1): this bit should be written with bit 0 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD1_POS            INT32_C(1)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD2_POS            INT32_C(2)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD3_POS            INT32_C(3)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD4_POS            INT32_C(4)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD5_POS            INT32_C(5)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD6_POS            INT32_C(6)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD7_POS            INT32_C(7)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD8_POS            INT32_C(8)    /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_SADD9_POS            INT32_C(9)    /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_RD_WRN_POS           INT32_C(10)   /** @brief Transfer direction (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C3_CR2_ADD10_POS            INT32_C(11)   /** @brief 10-bit addressing mode (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C3_CR2_HEAD10R_POS          INT32_C(12)   /** @brief 10-bit address header only read direction (master receiver mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C3_CR2_START_POS            INT32_C(13)   /** @brief Start generation this bit is set by software, and cleared by hardware after the start followed by the address sequence is sent, by an arbitration loss, by a timeout error detection, or when PE = 0. It can also be cleared by software by writing 1 to the ADDRCF bit in the I2C_ICR register. If the I2C is already in master mode with AUTOEND = 0, setting this bit generates a repeated start condition when RELOAD=0, after the end of the NBYTES transfer. Otherwise setting this bit will generate a START condition once the bus is free. Note: writing 0 to this bit has no effect. The START bit can be set even if the bus is BUSY or I2C is in slave mode. This bit has no effect when RELOAD is set.. */
  #define I2C3_CR2_STOP_POS             INT32_C(14)   /** @brief Stop generation (master mode) the bit is set by software, cleared by hardware when a stop condition is detected, or when PE = 0. In master mode: note: writing 0 to this bit has no effect.. */
  #define I2C3_CR2_NACK_POS             INT32_C(15)   /** @brief NACK generation (slave mode) the bit is set by software, cleared by hardware when the NACK is sent, or when a STOP condition or an address matched is received, or when PE=0. Note: writing 0 to this bit has no effect. This bit is used in slave mode only: in master receiver mode, NACK is automatically generated after last byte preceding STOP or RESTART condition, whatever the NACK bit value. When an overrun occurs in slave receiver NOSTRETCH mode, a NACK is automatically generated whatever the NACK bit value. When hardware PEC checking is enabled (PECBYTE=1), the PEC acknowledge value does not depend on the NACK value.. */
  #define I2C3_CR2_NBYTES_POS           INT32_C(16)   /** @brief Number of bytes the number of bytes to be transmitted/received is programmed there. This field is dont care in slave mode with SBC=0. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C3_CR2_RELOAD_POS           INT32_C(24)   /** @brief NBYTES reload mode this bit is set and cleared by software.. */
  #define I2C3_CR2_AUTOEND_POS          INT32_C(25)   /** @brief Automatic end mode (master mode) this bit is set and cleared by software. Note: this bit has no effect in slave mode or when the RELOAD bit is set.. */
  #define I2C3_CR2_PECBYTE_POS          INT32_C(26)   /** @brief Packet error checking byte this bit is set by software, and cleared by hardware when the PEC is transferred, or when a STOP condition or an address matched is received, also when PE=0. Note: writing 0 to this bit has no effect. This bit has no effect when RELOAD is set. This bit has no effect is slave mode when SBC=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_OAR1_OA1_POS             INT32_C(0)    /** @brief Interface address 7-bit addressing mode: dont care 10-bit addressing mode: bits 9:8 of address note: these bits can be written only when OA1EN=0. OA1[7:1]: interface address bits 7:1 of address note: these bits can be written only when OA1EN=0. OA1[0]: interface address 7-bit addressing mode: dont care 10-bit addressing mode: bit 0 of address note: this bit can be written only when OA1EN=0.. */
  #define I2C3_OAR1_OA1MODE_POS         INT32_C(10)   /** @brief Own address 1 10-bit mode note: this bit can be written only when OA1EN=0.. */
  #define I2C3_OAR1_OA1EN_POS           INT32_C(15)   /** @brief Own address 1 enable. */
  #define I2C3_OAR2_OA2_POS             INT32_C(1)    /** @brief Interface address bits 7:1 of address note: these bits can be written only when OA2EN=0.. */
  #define I2C3_OAR2_OA2MSK_POS          INT32_C(8)    /** @brief Own address 2 masks note: these bits can be written only when OA2EN=0. As soon as OA2MSK is not equal to 0, the reserved I2C addresses (0b0000xxx and 0b1111xxx) are not acknowledged even if the comparison matches.. */
  #define I2C3_OAR2_OA2EN_POS           INT32_C(15)   /** @brief Own address 2 enable. */
  #define I2C3_TIMINGR_SCLL_POS         INT32_C(0)    /** @brief SCL low period (master mode) this field is used to generate the SCL low period in master mode. TSCLL = (SCLL+1) x tpresc note: SCLL is also used to generate tbuf and tsu:sta timings.. */
  #define I2C3_TIMINGR_SCLH_POS         INT32_C(8)    /** @brief SCL high period (master mode) this field is used to generate the SCL high period in master mode. TSCLH = (SCLH+1) x tpresc note: SCLH is also used to generate tsu:sto and thd:sta timing.. */
  #define I2C3_TIMINGR_SDADEL_POS       INT32_C(16)   /** @brief Data hold time this field is used to generate the delay tsdadel between SCL falling edge and SDA edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tsdadel. TSDADEL= SDADEL x tpresc note: SDADEL is used to generate thd:dat timing.. */
  #define I2C3_TIMINGR_SCLDEL_POS       INT32_C(20)   /** @brief Data setup time this field is used to generate a delay tscldel between SDA edge and SCL rising edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tscldel. TSCLDEL = (SCLDEL+1) x tpresc note: tscldel is used to generate tsu:dat timing.. */
  #define I2C3_TIMINGR_PRESC_POS        INT32_C(28)   /** @brief Timing prescaler this field is used to prescale I2CCLK in order to generate the clock period tpresc used for data setup and hold counters (refer to I2C timings on page9) and for SCL high and low level counters (refer to I2C master initialization on page24). TPRESC = (PRESC+1) x ti2cclk. */
  #define I2C3_TIMEOUTR_TIMEOUTA_POS    INT32_C(0)    /** @brief Bus timeout A this field is used to configure: the SCL low timeout condition ttimeout when TIDLE=0 ttimeout= (TIMEOUTA+1) x 2048 x ti2cclk the bus idle condition (both SCL and SDA high) when TIDLE=1 tidle= (TIMEOUTA+1) x 4 x ti2cclk note: these bits can be written only when TIMOUTEN=0.. */
  #define I2C3_TIMEOUTR_TIDLE_POS       INT32_C(12)   /** @brief Idle clock timeout detection note: this bit can be written only when TIMOUTEN=0.. */
  #define I2C3_TIMEOUTR_TIMOUTEN_POS    INT32_C(15)   /** @brief Clock timeout enable. */
  #define I2C3_TIMEOUTR_TIMEOUTB_POS    INT32_C(16)   /** @brief Bus timeout B this field is used to configure the cumulative clock extension timeout: in master mode, the master cumulative clock low extend time (tlow:mext) is detected in slave mode, the slave cumulative clock low extend time (tlow:sext) is detected tlow:ext= (TIMEOUTB+1) x 2048 x ti2cclk note: these bits can be written only when TEXTEN=0.. */
  #define I2C3_TIMEOUTR_TEXTEN_POS      INT32_C(31)   /** @brief Extended clock timeout enable. */
  #define I2C3_ISR_TXE_POS              INT32_C(0)    /** @brief Transmit data register empty (transmitters) this bit is set by hardware when the I2C_TXDR register is empty. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software in order to flush the transmit data register I2C_TXDR. Note: this bit is set by hardware when PE=0.. */
  #define I2C3_ISR_TXIS_POS             INT32_C(1)    /** @brief Transmit interrupt status (transmitters) this bit is set by hardware when the I2C_TXDR register is empty and the data to be transmitted must be written in the I2C_TXDR register. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software when NOSTRETCH=1 only, in order to generate a TXIS event (interrupt if TXIE=1 or DMA request if TXDMAEN=1). Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_RXNE_POS             INT32_C(2)    /** @brief Receive data register not empty (receivers) this bit is set by hardware when the received data is copied into the I2C_RXDR register, and is ready to be read. It is cleared when I2C_RXDR is read. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_ADDR_POS             INT32_C(3)    /** @brief Address matched (slave mode) this bit is set by hardware as soon as the received slave address matched with one of the enabled slave addresses. It is cleared by software by setting ADDRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_NACKF_POS            INT32_C(4)    /** @brief Not acknowledge received flag this flag is set by hardware when a NACK is received after a byte transmission. It is cleared by software by setting the NACKCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_STOPF_POS            INT32_C(5)    /** @brief Stop detection flag this flag is set by hardware when a stop condition is detected on the bus and the peripheral is involved in this transfer: either as a master, provided that the STOP condition is generated by the peripheral. Or as a slave, provided that the peripheral has been addressed previously during this transfer. It is cleared by software by setting the STOPCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_TC_POS               INT32_C(6)    /** @brief Transfer complete (master mode) this flag is set by hardware when RELOAD=0, AUTOEND=0 and NBYTES data have been transferred. It is cleared by software when START bit or STOP bit is set. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_TCR_POS              INT32_C(7)    /** @brief Transfer complete reload this flag is set by hardware when RELOAD=1 and NBYTES data have been transferred. It is cleared by software when NBYTES is written to a non-zero value. Note: this bit is cleared by hardware when PE=0. This flag is only for master mode, or for slave mode when the SBC bit is set.. */
  #define I2C3_ISR_BERR_POS             INT32_C(8)    /** @brief Bus error this flag is set by hardware when a misplaced start or stop condition is detected whereas the peripheral is involved in the transfer. The flag is not set during the address phase in slave mode. It is cleared by software by setting BERRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_ARLO_POS             INT32_C(9)    /** @brief Arbitration lost this flag is set by hardware in case of arbitration loss. It is cleared by software by setting the ARLOCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_OVR_POS              INT32_C(10)   /** @brief Overrun/Underrun (slave mode) this flag is set by hardware in slave mode with NOSTRETCH=1, when an overrun/underrun error occurs. It is cleared by software by setting the OVRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C3_ISR_PECERR_POS           INT32_C(11)   /** @brief PEC error in reception this flag is set by hardware when the received PEC does not match with the PEC register content. A NACK is automatically sent after the wrong PEC reception. It is cleared by software by setting the PECCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_ISR_TIMEOUT_POS          INT32_C(12)   /** @brief Timeout or tlow detection flag this flag is set by hardware when a timeout or extended clock timeout occurred. It is cleared by software by setting the TIMEOUTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_ISR_ALERT_POS            INT32_C(13)   /** @brief SMBus alert this flag is set by hardware when SMBHEN=1 (smbus host configuration), ALERTEN=1 and a SMBALERT event (falling edge) is detected on SMBA pin. It is cleared by software by setting the ALERTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_ISR_BUSY_POS             INT32_C(15)   /** @brief Bus busy this flag indicates that a communication is in progress on the bus. It is set by hardware when a START condition is detected. It is cleared by hardware when a stop condition is detected, or when PE=0.. */
  #define I2C3_ISR_DIR_POS              INT32_C(16)   /** @brief Transfer direction (slave mode) this flag is updated when an address match event occurs (ADDR=1).. */
  #define I2C3_ISR_ADDCODE_POS          INT32_C(17)   /** @brief Address match code (slave mode) these bits are updated with the received address when an address match event occurs (ADDR = 1). In the case of a 10-bit address, ADDCODE provides the 10-bit header followed by the 2 msbs of the address.. */
  #define I2C3_ICR_ADDRCF_POS           INT32_C(3)    /** @brief Address matched flag clear writing 1 to this bit clears the ADDR flag in the I2C_ISR register. Writing 1 to this bit also clears the START bit in the I2C_CR2 register.. */
  #define I2C3_ICR_NACKCF_POS           INT32_C(4)    /** @brief Not acknowledge flag clear writing 1 to this bit clears the ACKF flag in I2C_ISR register.. */
  #define I2C3_ICR_STOPCF_POS           INT32_C(5)    /** @brief Stop detection flag clear writing 1 to this bit clears the STOPF flag in the I2C_ISR register.. */
  #define I2C3_ICR_BERRCF_POS           INT32_C(8)    /** @brief Bus error flag clear writing 1 to this bit clears the BERRF flag in the I2C_ISR register.. */
  #define I2C3_ICR_ARLOCF_POS           INT32_C(9)    /** @brief Arbitration lost flag clear writing 1 to this bit clears the ARLO flag in the I2C_ISR register.. */
  #define I2C3_ICR_OVRCF_POS            INT32_C(10)   /** @brief Overrun/Underrun flag clear writing 1 to this bit clears the OVR flag in the I2C_ISR register.. */
  #define I2C3_ICR_PECCF_POS            INT32_C(11)   /** @brief PEC error flag clear writing 1 to this bit clears the PECERR flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_ICR_TIMOUTCF_POS         INT32_C(12)   /** @brief Timeout detection flag clear writing 1 to this bit clears the TIMEOUT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_ICR_ALERTCF_POS          INT32_C(13)   /** @brief Alert flag clear writing 1 to this bit clears the ALERT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C3_PECR_PEC_POS             INT32_C(0)    /** @brief Packet error checking register this field contains the internal PEC when PECEN=1. The PEC is cleared by hardware when PE=0.. */
  #define I2C3_RXDR_RXDATA_POS          INT32_C(0)    /** @brief 8-bit receive data data byte received from the I2C bus.. */
  #define I2C3_TXDR_TXDATA_POS          INT32_C(0)    /** @brief 8-bit transmit data data byte to be transmitted to the I2C bus. Note: these bits can be written only when TXE=1.. */

  /*************************************************************************************************
   * @section I2C4 Definitions
   *************************************************************************************************/

  /**** @subsection Register Definitions ****/

  #define I2C4_CR1_PTR        (*(RW_ uint32_t*)UINT32_C(0x58001C00))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C4_CR2_PTR        (*(RW_ uint32_t*)UINT32_C(0x58001C04))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C4_OAR1_PTR       (*(RW_ uint32_t*)UINT32_C(0x58001C08))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C4_OAR2_PTR       (*(RW_ uint32_t*)UINT32_C(0x58001C0C))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C4_TIMINGR_PTR    (*(RW_ uint32_t*)UINT32_C(0x58001C10))   /** @brief Access: no wait states. */
  #define I2C4_TIMEOUTR_PTR   (*(RW_ uint32_t*)UINT32_C(0x58001C14))   /** @brief Access: no wait states, except if a write access occurs while a write access to this register is ongoing. In this case, wait states are inserted in the second write access until the previous one is completed. The latency of the second write access can be up to 2 x PCLK1 + 6 x I2CCLK.. */
  #define I2C4_ISR_PTR        (*(RW_ uint32_t*)UINT32_C(0x58001C18))   /** @brief Access: no wait states. */
  #define I2C4_ICR_PTR        (*(WO_ uint32_t*)UINT32_C(0x58001C1C))   /** @brief Access: no wait states. */
  #define I2C4_PECR_PTR       (*(RO_ uint32_t*)UINT32_C(0x58001C20))   /** @brief Access: no wait states. */
  #define I2C4_RXDR_PTR       (*(RO_ uint32_t*)UINT32_C(0x58001C24))   /** @brief Access: no wait states. */
  #define I2C4_TXDR_PTR       (*(RW_ uint32_t*)UINT32_C(0x58001C28))   /** @brief Access: no wait states. */

  /**** @subsection Field Mask Definitions ****/

  #define I2C4_CR1_PE_MSK               UINT32_C(0x00000001)   /** @brief Peripheral enable note: when PE=0, the I2C SCL and SDA lines are released. Internal state machines and status bits are put back to their reset value. When cleared, PE must be kept low for at least 3 APB clock cycles.. */
  #define I2C4_CR1_TXIE_MSK             UINT32_C(0x00000002)   /** @brief TX interrupt enable. */
  #define I2C4_CR1_RXIE_MSK             UINT32_C(0x00000004)   /** @brief RX interrupt enable. */
  #define I2C4_CR1_ADDRIE_MSK           UINT32_C(0x00000008)   /** @brief Address match interrupt enable (slave only). */
  #define I2C4_CR1_NACKIE_MSK           UINT32_C(0x00000010)   /** @brief Not acknowledge received interrupt enable. */
  #define I2C4_CR1_STOPIE_MSK           UINT32_C(0x00000020)   /** @brief STOP detection interrupt enable. */
  #define I2C4_CR1_TCIE_MSK             UINT32_C(0x00000040)   /** @brief Transfer complete interrupt enable note: any of these events will generate an interrupt: transfer complete (TC) transfer complete reload (TCR). */
  #define I2C4_CR1_ERRIE_MSK            UINT32_C(0x00000080)   /** @brief Error interrupts enable note: any of these errors generate an interrupt: arbitration loss (ARLO) bus error detection (BERR) overrun/underrun (OVR) timeout detection (TIMEOUT) PEC error detection (PECERR) alert pin event detection (ALERT). */
  #define I2C4_CR1_DNF_MSK              UINT32_C(0x00000F00)   /** @brief Digital noise filter these bits are used to configure the digital noise filter on SDA and SCL input. The digital filter will filter spikes with a length of up to DNF[3:0] * ti2cclk ... Note: if the analog filter is also enabled, the digital filter is added to the analog filter. This filter can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C4_CR1_ANFOFF_MSK           UINT32_C(0x00001000)   /** @brief Analog noise filter OFF note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C4_CR1_TXDMAEN_MSK          UINT32_C(0x00004000)   /** @brief DMA transmission requests enable. */
  #define I2C4_CR1_RXDMAEN_MSK          UINT32_C(0x00008000)   /** @brief DMA reception requests enable. */
  #define I2C4_CR1_SBC_MSK              UINT32_C(0x00010000)   /** @brief Slave byte control this bit is used to enable hardware byte control in slave mode.. */
  #define I2C4_CR1_NOSTRETCH_MSK        UINT32_C(0x00020000)   /** @brief Clock stretching disable this bit is used to disable clock stretching in slave mode. It must be kept cleared in master mode. Note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C4_CR1_WUPEN_MSK            UINT32_C(0x00040000)   /** @brief Wakeup from stop mode enable note: if the wakeup from stop mode feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation. Note: WUPEN can be set only when DNF = 0000. */
  #define I2C4_CR1_GCEN_MSK             UINT32_C(0x00080000)   /** @brief General call enable. */
  #define I2C4_CR1_SMBHEN_MSK           UINT32_C(0x00100000)   /** @brief SMBus host address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_CR1_SMBDEN_MSK           UINT32_C(0x00200000)   /** @brief SMBus device default address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_CR1_ALERTEN_MSK          UINT32_C(0x00400000)   /** @brief SMBus alert enable device mode (SMBHEN=0): host mode (SMBHEN=1): note: when ALERTEN=0, the SMBA pin can be used as a standard GPIO. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_CR1_PECEN_MSK            UINT32_C(0x00800000)   /** @brief PEC enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_CR2_SADD0_MSK            UINT32_C(0x00000001)   /** @brief Slave address bit 0 (master mode) in 7-bit addressing mode (ADD10 = 0): this bit is dont care in 10-bit addressing mode (ADD10 = 1): this bit should be written with bit 0 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD1_MSK            UINT32_C(0x00000002)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD2_MSK            UINT32_C(0x00000004)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD3_MSK            UINT32_C(0x00000008)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD4_MSK            UINT32_C(0x00000010)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD5_MSK            UINT32_C(0x00000020)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD6_MSK            UINT32_C(0x00000040)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD7_MSK            UINT32_C(0x00000080)   /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD8_MSK            UINT32_C(0x00000100)   /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD9_MSK            UINT32_C(0x00000200)   /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_RD_WRN_MSK           UINT32_C(0x00000400)   /** @brief Transfer direction (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C4_CR2_ADD10_MSK            UINT32_C(0x00000800)   /** @brief 10-bit addressing mode (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C4_CR2_HEAD10R_MSK          UINT32_C(0x00001000)   /** @brief 10-bit address header only read direction (master receiver mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C4_CR2_START_MSK            UINT32_C(0x00002000)   /** @brief Start generation this bit is set by software, and cleared by hardware after the start followed by the address sequence is sent, by an arbitration loss, by a timeout error detection, or when PE = 0. It can also be cleared by software by writing 1 to the ADDRCF bit in the I2C_ICR register. If the I2C is already in master mode with AUTOEND = 0, setting this bit generates a repeated start condition when RELOAD=0, after the end of the NBYTES transfer. Otherwise setting this bit will generate a START condition once the bus is free. Note: writing 0 to this bit has no effect. The START bit can be set even if the bus is BUSY or I2C is in slave mode. This bit has no effect when RELOAD is set.. */
  #define I2C4_CR2_STOP_MSK             UINT32_C(0x00004000)   /** @brief Stop generation (master mode) the bit is set by software, cleared by hardware when a stop condition is detected, or when PE = 0. In master mode: note: writing 0 to this bit has no effect.. */
  #define I2C4_CR2_NACK_MSK             UINT32_C(0x00008000)   /** @brief NACK generation (slave mode) the bit is set by software, cleared by hardware when the NACK is sent, or when a STOP condition or an address matched is received, or when PE=0. Note: writing 0 to this bit has no effect. This bit is used in slave mode only: in master receiver mode, NACK is automatically generated after last byte preceding STOP or RESTART condition, whatever the NACK bit value. When an overrun occurs in slave receiver NOSTRETCH mode, a NACK is automatically generated whatever the NACK bit value. When hardware PEC checking is enabled (PECBYTE=1), the PEC acknowledge value does not depend on the NACK value.. */
  #define I2C4_CR2_NBYTES_MSK           UINT32_C(0x00FF0000)   /** @brief Number of bytes the number of bytes to be transmitted/received is programmed there. This field is dont care in slave mode with SBC=0. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_RELOAD_MSK           UINT32_C(0x01000000)   /** @brief NBYTES reload mode this bit is set and cleared by software.. */
  #define I2C4_CR2_AUTOEND_MSK          UINT32_C(0x02000000)   /** @brief Automatic end mode (master mode) this bit is set and cleared by software. Note: this bit has no effect in slave mode or when the RELOAD bit is set.. */
  #define I2C4_CR2_PECBYTE_MSK          UINT32_C(0x04000000)   /** @brief Packet error checking byte this bit is set by software, and cleared by hardware when the PEC is transferred, or when a STOP condition or an address matched is received, also when PE=0. Note: writing 0 to this bit has no effect. This bit has no effect when RELOAD is set. This bit has no effect is slave mode when SBC=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_OAR1_OA1_MSK             UINT32_C(0x000003FF)   /** @brief Interface address 7-bit addressing mode: dont care 10-bit addressing mode: bits 9:8 of address note: these bits can be written only when OA1EN=0. OA1[7:1]: interface address bits 7:1 of address note: these bits can be written only when OA1EN=0. OA1[0]: interface address 7-bit addressing mode: dont care 10-bit addressing mode: bit 0 of address note: this bit can be written only when OA1EN=0.. */
  #define I2C4_OAR1_OA1MODE_MSK         UINT32_C(0x00000400)   /** @brief Own address 1 10-bit mode note: this bit can be written only when OA1EN=0.. */
  #define I2C4_OAR1_OA1EN_MSK           UINT32_C(0x00008000)   /** @brief Own address 1 enable. */
  #define I2C4_OAR2_OA2_MSK             UINT32_C(0x000000FE)   /** @brief Interface address bits 7:1 of address note: these bits can be written only when OA2EN=0.. */
  #define I2C4_OAR2_OA2MSK_MSK          UINT32_C(0x00000700)   /** @brief Own address 2 masks note: these bits can be written only when OA2EN=0. As soon as OA2MSK is not equal to 0, the reserved I2C addresses (0b0000xxx and 0b1111xxx) are not acknowledged even if the comparison matches.. */
  #define I2C4_OAR2_OA2EN_MSK           UINT32_C(0x00008000)   /** @brief Own address 2 enable. */
  #define I2C4_TIMINGR_SCLL_MSK         UINT32_C(0x000000FF)   /** @brief SCL low period (master mode) this field is used to generate the SCL low period in master mode. TSCLL = (SCLL+1) x tpresc note: SCLL is also used to generate tbuf and tsu:sta timings.. */
  #define I2C4_TIMINGR_SCLH_MSK         UINT32_C(0x0000FF00)   /** @brief SCL high period (master mode) this field is used to generate the SCL high period in master mode. TSCLH = (SCLH+1) x tpresc note: SCLH is also used to generate tsu:sto and thd:sta timing.. */
  #define I2C4_TIMINGR_SDADEL_MSK       UINT32_C(0x000F0000)   /** @brief Data hold time this field is used to generate the delay tsdadel between SCL falling edge and SDA edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tsdadel. TSDADEL= SDADEL x tpresc note: SDADEL is used to generate thd:dat timing.. */
  #define I2C4_TIMINGR_SCLDEL_MSK       UINT32_C(0x00F00000)   /** @brief Data setup time this field is used to generate a delay tscldel between SDA edge and SCL rising edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tscldel. TSCLDEL = (SCLDEL+1) x tpresc note: tscldel is used to generate tsu:dat timing.. */
  #define I2C4_TIMINGR_PRESC_MSK        UINT32_C(0xF0000000)   /** @brief Timing prescaler this field is used to prescale I2CCLK in order to generate the clock period tpresc used for data setup and hold counters (refer to I2C timings on page9) and for SCL high and low level counters (refer to I2C master initialization on page24). TPRESC = (PRESC+1) x ti2cclk. */
  #define I2C4_TIMEOUTR_TIMEOUTA_MSK    UINT32_C(0x00000FFF)   /** @brief Bus timeout A this field is used to configure: the SCL low timeout condition ttimeout when TIDLE=0 ttimeout= (TIMEOUTA+1) x 2048 x ti2cclk the bus idle condition (both SCL and SDA high) when TIDLE=1 tidle= (TIMEOUTA+1) x 4 x ti2cclk note: these bits can be written only when TIMOUTEN=0.. */
  #define I2C4_TIMEOUTR_TIDLE_MSK       UINT32_C(0x00001000)   /** @brief Idle clock timeout detection note: this bit can be written only when TIMOUTEN=0.. */
  #define I2C4_TIMEOUTR_TIMOUTEN_MSK    UINT32_C(0x00008000)   /** @brief Clock timeout enable. */
  #define I2C4_TIMEOUTR_TIMEOUTB_MSK    UINT32_C(0x0FFF0000)   /** @brief Bus timeout B this field is used to configure the cumulative clock extension timeout: in master mode, the master cumulative clock low extend time (tlow:mext) is detected in slave mode, the slave cumulative clock low extend time (tlow:sext) is detected tlow:ext= (TIMEOUTB+1) x 2048 x ti2cclk note: these bits can be written only when TEXTEN=0.. */
  #define I2C4_TIMEOUTR_TEXTEN_MSK      UINT32_C(0x80000000)   /** @brief Extended clock timeout enable. */
  #define I2C4_ISR_TXE_MSK              UINT32_C(0x00000001)   /** @brief Transmit data register empty (transmitters) this bit is set by hardware when the I2C_TXDR register is empty. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software in order to flush the transmit data register I2C_TXDR. Note: this bit is set by hardware when PE=0.. */
  #define I2C4_ISR_TXIS_MSK             UINT32_C(0x00000002)   /** @brief Transmit interrupt status (transmitters) this bit is set by hardware when the I2C_TXDR register is empty and the data to be transmitted must be written in the I2C_TXDR register. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software when NOSTRETCH=1 only, in order to generate a TXIS event (interrupt if TXIE=1 or DMA request if TXDMAEN=1). Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_RXNE_MSK             UINT32_C(0x00000004)   /** @brief Receive data register not empty (receivers) this bit is set by hardware when the received data is copied into the I2C_RXDR register, and is ready to be read. It is cleared when I2C_RXDR is read. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_ADDR_MSK             UINT32_C(0x00000008)   /** @brief Address matched (slave mode) this bit is set by hardware as soon as the received slave address matched with one of the enabled slave addresses. It is cleared by software by setting ADDRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_NACKF_MSK            UINT32_C(0x00000010)   /** @brief Not acknowledge received flag this flag is set by hardware when a NACK is received after a byte transmission. It is cleared by software by setting the NACKCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_STOPF_MSK            UINT32_C(0x00000020)   /** @brief Stop detection flag this flag is set by hardware when a stop condition is detected on the bus and the peripheral is involved in this transfer: either as a master, provided that the STOP condition is generated by the peripheral. Or as a slave, provided that the peripheral has been addressed previously during this transfer. It is cleared by software by setting the STOPCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_TC_MSK               UINT32_C(0x00000040)   /** @brief Transfer complete (master mode) this flag is set by hardware when RELOAD=0, AUTOEND=0 and NBYTES data have been transferred. It is cleared by software when START bit or STOP bit is set. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_TCR_MSK              UINT32_C(0x00000080)   /** @brief Transfer complete reload this flag is set by hardware when RELOAD=1 and NBYTES data have been transferred. It is cleared by software when NBYTES is written to a non-zero value. Note: this bit is cleared by hardware when PE=0. This flag is only for master mode, or for slave mode when the SBC bit is set.. */
  #define I2C4_ISR_BERR_MSK             UINT32_C(0x00000100)   /** @brief Bus error this flag is set by hardware when a misplaced start or stop condition is detected whereas the peripheral is involved in the transfer. The flag is not set during the address phase in slave mode. It is cleared by software by setting BERRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_ARLO_MSK             UINT32_C(0x00000200)   /** @brief Arbitration lost this flag is set by hardware in case of arbitration loss. It is cleared by software by setting the ARLOCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_OVR_MSK              UINT32_C(0x00000400)   /** @brief Overrun/Underrun (slave mode) this flag is set by hardware in slave mode with NOSTRETCH=1, when an overrun/underrun error occurs. It is cleared by software by setting the OVRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_PECERR_MSK           UINT32_C(0x00000800)   /** @brief PEC error in reception this flag is set by hardware when the received PEC does not match with the PEC register content. A NACK is automatically sent after the wrong PEC reception. It is cleared by software by setting the PECCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_ISR_TIMEOUT_MSK          UINT32_C(0x00001000)   /** @brief Timeout or tlow detection flag this flag is set by hardware when a timeout or extended clock timeout occurred. It is cleared by software by setting the TIMEOUTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_ISR_ALERT_MSK            UINT32_C(0x00002000)   /** @brief SMBus alert this flag is set by hardware when SMBHEN=1 (smbus host configuration), ALERTEN=1 and a SMBALERT event (falling edge) is detected on SMBA pin. It is cleared by software by setting the ALERTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_ISR_BUSY_MSK             UINT32_C(0x00008000)   /** @brief Bus busy this flag indicates that a communication is in progress on the bus. It is set by hardware when a START condition is detected. It is cleared by hardware when a stop condition is detected, or when PE=0.. */
  #define I2C4_ISR_DIR_MSK              UINT32_C(0x00010000)   /** @brief Transfer direction (slave mode) this flag is updated when an address match event occurs (ADDR=1).. */
  #define I2C4_ISR_ADDCODE_MSK          UINT32_C(0x00FE0000)   /** @brief Address match code (slave mode) these bits are updated with the received address when an address match event occurs (ADDR = 1). In the case of a 10-bit address, ADDCODE provides the 10-bit header followed by the 2 msbs of the address.. */
  #define I2C4_ICR_ADDRCF_MSK           UINT32_C(0x00000008)   /** @brief Address matched flag clear writing 1 to this bit clears the ADDR flag in the I2C_ISR register. Writing 1 to this bit also clears the START bit in the I2C_CR2 register.. */
  #define I2C4_ICR_NACKCF_MSK           UINT32_C(0x00000010)   /** @brief Not acknowledge flag clear writing 1 to this bit clears the ACKF flag in I2C_ISR register.. */
  #define I2C4_ICR_STOPCF_MSK           UINT32_C(0x00000020)   /** @brief Stop detection flag clear writing 1 to this bit clears the STOPF flag in the I2C_ISR register.. */
  #define I2C4_ICR_BERRCF_MSK           UINT32_C(0x00000100)   /** @brief Bus error flag clear writing 1 to this bit clears the BERRF flag in the I2C_ISR register.. */
  #define I2C4_ICR_ARLOCF_MSK           UINT32_C(0x00000200)   /** @brief Arbitration lost flag clear writing 1 to this bit clears the ARLO flag in the I2C_ISR register.. */
  #define I2C4_ICR_OVRCF_MSK            UINT32_C(0x00000400)   /** @brief Overrun/Underrun flag clear writing 1 to this bit clears the OVR flag in the I2C_ISR register.. */
  #define I2C4_ICR_PECCF_MSK            UINT32_C(0x00000800)   /** @brief PEC error flag clear writing 1 to this bit clears the PECERR flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_ICR_TIMOUTCF_MSK         UINT32_C(0x00001000)   /** @brief Timeout detection flag clear writing 1 to this bit clears the TIMEOUT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_ICR_ALERTCF_MSK          UINT32_C(0x00002000)   /** @brief Alert flag clear writing 1 to this bit clears the ALERT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_PECR_PEC_MSK             UINT32_C(0x000000FF)   /** @brief Packet error checking register this field contains the internal PEC when PECEN=1. The PEC is cleared by hardware when PE=0.. */
  #define I2C4_RXDR_RXDATA_MSK          UINT32_C(0x000000FF)   /** @brief 8-bit receive data data byte received from the I2C bus.. */
  #define I2C4_TXDR_TXDATA_MSK          UINT32_C(0x000000FF)   /** @brief 8-bit transmit data data byte to be transmitted to the I2C bus. Note: these bits can be written only when TXE=1.. */

  /**** @subsection Field Position Definitions ****/

  #define I2C4_CR1_PE_POS               INT32_C(0)    /** @brief Peripheral enable note: when PE=0, the I2C SCL and SDA lines are released. Internal state machines and status bits are put back to their reset value. When cleared, PE must be kept low for at least 3 APB clock cycles.. */
  #define I2C4_CR1_TXIE_POS             INT32_C(1)    /** @brief TX interrupt enable. */
  #define I2C4_CR1_RXIE_POS             INT32_C(2)    /** @brief RX interrupt enable. */
  #define I2C4_CR1_ADDRIE_POS           INT32_C(3)    /** @brief Address match interrupt enable (slave only). */
  #define I2C4_CR1_NACKIE_POS           INT32_C(4)    /** @brief Not acknowledge received interrupt enable. */
  #define I2C4_CR1_STOPIE_POS           INT32_C(5)    /** @brief STOP detection interrupt enable. */
  #define I2C4_CR1_TCIE_POS             INT32_C(6)    /** @brief Transfer complete interrupt enable note: any of these events will generate an interrupt: transfer complete (TC) transfer complete reload (TCR). */
  #define I2C4_CR1_ERRIE_POS            INT32_C(7)    /** @brief Error interrupts enable note: any of these errors generate an interrupt: arbitration loss (ARLO) bus error detection (BERR) overrun/underrun (OVR) timeout detection (TIMEOUT) PEC error detection (PECERR) alert pin event detection (ALERT). */
  #define I2C4_CR1_DNF_POS              INT32_C(8)    /** @brief Digital noise filter these bits are used to configure the digital noise filter on SDA and SCL input. The digital filter will filter spikes with a length of up to DNF[3:0] * ti2cclk ... Note: if the analog filter is also enabled, the digital filter is added to the analog filter. This filter can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C4_CR1_ANFOFF_POS           INT32_C(12)   /** @brief Analog noise filter OFF note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C4_CR1_TXDMAEN_POS          INT32_C(14)   /** @brief DMA transmission requests enable. */
  #define I2C4_CR1_RXDMAEN_POS          INT32_C(15)   /** @brief DMA reception requests enable. */
  #define I2C4_CR1_SBC_POS              INT32_C(16)   /** @brief Slave byte control this bit is used to enable hardware byte control in slave mode.. */
  #define I2C4_CR1_NOSTRETCH_POS        INT32_C(17)   /** @brief Clock stretching disable this bit is used to disable clock stretching in slave mode. It must be kept cleared in master mode. Note: this bit can only be programmed when the I2C is disabled (PE = 0).. */
  #define I2C4_CR1_WUPEN_POS            INT32_C(18)   /** @brief Wakeup from stop mode enable note: if the wakeup from stop mode feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation. Note: WUPEN can be set only when DNF = 0000. */
  #define I2C4_CR1_GCEN_POS             INT32_C(19)   /** @brief General call enable. */
  #define I2C4_CR1_SMBHEN_POS           INT32_C(20)   /** @brief SMBus host address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_CR1_SMBDEN_POS           INT32_C(21)   /** @brief SMBus device default address enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_CR1_ALERTEN_POS          INT32_C(22)   /** @brief SMBus alert enable device mode (SMBHEN=0): host mode (SMBHEN=1): note: when ALERTEN=0, the SMBA pin can be used as a standard GPIO. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_CR1_PECEN_POS            INT32_C(23)   /** @brief PEC enable note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_CR2_SADD0_POS            INT32_C(0)    /** @brief Slave address bit 0 (master mode) in 7-bit addressing mode (ADD10 = 0): this bit is dont care in 10-bit addressing mode (ADD10 = 1): this bit should be written with bit 0 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD1_POS            INT32_C(1)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD2_POS            INT32_C(2)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD3_POS            INT32_C(3)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD4_POS            INT32_C(4)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD5_POS            INT32_C(5)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD6_POS            INT32_C(6)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD7_POS            INT32_C(7)    /** @brief Slave address bit 7:1 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits should be written with the 7-bit slave address to be sent in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 7:1 of the slave address to be sent. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD8_POS            INT32_C(8)    /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_SADD9_POS            INT32_C(9)    /** @brief Slave address bit 9:8 (master mode) in 7-bit addressing mode (ADD10 = 0): these bits are dont care in 10-bit addressing mode (ADD10 = 1): these bits should be written with bits 9:8 of the slave address to be sent note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_RD_WRN_POS           INT32_C(10)   /** @brief Transfer direction (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C4_CR2_ADD10_POS            INT32_C(11)   /** @brief 10-bit addressing mode (master mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C4_CR2_HEAD10R_POS          INT32_C(12)   /** @brief 10-bit address header only read direction (master receiver mode) note: changing this bit when the START bit is set is not allowed.. */
  #define I2C4_CR2_START_POS            INT32_C(13)   /** @brief Start generation this bit is set by software, and cleared by hardware after the start followed by the address sequence is sent, by an arbitration loss, by a timeout error detection, or when PE = 0. It can also be cleared by software by writing 1 to the ADDRCF bit in the I2C_ICR register. If the I2C is already in master mode with AUTOEND = 0, setting this bit generates a repeated start condition when RELOAD=0, after the end of the NBYTES transfer. Otherwise setting this bit will generate a START condition once the bus is free. Note: writing 0 to this bit has no effect. The START bit can be set even if the bus is BUSY or I2C is in slave mode. This bit has no effect when RELOAD is set.. */
  #define I2C4_CR2_STOP_POS             INT32_C(14)   /** @brief Stop generation (master mode) the bit is set by software, cleared by hardware when a stop condition is detected, or when PE = 0. In master mode: note: writing 0 to this bit has no effect.. */
  #define I2C4_CR2_NACK_POS             INT32_C(15)   /** @brief NACK generation (slave mode) the bit is set by software, cleared by hardware when the NACK is sent, or when a STOP condition or an address matched is received, or when PE=0. Note: writing 0 to this bit has no effect. This bit is used in slave mode only: in master receiver mode, NACK is automatically generated after last byte preceding STOP or RESTART condition, whatever the NACK bit value. When an overrun occurs in slave receiver NOSTRETCH mode, a NACK is automatically generated whatever the NACK bit value. When hardware PEC checking is enabled (PECBYTE=1), the PEC acknowledge value does not depend on the NACK value.. */
  #define I2C4_CR2_NBYTES_POS           INT32_C(16)   /** @brief Number of bytes the number of bytes to be transmitted/received is programmed there. This field is dont care in slave mode with SBC=0. Note: changing these bits when the START bit is set is not allowed.. */
  #define I2C4_CR2_RELOAD_POS           INT32_C(24)   /** @brief NBYTES reload mode this bit is set and cleared by software.. */
  #define I2C4_CR2_AUTOEND_POS          INT32_C(25)   /** @brief Automatic end mode (master mode) this bit is set and cleared by software. Note: this bit has no effect in slave mode or when the RELOAD bit is set.. */
  #define I2C4_CR2_PECBYTE_POS          INT32_C(26)   /** @brief Packet error checking byte this bit is set by software, and cleared by hardware when the PEC is transferred, or when a STOP condition or an address matched is received, also when PE=0. Note: writing 0 to this bit has no effect. This bit has no effect when RELOAD is set. This bit has no effect is slave mode when SBC=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_OAR1_OA1_POS             INT32_C(0)    /** @brief Interface address 7-bit addressing mode: dont care 10-bit addressing mode: bits 9:8 of address note: these bits can be written only when OA1EN=0. OA1[7:1]: interface address bits 7:1 of address note: these bits can be written only when OA1EN=0. OA1[0]: interface address 7-bit addressing mode: dont care 10-bit addressing mode: bit 0 of address note: this bit can be written only when OA1EN=0.. */
  #define I2C4_OAR1_OA1MODE_POS         INT32_C(10)   /** @brief Own address 1 10-bit mode note: this bit can be written only when OA1EN=0.. */
  #define I2C4_OAR1_OA1EN_POS           INT32_C(15)   /** @brief Own address 1 enable. */
  #define I2C4_OAR2_OA2_POS             INT32_C(1)    /** @brief Interface address bits 7:1 of address note: these bits can be written only when OA2EN=0.. */
  #define I2C4_OAR2_OA2MSK_POS          INT32_C(8)    /** @brief Own address 2 masks note: these bits can be written only when OA2EN=0. As soon as OA2MSK is not equal to 0, the reserved I2C addresses (0b0000xxx and 0b1111xxx) are not acknowledged even if the comparison matches.. */
  #define I2C4_OAR2_OA2EN_POS           INT32_C(15)   /** @brief Own address 2 enable. */
  #define I2C4_TIMINGR_SCLL_POS         INT32_C(0)    /** @brief SCL low period (master mode) this field is used to generate the SCL low period in master mode. TSCLL = (SCLL+1) x tpresc note: SCLL is also used to generate tbuf and tsu:sta timings.. */
  #define I2C4_TIMINGR_SCLH_POS         INT32_C(8)    /** @brief SCL high period (master mode) this field is used to generate the SCL high period in master mode. TSCLH = (SCLH+1) x tpresc note: SCLH is also used to generate tsu:sto and thd:sta timing.. */
  #define I2C4_TIMINGR_SDADEL_POS       INT32_C(16)   /** @brief Data hold time this field is used to generate the delay tsdadel between SCL falling edge and SDA edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tsdadel. TSDADEL= SDADEL x tpresc note: SDADEL is used to generate thd:dat timing.. */
  #define I2C4_TIMINGR_SCLDEL_POS       INT32_C(20)   /** @brief Data setup time this field is used to generate a delay tscldel between SDA edge and SCL rising edge. In master mode and in slave mode with NOSTRETCH = 0, the SCL line is stretched low during tscldel. TSCLDEL = (SCLDEL+1) x tpresc note: tscldel is used to generate tsu:dat timing.. */
  #define I2C4_TIMINGR_PRESC_POS        INT32_C(28)   /** @brief Timing prescaler this field is used to prescale I2CCLK in order to generate the clock period tpresc used for data setup and hold counters (refer to I2C timings on page9) and for SCL high and low level counters (refer to I2C master initialization on page24). TPRESC = (PRESC+1) x ti2cclk. */
  #define I2C4_TIMEOUTR_TIMEOUTA_POS    INT32_C(0)    /** @brief Bus timeout A this field is used to configure: the SCL low timeout condition ttimeout when TIDLE=0 ttimeout= (TIMEOUTA+1) x 2048 x ti2cclk the bus idle condition (both SCL and SDA high) when TIDLE=1 tidle= (TIMEOUTA+1) x 4 x ti2cclk note: these bits can be written only when TIMOUTEN=0.. */
  #define I2C4_TIMEOUTR_TIDLE_POS       INT32_C(12)   /** @brief Idle clock timeout detection note: this bit can be written only when TIMOUTEN=0.. */
  #define I2C4_TIMEOUTR_TIMOUTEN_POS    INT32_C(15)   /** @brief Clock timeout enable. */
  #define I2C4_TIMEOUTR_TIMEOUTB_POS    INT32_C(16)   /** @brief Bus timeout B this field is used to configure the cumulative clock extension timeout: in master mode, the master cumulative clock low extend time (tlow:mext) is detected in slave mode, the slave cumulative clock low extend time (tlow:sext) is detected tlow:ext= (TIMEOUTB+1) x 2048 x ti2cclk note: these bits can be written only when TEXTEN=0.. */
  #define I2C4_TIMEOUTR_TEXTEN_POS      INT32_C(31)   /** @brief Extended clock timeout enable. */
  #define I2C4_ISR_TXE_POS              INT32_C(0)    /** @brief Transmit data register empty (transmitters) this bit is set by hardware when the I2C_TXDR register is empty. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software in order to flush the transmit data register I2C_TXDR. Note: this bit is set by hardware when PE=0.. */
  #define I2C4_ISR_TXIS_POS             INT32_C(1)    /** @brief Transmit interrupt status (transmitters) this bit is set by hardware when the I2C_TXDR register is empty and the data to be transmitted must be written in the I2C_TXDR register. It is cleared when the next data to be sent is written in the I2C_TXDR register. This bit can be written to 1 by software when NOSTRETCH=1 only, in order to generate a TXIS event (interrupt if TXIE=1 or DMA request if TXDMAEN=1). Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_RXNE_POS             INT32_C(2)    /** @brief Receive data register not empty (receivers) this bit is set by hardware when the received data is copied into the I2C_RXDR register, and is ready to be read. It is cleared when I2C_RXDR is read. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_ADDR_POS             INT32_C(3)    /** @brief Address matched (slave mode) this bit is set by hardware as soon as the received slave address matched with one of the enabled slave addresses. It is cleared by software by setting ADDRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_NACKF_POS            INT32_C(4)    /** @brief Not acknowledge received flag this flag is set by hardware when a NACK is received after a byte transmission. It is cleared by software by setting the NACKCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_STOPF_POS            INT32_C(5)    /** @brief Stop detection flag this flag is set by hardware when a stop condition is detected on the bus and the peripheral is involved in this transfer: either as a master, provided that the STOP condition is generated by the peripheral. Or as a slave, provided that the peripheral has been addressed previously during this transfer. It is cleared by software by setting the STOPCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_TC_POS               INT32_C(6)    /** @brief Transfer complete (master mode) this flag is set by hardware when RELOAD=0, AUTOEND=0 and NBYTES data have been transferred. It is cleared by software when START bit or STOP bit is set. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_TCR_POS              INT32_C(7)    /** @brief Transfer complete reload this flag is set by hardware when RELOAD=1 and NBYTES data have been transferred. It is cleared by software when NBYTES is written to a non-zero value. Note: this bit is cleared by hardware when PE=0. This flag is only for master mode, or for slave mode when the SBC bit is set.. */
  #define I2C4_ISR_BERR_POS             INT32_C(8)    /** @brief Bus error this flag is set by hardware when a misplaced start or stop condition is detected whereas the peripheral is involved in the transfer. The flag is not set during the address phase in slave mode. It is cleared by software by setting BERRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_ARLO_POS             INT32_C(9)    /** @brief Arbitration lost this flag is set by hardware in case of arbitration loss. It is cleared by software by setting the ARLOCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_OVR_POS              INT32_C(10)   /** @brief Overrun/Underrun (slave mode) this flag is set by hardware in slave mode with NOSTRETCH=1, when an overrun/underrun error occurs. It is cleared by software by setting the OVRCF bit. Note: this bit is cleared by hardware when PE=0.. */
  #define I2C4_ISR_PECERR_POS           INT32_C(11)   /** @brief PEC error in reception this flag is set by hardware when the received PEC does not match with the PEC register content. A NACK is automatically sent after the wrong PEC reception. It is cleared by software by setting the PECCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_ISR_TIMEOUT_POS          INT32_C(12)   /** @brief Timeout or tlow detection flag this flag is set by hardware when a timeout or extended clock timeout occurred. It is cleared by software by setting the TIMEOUTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_ISR_ALERT_POS            INT32_C(13)   /** @brief SMBus alert this flag is set by hardware when SMBHEN=1 (smbus host configuration), ALERTEN=1 and a SMBALERT event (falling edge) is detected on SMBA pin. It is cleared by software by setting the ALERTCF bit. Note: this bit is cleared by hardware when PE=0. If the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_ISR_BUSY_POS             INT32_C(15)   /** @brief Bus busy this flag indicates that a communication is in progress on the bus. It is set by hardware when a START condition is detected. It is cleared by hardware when a stop condition is detected, or when PE=0.. */
  #define I2C4_ISR_DIR_POS              INT32_C(16)   /** @brief Transfer direction (slave mode) this flag is updated when an address match event occurs (ADDR=1).. */
  #define I2C4_ISR_ADDCODE_POS          INT32_C(17)   /** @brief Address match code (slave mode) these bits are updated with the received address when an address match event occurs (ADDR = 1). In the case of a 10-bit address, ADDCODE provides the 10-bit header followed by the 2 msbs of the address.. */
  #define I2C4_ICR_ADDRCF_POS           INT32_C(3)    /** @brief Address matched flag clear writing 1 to this bit clears the ADDR flag in the I2C_ISR register. Writing 1 to this bit also clears the START bit in the I2C_CR2 register.. */
  #define I2C4_ICR_NACKCF_POS           INT32_C(4)    /** @brief Not acknowledge flag clear writing 1 to this bit clears the ACKF flag in I2C_ISR register.. */
  #define I2C4_ICR_STOPCF_POS           INT32_C(5)    /** @brief Stop detection flag clear writing 1 to this bit clears the STOPF flag in the I2C_ISR register.. */
  #define I2C4_ICR_BERRCF_POS           INT32_C(8)    /** @brief Bus error flag clear writing 1 to this bit clears the BERRF flag in the I2C_ISR register.. */
  #define I2C4_ICR_ARLOCF_POS           INT32_C(9)    /** @brief Arbitration lost flag clear writing 1 to this bit clears the ARLO flag in the I2C_ISR register.. */
  #define I2C4_ICR_OVRCF_POS            INT32_C(10)   /** @brief Overrun/Underrun flag clear writing 1 to this bit clears the OVR flag in the I2C_ISR register.. */
  #define I2C4_ICR_PECCF_POS            INT32_C(11)   /** @brief PEC error flag clear writing 1 to this bit clears the PECERR flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_ICR_TIMOUTCF_POS         INT32_C(12)   /** @brief Timeout detection flag clear writing 1 to this bit clears the TIMEOUT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_ICR_ALERTCF_POS          INT32_C(13)   /** @brief Alert flag clear writing 1 to this bit clears the ALERT flag in the I2C_ISR register. Note: if the smbus feature is not supported, this bit is reserved and forced by hardware to 0. Please refer to section25.3: I2C implementation.. */
  #define I2C4_PECR_PEC_POS             INT32_C(0)    /** @brief Packet error checking register this field contains the internal PEC when PECEN=1. The PEC is cleared by hardware when PE=0.. */
  #define I2C4_RXDR_RXDATA_POS          INT32_C(0)    /** @brief 8-bit receive data data byte received from the I2C bus.. */
  #define I2C4_TXDR_TXDATA_POS          INT32_C(0)    /** @brief 8-bit transmit data data byte to be transmitted to the I2C bus. Note: these bits can be written only when TXE=1.. */

  /*************************************************************************************************
   * @section GPIOA Definitions
   *************************************************************************************************/

  /**** @subsection Register Definitions ****/

  #define GPIOA_MODER_PTR     (*(RW_ uint32_t*)UINT32_C(0x58020000))   /** @brief GPIO port mode register. */
  #define GPIOA_OTYPER_PTR    (*(RW_ uint32_t*)UINT32_C(0x58020004))   /** @brief GPIO port output type register. */
  #define GPIOA_OSPEEDR_PTR   (*(RW_ uint32_t*)UINT32_C(0x58020008))   /** @brief GPIO port output speed register. */
  #define GPIOA_PUPDR_PTR     (*(RW_ uint32_t*)UINT32_C(0x5802000C))   /** @brief GPIO port pull-up/pull-down register. */
  #define GPIOA_IDR_PTR       (*(RO_ uint32_t*)UINT32_C(0x58020010))   /** @brief GPIO port input data register. */
  #define GPIOA_ODR_PTR       (*(RW_ uint32_t*)UINT32_C(0x58020014))   /** @brief GPIO port output data register. */
  #define GPIOA_BSRR_PTR      (*(WO_ uint32_t*)UINT32_C(0x58020018))   /** @brief GPIO port bit set/reset register. */
  #define GPIOA_LCKR_PTR      (*(RW_ uint32_t*)UINT32_C(0x5802001C))   /** @brief This register is used to lock the configuration of the port bits when a correct write sequence is applied to bit 16 (LCKK). The value of bits [15:0] is used to lock the configuration of the GPIO. During the write sequence, the value of LCKR[15:0] must not change. When the LOCK sequence has been applied on a port bit, the value of this port bit can no longer be modified until the next MCU reset or peripheral reset.a specific write sequence is used to write to the gpiox_lckr register. Only word access (32-bit long) is allowed during this locking sequence.each lock bit freezes a specific configuration register (control and alternate function registers).. */
  #define GPIOA_AFRL_PTR      (*(RW_ uint32_t*)UINT32_C(0x58020020))   /** @brief GPIO alternate function low register. */
  #define GPIOA_AFRH_PTR      (*(RW_ uint32_t*)UINT32_C(0x58020024))   /** @brief GPIO alternate function high register. */

