  #define GPIOA_MODER_MODE3_MSK        UINT32_C(0x000000C0)   /** @brief [1:0]: port x configuration bits (y = 0..15) these bits are written by software to configure the I/O mode.. */
  #define GPIOA_MODER_MODE4_MSK        UINT32_C(0x00000300)   /** @brief [1:0]: port x configuration bits (y = 0..15) these bits are written by software to configure the I/O mode.. */
  #define GPIOA_MODER_MODE5_MSK        UINT32_C(0x00000C00)   /** @brief [1:0]: port x configuration bits (y = 0..15) these bits are written by software to configure the I/O mode.. */
  #define GPIOA_MODER_MODE6_MSK        UINT32_C(0x00003000)   /** @brief [1:0]: port x configuration bits (y = 0..15) these bits are written by software to configure the I/O mode.. */
  #define GPIOA_MODER_MODE7_MSK        UINT32_C(0x0000C000)   /** @brief [1:0]: port x configuration bits (y = 0..15) these bits are written by software to configure the I/O mode.. */
  #define GPIOA_MODER_MODE8_MSK        UINT32_C(0x00030000)   /** @brief [1:0]: port x configuration bits (y = 0..15) these bits are written by software to configure the I/O mode.. */
  #define GPIOA_MODER_MODE9_MSK        UINT32_C(0x000C0000)   /** @brief [1:0]: port x configuration bits (y = 0..15) these bits are written by software to configure the I/O mode.. */
  #define GPIOA_MODER_MODE10_MSK       UINT32_C(0x00300000)   /** @brief [1:0]: port x configuration bits (y = 0..15) these bits are written by software to configure the I/O mode.. */
  #define GPIOA_MODER_MODE11_MSK       UINT32_C(0x00C00000)   /** @brief [1:0]: port x configuration bits (y = 0..15) these bits are written by software to configure the I/O mode.. */
  #define GPIOA_MODER_MODE12_MSK       UINT32_C(0x03000000)   /** @brief [1:0]: port x configuration bits (y = 0..15) these bits are written by software to configure the I/O mode.. */
  #define GPIOA_MODER_MODE13_MSK       UINT32_C(0x0C000000)   /** @brief [1:0]: port x configuration bits (y = 0..15) these bits are written by software to configure the I/O mode.. */
  #define GPIOA_MODER_MODE14_MSK       UINT32_C(0x30000000)   /** @brief [1:0]: port x configuration bits (y = 0..15) these bits are written by software to configure the I/O mode.. */
  #define GPIOA_MODER_MODE15_MSK       UINT32_C(0xC0000000)   /** @brief [1:0]: port x configuration bits (y = 0..15) these bits are written by software to configure the I/O mode.. */
  #define GPIOA_OTYPER_OT0_MSK         UINT32_C(0x00000001)   /** @brief Port x configuration bits (y = 0..15) these bits are written by software to configure the I/O output type.. */
