  #define GPIOD_OSPEEDR_PTR   (*(RW_ uint32_t*)UINT32_C(0x58020C08))   /** @brief GPIO port output speed register. */
  #define GPIOD_PUPDR_PTR     (*(RW_ uint32_t*)UINT32_C(0x58020C0C))   /** @brief GPIO port pull-up/pull-down register. */
  #define GPIOD_IDR_PTR       (*(RO_ uint32_t*)UINT32_C(0x58020C10))   /** @brief GPIO port input data register. */
  #define GPIOD_ODR_PTR       (*(RW_ uint32_t*)UINT32_C(0x58020C14))   /** @brief GPIO port output data register. */
  #define GPIOD_BSRR_PTR      (*(WO_ uint32_t*)UINT32_C(0x58020C18))   /** @brief GPIO port bit set/reset register. */
  #define GPIOD_LCKR_PTR      (*(RW_ uint32_t*)UINT32_C(0x58020C1C))   /** @brief This register is used to lock the configuration of the port bits when a correct write sequence is applied to bit 16 (LCKK). The value of bits [15:0] is used to lock the configuration of the GPIO. During the write sequence, the value of LCKR[15:0] must not change. When the LOCK sequence has been applied on a port bit, the value of this port bit can no longer be modified until the next MCU reset or peripheral reset.a specific write sequence is used to write to the gpiox_lckr register. Only word access (32-bit long) is allowed during this locking sequence.each lock bit freezes a specific configuration register (control and alternate function registers).. */
  #define GPIOD_AFRL_PTR      (*(RW_ uint32_t*)UINT32_C(0x58020C20))   /** @brief GPIO alternate function low register. */
  #define GPIOD_AFRH_PTR      (*(RW_ uint32_t*)UINT32_C(0x58020C24))   /** @brief GPIO alternate function high register. */

