  /**** @subsection Register Definitions ****/

  #define JPEG_CONFR0_PTR    (*(WO_ uint32_t*)UINT32_C(0x52003000))   /** @brief JPEG codec control register. */
  #define JPEG_CONFR1_PTR    (*(RW_ uint32_t*)UINT32_C(0x52003004))   /** @brief JPEG codec configuration register 1. */
  #define JPEG_CONFR2_PTR    (*(RW_ uint32_t*)UINT32_C(0x52003008))   /** @brief JPEG codec configuration register 2. */
  #define JPEG_CONFR3_PTR    (*(RW_ uint32_t*)UINT32_C(0x5200300C))   /** @brief JPEG codec configuration register 3. */
  #define JPEG_CONFRN1_PTR   (*(RW_ uint32_t*)UINT32_C(0x52003010))   /** @brief JPEG codec configuration register 4-7. */
  #define JPEG_CONFRN2_PTR   (*(RW_ uint32_t*)UINT32_C(0x52003014))   /** @brief JPEG codec configuration register 4-7. */
  #define JPEG_CONFRN3_PTR   (*(RW_ uint32_t*)UINT32_C(0x52003018))   /** @brief JPEG codec configuration register 4-7. */
  #define JPEG_CONFRN4_PTR   (*(RW_ uint32_t*)UINT32_C(0x5200301C))   /** @brief JPEG codec configuration register 4-7. */
  #define JPEG_CR_PTR        (*(RW_ uint32_t*)UINT32_C(0x52003030))   /** @brief JPEG control register. */
  #define JPEG_SR_PTR        (*(RO_ uint32_t*)UINT32_C(0x52003034))   /** @brief JPEG status register. */
  #define JPEG_CFR_PTR       (*(RW_ uint32_t*)UINT32_C(0x52003038))   /** @brief JPEG clear flag register. */
  #define JPEG_DIR_PTR       (*(WO_ uint32_t*)UINT32_C(0x52003040))   /** @brief JPEG data input register. */
  #define JPEG_DOR_PTR       (*(RO_ uint32_t*)UINT32_C(0x52003044))   /** @brief JPEG data output register. */

  /**** @subsection Field Mask Definitions ****/

  #define JPEG_CONFR0_START_MSK         UINT32_C(0x00000001)   /** @brief Start this bit start or stop the encoding or decoding process. Read this register always return 0.. */
  #define JPEG_CONFR1_NF_MSK            UINT32_C(0x00000003)   /** @brief Number of color components this field defines the number of color components minus 1.. */
  #define JPEG_CONFR1_DE_MSK            UINT32_C(0x00000008)   /** @brief Decoding enable this bit selects the coding or decoding process. */
  #define JPEG_CONFR1_COLORSPACE_MSK    UINT32_C(0x00000030)   /** @brief Color space this filed defines the number of quantization tables minus 1 to insert in the output stream.. */
  #define JPEG_CONFR1_NS_MSK            UINT32_C(0x000000C0)   /** @brief Number of components for scan this field defines the number of components minus 1 for scan header marker segment.. */
  #define JPEG_CONFR1_HDR_MSK           UINT32_C(0x00000100)   /** @brief Header processing this bit enable the header processing (generation/parsing).. */
  #define JPEG_CONFR1_YSIZE_MSK         UINT32_C(0xFFFF0000)   /** @brief Y size this field defines the number of lines in source image.. */
  #define JPEG_CONFR2_NMCU_MSK          UINT32_C(0x03FFFFFF)   /** @brief Number of MCU for encoding: this field defines the number of MCU units minus 1 to encode. For decoding: this field indicates the number of complete MCU units minus 1 to be decoded (this field is updated after the JPEG header parsing). If the decoded image size has not a X or Y size multiple of 8 or 16 (depending on the sub-sampling process), the resulting incomplete or empty MCU must be added to this value to get the total number of MCU generated.. */
