  /**** @subsection Field Mask Definitions ****/

  #define MDMA_MDMA_GISR0_GIF0_MSK          UINT32_C(0x00000001)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF1_MSK          UINT32_C(0x00000002)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF2_MSK          UINT32_C(0x00000004)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF3_MSK          UINT32_C(0x00000008)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF4_MSK          UINT32_C(0x00000010)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF5_MSK          UINT32_C(0x00000020)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF6_MSK          UINT32_C(0x00000040)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF7_MSK          UINT32_C(0x00000080)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF8_MSK          UINT32_C(0x00000100)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF9_MSK          UINT32_C(0x00000200)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF10_MSK         UINT32_C(0x00000400)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF11_MSK         UINT32_C(0x00000800)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF12_MSK         UINT32_C(0x00001000)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF13_MSK         UINT32_C(0x00002000)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF14_MSK         UINT32_C(0x00004000)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_GISR0_GIF15_MSK         UINT32_C(0x00008000)   /** @brief Channel x global interrupt flag (x=...) this bit is set and reset by hardware. It is a logical OR of all the channel x interrupt flags (ctcifx, btifx, brtifx, teifx) which are enabled in the interrupt mask register (ctciex, btiex, brtiex, teiex). */
  #define MDMA_MDMA_C0ISR_TEIF0_MSK         UINT32_C(0x00000001)   /** @brief Channel x transfer error interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C0ISR_CTCIF0_MSK        UINT32_C(0x00000002)   /** @brief Channel x channel transfer complete interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register. CTC is set when the last block was transferred and the channel has been automatically disabled. CTC is also set when the channel is suspended, as a result of writing EN bit to 0.. */
  #define MDMA_MDMA_C0ISR_BRTIF0_MSK        UINT32_C(0x00000004)   /** @brief Channel x block repeat transfer complete interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C0ISR_BTIF0_MSK         UINT32_C(0x00000008)   /** @brief Channel x block transfer complete interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C0ISR_TCIF0_MSK         UINT32_C(0x00000010)   /** @brief Channel x buffer transfer complete. */
  #define MDMA_MDMA_C0ISR_CRQA0_MSK         UINT32_C(0x00010000)   /** @brief Channel x request active flag. */
  #define MDMA_MDMA_C0IFCR_CTEIF0_MSK       UINT32_C(0x00000001)   /** @brief Channel x clear transfer error interrupt flag writing a 1 into this bit clears teifx in the mdma_isry register. */
  #define MDMA_MDMA_C0IFCR_CCTCIF0_MSK      UINT32_C(0x00000002)   /** @brief Clear channel transfer complete interrupt flag for channel x writing a 1 into this bit clears ctcifx in the mdma_isry register. */
  #define MDMA_MDMA_C0IFCR_CBRTIF0_MSK      UINT32_C(0x00000004)   /** @brief Channel x clear block repeat transfer complete interrupt flag writing a 1 into this bit clears brtifx in the mdma_isry register. */
  #define MDMA_MDMA_C0IFCR_CBTIF0_MSK       UINT32_C(0x00000008)   /** @brief Channel x clear block transfer complete interrupt flag writing a 1 into this bit clears btifx in the mdma_isry register. */
  #define MDMA_MDMA_C0IFCR_CLTCIF0_MSK      UINT32_C(0x00000010)   /** @brief CLear buffer transfer complete interrupt flag for channel x writing a 1 into this bit clears tcifx in the mdma_isry register. */
  #define MDMA_MDMA_C0ESR_TEA_MSK           UINT32_C(0x0000007F)   /** @brief Transfer error address these bits are set and cleared by HW, in case of an MDMA data transfer error. It is used in conjunction with TED. This field indicates the 7 lsbits of the address which generated a transfer/access error. It may be used by SW to retrieve the failing address, by adding this value (truncated to the buffer transfer length size) to the current SAR/DAR value. Note: the SAR/DAR current value doesnt reflect this last address due to the FIFO management system. The SAR/DAR are only updated at the end of a (buffer) transfer (of TLEN+1 bytes). Note: it is not set in case of a link data error.. */
  #define MDMA_MDMA_C0ESR_TED_MSK           UINT32_C(0x00000080)   /** @brief Transfer error direction these bit is set and cleared by HW, in case of an MDMA data transfer error.. */
  #define MDMA_MDMA_C0ESR_TELD_MSK          UINT32_C(0x00000100)   /** @brief Transfer error link data these bit is set by HW, in case of a transfer error while reading the block link data structure. It is cleared by software writing 1 to the cteifx bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C0ESR_TEMD_MSK          UINT32_C(0x00000200)   /** @brief Transfer error mask data these bit is set by HW, in case of a transfer error while writing the mask data. It is cleared by software writing 1 to the cteifx bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C0ESR_ASE_MSK           UINT32_C(0x00000400)   /** @brief Address/Size error these bit is set by HW, when the programmed address is not aligned with the data size. TED will indicate whether the problem is on the source or destination. It is cleared by software writing 1 to the cteifx bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C0ESR_BSE_MSK           UINT32_C(0x00000800)   /** @brief Block size error these bit is set by HW, when the block size is not an integer multiple of the data size either for source or destination. TED will indicate whether the problem is on the source or destination. It is cleared by software writing 1 to the cteifx bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C0CR_EN_MSK             UINT32_C(0x00000001)   /** @brief Channel enable. */
  #define MDMA_MDMA_C0CR_TEIE_MSK           UINT32_C(0x00000002)   /** @brief Transfer error interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C0CR_CTCIE_MSK          UINT32_C(0x00000004)   /** @brief Channel transfer complete interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C0CR_BRTIE_MSK          UINT32_C(0x00000008)   /** @brief Block repeat transfer interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C0CR_BTIE_MSK           UINT32_C(0x00000010)   /** @brief Block transfer interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C0CR_TCIE_MSK           UINT32_C(0x00000020)   /** @brief Buffer transfer complete interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C0CR_PL_MSK             UINT32_C(0x000000C0)   /** @brief Priority level these bits are set and cleared by software. These bits are protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C0CR_BEX_MSK            UINT32_C(0x00001000)   /** @brief Byte endianness exchange. */
  #define MDMA_MDMA_C0CR_HEX_MSK            UINT32_C(0x00002000)   /** @brief Half word endianes exchange. */
  #define MDMA_MDMA_C0CR_WEX_MSK            UINT32_C(0x00004000)   /** @brief Word endianness exchange. */
  #define MDMA_MDMA_C0CR_SWRQ_MSK           UINT32_C(0x00010000)   /** @brief SW request writing a 1 into this bit sets the crqax in mdma_isry register, activating the request on channel x note: either the whole cxcr register or the 8-bit/16-bit register @ address offset: 0x4e + 0x40 chn may be used for SWRQ activation. In case of a SW request, acknowledge is not generated (neither HW signal, nor cxmar write access).. */
  #define MDMA_MDMA_C0TCR_SINC_MSK          UINT32_C(0x00000003)   /** @brief Source increment mode these bits are set and cleared by software. These bits are protected and can be written only if EN is 0 note: when source is AHB (SBUS=1), SINC = 00 is forbidden. In linked list mode, at the end of a block (single or last block in repeated block transfer mode), this register will be loaded from memory (from address given by current LAR[31:0] + 0x00).. */
  #define MDMA_MDMA_C0TCR_DINC_MSK          UINT32_C(0x0000000C)   /** @brief Destination increment mode these bits are set and cleared by software. These bits are protected and can be written only if EN is 0 note: when destination is AHB (DBUS=1), DINC = 00 is forbidden.. */
  #define MDMA_MDMA_C0TCR_SSIZE_MSK         UINT32_C(0x00000030)   /** @brief Source data size these bits are set and cleared by software. These bits are protected and can be written only if EN is 0 note: if a value of 11 is programmed for the TCM access/ahb port, a transfer error will occur (TEIF bit set) if SINCOS &lt; SSIZE and SINC &#8800; 00, the result will be unpredictable. Note: SSIZE = 11 (double-word) is forbidden when source is TCM/AHB bus (SBUS=1).. */
  #define MDMA_MDMA_C0TCR_DSIZE_MSK         UINT32_C(0x000000C0)   /** @brief Destination data size these bits are set and cleared by software. These bits are protected and can be written only if EN is 0. Note: if a value of 11 is programmed for the TCM access/ahb port, a transfer error will occur (TEIF bit set) if DINCOS &lt; DSIZE and DINC &#8800; 00, the result will be unpredictable. Note: DSIZE = 11 (double-word) is forbidden when destination is TCM/AHB bus (DBUS=1).. */
  #define MDMA_MDMA_C0TCR_SINCOS_MSK        UINT32_C(0x00000300)   /** @brief Source increment offset size. */
  #define MDMA_MDMA_C0TCR_DINCOS_MSK        UINT32_C(0x00000C00)   /** @brief Destination increment offset. */
  #define MDMA_MDMA_C0TCR_SBURST_MSK        UINT32_C(0x00007000)   /** @brief Source burst transfer configuration. */
  #define MDMA_MDMA_C0TCR_DBURST_MSK        UINT32_C(0x00038000)   /** @brief Destination burst transfer configuration. */
  #define MDMA_MDMA_C0TCR_TLEN_MSK          UINT32_C(0x01FC0000)   /** @brief Buffer transfer lengh. */
  #define MDMA_MDMA_C0TCR_PKE_MSK           UINT32_C(0x02000000)   /** @brief PacK enable these bit is set and cleared by software. If the source size is smaller than the destination, it will be padded according to the PAM value. If the source data size is larger than the destination one, it will be truncated. The alignment will be done according to the PAM[0] value. This bit is protected and can be written only if EN is 0. */
  #define MDMA_MDMA_C0TCR_PAM_MSK           UINT32_C(0x0C000000)   /** @brief Padding/Alignement mode these bits are set and cleared by software. Case 1: source data size smaller than destination data size - 3 options are valid. Case 2: source data size larger than destination data size. The remainder part is discarded. When PKE = 1 or DSIZE=SSIZE, these bits are ignored. These bits are protected and can be written only if EN is 0. */
  #define MDMA_MDMA_C0TCR_TRGM_MSK          UINT32_C(0x30000000)   /** @brief Trigger mode these bits are set and cleared by software. Note: if TRGM is 11 for the current block, all the values loaded at the end of the current block through the linked list mechanism must keep the same value (TRGM=11) and the same SWRM value, otherwise the result is undefined. These bits are protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C0TCR_SWRM_MSK          UINT32_C(0x40000000)   /** @brief SW request mode this bit is set and cleared by software. If a HW or SW request is currently active, the bit change will be delayed until the current transfer is completed. If the cxmar contains a valid address, the cxmdr value will also be written @ cxmar address. This bit is protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C0TCR_BWM_MSK           UINT32_C(0x80000000)   /** @brief Bufferable write mode this bit is set and cleared by software. This bit is protected and can be written only if EN is 0. Note: all MDMA destination accesses are non-cacheable.. */
  #define MDMA_MDMA_C0BNDTR_BNDT_MSK        UINT32_C(0x0001FFFF)   /** @brief Block number of data to transfer. */
  #define MDMA_MDMA_C0BNDTR_BRSUM_MSK       UINT32_C(0x00040000)   /** @brief Block repeat source address update mode these bits are protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C0BNDTR_BRDUM_MSK       UINT32_C(0x00080000)   /** @brief Block repeat destination address update mode these bits are protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C0BNDTR_BRC_MSK         UINT32_C(0xFFF00000)   /** @brief Block repeat count this field contains the number of repetitions of the current block (0 to 4095). When the channel is enabled, this register is read-only, indicating the remaining number of blocks, excluding the current one. This register decrements after each complete block transfer. Once the last block transfer has completed, this register can either stay at zero or be reloaded automatically from memory (in linked list mode - i.e. Link address valid). These bits are protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C0SAR_SAR_MSK           UINT32_C(0xFFFFFFFF)   /** @brief Source adr base. */
  #define MDMA_MDMA_C0DAR_DAR_MSK           UINT32_C(0xFFFFFFFF)   /** @brief Destination adr base. */
  #define MDMA_MDMA_C0BRUR_SUV_MSK          UINT32_C(0x0000FFFF)   /** @brief Source adresse update value. */
  #define MDMA_MDMA_C0BRUR_DUV_MSK          UINT32_C(0xFFFF0000)   /** @brief Destination address update. */
  #define MDMA_MDMA_C0LAR_LAR_MSK           UINT32_C(0xFFFFFFFF)   /** @brief Link address register. */
  #define MDMA_MDMA_C0TBR_TSEL_MSK          UINT32_C(0x0000003F)   /** @brief Trigger selection. */
  #define MDMA_MDMA_C0TBR_SBUS_MSK          UINT32_C(0x00010000)   /** @brief Source BUS select this bit is protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C0TBR_DBUS_MSK          UINT32_C(0x00020000)   /** @brief Destination BUS slect this bit is protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C0MAR_MAR_MSK           UINT32_C(0xFFFFFFFF)   /** @brief Mask address. */
  #define MDMA_MDMA_C0MDR_MDR_MSK           UINT32_C(0xFFFFFFFF)   /** @brief Mask data. */
  #define MDMA_MDMA_C1ISR_TEIF1_MSK         UINT32_C(0x00000001)   /** @brief Channel x transfer error interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C1ISR_CTCIF1_MSK        UINT32_C(0x00000002)   /** @brief Channel x channel transfer complete interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register. CTC is set when the last block was transferred and the channel has been automatically disabled. CTC is also set when the channel is suspended, as a result of writing EN bit to 0.. */
  #define MDMA_MDMA_C1ISR_BRTIF1_MSK        UINT32_C(0x00000004)   /** @brief Channel x block repeat transfer complete interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C1ISR_BTIF1_MSK         UINT32_C(0x00000008)   /** @brief Channel x block transfer complete interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C1ISR_TCIF1_MSK         UINT32_C(0x00000010)   /** @brief Channel x buffer transfer complete. */
  #define MDMA_MDMA_C1ISR_CRQA1_MSK         UINT32_C(0x00010000)   /** @brief Channel x request active flag. */
  #define MDMA_MDMA_C1IFCR_CTEIF1_MSK       UINT32_C(0x00000001)   /** @brief Channel x clear transfer error interrupt flag writing a 1 into this bit clears teifx in the mdma_isry register. */
  #define MDMA_MDMA_C1IFCR_CCTCIF1_MSK      UINT32_C(0x00000002)   /** @brief Clear channel transfer complete interrupt flag for channel x writing a 1 into this bit clears ctcifx in the mdma_isry register. */
  #define MDMA_MDMA_C1IFCR_CBRTIF1_MSK      UINT32_C(0x00000004)   /** @brief Channel x clear block repeat transfer complete interrupt flag writing a 1 into this bit clears brtifx in the mdma_isry register. */
  #define MDMA_MDMA_C1IFCR_CBTIF1_MSK       UINT32_C(0x00000008)   /** @brief Channel x clear block transfer complete interrupt flag writing a 1 into this bit clears btifx in the mdma_isry register. */
  #define MDMA_MDMA_C1IFCR_CLTCIF1_MSK      UINT32_C(0x00000010)   /** @brief CLear buffer transfer complete interrupt flag for channel x writing a 1 into this bit clears tcifx in the mdma_isry register. */
  #define MDMA_MDMA_C1ESR_TEA_MSK           UINT32_C(0x0000007F)   /** @brief Transfer error address these bits are set and cleared by HW, in case of an MDMA data transfer error. It is used in conjunction with TED. This field indicates the 7 lsbits of the address which generated a transfer/access error. It may be used by SW to retrieve the failing address, by adding this value (truncated to the buffer transfer length size) to the current SAR/DAR value. Note: the SAR/DAR current value doesnt reflect this last address due to the FIFO management system. The SAR/DAR are only updated at the end of a (buffer) transfer (of TLEN+1 bytes). Note: it is not set in case of a link data error.. */
  #define MDMA_MDMA_C1ESR_TED_MSK           UINT32_C(0x00000080)   /** @brief Transfer error direction these bit is set and cleared by HW, in case of an MDMA data transfer error.. */
  #define MDMA_MDMA_C1ESR_TELD_MSK          UINT32_C(0x00000100)   /** @brief Transfer error link data these bit is set by HW, in case of a transfer error while reading the block link data structure. It is cleared by software writing 1 to the cteifx bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C1ESR_TEMD_MSK          UINT32_C(0x00000200)   /** @brief Transfer error mask data these bit is set by HW, in case of a transfer error while writing the mask data. It is cleared by software writing 1 to the cteifx bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C1ESR_ASE_MSK           UINT32_C(0x00000400)   /** @brief Address/Size error these bit is set by HW, when the programmed address is not aligned with the data size. TED will indicate whether the problem is on the source or destination. It is cleared by software writing 1 to the cteifx bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C1ESR_BSE_MSK           UINT32_C(0x00000800)   /** @brief Block size error these bit is set by HW, when the block size is not an integer multiple of the data size either for source or destination. TED will indicate whether the problem is on the source or destination. It is cleared by software writing 1 to the cteifx bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C1CR_EN_MSK             UINT32_C(0x00000001)   /** @brief Channel enable. */
  #define MDMA_MDMA_C1CR_TEIE_MSK           UINT32_C(0x00000002)   /** @brief Transfer error interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C1CR_CTCIE_MSK          UINT32_C(0x00000004)   /** @brief Channel transfer complete interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C1CR_BRTIE_MSK          UINT32_C(0x00000008)   /** @brief Block repeat transfer interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C1CR_BTIE_MSK           UINT32_C(0x00000010)   /** @brief Block transfer interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C1CR_TCIE_MSK           UINT32_C(0x00000020)   /** @brief Buffer transfer complete interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C1CR_PL_MSK             UINT32_C(0x000000C0)   /** @brief Priority level these bits are set and cleared by software. These bits are protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C1CR_BEX_MSK            UINT32_C(0x00001000)   /** @brief Byte endianness exchange. */
  #define MDMA_MDMA_C1CR_HEX_MSK            UINT32_C(0x00002000)   /** @brief Half word endianes exchange. */
  #define MDMA_MDMA_C1CR_WEX_MSK            UINT32_C(0x00004000)   /** @brief Word endianness exchange. */
  #define MDMA_MDMA_C1CR_SWRQ_MSK           UINT32_C(0x00010000)   /** @brief SW request writing a 1 into this bit sets the crqax in mdma_isry register, activating the request on channel x note: either the whole cxcr register or the 8-bit/16-bit register @ address offset: 0x4e + 0x40 chn may be used for SWRQ activation. In case of a SW request, acknowledge is not generated (neither HW signal, nor cxmar write access).. */
  #define MDMA_MDMA_C1TCR_SINC_MSK          UINT32_C(0x00000003)   /** @brief Source increment mode these bits are set and cleared by software. These bits are protected and can be written only if EN is 0 note: when source is AHB (SBUS=1), SINC = 00 is forbidden. In linked list mode, at the end of a block (single or last block in repeated block transfer mode), this register will be loaded from memory (from address given by current LAR[31:0] + 0x00).. */
  #define MDMA_MDMA_C1TCR_DINC_MSK          UINT32_C(0x0000000C)   /** @brief Destination increment mode these bits are set and cleared by software. These bits are protected and can be written only if EN is 0 note: when destination is AHB (DBUS=1), DINC = 00 is forbidden.. */
  #define MDMA_MDMA_C1TCR_SSIZE_MSK         UINT32_C(0x00000030)   /** @brief Source data size these bits are set and cleared by software. These bits are protected and can be written only if EN is 0 note: if a value of 11 is programmed for the TCM access/ahb port, a transfer error will occur (TEIF bit set) if SINCOS &lt; SSIZE and SINC &#8800; 00, the result will be unpredictable. Note: SSIZE = 11 (double-word) is forbidden when source is TCM/AHB bus (SBUS=1).. */
