  #define MDMA_MDMA_C3ESR_BSE_POS           INT32_C(11)   /** @brief Block size error these bit is set by HW, when the block size is not an integer multiple of the data size either for source or destination. TED will indicate whether the problem is on the source or destination. It is cleared by software writing 1 to the cteifx bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C3CR_EN_POS             INT32_C(0)    /** @brief Channel enable. */
  #define MDMA_MDMA_C3CR_TEIE_POS           INT32_C(1)    /** @brief Transfer error interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C3CR_CTCIE_POS          INT32_C(2)    /** @brief Channel transfer complete interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C3CR_BRTIE_POS          INT32_C(3)    /** @brief Block repeat transfer interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C3CR_BTIE_POS           INT32_C(4)    /** @brief Block transfer interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C3CR_TCIE_POS           INT32_C(5)    /** @brief Buffer transfer complete interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C3CR_PL_POS             INT32_C(6)    /** @brief Priority level these bits are set and cleared by software. These bits are protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C3CR_BEX_POS            INT32_C(12)   /** @brief Byte endianness exchange. */
  #define MDMA_MDMA_C3CR_HEX_POS            INT32_C(13)   /** @brief Half word endianes exchange. */
  #define MDMA_MDMA_C3CR_WEX_POS            INT32_C(14)   /** @brief Word endianness exchange. */
  #define MDMA_MDMA_C3CR_SWRQ_POS           INT32_C(16)   /** @brief SW request writing a 1 into this bit sets the crqax in mdma_isry register, activating the request on channel x note: either the whole cxcr register or the 8-bit/16-bit register @ address offset: 0x4e + 0x40 chn may be used for SWRQ activation. In case of a SW request, acknowledge is not generated (neither HW signal, nor cxmar write access).. */
  #define MDMA_MDMA_C3TCR_SINC_POS          INT32_C(0)    /** @brief Source increment mode these bits are set and cleared by software. These bits are protected and can be written only if EN is 0 note: when source is AHB (SBUS=1), SINC = 00 is forbidden. In linked list mode, at the end of a block (single or last block in repeated block transfer mode), this register will be loaded from memory (from address given by current LAR[31:0] + 0x00).. */
  #define MDMA_MDMA_C3TCR_DINC_POS          INT32_C(2)    /** @brief Destination increment mode these bits are set and cleared by software. These bits are protected and can be written only if EN is 0 note: when destination is AHB (DBUS=1), DINC = 00 is forbidden.. */
  #define MDMA_MDMA_C3TCR_SSIZE_POS         INT32_C(4)    /** @brief Source data size these bits are set and cleared by software. These bits are protected and can be written only if EN is 0 note: if a value of 11 is programmed for the TCM access/ahb port, a transfer error will occur (TEIF bit set) if SINCOS &lt; SSIZE and SINC &#8800; 00, the result will be unpredictable. Note: SSIZE = 11 (double-word) is forbidden when source is TCM/AHB bus (SBUS=1).. */
  #define MDMA_MDMA_C3TCR_DSIZE_POS         INT32_C(6)    /** @brief Destination data size these bits are set and cleared by software. These bits are protected and can be written only if EN is 0. Note: if a value of 11 is programmed for the TCM access/ahb port, a transfer error will occur (TEIF bit set) if DINCOS &lt; DSIZE and DINC &#8800; 00, the result will be unpredictable. Note: DSIZE = 11 (double-word) is forbidden when destination is TCM/AHB bus (DBUS=1).. */
  #define MDMA_MDMA_C3TCR_SINCOS_POS        INT32_C(8)    /** @brief Source increment offset size. */
  #define MDMA_MDMA_C3TCR_DINCOS_POS        INT32_C(10)   /** @brief Destination increment offset. */
  #define MDMA_MDMA_C3TCR_SBURST_POS        INT32_C(12)   /** @brief Source burst transfer configuration. */
  #define MDMA_MDMA_C3TCR_DBURST_POS        INT32_C(15)   /** @brief Destination burst transfer configuration. */
  #define MDMA_MDMA_C3TCR_TLEN_POS          INT32_C(18)   /** @brief Buffer transfer lengh. */
  #define MDMA_MDMA_C3TCR_PKE_POS           INT32_C(25)   /** @brief PacK enable these bit is set and cleared by software. If the source size is smaller than the destination, it will be padded according to the PAM value. If the source data size is larger than the destination one, it will be truncated. The alignment will be done according to the PAM[0] value. This bit is protected and can be written only if EN is 0. */
  #define MDMA_MDMA_C3TCR_PAM_POS           INT32_C(26)   /** @brief Padding/Alignement mode these bits are set and cleared by software. Case 1: source data size smaller than destination data size - 3 options are valid. Case 2: source data size larger than destination data size. The remainder part is discarded. When PKE = 1 or DSIZE=SSIZE, these bits are ignored. These bits are protected and can be written only if EN is 0. */
  #define MDMA_MDMA_C3TCR_TRGM_POS          INT32_C(28)   /** @brief Trigger mode these bits are set and cleared by software. Note: if TRGM is 11 for the current block, all the values loaded at the end of the current block through the linked list mechanism must keep the same value (TRGM=11) and the same SWRM value, otherwise the result is undefined. These bits are protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C3TCR_SWRM_POS          INT32_C(30)   /** @brief SW request mode this bit is set and cleared by software. If a HW or SW request is currently active, the bit change will be delayed until the current transfer is completed. If the cxmar contains a valid address, the cxmdr value will also be written @ cxmar address. This bit is protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C3TCR_BWM_POS           INT32_C(31)   /** @brief Bufferable write mode this bit is set and cleared by software. This bit is protected and can be written only if EN is 0. Note: all MDMA destination accesses are non-cacheable.. */
