  #define MDMA_MDMA_C6CR_CTCIE_POS          INT32_C(2)    /** @brief Channel transfer complete interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C6CR_BRTIE_POS          INT32_C(3)    /** @brief Block repeat transfer interrupt enable this bit is set and cleared by software.. */
