  #define MDMA_MDMA_C8CR_BRTIE_POS          INT32_C(3)    /** @brief Block repeat transfer interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C8CR_BTIE_POS           INT32_C(4)    /** @brief Block transfer interrupt enable this bit is set and cleared by software.. */
  #define MDMA_MDMA_C8CR_TCIE_POS           INT32_C(5)    /** @brief Buffer transfer complete interrupt enable this bit is set and cleared by software.. */
