  #define MDMA_MDMA_C9TCR_PAM_POS           INT32_C(26)   /** @brief Padding/Alignement mode these bits are set and cleared by software. Case 1: source data size smaller than destination data size - 3 options are valid. Case 2: source data size larger than destination data size. The remainder part is discarded. When PKE = 1 or DSIZE=SSIZE, these bits are ignored. These bits are protected and can be written only if EN is 0. */
  #define MDMA_MDMA_C9TCR_TRGM_POS          INT32_C(28)   /** @brief Trigger mode these bits are set and cleared by software. Note: if TRGM is 11 for the current block, all the values loaded at the end of the current block through the linked list mechanism must keep the same value (TRGM=11) and the same SWRM value, otherwise the result is undefined. These bits are protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C9TCR_SWRM_POS          INT32_C(30)   /** @brief SW request mode this bit is set and cleared by software. If a HW or SW request is currently active, the bit change will be delayed until the current transfer is completed. If the cxmar contains a valid address, the cxmdr value will also be written @ cxmar address. This bit is protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C9TCR_BWM_POS           INT32_C(31)   /** @brief Bufferable write mode this bit is set and cleared by software. This bit is protected and can be written only if EN is 0. Note: all MDMA destination accesses are non-cacheable.. */
  #define MDMA_MDMA_C9BNDTR_BNDT_POS        INT32_C(0)    /** @brief Block number of data to transfer. */
  #define MDMA_MDMA_C9BNDTR_BRSUM_POS       INT32_C(18)   /** @brief Block repeat source address update mode these bits are protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C9BNDTR_BRDUM_POS       INT32_C(19)   /** @brief Block repeat destination address update mode these bits are protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C9BNDTR_BRC_POS         INT32_C(20)   /** @brief Block repeat count this field contains the number of repetitions of the current block (0 to 4095). When the channel is enabled, this register is read-only, indicating the remaining number of blocks, excluding the current one. This register decrements after each complete block transfer. Once the last block transfer has completed, this register can either stay at zero or be reloaded automatically from memory (in linked list mode - i.e. Link address valid). These bits are protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C9SAR_SAR_POS           INT32_C(0)    /** @brief Source adr base. */
  #define MDMA_MDMA_C9DAR_DAR_POS           INT32_C(0)    /** @brief Destination adr base. */
  #define MDMA_MDMA_C9BRUR_SUV_POS          INT32_C(0)    /** @brief Source adresse update value. */
  #define MDMA_MDMA_C9BRUR_DUV_POS          INT32_C(16)   /** @brief Destination address update. */
  #define MDMA_MDMA_C9LAR_LAR_POS           INT32_C(0)    /** @brief Link address register. */
  #define MDMA_MDMA_C9TBR_TSEL_POS          INT32_C(0)    /** @brief Trigger selection. */
  #define MDMA_MDMA_C9TBR_SBUS_POS          INT32_C(16)   /** @brief Source BUS select this bit is protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C9TBR_DBUS_POS          INT32_C(17)   /** @brief Destination BUS slect this bit is protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C9MAR_MAR_POS           INT32_C(0)    /** @brief Mask address. */
  #define MDMA_MDMA_C9MDR_MDR_POS           INT32_C(0)    /** @brief Mask data. */
  #define MDMA_MDMA_C10ISR_TEIF10_POS       INT32_C(0)    /** @brief Channel x transfer error interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C10ISR_CTCIF10_POS      INT32_C(1)    /** @brief Channel x channel transfer complete interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register. CTC is set when the last block was transferred and the channel has been automatically disabled. CTC is also set when the channel is suspended, as a result of writing EN bit to 0.. */
  #define MDMA_MDMA_C10ISR_BRTIF10_POS      INT32_C(2)    /** @brief Channel x block repeat transfer complete interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C10ISR_BTIF10_POS       INT32_C(3)    /** @brief Channel x block transfer complete interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register.. */
