  #define MDMA_MDMA_C11BNDTR_BRC_POS        INT32_C(20)   /** @brief Block repeat count this field contains the number of repetitions of the current block (0 to 4095). When the channel is enabled, this register is read-only, indicating the remaining number of blocks, excluding the current one. This register decrements after each complete block transfer. Once the last block transfer has completed, this register can either stay at zero or be reloaded automatically from memory (in linked list mode - i.e. Link address valid). These bits are protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C11SAR_SAR_POS          INT32_C(0)    /** @brief Source adr base. */
  #define MDMA_MDMA_C11DAR_DAR_POS          INT32_C(0)    /** @brief Destination adr base. */
  #define MDMA_MDMA_C11BRUR_SUV_POS         INT32_C(0)    /** @brief Source adresse update value. */
  #define MDMA_MDMA_C11BRUR_DUV_POS         INT32_C(16)   /** @brief Destination address update. */
  #define MDMA_MDMA_C11LAR_LAR_POS          INT32_C(0)    /** @brief Link address register. */
  #define MDMA_MDMA_C11TBR_TSEL_POS         INT32_C(0)    /** @brief Trigger selection. */
  #define MDMA_MDMA_C11TBR_SBUS_POS         INT32_C(16)   /** @brief Source BUS select this bit is protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C11TBR_DBUS_POS         INT32_C(17)   /** @brief Destination BUS slect this bit is protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C11MAR_MAR_POS          INT32_C(0)    /** @brief Mask address. */
  #define MDMA_MDMA_C11MDR_MDR_POS          INT32_C(0)    /** @brief Mask data. */
  #define MDMA_MDMA_C12ISR_TEIF12_POS       INT32_C(0)    /** @brief Channel x transfer error interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C12ISR_CTCIF12_POS      INT32_C(1)    /** @brief Channel x channel transfer complete interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register. CTC is set when the last block was transferred and the channel has been automatically disabled. CTC is also set when the channel is suspended, as a result of writing EN bit to 0.. */
  #define MDMA_MDMA_C12ISR_BRTIF12_POS      INT32_C(2)    /** @brief Channel x block repeat transfer complete interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C12ISR_BTIF12_POS       INT32_C(3)    /** @brief Channel x block transfer complete interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register.. */
