  #define MDMA_MDMA_C14TBR_SBUS_POS         INT32_C(16)   /** @brief Source BUS select this bit is protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C14TBR_DBUS_POS         INT32_C(17)   /** @brief Destination BUS slect this bit is protected and can be written only if EN is 0.. */
  #define MDMA_MDMA_C14MAR_MAR_POS          INT32_C(0)    /** @brief Mask address. */
  #define MDMA_MDMA_C14MDR_MDR_POS          INT32_C(0)    /** @brief Mask data. */
  #define MDMA_MDMA_C15ISR_TEIF15_POS       INT32_C(0)    /** @brief Channel x transfer error interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register.. */
  #define MDMA_MDMA_C15ISR_CTCIF15_POS      INT32_C(1)    /** @brief Channel x channel transfer complete interrupt flag this bit is set by hardware. It is cleared by software writing 1 to the corresponding bit in the dma_ifcry register. CTC is set when the last block was transferred and the channel has been automatically disabled. CTC is also set when the channel is suspended, as a result of writing EN bit to 0.. */
