  /**** @subsection Register Definitions ****/

  #define QUADSPI_CR_PTR      (*(RW_ uint32_t*)UINT32_C(0x52005000))   /** @brief QUADSPI control register. */
  #define QUADSPI_DCR_PTR     (*(RW_ uint32_t*)UINT32_C(0x52005004))   /** @brief QUADSPI device configuration register. */
  #define QUADSPI_SR_PTR      (*(RO_ uint32_t*)UINT32_C(0x52005008))   /** @brief QUADSPI status register. */
  #define QUADSPI_FCR_PTR     (*(RW_ uint32_t*)UINT32_C(0x5200500C))   /** @brief QUADSPI flag clear register. */
  #define QUADSPI_DLR_PTR     (*(RW_ uint32_t*)UINT32_C(0x52005010))   /** @brief QUADSPI data length register. */
  #define QUADSPI_CCR_PTR     (*(RW_ uint32_t*)UINT32_C(0x52005014))   /** @brief QUADSPI communication configuration register. */
  #define QUADSPI_AR_PTR      (*(RW_ uint32_t*)UINT32_C(0x52005018))   /** @brief QUADSPI address register. */
  #define QUADSPI_ABR_PTR     (*(RW_ uint32_t*)UINT32_C(0x5200501C))   /** @brief QUADSPI alternate bytes registers. */
  #define QUADSPI_DR_PTR      (*(RW_ uint32_t*)UINT32_C(0x52005020))   /** @brief QUADSPI data register. */
  #define QUADSPI_PSMKR_PTR   (*(RW_ uint32_t*)UINT32_C(0x52005024))   /** @brief QUADSPI polling status mask register. */
  #define QUADSPI_PSMAR_PTR   (*(RW_ uint32_t*)UINT32_C(0x52005028))   /** @brief QUADSPI polling status match register. */
  #define QUADSPI_PIR_PTR     (*(RW_ uint32_t*)UINT32_C(0x5200502C))   /** @brief QUADSPI polling interval register. */
  #define QUADSPI_LPTR_PTR    (*(RW_ uint32_t*)UINT32_C(0x52005030))   /** @brief QUADSPI low-power timeout register. */

  /**** @subsection Field Mask Definitions ****/

  #define QUADSPI_CR_EN_MSK               UINT32_C(0x00000001)   /** @brief Enable enable the QUADSPI.. */
  #define QUADSPI_CR_ABORT_MSK            UINT32_C(0x00000002)   /** @brief Abort request this bit aborts the on-going command sequence. It is automatically reset once the abort is complete. This bit stops the current transfer. In polling mode or memory-mapped mode, this bit also reset the APM bit or the DM bit.. */
  #define QUADSPI_CR_DMAEN_MSK            UINT32_C(0x00000004)   /** @brief DMA enable in indirect mode, DMA can be used to input or output data via the QUADSPI_DR register. DMA transfers are initiated when the FIFO threshold flag, FTF, is set.. */
  #define QUADSPI_CR_TCEN_MSK             UINT32_C(0x00000008)   /** @brief Timeout counter enable this bit is valid only when memory-mapped mode (FMODE = 11) is selected. Activating this bit causes the chip select (ncs) to be released (and thus reduces consumption) if there has not been an access after a certain amount of time, where this time is defined by TIMEOUT[15:0] (QUADSPI_LPTR). Enable the timeout counter. By default, the QUADSPI never stops its prefetch operation, keeping the previous read operation active with ncs maintained low, even if no access to the flash memory occurs for a long time. Since flash memories tend to consume more when ncs is held low, the application might want to activate the timeout counter (TCEN = 1, QUADSPI_CR[3]) so that ncs is released after a period of TIMEOUT[15:0] (QUADSPI_LPTR) cycles have elapsed without an access since when the FIFO becomes full with prefetch data. This bit can be modified only when BUSY = 0.. */
  #define QUADSPI_CR_SSHIFT_MSK           UINT32_C(0x00000010)   /** @brief Sample shift by default, the QUADSPI samples data 1/2 of a CLK cycle after the data is driven by the flash memory. This bit allows the data is to be sampled later in order to account for external signal delays. Firmware must assure that SSHIFT = 0 when in DDR mode (when DDRM = 1). This field can be modified only when BUSY = 0.. */
  #define QUADSPI_CR_DFM_MSK              UINT32_C(0x00000040)   /** @brief Dual-flash mode this bit activates dual-flash mode, where two external flash memories are used simultaneously to double throughput and capacity. This bit can be modified only when BUSY = 0.. */
  #define QUADSPI_CR_FSEL_MSK             UINT32_C(0x00000080)   /** @brief Flash memory selection this bit selects the flash memory to be addressed in single flash mode (when DFM = 0). This bit can be modified only when BUSY = 0. This bit is ignored when DFM = 1.. */
  #define QUADSPI_CR_FTHRES_MSK           UINT32_C(0x00001F00)   /** @brief FIFO threshold level defines, in indirect mode, the threshold number of bytes in the FIFO that will cause the FIFO threshold flag (FTF, QUADSPI_SR[2]) to be set. In indirect write mode (FMODE = 00): ... In indirect read mode (FMODE = 01): ... If DMAEN = 1, then the DMA controller for the corresponding channel must be disabled before changing the FTHRES value.. */
  #define QUADSPI_CR_TEIE_MSK             UINT32_C(0x00010000)   /** @brief Transfer error interrupt enable this bit enables the transfer error interrupt.. */
  #define QUADSPI_CR_TCIE_MSK             UINT32_C(0x00020000)   /** @brief Transfer complete interrupt enable this bit enables the transfer complete interrupt.. */
  #define QUADSPI_CR_FTIE_MSK             UINT32_C(0x00040000)   /** @brief FIFO threshold interrupt enable this bit enables the FIFO threshold interrupt.. */
  #define QUADSPI_CR_SMIE_MSK             UINT32_C(0x00080000)   /** @brief Status match interrupt enable this bit enables the status match interrupt.. */
  #define QUADSPI_CR_TOIE_MSK             UINT32_C(0x00100000)   /** @brief TimeOut interrupt enable this bit enables the timeout interrupt.. */
  #define QUADSPI_CR_APMS_MSK             UINT32_C(0x00400000)   /** @brief Automatic poll mode stop this bit determines if automatic polling is stopped after a match. This bit can be modified only when BUSY = 0.. */
  #define QUADSPI_CR_PMM_MSK              UINT32_C(0x00800000)   /** @brief Polling match mode this bit indicates which method should be used for determining a match during automatic polling mode. This bit can be modified only when BUSY = 0.. */
  #define QUADSPI_CR_PRESCALER_MSK        UINT32_C(0xFF000000)   /** @brief Clock prescaler. */
  #define QUADSPI_DCR_CKMODE_MSK          UINT32_C(0x00000001)   /** @brief Indicates the level that clk takes between command. */
  #define QUADSPI_DCR_CSHT_MSK            UINT32_C(0x00000700)   /** @brief Chip select high time CSHT+1 defines the minimum number of CLK cycles which the chip select (ncs) must remain high between commands issued to the flash memory. ... This field can be modified only when BUSY = 0.. */
  #define QUADSPI_DCR_FSIZE_MSK           UINT32_C(0x001F0000)   /** @brief Flash memory size this field defines the size of external memory using the following formula: number of bytes in flash memory = 2[FSIZE+1] FSIZE+1 is effectively the number of address bits required to address the flash memory. The flash memory capacity can be up to 4GB (addressed using 32 bits) in indirect mode, but the addressable space in memory-mapped mode is limited to 256MB. If DFM = 1, FSIZE indicates the total capacity of the two flash memories together. This field can be modified only when BUSY = 0.. */
  #define QUADSPI_SR_TEF_MSK              UINT32_C(0x00000001)   /** @brief Transfer error flag this bit is set in indirect mode when an invalid address is being accessed in indirect mode. It is cleared by writing 1 to CTEF.. */
  #define QUADSPI_SR_TCF_MSK              UINT32_C(0x00000002)   /** @brief Transfer complete flag this bit is set in indirect mode when the programmed number of data has been transferred or in any mode when the transfer has been aborted.it is cleared by writing 1 to CTCF.. */
  #define QUADSPI_SR_FTF_MSK              UINT32_C(0x00000004)   /** @brief FIFO threshold flag in indirect mode, this bit is set when the FIFO threshold has been reached, or if there is any data left in the FIFO after reads from the flash memory are complete. It is cleared automatically as soon as threshold condition is no longer true. In automatic polling mode this bit is set every time the status register is read, and the bit is cleared when the data register is read.. */
  #define QUADSPI_SR_SMF_MSK              UINT32_C(0x00000008)   /** @brief Status match flag this bit is set in automatic polling mode when the unmasked received data matches the corresponding bits in the match register (QUADSPI_PSMAR). It is cleared by writing 1 to CSMF.. */
  #define QUADSPI_SR_TOF_MSK              UINT32_C(0x00000010)   /** @brief Timeout flag this bit is set when timeout occurs. It is cleared by writing 1 to CTOF.. */
  #define QUADSPI_SR_BUSY_MSK             UINT32_C(0x00000020)   /** @brief Busy this bit is set when an operation is on going. This bit clears automatically when the operation with the flash memory is finished and the FIFO is empty.. */
  #define QUADSPI_SR_FLEVEL_MSK           UINT32_C(0x00003F00)   /** @brief FIFO level this field gives the number of valid bytes which are being held in the FIFO. FLEVEL = 0 when the FIFO is empty, and 16 when it is full. In memory-mapped mode and in automatic status polling mode, FLEVEL is zero.. */
  #define QUADSPI_FCR_CTEF_MSK            UINT32_C(0x00000001)   /** @brief Clear transfer error flag writing 1 clears the TEF flag in the QUADSPI_SR register. */
  #define QUADSPI_FCR_CTCF_MSK            UINT32_C(0x00000002)   /** @brief Clear transfer complete flag writing 1 clears the TCF flag in the QUADSPI_SR register. */
  #define QUADSPI_FCR_CSMF_MSK            UINT32_C(0x00000008)   /** @brief Clear status match flag writing 1 clears the SMF flag in the QUADSPI_SR register. */
  #define QUADSPI_FCR_CTOF_MSK            UINT32_C(0x00000010)   /** @brief Clear timeout flag writing 1 clears the TOF flag in the QUADSPI_SR register. */
  #define QUADSPI_DLR_DL_MSK              UINT32_C(0xFFFFFFFF)   /** @brief Data length number of data to be retrieved (value+1) in indirect and status-polling modes. A value no greater than 3 (indicating 4 bytes) should be used for status-polling mode. All 1s in indirect mode means undefined length, where QUADSPI will continue until the end of memory, as defined by FSIZE. 0x0000_0000: 1 byte is to be transferred 0x0000_0001: 2 bytes are to be transferred 0x0000_0002: 3 bytes are to be transferred 0x0000_0003: 4 bytes are to be transferred ... 0xFFFF_FFFD: 4,294,967,294 (4G-2) bytes are to be transferred 0xffff_fffe: 4,294,967,295 (4G-1) bytes are to be transferred 0xffff_ffff: undefined length -- all bytes until the end of flash memory (as defined by FSIZE) are to be transferred. Continue reading indefinitely if FSIZE = 0x1f. DL[0] is stuck at 1 in dual-flash mode (DFM = 1) even when 0 is written to this bit, thus assuring that each access transfers an even number of bytes. This field has no effect when in memory-mapped mode (FMODE = 10). This field can be written only when BUSY = 0.. */
  #define QUADSPI_CCR_INSTRUCTION_MSK     UINT32_C(0x000000FF)   /** @brief Instruction instruction to be send to the external SPI device. This field can be written only when BUSY = 0.. */
  #define QUADSPI_CCR_IMODE_MSK           UINT32_C(0x00000300)   /** @brief Instruction mode this field defines the instruction phase mode of operation: this field can be written only when BUSY = 0.. */
  #define QUADSPI_CCR_ADMODE_MSK          UINT32_C(0x00000C00)   /** @brief Address mode this field defines the address phase mode of operation: this field can be written only when BUSY = 0.. */
  #define QUADSPI_CCR_ADSIZE_MSK          UINT32_C(0x00003000)   /** @brief Address size this bit defines address size: this field can be written only when BUSY = 0.. */
  #define QUADSPI_CCR_ABMODE_MSK          UINT32_C(0x0000C000)   /** @brief Alternate bytes mode this field defines the alternate-bytes phase mode of operation: this field can be written only when BUSY = 0.. */
  #define QUADSPI_CCR_ABSIZE_MSK          UINT32_C(0x00030000)   /** @brief Alternate bytes size this bit defines alternate bytes size: this field can be written only when BUSY = 0.. */
  #define QUADSPI_CCR_DCYC_MSK            UINT32_C(0x007C0000)   /** @brief Number of dummy cycles this field defines the duration of the dummy phase. In both SDR and DDR modes, it specifies a number of CLK cycles (0-31). This field can be written only when BUSY = 0.. */
  #define QUADSPI_CCR_DMODE_MSK           UINT32_C(0x03000000)   /** @brief Data mode this field defines the data phases mode of operation: this field also determines the dummy phase mode of operation. This field can be written only when BUSY = 0.. */
  #define QUADSPI_CCR_FMODE_MSK           UINT32_C(0x0C000000)   /** @brief Functional mode this field defines the QUADSPI functional mode of operation. If DMAEN = 1 already, then the DMA controller for the corresponding channel must be disabled before changing the FMODE value. This field can be written only when BUSY = 0.. */
  #define QUADSPI_CCR_SIOO_MSK            UINT32_C(0x10000000)   /** @brief Send instruction only once mode see section15.3.11: sending the instruction only once on page13. This bit has no effect when IMODE = 00. This field can be written only when BUSY = 0.. */
  #define QUADSPI_CCR_DHHC_MSK            UINT32_C(0x40000000)   /** @brief DDR hold delay the data output by 1/4 of the QUADSPI output clock cycle in DDR mode: this feature is only active in DDR mode. This field can be written only when BUSY = 0.. */
  #define QUADSPI_CCR_DDRM_MSK            UINT32_C(0x80000000)   /** @brief Double data rate mode this bit sets the DDR mode for the address, alternate byte and data phase: this field can be written only when BUSY = 0.. */
  #define QUADSPI_AR_ADDRESS_MSK          UINT32_C(0xFFFFFFFF)   /** @brief [31 0]: address address to be send to the external flash memory writes to this field are ignored when BUSY = 0 or when FMODE = 11 (memory-mapped mode). In dual flash mode, ADDRESS[0] is automatically stuck to 0 as the address should always be even. */
  #define QUADSPI_ABR_ALTERNATE_MSK       UINT32_C(0xFFFFFFFF)   /** @brief Alternate bytes optional data to be send to the external SPI device right after the address. This field can be written only when BUSY = 0.. */
  #define QUADSPI_DR_DATA_MSK             UINT32_C(0xFFFFFFFF)   /** @brief Data data to be sent/received to/from the external SPI device. In indirect write mode, data written to this register is stored on the FIFO before it is sent to the flash memory during the data phase. If the FIFO is too full, a write operation is stalled until the FIFO has enough space to accept the amount of data being written. In indirect read mode, reading this register gives (via the FIFO) the data which was received from the flash memory. If the FIFO does not have as many bytes as requested by the read operation and if BUSY=1, the read operation is stalled until enough data is present or until the transfer is complete, whichever happens first. In automatic polling mode, this register contains the last data read from the flash memory (without masking). Word, halfword, and byte accesses to this register are supported. In indirect write mode, a byte write adds 1 byte to the FIFO, a halfword write 2, and a word write 4. Similarly, in indirect read mode, a byte read removes 1 byte from the FIFO, a halfword read 2, and a word read 4. Accesses in indirect mode must be aligned to the bottom of this register: a byte read must read DATA[7:0] and a halfword read must read DATA[15:0].. */
  #define QUADSPI_PSMKR_MASK_MSK          UINT32_C(0xFFFFFFFF)   /** @brief Status mask mask to be applied to the status bytes received in polling mode. For bit n: this field can be written only when BUSY = 0.. */
  #define QUADSPI_PSMAR_MATCH_MSK         UINT32_C(0xFFFFFFFF)   /** @brief Status match value to be compared with the masked status register to get a match. This field can be written only when BUSY = 0.. */
  #define QUADSPI_PIR_INTERVAL_MSK        UINT32_C(0x0000FFFF)   /** @brief Polling interval number of CLK cycles between to read during automatic polling phases. This field can be written only when BUSY = 0.. */
  #define QUADSPI_LPTR_TIMEOUT_MSK        UINT32_C(0x0000FFFF)   /** @brief Timeout period after each access in memory-mapped mode, the QUADSPI prefetches the subsequent bytes and holds these bytes in the FIFO. This field indicates how many CLK cycles the QUADSPI waits after the FIFO becomes full until it raises ncs, putting the flash memory in a lower-consumption state. This field can be written only when BUSY = 0.. */

