  /**** @subsection Register Definitions ****/

  #define RNG_CR_PTR   (*(RW_ uint32_t*)UINT32_C(0x48021800))   /** @brief RNG control register. */
  #define RNG_SR_PTR   (*(RW_ uint32_t*)UINT32_C(0x48021804))   /** @brief RNG status register. */
  #define RNG_DR_PTR   (*(RO_ uint32_t*)UINT32_C(0x48021808))   /** @brief The RNG_DR register is a read-only register that delivers a 32-bit random value when read. The content of this register is valid when DRDY= 1, even if RNGEN=0.. */

  /**** @subsection Field Mask Definitions ****/

  #define RNG_CR_RNGEN_MSK    UINT32_C(0x00000004)   /** @brief Random number generator enable. */
  #define RNG_CR_IE_MSK       UINT32_C(0x00000008)   /** @brief Interrupt enable. */
  #define RNG_CR_CED_MSK      UINT32_C(0x00000020)   /** @brief Clock error detection note: the clock error detection can be used only when ck_rc48 or ck_pll1_q (ck_pll1_q = 48mhz) source is selected otherwise, CED bit must be equal to 1. The clock error detection cannot be enabled nor disabled on the fly when RNG peripheral is enabled, to enable or disable CED the RNG must be disabled.. */
  #define RNG_SR_DRDY_MSK     UINT32_C(0x00000001)   /** @brief Data ready note: if IE=1 in RNG_CR, an interrupt is generated when DRDY=1. It can rise when the peripheral is disabled. When the output buffer becomes empty (after reading RNG_DR), this bit returns to 0 until a new random value is generated.. */
  #define RNG_SR_CECS_MSK     UINT32_C(0x00000002)   /** @brief Clock error current status note: this bit is meaningless if CED (clock error detection) bit in RNG_CR is equal to 1.. */
  #define RNG_SR_SECS_MSK     UINT32_C(0x00000004)   /** @brief Seed error current status ** more than 64 consecutive bits at the same value (0 or 1) ** more than 32 consecutive alternances of 0 and 1 (0101010101...01). */
  #define RNG_SR_CEIS_MSK     UINT32_C(0x00000020)   /** @brief Clock error interrupt status this bit is set at the same time as CECS. It is cleared by writing it to 0. An interrupt is pending if IE = 1 in the RNG_CR register. Note: this bit is meaningless if CED (clock error detection) bit in RNG_CR is equal to 1.. */
  #define RNG_SR_SEIS_MSK     UINT32_C(0x00000040)   /** @brief Seed error interrupt status this bit is set at the same time as SECS. It is cleared by writing it to 0. ** more than 64 consecutive bits at the same value (0 or 1) ** more than 32 consecutive alternances of 0 and 1 (0101010101...01) an interrupt is pending if IE = 1 in the RNG_CR register.. */
  #define RNG_DR_RNDATA_MSK   UINT32_C(0xFFFFFFFF)   /** @brief Random data 32-bit random data which are valid when DRDY=1.. */

  /**** @subsection Field Position Definitions ****/

  #define RNG_CR_RNGEN_POS    INT32_C(2)   /** @brief Random number generator enable. */
  #define RNG_CR_IE_POS       INT32_C(3)   /** @brief Interrupt enable. */
  #define RNG_CR_CED_POS      INT32_C(5)   /** @brief Clock error detection note: the clock error detection can be used only when ck_rc48 or ck_pll1_q (ck_pll1_q = 48mhz) source is selected otherwise, CED bit must be equal to 1. The clock error detection cannot be enabled nor disabled on the fly when RNG peripheral is enabled, to enable or disable CED the RNG must be disabled.. */
  #define RNG_SR_DRDY_POS     INT32_C(0)   /** @brief Data ready note: if IE=1 in RNG_CR, an interrupt is generated when DRDY=1. It can rise when the peripheral is disabled. When the output buffer becomes empty (after reading RNG_DR), this bit returns to 0 until a new random value is generated.. */
  #define RNG_SR_CECS_POS     INT32_C(1)   /** @brief Clock error current status note: this bit is meaningless if CED (clock error detection) bit in RNG_CR is equal to 1.. */
  #define RNG_SR_SECS_POS     INT32_C(2)   /** @brief Seed error current status ** more than 64 consecutive bits at the same value (0 or 1) ** more than 32 consecutive alternances of 0 and 1 (0101010101...01). */
  #define RNG_SR_CEIS_POS     INT32_C(5)   /** @brief Clock error interrupt status this bit is set at the same time as CECS. It is cleared by writing it to 0. An interrupt is pending if IE = 1 in the RNG_CR register. Note: this bit is meaningless if CED (clock error detection) bit in RNG_CR is equal to 1.. */
  #define RNG_SR_SEIS_POS     INT32_C(6)   /** @brief Seed error interrupt status this bit is set at the same time as SECS. It is cleared by writing it to 0. ** more than 64 consecutive bits at the same value (0 or 1) ** more than 32 consecutive alternances of 0 and 1 (0101010101...01) an interrupt is pending if IE = 1 in the RNG_CR register.. */
  #define RNG_DR_RNDATA_POS   INT32_C(0)   /** @brief Random data 32-bit random data which are valid when DRDY=1.. */

