  #define RTC_RTC_TR_HT_MSK                     UINT32_C(0x00300000)   /** @brief Hour tens in BCD format. */
  #define RTC_RTC_TR_PM_MSK                     UINT32_C(0x00400000)   /** @brief AM/PM notation. */
  #define RTC_RTC_DR_DU_MSK                     UINT32_C(0x0000000F)   /** @brief Date units in BCD format. */
  #define RTC_RTC_DR_DT_MSK                     UINT32_C(0x00000030)   /** @brief Date tens in BCD format. */
  #define RTC_RTC_DR_MU_MSK                     UINT32_C(0x00000F00)   /** @brief Month units in BCD format. */
  #define RTC_RTC_DR_MT_MSK                     UINT32_C(0x00001000)   /** @brief Month tens in BCD format. */
  #define RTC_RTC_DR_WDU_MSK                    UINT32_C(0x0000E000)   /** @brief Week day units. */
  #define RTC_RTC_DR_YU_MSK                     UINT32_C(0x000F0000)   /** @brief Year units in BCD format. */
  #define RTC_RTC_DR_YT_MSK                     UINT32_C(0x00F00000)   /** @brief Year tens in BCD format. */
  #define RTC_RTC_CR_WUCKSEL_MSK                UINT32_C(0x00000007)   /** @brief Wakeup clock selection. */
  #define RTC_RTC_CR_TSEDGE_MSK                 UINT32_C(0x00000008)   /** @brief Time-stamp event active edge TSE must be reset when TSEDGE is changed to avoid unwanted TSF setting.. */
  #define RTC_RTC_CR_REFCKON_MSK                UINT32_C(0x00000010)   /** @brief RTC_REFIN reference clock detection enable (50 or 60hz) note: PREDIV_S must be 0x00ff.. */
  #define RTC_RTC_CR_BYPSHAD_MSK                UINT32_C(0x00000020)   /** @brief Bypass the shadow registers note: if the frequency of the APB clock is less than seven times the frequency of RTCCLK, BYPSHAD must be set to 1.. */
  #define RTC_RTC_CR_FMT_MSK                    UINT32_C(0x00000040)   /** @brief Hour format. */
  #define RTC_RTC_CR_ALRAE_MSK                  UINT32_C(0x00000100)   /** @brief Alarm A enable. */
  #define RTC_RTC_CR_ALRBE_MSK                  UINT32_C(0x00000200)   /** @brief Alarm B enable. */
  #define RTC_RTC_CR_WUTE_MSK                   UINT32_C(0x00000400)   /** @brief Wakeup timer enable. */
  #define RTC_RTC_CR_TSE_MSK                    UINT32_C(0x00000800)   /** @brief Timestamp enable. */
  #define RTC_RTC_CR_ALRAIE_MSK                 UINT32_C(0x00001000)   /** @brief Alarm A interrupt enable. */
  #define RTC_RTC_CR_ALRBIE_MSK                 UINT32_C(0x00002000)   /** @brief Alarm B interrupt enable. */
  #define RTC_RTC_CR_WUTIE_MSK                  UINT32_C(0x00004000)   /** @brief Wakeup timer interrupt enable. */
  #define RTC_RTC_CR_TSIE_MSK                   UINT32_C(0x00008000)   /** @brief Time-stamp interrupt enable. */
  #define RTC_RTC_CR_ADD1H_MSK                  UINT32_C(0x00010000)   /** @brief Add 1 hour (summer time change) when this bit is set outside initialization mode, 1 hour is added to the calendar time. This bit is always read as 0.. */
  #define RTC_RTC_CR_SUB1H_MSK                  UINT32_C(0x00020000)   /** @brief Subtract 1 hour (winter time change) when this bit is set outside initialization mode, 1 hour is subtracted to the calendar time if the current hour is not 0. This bit is always read as 0. Setting this bit has no effect when current hour is 0.. */
  #define RTC_RTC_CR_BKP_MSK                    UINT32_C(0x00040000)   /** @brief Backup this bit can be written by the user to memorize whether the daylight saving time change has been performed or not.. */
  #define RTC_RTC_CR_COSEL_MSK                  UINT32_C(0x00080000)   /** @brief Calibration output selection when COE=1, this bit selects which signal is output on RTC_CALIB. These frequencies are valid for RTCCLK at 32.768 khz and prescalers at their default values (PREDIV_A=127 and PREDIV_S=255). Refer to section24.3.15: calibration clock output. */
  #define RTC_RTC_CR_POL_MSK                    UINT32_C(0x00100000)   /** @brief Output polarity this bit is used to configure the polarity of RTC_ALARM output. */
  #define RTC_RTC_CR_OSEL_MSK                   UINT32_C(0x00600000)   /** @brief Output selection these bits are used to select the flag to be routed to RTC_ALARM output. */
  #define RTC_RTC_CR_COE_MSK                    UINT32_C(0x00800000)   /** @brief Calibration output enable this bit enables the RTC_CALIB output. */
  #define RTC_RTC_CR_ITSE_MSK                   UINT32_C(0x01000000)   /** @brief Timestamp on internal event enable. */
  #define RTC_RTC_ISR_ALRAWF_MSK                UINT32_C(0x00000001)   /** @brief Alarm A write flag this bit is set by hardware when alarm A values can be changed, after the ALRAE bit has been set to 0 in RTC_CR. It is cleared by hardware in initialization mode.. */
  #define RTC_RTC_ISR_ALRBWF_MSK                UINT32_C(0x00000002)   /** @brief Alarm B write flag this bit is set by hardware when alarm B values can be changed, after the ALRBE bit has been set to 0 in RTC_CR. It is cleared by hardware in initialization mode.. */
  #define RTC_RTC_ISR_WUTWF_MSK                 UINT32_C(0x00000004)   /** @brief Wakeup timer write flag this bit is set by hardware up to 2 RTCCLK cycles after the WUTE bit has been set to 0 in RTC_CR, and is cleared up to 2 RTCCLK cycles after the WUTE bit has been set to 1. The wakeup timer values can be changed when WUTE bit is cleared and WUTWF is set.. */
  #define RTC_RTC_ISR_SHPF_MSK                  UINT32_C(0x00000008)   /** @brief Shift operation pending this flag is set by hardware as soon as a shift operation is initiated by a write to the RTC_SHIFTR register. It is cleared by hardware when the corresponding shift operation has been executed. Writing to the SHPF bit has no effect.. */
  #define RTC_RTC_ISR_INITS_MSK                 UINT32_C(0x00000010)   /** @brief Initialization status flag this bit is set by hardware when the calendar year field is different from 0 (backup domain reset state).. */
  #define RTC_RTC_ISR_RSF_MSK                   UINT32_C(0x00000020)   /** @brief Registers synchronization flag this bit is set by hardware each time the calendar registers are copied into the shadow registers (rtc_ssrx, rtc_trx and rtc_drx). This bit is cleared by hardware in initialization mode, while a shift operation is pending (SHPF=1), or when in bypass shadow register mode (BYPSHAD=1). This bit can also be cleared by software. It is cleared either by software or by hardware in initialization mode.. */
  #define RTC_RTC_ISR_INITF_MSK                 UINT32_C(0x00000040)   /** @brief Initialization flag when this bit is set to 1, the RTC is in initialization state, and the time, date and prescaler registers can be updated.. */
  #define RTC_RTC_ISR_INIT_MSK                  UINT32_C(0x00000080)   /** @brief Initialization mode. */
  #define RTC_RTC_ISR_ALRAF_MSK                 UINT32_C(0x00000100)   /** @brief Alarm A flag this flag is set by hardware when the time/date registers (RTC_TR and RTC_DR) match the alarm A register (RTC_ALRMAR). This flag is cleared by software by writing 0.. */
  #define RTC_RTC_ISR_ALRBF_MSK                 UINT32_C(0x00000200)   /** @brief Alarm B flag this flag is set by hardware when the time/date registers (RTC_TR and RTC_DR) match the alarm B register (RTC_ALRMBR). This flag is cleared by software by writing 0.. */
  #define RTC_RTC_ISR_WUTF_MSK                  UINT32_C(0x00000400)   /** @brief Wakeup timer flag this flag is set by hardware when the wakeup auto-reload counter reaches 0. This flag is cleared by software by writing 0. This flag must be cleared by software at least 1.5 RTCCLK periods before WUTF is set to 1 again.. */
  #define RTC_RTC_ISR_TSF_MSK                   UINT32_C(0x00000800)   /** @brief Time-stamp flag this flag is set by hardware when a time-stamp event occurs. This flag is cleared by software by writing 0.. */
  #define RTC_RTC_ISR_TSOVF_MSK                 UINT32_C(0x00001000)   /** @brief Time-stamp overflow flag this flag is set by hardware when a time-stamp event occurs while TSF is already set. This flag is cleared by software by writing 0. It is recommended to check and then clear TSOVF only after clearing the TSF bit. Otherwise, an overflow might not be noticed if a time-stamp event occurs immediately before the TSF bit is cleared.. */
  #define RTC_RTC_ISR_TAMP1F_MSK                UINT32_C(0x00002000)   /** @brief RTC_TAMP1 detection flag this flag is set by hardware when a tamper detection event is detected on the RTC_TAMP1 input. It is cleared by software writing 0. */
  #define RTC_RTC_ISR_TAMP2F_MSK                UINT32_C(0x00004000)   /** @brief RTC_TAMP2 detection flag this flag is set by hardware when a tamper detection event is detected on the RTC_TAMP2 input. It is cleared by software writing 0. */
  #define RTC_RTC_ISR_TAMP3F_MSK                UINT32_C(0x00008000)   /** @brief RTC_TAMP3 detection flag this flag is set by hardware when a tamper detection event is detected on the RTC_TAMP3 input. It is cleared by software writing 0. */
  #define RTC_RTC_ISR_RECALPF_MSK               UINT32_C(0x00010000)   /** @brief Recalibration pending flag the RECALPF status flag is automatically set to 1 when software writes to the RTC_CALR register, indicating that the RTC_CALR register is blocked. When the new calibration settings are taken into account, this bit returns to 0. Refer to re-calibration on-the-fly.. */
  #define RTC_RTC_ISR_ITSF_MSK                  UINT32_C(0x00020000)   /** @brief Internal ttime-stamp flag. */
  #define RTC_RTC_PRER_PREDIV_S_MSK             UINT32_C(0x00007FFF)   /** @brief Synchronous prescaler factor this is the synchronous division factor: ck_spre frequency = ck_apre frequency/(prediv_s+1). */
  #define RTC_RTC_PRER_PREDIV_A_MSK             UINT32_C(0x007F0000)   /** @brief Asynchronous prescaler factor this is the asynchronous division factor: ck_apre frequency = RTCCLK frequency/(prediv_a+1). */
  #define RTC_RTC_WUTR_WUT_MSK                  UINT32_C(0x0000FFFF)   /** @brief Wakeup auto-reload value bits when the wakeup timer is enabled (WUTE set to 1), the WUTF flag is set every (WUT[15:0] + 1) ck_wut cycles. The ck_wut period is selected through WUCKSEL[2:0] bits of the RTC_CR register when WUCKSEL[2] = 1, the wakeup timer becomes 17-bits and WUCKSEL[1] effectively becomes WUT[16] the most-significant bit to be reloaded into the timer. The first assertion of WUTF occurs (WUT+1) ck_wut cycles after WUTE is set. Setting WUT[15:0] to 0x0000 with WUCKSEL[2:0] =011 (RTCCLK/2) is forbidden.. */
  #define RTC_RTC_ALRMAR_SU_MSK                 UINT32_C(0x0000000F)   /** @brief Second units in BCD format.. */
  #define RTC_RTC_ALRMAR_ST_MSK                 UINT32_C(0x00000070)   /** @brief Second tens in BCD format.. */
  #define RTC_RTC_ALRMAR_MSK1_MSK               UINT32_C(0x00000080)   /** @brief Alarm A seconds mask. */
  #define RTC_RTC_ALRMAR_MNU_MSK                UINT32_C(0x00000F00)   /** @brief Minute units in BCD format.. */
  #define RTC_RTC_ALRMAR_MNT_MSK                UINT32_C(0x00007000)   /** @brief Minute tens in BCD format.. */
