  #define RTC_RTC_CR_TSE_POS                    INT32_C(11)   /** @brief Timestamp enable. */
  #define RTC_RTC_CR_ALRAIE_POS                 INT32_C(12)   /** @brief Alarm A interrupt enable. */
  #define RTC_RTC_CR_ALRBIE_POS                 INT32_C(13)   /** @brief Alarm B interrupt enable. */
  #define RTC_RTC_CR_WUTIE_POS                  INT32_C(14)   /** @brief Wakeup timer interrupt enable. */
  #define RTC_RTC_CR_TSIE_POS                   INT32_C(15)   /** @brief Time-stamp interrupt enable. */
  #define RTC_RTC_CR_ADD1H_POS                  INT32_C(16)   /** @brief Add 1 hour (summer time change) when this bit is set outside initialization mode, 1 hour is added to the calendar time. This bit is always read as 0.. */
  #define RTC_RTC_CR_SUB1H_POS                  INT32_C(17)   /** @brief Subtract 1 hour (winter time change) when this bit is set outside initialization mode, 1 hour is subtracted to the calendar time if the current hour is not 0. This bit is always read as 0. Setting this bit has no effect when current hour is 0.. */
