  #define RTC_RTC_ISR_INIT_POS                  INT32_C(7)    /** @brief Initialization mode. */
  #define RTC_RTC_ISR_ALRAF_POS                 INT32_C(8)    /** @brief Alarm A flag this flag is set by hardware when the time/date registers (RTC_TR and RTC_DR) match the alarm A register (RTC_ALRMAR). This flag is cleared by software by writing 0.. */
  #define RTC_RTC_ISR_ALRBF_POS                 INT32_C(9)    /** @brief Alarm B flag this flag is set by hardware when the time/date registers (RTC_TR and RTC_DR) match the alarm B register (RTC_ALRMBR). This flag is cleared by software by writing 0.. */
  #define RTC_RTC_ISR_WUTF_POS                  INT32_C(10)   /** @brief Wakeup timer flag this flag is set by hardware when the wakeup auto-reload counter reaches 0. This flag is cleared by software by writing 0. This flag must be cleared by software at least 1.5 RTCCLK periods before WUTF is set to 1 again.. */
  #define RTC_RTC_ISR_TSF_POS                   INT32_C(11)   /** @brief Time-stamp flag this flag is set by hardware when a time-stamp event occurs. This flag is cleared by software by writing 0.. */
  #define RTC_RTC_ISR_TSOVF_POS                 INT32_C(12)   /** @brief Time-stamp overflow flag this flag is set by hardware when a time-stamp event occurs while TSF is already set. This flag is cleared by software by writing 0. It is recommended to check and then clear TSOVF only after clearing the TSF bit. Otherwise, an overflow might not be noticed if a time-stamp event occurs immediately before the TSF bit is cleared.. */
  #define RTC_RTC_ISR_TAMP1F_POS                INT32_C(13)   /** @brief RTC_TAMP1 detection flag this flag is set by hardware when a tamper detection event is detected on the RTC_TAMP1 input. It is cleared by software writing 0. */
  #define RTC_RTC_ISR_TAMP2F_POS                INT32_C(14)   /** @brief RTC_TAMP2 detection flag this flag is set by hardware when a tamper detection event is detected on the RTC_TAMP2 input. It is cleared by software writing 0. */
  #define RTC_RTC_ISR_TAMP3F_POS                INT32_C(15)   /** @brief RTC_TAMP3 detection flag this flag is set by hardware when a tamper detection event is detected on the RTC_TAMP3 input. It is cleared by software writing 0. */
  #define RTC_RTC_ISR_RECALPF_POS               INT32_C(16)   /** @brief Recalibration pending flag the RECALPF status flag is automatically set to 1 when software writes to the RTC_CALR register, indicating that the RTC_CALR register is blocked. When the new calibration settings are taken into account, this bit returns to 0. Refer to re-calibration on-the-fly.. */
  #define RTC_RTC_ISR_ITSF_POS                  INT32_C(17)   /** @brief Internal ttime-stamp flag. */
