  #define RTC_RTC_OR_RTC_ALARM_TYPE_POS         INT32_C(0)    /** @brief RTC_ALARM output type on PC13. */
  #define RTC_RTC_OR_RTC_OUT_RMP_POS            INT32_C(1)    /** @brief RTC_OUT remap. */
