  #define SDMMC1_DCTRL_FIFORST_MSK             UINT32_C(0x00002000)   /** @brief FIFO reset, will flush any remaining data. This bit can only be written by firmware when IDMAEN= 0 and DPSM is active (DPSMACT = 1). This bit will only take effect when a transfer error or transfer hold occurs.. */
  #define SDMMC1_DCNTR_DATACOUNT_MSK           UINT32_C(0x01FFFFFF)   /** @brief Data count value when read, the number of remaining data bytes to be transferred is returned. Write has no effect.. */
  #define SDMMC1_STAR_CCRCFAIL_MSK             UINT32_C(0x00000001)   /** @brief Command response received (CRC check failed). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_DCRCFAIL_MSK             UINT32_C(0x00000002)   /** @brief Data block sent/received (CRC check failed). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_CTIMEOUT_MSK             UINT32_C(0x00000004)   /** @brief Command response timeout. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR. The command timeout period has a fixed value of 64 SDMMC_CK clock periods.. */
