  #define SDMMC1_STAR_CPSMACT_MSK              UINT32_C(0x00002000)   /** @brief Command path state machine active, i.e. Not in idle state. This is a hardware status flag only, does not generate an interrupt.. */
  #define SDMMC1_STAR_TXFIFOHE_MSK             UINT32_C(0x00004000)   /** @brief Transmit FIFO half empty at least half the number of words can be written into the FIFO. This bit is cleared when the FIFO becomes half+1 full.. */
