  #define SDMMC1_IDMABSIZER_IDMABNDT_MSK       UINT32_C(0x00001FE0)   /** @brief Number of transfers per buffer. This 8-bit value shall be multiplied by 8 to get the size of the buffer in 32-bit words and by 32 to get the size of the buffer in bytes. Example: IDMABNDT = 0x01: buffer size = 8 words = 32 bytes. These bits can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC1_IDMABASE0R_IDMABASE0_MSK      UINT32_C(0xFFFFFFFF)   /** @brief Buffer 0 memory base address bits [31:2], shall be word aligned (bit [1:0] are always 0 and read only). This register can be written by firmware when DPSM is inactive (DPSMACT = 0), and can dynamically be written by firmware when DPSM active (DPSMACT = 1) and memory buffer 0 is inactive (IDMABACT = 1).. */
  #define SDMMC1_IDMABASE1R_IDMABASE1_MSK      UINT32_C(0xFFFFFFFF)   /** @brief Buffer 1 memory base address, shall be word aligned (bit [1:0] are always 0 and read only). This register can be written by firmware when DPSM is inactive (DPSMACT = 0), and can dynamically be written by firmware when DPSM active (DPSMACT = 1) and memory buffer 1 is inactive (IDMABACT = 0).. */
  #define SDMMC1_FIFOR_FIFODATA_MSK            UINT32_C(0xFFFFFFFF)   /** @brief Receive and transmit FIFO data this register can only be read or written by firmware when the DPSM is active (DPSMACT=1). The FIFO data occupies 16 entries of 32-bit words.. */
  #define SDMMC1_RESPCMDR_RESPCMD_MSK          UINT32_C(0x0000003F)   /** @brief Response command index. */

  /**** @subsection Field Position Definitions ****/

  #define SDMMC1_POWER_PWRCTRL_POS             INT32_C(0)    /** @brief SDMMC state control bits. These bits can only be written when the SDMMC is not in the power-on state (PWRCTRL?11). These bits are used to define the functional state of the SDMMC signals: any further write will be ignored, PWRCTRL value will keep 11.. */
  #define SDMMC1_POWER_VSWITCH_POS             INT32_C(2)    /** @brief Voltage switch sequence start. This bit is used to start the timing critical section of the voltage switch sequence:. */
  #define SDMMC1_POWER_VSWITCHEN_POS           INT32_C(3)    /** @brief Voltage switch procedure enable. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). This bit is used to stop the SDMMC_CK after the voltage switch command response:. */
  #define SDMMC1_POWER_DIRPOL_POS              INT32_C(4)    /** @brief Data and command direction signals polarity selection. This bit can only be written when the SDMMC is in the power-off state (PWRCTRL = 00).. */
  #define SDMMC1_CLKCR_CLKDIV_POS              INT32_C(0)    /** @brief Clock divide factor this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). This field defines the divide factor between the input clock (SDMMCCLK) and the output clock (SDMMC_CK): SDMMC_CK frequency = SDMMCCLK / [2 * CLKDIV]. 0xx: etc.. Xxx: etc... */
  #define SDMMC1_CLKCR_PWRSAV_POS              INT32_C(12)   /** @brief Power saving configuration bit this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0) for power saving, the SDMMC_CK clock output can be disabled when the bus is idle by setting PWRSAV:. */
  #define SDMMC1_CLKCR_WIDBUS_POS              INT32_C(14)   /** @brief Wide bus mode enable bit this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). */
  #define SDMMC1_CLKCR_NEGEDGE_POS             INT32_C(16)   /** @brief SDMMC_CK dephasing selection bit for data and command. This bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). When clock division = 1 (CLKDIV = 0), this bit has no effect. Data and command change on SDMMC_CK falling edge. When clock division &gt;1 (CLKDIV &gt; 0) &amp; DDR = 0: - SDMMC_CK edge occurs on SDMMCCLK rising edge. When clock division >1 (CLKDIV > 0) & DDR = 1: - data changed on the SDMMCCLK falling edge succeeding a SDMMC_CK edge. - SDMMC_CK edge occurs on SDMMCCLK rising edge. - data changed on the SDMMC_CK falling edge succeeding a SDMMC_CK edge. - SDMMC_CK edge occurs on SDMMCCLK rising edge.. */
  #define SDMMC1_CLKCR_HWFC_EN_POS             INT32_C(17)   /** @brief Hardware flow control enable this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0) when hardware flow control is enabled, the meaning of the TXFIFOE and RXFIFOF flags change, please see SDMMC status register definition in section56.8.11.. */
  #define SDMMC1_CLKCR_DDR_POS                 INT32_C(18)   /** @brief Data rate signaling selection this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0) DDR rate shall only be selected with 4-bit or 8-bit wide bus mode. (WIDBUS &gt; 00). DDR = 1 has no effect when WIDBUS = 00 (1-bit wide bus). DDR rate shall only be selected with clock division &gt;1. (CLKDIV &gt; 0). */
  #define SDMMC1_CLKCR_BUSSPEED_POS            INT32_C(19)   /** @brief Bus speed mode selection between DS, HS, SDR12, SDR25 and SDR50, DDR50, SDR104. This bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). */
  #define SDMMC1_CLKCR_SELCLKRX_POS            INT32_C(20)   /** @brief Receive clock selection. These bits can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). */
  #define SDMMC1_ARGR_CMDARG_POS               INT32_C(0)    /** @brief Command argument. These bits can only be written by firmware when CPSM is disabled (CPSMEN = 0). Command argument sent to a card as part of a command message. If a command contains an argument, it must be loaded into this register before writing a command to the command register.. */
  #define SDMMC1_CMDR_CMDINDEX_POS             INT32_C(0)    /** @brief Command index. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). The command index is sent to the card as part of a command message.. */
  #define SDMMC1_CMDR_CMDTRANS_POS             INT32_C(6)    /** @brief The CPSM treats the command as a data transfer command, stops the interrupt period, and signals dataenable to the DPSM this bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). If this bit is set, the CPSM issues an end of interrupt period and issues dataenable signal to the DPSM when the command is sent.. */
  #define SDMMC1_CMDR_CMDSTOP_POS              INT32_C(7)    /** @brief The CPSM treats the command as a stop transmission command and signals abort to the DPSM. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). If this bit is set, the CPSM issues the abort signal to the DPSM when the command is sent.. */
  #define SDMMC1_CMDR_WAITRESP_POS             INT32_C(8)    /** @brief Wait for response bits. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). They are used to configure whether the CPSM is to wait for a response, and if yes, which kind of response.. */
  #define SDMMC1_CMDR_WAITINT_POS              INT32_C(10)   /** @brief CPSM waits for interrupt request. If this bit is set, the CPSM disables command timeout and waits for an card interrupt request (response). If this bit is cleared in the CPSM wait state, will cause the abort of the interrupt mode.. */
  #define SDMMC1_CMDR_WAITPEND_POS             INT32_C(11)   /** @brief CPSM waits for end of data transfer (cmdpend internal signal) from DPSM. This bit when set, the CPSM waits for the end of data transfer trigger before it starts sending a command. WAITPEND is only taken into account when DTMODE = MMC stream data transfer, WIDBUS = 1-bit wide bus mode, DPSMACT = 1 and DTDIR = from host to card.. */
  #define SDMMC1_CMDR_CPSMEN_POS               INT32_C(12)   /** @brief Command path state machine (CPSM) enable bit this bit is written 1 by firmware, and cleared by hardware when the CPSM enters the idle state. If this bit is set, the CPSM is enabled. When DTEN = 1, no command will be transfered nor boot procedure will be started. CPSMEN is cleared to 0.. */
  #define SDMMC1_CMDR_DTHOLD_POS               INT32_C(13)   /** @brief Hold new data block transmission and reception in the DPSM. If this bit is set, the DPSM will not move from the wait_s state to the send state or from the wait_r state to the receive state.. */
  #define SDMMC1_CMDR_BOOTMODE_POS             INT32_C(14)   /** @brief Select the boot mode procedure to be used. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). */
  #define SDMMC1_CMDR_BOOTEN_POS               INT32_C(15)   /** @brief Enable boot mode procedure.. */
  #define SDMMC1_CMDR_CMDSUSPEND_POS           INT32_C(16)   /** @brief The CPSM treats the command as a suspend or resume command and signals interrupt period start/end. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). CMDSUSPEND = 1 and CMDTRANS = 0 suspend command, start interrupt period when response bit BS=0. CMDSUSPEND = 1 and CMDTRANS = 1 resume command with data, end interrupt period when response bit DF=1.. */
  #define SDMMC1_RESP1R_CARDSTATUS1_POS        INT32_C(0)    /** @brief See table 432. */
  #define SDMMC1_RESP2R_CARDSTATUS2_POS        INT32_C(0)    /** @brief See table404.. */
  #define SDMMC1_RESP3R_CARDSTATUS3_POS        INT32_C(0)    /** @brief See table404.. */
  #define SDMMC1_RESP4R_CARDSTATUS4_POS        INT32_C(0)    /** @brief See table404.. */
  #define SDMMC1_DTIMER_DATATIME_POS           INT32_C(0)    /** @brief Data and r1b busy timeout period this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). Data and r1b busy timeout period expressed in card bus clock periods.. */
  #define SDMMC1_DLENR_DATALENGTH_POS          INT32_C(0)    /** @brief Data length value this register can only be written by firmware when DPSM is inactive (DPSMACT = 0). Number of data bytes to be transferred. When DDR = 1 DATALENGTH is truncated to a multiple of 2. (The last odd byte is not transfered) when DATALENGTH = 0 no data will be transfered, when requested by a CPSMEN and CMDTRANS = 1 also no command will be transfered. DTEN and CPSMEN are cleared to 0.. */
  #define SDMMC1_DCTRL_DTEN_POS                INT32_C(0)    /** @brief Data transfer enable bit this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0). This bit is cleared by hardware when data transfer completes. This bit shall only be used to transfer data when no associated data transfer command is used, i.e. Shall not be used with SD or emmc cards.. */
  #define SDMMC1_DCTRL_DTDIR_POS               INT32_C(1)    /** @brief Data transfer direction selection this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC1_DCTRL_DTMODE_POS              INT32_C(2)    /** @brief Data transfer mode selection. This bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC1_DCTRL_DBLOCKSIZE_POS          INT32_C(4)    /** @brief Data block size this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0). Define the data block length when the block data transfer mode is selected: when DATALENGTH is not a multiple of DBLOCKSIZE, the transfered data is truncated at a multiple of DBLOCKSIZE. (Any remain data will not be transfered.) when DDR = 1, DBLOCKSIZE = 0000 shall not be used. (No data will be transfered). */
  #define SDMMC1_DCTRL_RWSTART_POS             INT32_C(8)    /** @brief Read wait start. If this bit is set, read wait operation starts.. */
  #define SDMMC1_DCTRL_RWSTOP_POS              INT32_C(9)    /** @brief Read wait stop this bit is written by firmware and auto cleared by hardware when the DPSM moves from the READ_WAIT state to the WAIT_R or IDLE state.. */
  #define SDMMC1_DCTRL_RWMOD_POS               INT32_C(10)   /** @brief Read wait mode. This bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC1_DCTRL_SDIOEN_POS              INT32_C(11)   /** @brief SD I/O interrupt enable functions this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0). If this bit is set, the DPSM enables the SD I/O card specific interrupt operation.. */
  #define SDMMC1_DCTRL_BOOTACKEN_POS           INT32_C(12)   /** @brief Enable the reception of the boot acknowledgment. This bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC1_DCTRL_FIFORST_POS             INT32_C(13)   /** @brief FIFO reset, will flush any remaining data. This bit can only be written by firmware when IDMAEN= 0 and DPSM is active (DPSMACT = 1). This bit will only take effect when a transfer error or transfer hold occurs.. */
  #define SDMMC1_DCNTR_DATACOUNT_POS           INT32_C(0)    /** @brief Data count value when read, the number of remaining data bytes to be transferred is returned. Write has no effect.. */
  #define SDMMC1_STAR_CCRCFAIL_POS             INT32_C(0)    /** @brief Command response received (CRC check failed). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_DCRCFAIL_POS             INT32_C(1)    /** @brief Data block sent/received (CRC check failed). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_CTIMEOUT_POS             INT32_C(2)    /** @brief Command response timeout. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR. The command timeout period has a fixed value of 64 SDMMC_CK clock periods.. */
  #define SDMMC1_STAR_DTIMEOUT_POS             INT32_C(3)    /** @brief Data timeout. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_TXUNDERR_POS             INT32_C(4)    /** @brief Transmit FIFO underrun error or IDMA read transfer error. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_RXOVERR_POS              INT32_C(5)    /** @brief Received FIFO overrun error or IDMA write transfer error. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_CMDREND_POS              INT32_C(6)    /** @brief Command response received (CRC check passed, or no CRC). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_CMDSENT_POS              INT32_C(7)    /** @brief Command sent (no response required). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_DATAEND_POS              INT32_C(8)    /** @brief Data transfer ended correctly. (data counter, DATACOUNT is zero and no errors occur). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_DHOLD_POS                INT32_C(9)    /** @brief Data transfer hold. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_DBCKEND_POS              INT32_C(10)   /** @brief Data block sent/received. (CRC check passed) and DPSM moves to the READWAIT state. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_DABORT_POS               INT32_C(11)   /** @brief Data transfer aborted by CMD12. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_DPSMACT_POS              INT32_C(12)   /** @brief Data path state machine active, i.e. Not in idle state. This is a hardware status flag only, does not generate an interrupt.. */
  #define SDMMC1_STAR_CPSMACT_POS              INT32_C(13)   /** @brief Command path state machine active, i.e. Not in idle state. This is a hardware status flag only, does not generate an interrupt.. */
  #define SDMMC1_STAR_TXFIFOHE_POS             INT32_C(14)   /** @brief Transmit FIFO half empty at least half the number of words can be written into the FIFO. This bit is cleared when the FIFO becomes half+1 full.. */
  #define SDMMC1_STAR_RXFIFOHF_POS             INT32_C(15)   /** @brief Receive FIFO half full there are at least half the number of words in the FIFO. This bit is cleared when the FIFO becomes half+1 empty.. */
  #define SDMMC1_STAR_TXFIFOF_POS              INT32_C(16)   /** @brief Transmit FIFO full this is a hardware status flag only, does not generate an interrupt. This bit is cleared when one FIFO location becomes empty.. */
  #define SDMMC1_STAR_RXFIFOF_POS              INT32_C(17)   /** @brief Receive FIFO full this bit is cleared when one FIFO location becomes empty.. */
  #define SDMMC1_STAR_TXFIFOE_POS              INT32_C(18)   /** @brief Transmit FIFO empty this bit is cleared when one FIFO location becomes full.. */
  #define SDMMC1_STAR_RXFIFOE_POS              INT32_C(19)   /** @brief Receive FIFO empty this is a hardware status flag only, does not generate an interrupt. This bit is cleared when one FIFO location becomes full.. */
  #define SDMMC1_STAR_BUSYD0_POS               INT32_C(20)   /** @brief Inverted value of SDMMC_D0 line (busy), sampled at the end of a CMD response and a second time 2 SDMMC_CK cycles after the CMD response. This bit is reset to not busy when the SDMMCD0 line changes from busy to not busy. This bit does not signal busy due to data transfer. This is a hardware status flag only, it does not generate an interrupt.. */
  #define SDMMC1_STAR_BUSYD0END_POS            INT32_C(21)   /** @brief End of SDMMC_D0 busy following a CMD response detected. This indicates only end of busy following a CMD response. This bit does not signal busy due to data transfer. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_SDIOIT_POS               INT32_C(22)   /** @brief SDIO interrupt received. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_ACKFAIL_POS              INT32_C(23)   /** @brief Boot acknowledgment received (boot acknowledgment check fail). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_ACKTIMEOUT_POS           INT32_C(24)   /** @brief Boot acknowledgment timeout. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_VSWEND_POS               INT32_C(25)   /** @brief Voltage switch critical timing section completion. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_CKSTOP_POS               INT32_C(26)   /** @brief SDMMC_CK stopped in voltage switch procedure. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_IDMATE_POS               INT32_C(27)   /** @brief IDMA transfer error. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_STAR_IDMABTC_POS              INT32_C(28)   /** @brief IDMA buffer transfer complete. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC1_ICR_CCRCFAILC_POS             INT32_C(0)    /** @brief CCRCFAIL flag clear bit set by software to clear the CCRCFAIL flag.. */
  #define SDMMC1_ICR_DCRCFAILC_POS             INT32_C(1)    /** @brief DCRCFAIL flag clear bit set by software to clear the DCRCFAIL flag.. */
  #define SDMMC1_ICR_CTIMEOUTC_POS             INT32_C(2)    /** @brief CTIMEOUT flag clear bit set by software to clear the CTIMEOUT flag.. */
  #define SDMMC1_ICR_DTIMEOUTC_POS             INT32_C(3)    /** @brief DTIMEOUT flag clear bit set by software to clear the DTIMEOUT flag.. */
  #define SDMMC1_ICR_TXUNDERRC_POS             INT32_C(4)    /** @brief TXUNDERR flag clear bit set by software to clear TXUNDERR flag.. */
  #define SDMMC1_ICR_RXOVERRC_POS              INT32_C(5)    /** @brief RXOVERR flag clear bit set by software to clear the RXOVERR flag.. */
  #define SDMMC1_ICR_CMDRENDC_POS              INT32_C(6)    /** @brief CMDREND flag clear bit set by software to clear the CMDREND flag.. */
  #define SDMMC1_ICR_CMDSENTC_POS              INT32_C(7)    /** @brief CMDSENT flag clear bit set by software to clear the CMDSENT flag.. */
  #define SDMMC1_ICR_DATAENDC_POS              INT32_C(8)    /** @brief DATAEND flag clear bit set by software to clear the DATAEND flag.. */
  #define SDMMC1_ICR_DHOLDC_POS                INT32_C(9)    /** @brief DHOLD flag clear bit set by software to clear the DHOLD flag.. */
  #define SDMMC1_ICR_DBCKENDC_POS              INT32_C(10)   /** @brief DBCKEND flag clear bit set by software to clear the DBCKEND flag.. */
  #define SDMMC1_ICR_DABORTC_POS               INT32_C(11)   /** @brief DABORT flag clear bit set by software to clear the DABORT flag.. */
  #define SDMMC1_ICR_BUSYD0ENDC_POS            INT32_C(21)   /** @brief BUSYD0END flag clear bit set by software to clear the BUSYD0END flag.. */
  #define SDMMC1_ICR_SDIOITC_POS               INT32_C(22)   /** @brief SDIOIT flag clear bit set by software to clear the SDIOIT flag.. */
  #define SDMMC1_ICR_ACKFAILC_POS              INT32_C(23)   /** @brief ACKFAIL flag clear bit set by software to clear the ACKFAIL flag.. */
  #define SDMMC1_ICR_ACKTIMEOUTC_POS           INT32_C(24)   /** @brief ACKTIMEOUT flag clear bit set by software to clear the ACKTIMEOUT flag.. */
  #define SDMMC1_ICR_VSWENDC_POS               INT32_C(25)   /** @brief VSWEND flag clear bit set by software to clear the VSWEND flag.. */
  #define SDMMC1_ICR_CKSTOPC_POS               INT32_C(26)   /** @brief CKSTOP flag clear bit set by software to clear the CKSTOP flag.. */
  #define SDMMC1_ICR_IDMATEC_POS               INT32_C(27)   /** @brief IDMA transfer error clear bit set by software to clear the IDMATE flag.. */
  #define SDMMC1_ICR_IDMABTCC_POS              INT32_C(28)   /** @brief IDMA buffer transfer complete clear bit set by software to clear the IDMABTC flag.. */
  #define SDMMC1_MASKR_CCRCFAILIE_POS          INT32_C(0)    /** @brief Command CRC fail interrupt enable set and cleared by software to enable/disable interrupt caused by command CRC failure.. */
  #define SDMMC1_MASKR_DCRCFAILIE_POS          INT32_C(1)    /** @brief Data CRC fail interrupt enable set and cleared by software to enable/disable interrupt caused by data CRC failure.. */
  #define SDMMC1_MASKR_CTIMEOUTIE_POS          INT32_C(2)    /** @brief Command timeout interrupt enable set and cleared by software to enable/disable interrupt caused by command timeout.. */
  #define SDMMC1_MASKR_DTIMEOUTIE_POS          INT32_C(3)    /** @brief Data timeout interrupt enable set and cleared by software to enable/disable interrupt caused by data timeout.. */
  #define SDMMC1_MASKR_TXUNDERRIE_POS          INT32_C(4)    /** @brief Tx FIFO underrun error interrupt enable set and cleared by software to enable/disable interrupt caused by tx FIFO underrun error.. */
  #define SDMMC1_MASKR_RXOVERRIE_POS           INT32_C(5)    /** @brief Rx FIFO overrun error interrupt enable set and cleared by software to enable/disable interrupt caused by rx FIFO overrun error.. */
  #define SDMMC1_MASKR_CMDRENDIE_POS           INT32_C(6)    /** @brief Command response received interrupt enable set and cleared by software to enable/disable interrupt caused by receiving command response.. */
  #define SDMMC1_MASKR_CMDSENTIE_POS           INT32_C(7)    /** @brief Command sent interrupt enable set and cleared by software to enable/disable interrupt caused by sending command.. */
  #define SDMMC1_MASKR_DATAENDIE_POS           INT32_C(8)    /** @brief Data end interrupt enable set and cleared by software to enable/disable interrupt caused by data end.. */
  #define SDMMC1_MASKR_DHOLDIE_POS             INT32_C(9)    /** @brief Data hold interrupt enable set and cleared by software to enable/disable the interrupt generated when sending new data is hold in the DPSM wait_s state.. */
  #define SDMMC1_MASKR_DBCKENDIE_POS           INT32_C(10)   /** @brief Data block end interrupt enable set and cleared by software to enable/disable interrupt caused by data block end.. */
  #define SDMMC1_MASKR_DABORTIE_POS            INT32_C(11)   /** @brief Data transfer aborted interrupt enable set and cleared by software to enable/disable interrupt caused by a data transfer being aborted.. */
  #define SDMMC1_MASKR_TXFIFOHEIE_POS          INT32_C(14)   /** @brief Tx FIFO half empty interrupt enable set and cleared by software to enable/disable interrupt caused by tx FIFO half empty.. */
  #define SDMMC1_MASKR_RXFIFOHFIE_POS          INT32_C(15)   /** @brief Rx FIFO half full interrupt enable set and cleared by software to enable/disable interrupt caused by rx FIFO half full.. */
  #define SDMMC1_MASKR_RXFIFOFIE_POS           INT32_C(17)   /** @brief Rx FIFO full interrupt enable set and cleared by software to enable/disable interrupt caused by rx FIFO full.. */
  #define SDMMC1_MASKR_TXFIFOEIE_POS           INT32_C(18)   /** @brief Tx FIFO empty interrupt enable set and cleared by software to enable/disable interrupt caused by tx FIFO empty.. */
  #define SDMMC1_MASKR_BUSYD0ENDIE_POS         INT32_C(21)   /** @brief BUSYD0END interrupt enable set and cleared by software to enable/disable the interrupt generated when SDMMC_D0 signal changes from busy to NOT busy following a CMD response.. */
  #define SDMMC1_MASKR_SDIOITIE_POS            INT32_C(22)   /** @brief SDIO mode interrupt received interrupt enable set and cleared by software to enable/disable the interrupt generated when receiving the SDIO mode interrupt.. */
  #define SDMMC1_MASKR_ACKFAILIE_POS           INT32_C(23)   /** @brief Acknowledgment fail interrupt enable set and cleared by software to enable/disable interrupt caused by acknowledgment fail.. */
  #define SDMMC1_MASKR_ACKTIMEOUTIE_POS        INT32_C(24)   /** @brief Acknowledgment timeout interrupt enable set and cleared by software to enable/disable interrupt caused by acknowledgment timeout.. */
  #define SDMMC1_MASKR_VSWENDIE_POS            INT32_C(25)   /** @brief Voltage switch critical timing section completion interrupt enable set and cleared by software to enable/disable the interrupt generated when voltage switch critical timing section completion.. */
  #define SDMMC1_MASKR_CKSTOPIE_POS            INT32_C(26)   /** @brief Voltage switch clock stopped interrupt enable set and cleared by software to enable/disable interrupt caused by voltage switch clock stopped.. */
  #define SDMMC1_MASKR_IDMABTCIE_POS           INT32_C(28)   /** @brief IDMA buffer transfer complete interrupt enable set and cleared by software to enable/disable the interrupt generated when the IDMA has transferred all data belonging to a memory buffer.. */
  #define SDMMC1_ACKTIMER_ACKTIME_POS          INT32_C(0)    /** @brief Boot acknowledgment timeout period this bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). Boot acknowledgment timeout period expressed in card bus clock periods.. */
  #define SDMMC1_IDMACTRLR_IDMAEN_POS          INT32_C(0)    /** @brief IDMA enable this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC1_IDMACTRLR_IDMABMODE_POS       INT32_C(1)    /** @brief Buffer mode selection. This bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC1_IDMACTRLR_IDMABACT_POS        INT32_C(2)    /** @brief Double buffer mode active buffer indication this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0). When IDMA is enabled this bit is toggled by hardware.. */
  #define SDMMC1_IDMABSIZER_IDMABNDT_POS       INT32_C(5)    /** @brief Number of transfers per buffer. This 8-bit value shall be multiplied by 8 to get the size of the buffer in 32-bit words and by 32 to get the size of the buffer in bytes. Example: IDMABNDT = 0x01: buffer size = 8 words = 32 bytes. These bits can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC1_IDMABASE0R_IDMABASE0_POS      INT32_C(0)    /** @brief Buffer 0 memory base address bits [31:2], shall be word aligned (bit [1:0] are always 0 and read only). This register can be written by firmware when DPSM is inactive (DPSMACT = 0), and can dynamically be written by firmware when DPSM active (DPSMACT = 1) and memory buffer 0 is inactive (IDMABACT = 1).. */
  #define SDMMC1_IDMABASE1R_IDMABASE1_POS      INT32_C(0)    /** @brief Buffer 1 memory base address, shall be word aligned (bit [1:0] are always 0 and read only). This register can be written by firmware when DPSM is inactive (DPSMACT = 0), and can dynamically be written by firmware when DPSM active (DPSMACT = 1) and memory buffer 1 is inactive (IDMABACT = 0).. */
  #define SDMMC1_FIFOR_FIFODATA_POS            INT32_C(0)    /** @brief Receive and transmit FIFO data this register can only be read or written by firmware when the DPSM is active (DPSMACT=1). The FIFO data occupies 16 entries of 32-bit words.. */
  #define SDMMC1_RESPCMDR_RESPCMD_POS          INT32_C(0)    /** @brief Response command index. */

  /*************************************************************************************************
   * @section SDMMC2 Definitions
   *************************************************************************************************/

  /**** @subsection Register Definitions ****/

  #define SDMMC2_POWER_PTR        (*(RW_ uint32_t*)UINT32_C(0x48022400))   /** @brief SDMMC power control register. */
  #define SDMMC2_CLKCR_PTR        (*(RW_ uint32_t*)UINT32_C(0x48022404))   /** @brief The SDMMC_CLKCR register controls the SDMMC_CK output clock, the SDMMC_RX_CLK receive clock, and the bus width.. */
  #define SDMMC2_ARGR_PTR         (*(RW_ uint32_t*)UINT32_C(0x48022408))   /** @brief The SDMMC_ARGR register contains a 32-bit command argument, which is sent to a card as part of a command message.. */
  #define SDMMC2_CMDR_PTR         (*(RW_ uint32_t*)UINT32_C(0x4802240C))   /** @brief The SDMMC_CMDR register contains the command index and command type bits. The command index is sent to a card as part of a command message. The command type bits control the command path state machine (CPSM).. */
  #define SDMMC2_RESP1R_PTR       (*(RO_ uint32_t*)UINT32_C(0x48022414))   /** @brief The SDMMC_RESP1/2/3/4R registers contain the status of a card, which is part of the received response.. */
  #define SDMMC2_RESP2R_PTR       (*(RO_ uint32_t*)UINT32_C(0x48022418))   /** @brief The SDMMC_RESP1/2/3/4R registers contain the status of a card, which is part of the received response.. */
  #define SDMMC2_RESP3R_PTR       (*(RO_ uint32_t*)UINT32_C(0x4802241C))   /** @brief The SDMMC_RESP1/2/3/4R registers contain the status of a card, which is part of the received response.. */
  #define SDMMC2_RESP4R_PTR       (*(RO_ uint32_t*)UINT32_C(0x48022420))   /** @brief The SDMMC_RESP1/2/3/4R registers contain the status of a card, which is part of the received response.. */
  #define SDMMC2_DTIMER_PTR       (*(RW_ uint32_t*)UINT32_C(0x48022424))   /** @brief The SDMMC_DTIMER register contains the data timeout period, in card bus clock periods. A counter loads the value from the SDMMC_DTIMER register, and starts decrementing when the data path state machine (DPSM) enters the wait_r or busy state. If the timer reaches 0 while the DPSM is in either of these states, the timeout status flag is set.. */
  #define SDMMC2_DLENR_PTR        (*(RW_ uint32_t*)UINT32_C(0x48022428))   /** @brief The SDMMC_DLENR register contains the number of data bytes to be transferred. The value is loaded into the data counter when data transfer starts.. */
  #define SDMMC2_DCTRL_PTR        (*(RW_ uint32_t*)UINT32_C(0x4802242C))   /** @brief The SDMMC_DCTRL register control the data path state machine (DPSM).. */
  #define SDMMC2_DCNTR_PTR        (*(RO_ uint32_t*)UINT32_C(0x48022430))   /** @brief The SDMMC_DCNTR register loads the value from the data length register (see SDMMC_DLENR) when the DPSM moves from the idle state to the wait_r or wait_s state. As data is transferred, the counter decrements the value until it reaches 0. The DPSM then moves to the idle state and when there has been no error, the data status end flag (DATAEND) is set.. */
  #define SDMMC2_STAR_PTR         (*(RO_ uint32_t*)UINT32_C(0x48022434))   /** @brief The SDMMC_STAR register is a read-only register. It contains two types of flag:static flags (bits [29,21,11:0]): these bits remain asserted until they are cleared by writing to the SDMMC interrupt clear register (see sdmmc_icr)dynamic flags (bits [20:12]): these bits change state depending on the state of the underlying logic (for example, FIFO full and empty flags are asserted and de-asserted as data while written to the FIFO). */
  #define SDMMC2_ICR_PTR          (*(RW_ uint32_t*)UINT32_C(0x48022438))   /** @brief The SDMMC_ICR register is a write-only register. Writing a bit with 1 clears the corresponding bit in the SDMMC_STAR status register.. */
  #define SDMMC2_MASKR_PTR        (*(RW_ uint32_t*)UINT32_C(0x4802243C))   /** @brief The interrupt mask register determines which status flags generate an interrupt request by setting the corresponding bit to 1.. */
  #define SDMMC2_ACKTIMER_PTR     (*(RW_ uint32_t*)UINT32_C(0x48022440))   /** @brief The SDMMC_ACKTIMER register contains the acknowledgment timeout period, in SDMMC_CK bus clock periods. A counter loads the value from the SDMMC_ACKTIMER register, and starts decrementing when the data path state machine (DPSM) enters the wait_ack state. If the timer reaches 0 while the DPSM is in this states, the acknowledgment timeout status flag is set.. */
  #define SDMMC2_IDMACTRLR_PTR    (*(RW_ uint32_t*)UINT32_C(0x48022450))   /** @brief The receive and transmit fifos can be read or written as 32-bit wide registers. The fifos contain 32 entries on 32 sequential addresses. This allows the CPU to use its load and store multiple operands to read from/write to the FIFO.. */
  #define SDMMC2_IDMABSIZER_PTR   (*(RW_ uint32_t*)UINT32_C(0x48022454))   /** @brief The SDMMC_IDMABSIZER register contains the buffers size when in double buffer configuration.. */
  #define SDMMC2_IDMABASE0R_PTR   (*(RW_ uint32_t*)UINT32_C(0x48022458))   /** @brief The SDMMC_IDMABASE0R register contains the memory buffer base address in single buffer configuration and the buffer 0 base address in double buffer configuration.. */
  #define SDMMC2_IDMABASE1R_PTR   (*(RW_ uint32_t*)UINT32_C(0x4802245C))   /** @brief The SDMMC_IDMABASE1R register contains the double buffer configuration second buffer memory base address.. */
  #define SDMMC2_FIFOR_PTR        (*(RW_ uint32_t*)UINT32_C(0x48022480))   /** @brief The receive and transmit fifos can be only read or written as word (32-bit) wide registers. The fifos contain 16 entries on sequential addresses. This allows the CPU to use its load and store multiple operands to read from/write to the fifo.when accessing SDMMC_FIFOR with half word or byte access an AHB bus fault is generated.. */
  #define SDMMC2_RESPCMDR_PTR     (*(RO_ uint32_t*)UINT32_C(0x48022410))   /** @brief SDMMC command response register. */

  /**** @subsection Field Mask Definitions ****/

  #define SDMMC2_POWER_PWRCTRL_MSK             UINT32_C(0x00000003)   /** @brief SDMMC state control bits. These bits can only be written when the SDMMC is not in the power-on state (PWRCTRL?11). These bits are used to define the functional state of the SDMMC signals: any further write will be ignored, PWRCTRL value will keep 11.. */
  #define SDMMC2_POWER_VSWITCH_MSK             UINT32_C(0x00000004)   /** @brief Voltage switch sequence start. This bit is used to start the timing critical section of the voltage switch sequence:. */
  #define SDMMC2_POWER_VSWITCHEN_MSK           UINT32_C(0x00000008)   /** @brief Voltage switch procedure enable. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). This bit is used to stop the SDMMC_CK after the voltage switch command response:. */
  #define SDMMC2_POWER_DIRPOL_MSK              UINT32_C(0x00000010)   /** @brief Data and command direction signals polarity selection. This bit can only be written when the SDMMC is in the power-off state (PWRCTRL = 00).. */
  #define SDMMC2_CLKCR_CLKDIV_MSK              UINT32_C(0x000003FF)   /** @brief Clock divide factor this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). This field defines the divide factor between the input clock (SDMMCCLK) and the output clock (SDMMC_CK): SDMMC_CK frequency = SDMMCCLK / [2 * CLKDIV]. 0xx: etc.. Xxx: etc... */
  #define SDMMC2_CLKCR_PWRSAV_MSK              UINT32_C(0x00001000)   /** @brief Power saving configuration bit this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0) for power saving, the SDMMC_CK clock output can be disabled when the bus is idle by setting PWRSAV:. */
  #define SDMMC2_CLKCR_WIDBUS_MSK              UINT32_C(0x0000C000)   /** @brief Wide bus mode enable bit this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). */
  #define SDMMC2_CLKCR_NEGEDGE_MSK             UINT32_C(0x00010000)   /** @brief SDMMC_CK dephasing selection bit for data and command. This bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). When clock division = 1 (CLKDIV = 0), this bit has no effect. Data and command change on SDMMC_CK falling edge. When clock division &gt;1 (CLKDIV &gt; 0) &amp; DDR = 0: - SDMMC_CK edge occurs on SDMMCCLK rising edge. When clock division >1 (CLKDIV > 0) & DDR = 1: - data changed on the SDMMCCLK falling edge succeeding a SDMMC_CK edge. - SDMMC_CK edge occurs on SDMMCCLK rising edge. - data changed on the SDMMC_CK falling edge succeeding a SDMMC_CK edge. - SDMMC_CK edge occurs on SDMMCCLK rising edge.. */
  #define SDMMC2_CLKCR_HWFC_EN_MSK             UINT32_C(0x00020000)   /** @brief Hardware flow control enable this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0) when hardware flow control is enabled, the meaning of the TXFIFOE and RXFIFOF flags change, please see SDMMC status register definition in section56.8.11.. */
  #define SDMMC2_CLKCR_DDR_MSK                 UINT32_C(0x00040000)   /** @brief Data rate signaling selection this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0) DDR rate shall only be selected with 4-bit or 8-bit wide bus mode. (WIDBUS &gt; 00). DDR = 1 has no effect when WIDBUS = 00 (1-bit wide bus). DDR rate shall only be selected with clock division &gt;1. (CLKDIV &gt; 0). */
  #define SDMMC2_CLKCR_BUSSPEED_MSK            UINT32_C(0x00080000)   /** @brief Bus speed mode selection between DS, HS, SDR12, SDR25 and SDR50, DDR50, SDR104. This bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). */
  #define SDMMC2_CLKCR_SELCLKRX_MSK            UINT32_C(0x00300000)   /** @brief Receive clock selection. These bits can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). */
  #define SDMMC2_ARGR_CMDARG_MSK               UINT32_C(0xFFFFFFFF)   /** @brief Command argument. These bits can only be written by firmware when CPSM is disabled (CPSMEN = 0). Command argument sent to a card as part of a command message. If a command contains an argument, it must be loaded into this register before writing a command to the command register.. */
  #define SDMMC2_CMDR_CMDINDEX_MSK             UINT32_C(0x0000003F)   /** @brief Command index. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). The command index is sent to the card as part of a command message.. */
  #define SDMMC2_CMDR_CMDTRANS_MSK             UINT32_C(0x00000040)   /** @brief The CPSM treats the command as a data transfer command, stops the interrupt period, and signals dataenable to the DPSM this bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). If this bit is set, the CPSM issues an end of interrupt period and issues dataenable signal to the DPSM when the command is sent.. */
  #define SDMMC2_CMDR_CMDSTOP_MSK              UINT32_C(0x00000080)   /** @brief The CPSM treats the command as a stop transmission command and signals abort to the DPSM. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). If this bit is set, the CPSM issues the abort signal to the DPSM when the command is sent.. */
  #define SDMMC2_CMDR_WAITRESP_MSK             UINT32_C(0x00000300)   /** @brief Wait for response bits. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). They are used to configure whether the CPSM is to wait for a response, and if yes, which kind of response.. */
  #define SDMMC2_CMDR_WAITINT_MSK              UINT32_C(0x00000400)   /** @brief CPSM waits for interrupt request. If this bit is set, the CPSM disables command timeout and waits for an card interrupt request (response). If this bit is cleared in the CPSM wait state, will cause the abort of the interrupt mode.. */
  #define SDMMC2_CMDR_WAITPEND_MSK             UINT32_C(0x00000800)   /** @brief CPSM waits for end of data transfer (cmdpend internal signal) from DPSM. This bit when set, the CPSM waits for the end of data transfer trigger before it starts sending a command. WAITPEND is only taken into account when DTMODE = MMC stream data transfer, WIDBUS = 1-bit wide bus mode, DPSMACT = 1 and DTDIR = from host to card.. */
  #define SDMMC2_CMDR_CPSMEN_MSK               UINT32_C(0x00001000)   /** @brief Command path state machine (CPSM) enable bit this bit is written 1 by firmware, and cleared by hardware when the CPSM enters the idle state. If this bit is set, the CPSM is enabled. When DTEN = 1, no command will be transfered nor boot procedure will be started. CPSMEN is cleared to 0.. */
  #define SDMMC2_CMDR_DTHOLD_MSK               UINT32_C(0x00002000)   /** @brief Hold new data block transmission and reception in the DPSM. If this bit is set, the DPSM will not move from the wait_s state to the send state or from the wait_r state to the receive state.. */
  #define SDMMC2_CMDR_BOOTMODE_MSK             UINT32_C(0x00004000)   /** @brief Select the boot mode procedure to be used. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). */
  #define SDMMC2_CMDR_BOOTEN_MSK               UINT32_C(0x00008000)   /** @brief Enable boot mode procedure.. */
  #define SDMMC2_CMDR_CMDSUSPEND_MSK           UINT32_C(0x00010000)   /** @brief The CPSM treats the command as a suspend or resume command and signals interrupt period start/end. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). CMDSUSPEND = 1 and CMDTRANS = 0 suspend command, start interrupt period when response bit BS=0. CMDSUSPEND = 1 and CMDTRANS = 1 resume command with data, end interrupt period when response bit DF=1.. */
  #define SDMMC2_RESP1R_CARDSTATUS1_MSK        UINT32_C(0xFFFFFFFF)   /** @brief See table 432. */
  #define SDMMC2_RESP2R_CARDSTATUS2_MSK        UINT32_C(0xFFFFFFFF)   /** @brief See table404.. */
  #define SDMMC2_RESP3R_CARDSTATUS3_MSK        UINT32_C(0xFFFFFFFF)   /** @brief See table404.. */
  #define SDMMC2_RESP4R_CARDSTATUS4_MSK        UINT32_C(0xFFFFFFFF)   /** @brief See table404.. */
  #define SDMMC2_DTIMER_DATATIME_MSK           UINT32_C(0xFFFFFFFF)   /** @brief Data and r1b busy timeout period this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). Data and r1b busy timeout period expressed in card bus clock periods.. */
  #define SDMMC2_DLENR_DATALENGTH_MSK          UINT32_C(0x01FFFFFF)   /** @brief Data length value this register can only be written by firmware when DPSM is inactive (DPSMACT = 0). Number of data bytes to be transferred. When DDR = 1 DATALENGTH is truncated to a multiple of 2. (The last odd byte is not transfered) when DATALENGTH = 0 no data will be transfered, when requested by a CPSMEN and CMDTRANS = 1 also no command will be transfered. DTEN and CPSMEN are cleared to 0.. */
  #define SDMMC2_DCTRL_DTEN_MSK                UINT32_C(0x00000001)   /** @brief Data transfer enable bit this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0). This bit is cleared by hardware when data transfer completes. This bit shall only be used to transfer data when no associated data transfer command is used, i.e. Shall not be used with SD or emmc cards.. */
  #define SDMMC2_DCTRL_DTDIR_MSK               UINT32_C(0x00000002)   /** @brief Data transfer direction selection this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC2_DCTRL_DTMODE_MSK              UINT32_C(0x0000000C)   /** @brief Data transfer mode selection. This bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC2_DCTRL_DBLOCKSIZE_MSK          UINT32_C(0x000000F0)   /** @brief Data block size this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0). Define the data block length when the block data transfer mode is selected: when DATALENGTH is not a multiple of DBLOCKSIZE, the transfered data is truncated at a multiple of DBLOCKSIZE. (Any remain data will not be transfered.) when DDR = 1, DBLOCKSIZE = 0000 shall not be used. (No data will be transfered). */
  #define SDMMC2_DCTRL_RWSTART_MSK             UINT32_C(0x00000100)   /** @brief Read wait start. If this bit is set, read wait operation starts.. */
  #define SDMMC2_DCTRL_RWSTOP_MSK              UINT32_C(0x00000200)   /** @brief Read wait stop this bit is written by firmware and auto cleared by hardware when the DPSM moves from the READ_WAIT state to the WAIT_R or IDLE state.. */
  #define SDMMC2_DCTRL_RWMOD_MSK               UINT32_C(0x00000400)   /** @brief Read wait mode. This bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC2_DCTRL_SDIOEN_MSK              UINT32_C(0x00000800)   /** @brief SD I/O interrupt enable functions this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0). If this bit is set, the DPSM enables the SD I/O card specific interrupt operation.. */
  #define SDMMC2_DCTRL_BOOTACKEN_MSK           UINT32_C(0x00001000)   /** @brief Enable the reception of the boot acknowledgment. This bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC2_DCTRL_FIFORST_MSK             UINT32_C(0x00002000)   /** @brief FIFO reset, will flush any remaining data. This bit can only be written by firmware when IDMAEN= 0 and DPSM is active (DPSMACT = 1). This bit will only take effect when a transfer error or transfer hold occurs.. */
  #define SDMMC2_DCNTR_DATACOUNT_MSK           UINT32_C(0x01FFFFFF)   /** @brief Data count value when read, the number of remaining data bytes to be transferred is returned. Write has no effect.. */
  #define SDMMC2_STAR_CCRCFAIL_MSK             UINT32_C(0x00000001)   /** @brief Command response received (CRC check failed). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_DCRCFAIL_MSK             UINT32_C(0x00000002)   /** @brief Data block sent/received (CRC check failed). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_CTIMEOUT_MSK             UINT32_C(0x00000004)   /** @brief Command response timeout. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR. The command timeout period has a fixed value of 64 SDMMC_CK clock periods.. */
  #define SDMMC2_STAR_DTIMEOUT_MSK             UINT32_C(0x00000008)   /** @brief Data timeout. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_TXUNDERR_MSK             UINT32_C(0x00000010)   /** @brief Transmit FIFO underrun error or IDMA read transfer error. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_RXOVERR_MSK              UINT32_C(0x00000020)   /** @brief Received FIFO overrun error or IDMA write transfer error. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_CMDREND_MSK              UINT32_C(0x00000040)   /** @brief Command response received (CRC check passed, or no CRC). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_CMDSENT_MSK              UINT32_C(0x00000080)   /** @brief Command sent (no response required). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_DATAEND_MSK              UINT32_C(0x00000100)   /** @brief Data transfer ended correctly. (data counter, DATACOUNT is zero and no errors occur). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_DHOLD_MSK                UINT32_C(0x00000200)   /** @brief Data transfer hold. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_DBCKEND_MSK              UINT32_C(0x00000400)   /** @brief Data block sent/received. (CRC check passed) and DPSM moves to the READWAIT state. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_DABORT_MSK               UINT32_C(0x00000800)   /** @brief Data transfer aborted by CMD12. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_DPSMACT_MSK              UINT32_C(0x00001000)   /** @brief Data path state machine active, i.e. Not in idle state. This is a hardware status flag only, does not generate an interrupt.. */
  #define SDMMC2_STAR_CPSMACT_MSK              UINT32_C(0x00002000)   /** @brief Command path state machine active, i.e. Not in idle state. This is a hardware status flag only, does not generate an interrupt.. */
  #define SDMMC2_STAR_TXFIFOHE_MSK             UINT32_C(0x00004000)   /** @brief Transmit FIFO half empty at least half the number of words can be written into the FIFO. This bit is cleared when the FIFO becomes half+1 full.. */
  #define SDMMC2_STAR_RXFIFOHF_MSK             UINT32_C(0x00008000)   /** @brief Receive FIFO half full there are at least half the number of words in the FIFO. This bit is cleared when the FIFO becomes half+1 empty.. */
  #define SDMMC2_STAR_TXFIFOF_MSK              UINT32_C(0x00010000)   /** @brief Transmit FIFO full this is a hardware status flag only, does not generate an interrupt. This bit is cleared when one FIFO location becomes empty.. */
  #define SDMMC2_STAR_RXFIFOF_MSK              UINT32_C(0x00020000)   /** @brief Receive FIFO full this bit is cleared when one FIFO location becomes empty.. */
  #define SDMMC2_STAR_TXFIFOE_MSK              UINT32_C(0x00040000)   /** @brief Transmit FIFO empty this bit is cleared when one FIFO location becomes full.. */
  #define SDMMC2_STAR_RXFIFOE_MSK              UINT32_C(0x00080000)   /** @brief Receive FIFO empty this is a hardware status flag only, does not generate an interrupt. This bit is cleared when one FIFO location becomes full.. */
  #define SDMMC2_STAR_BUSYD0_MSK               UINT32_C(0x00100000)   /** @brief Inverted value of SDMMC_D0 line (busy), sampled at the end of a CMD response and a second time 2 SDMMC_CK cycles after the CMD response. This bit is reset to not busy when the SDMMCD0 line changes from busy to not busy. This bit does not signal busy due to data transfer. This is a hardware status flag only, it does not generate an interrupt.. */
  #define SDMMC2_STAR_BUSYD0END_MSK            UINT32_C(0x00200000)   /** @brief End of SDMMC_D0 busy following a CMD response detected. This indicates only end of busy following a CMD response. This bit does not signal busy due to data transfer. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_SDIOIT_MSK               UINT32_C(0x00400000)   /** @brief SDIO interrupt received. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_ACKFAIL_MSK              UINT32_C(0x00800000)   /** @brief Boot acknowledgment received (boot acknowledgment check fail). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_ACKTIMEOUT_MSK           UINT32_C(0x01000000)   /** @brief Boot acknowledgment timeout. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_VSWEND_MSK               UINT32_C(0x02000000)   /** @brief Voltage switch critical timing section completion. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_CKSTOP_MSK               UINT32_C(0x04000000)   /** @brief SDMMC_CK stopped in voltage switch procedure. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_IDMATE_MSK               UINT32_C(0x08000000)   /** @brief IDMA transfer error. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_IDMABTC_MSK              UINT32_C(0x10000000)   /** @brief IDMA buffer transfer complete. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_ICR_CCRCFAILC_MSK             UINT32_C(0x00000001)   /** @brief CCRCFAIL flag clear bit set by software to clear the CCRCFAIL flag.. */
  #define SDMMC2_ICR_DCRCFAILC_MSK             UINT32_C(0x00000002)   /** @brief DCRCFAIL flag clear bit set by software to clear the DCRCFAIL flag.. */
  #define SDMMC2_ICR_CTIMEOUTC_MSK             UINT32_C(0x00000004)   /** @brief CTIMEOUT flag clear bit set by software to clear the CTIMEOUT flag.. */
  #define SDMMC2_ICR_DTIMEOUTC_MSK             UINT32_C(0x00000008)   /** @brief DTIMEOUT flag clear bit set by software to clear the DTIMEOUT flag.. */
  #define SDMMC2_ICR_TXUNDERRC_MSK             UINT32_C(0x00000010)   /** @brief TXUNDERR flag clear bit set by software to clear TXUNDERR flag.. */
  #define SDMMC2_ICR_RXOVERRC_MSK              UINT32_C(0x00000020)   /** @brief RXOVERR flag clear bit set by software to clear the RXOVERR flag.. */
  #define SDMMC2_ICR_CMDRENDC_MSK              UINT32_C(0x00000040)   /** @brief CMDREND flag clear bit set by software to clear the CMDREND flag.. */
  #define SDMMC2_ICR_CMDSENTC_MSK              UINT32_C(0x00000080)   /** @brief CMDSENT flag clear bit set by software to clear the CMDSENT flag.. */
  #define SDMMC2_ICR_DATAENDC_MSK              UINT32_C(0x00000100)   /** @brief DATAEND flag clear bit set by software to clear the DATAEND flag.. */
  #define SDMMC2_ICR_DHOLDC_MSK                UINT32_C(0x00000200)   /** @brief DHOLD flag clear bit set by software to clear the DHOLD flag.. */
  #define SDMMC2_ICR_DBCKENDC_MSK              UINT32_C(0x00000400)   /** @brief DBCKEND flag clear bit set by software to clear the DBCKEND flag.. */
  #define SDMMC2_ICR_DABORTC_MSK               UINT32_C(0x00000800)   /** @brief DABORT flag clear bit set by software to clear the DABORT flag.. */
  #define SDMMC2_ICR_BUSYD0ENDC_MSK            UINT32_C(0x00200000)   /** @brief BUSYD0END flag clear bit set by software to clear the BUSYD0END flag.. */
  #define SDMMC2_ICR_SDIOITC_MSK               UINT32_C(0x00400000)   /** @brief SDIOIT flag clear bit set by software to clear the SDIOIT flag.. */
  #define SDMMC2_ICR_ACKFAILC_MSK              UINT32_C(0x00800000)   /** @brief ACKFAIL flag clear bit set by software to clear the ACKFAIL flag.. */
  #define SDMMC2_ICR_ACKTIMEOUTC_MSK           UINT32_C(0x01000000)   /** @brief ACKTIMEOUT flag clear bit set by software to clear the ACKTIMEOUT flag.. */
  #define SDMMC2_ICR_VSWENDC_MSK               UINT32_C(0x02000000)   /** @brief VSWEND flag clear bit set by software to clear the VSWEND flag.. */
  #define SDMMC2_ICR_CKSTOPC_MSK               UINT32_C(0x04000000)   /** @brief CKSTOP flag clear bit set by software to clear the CKSTOP flag.. */
  #define SDMMC2_ICR_IDMATEC_MSK               UINT32_C(0x08000000)   /** @brief IDMA transfer error clear bit set by software to clear the IDMATE flag.. */
  #define SDMMC2_ICR_IDMABTCC_MSK              UINT32_C(0x10000000)   /** @brief IDMA buffer transfer complete clear bit set by software to clear the IDMABTC flag.. */
  #define SDMMC2_MASKR_CCRCFAILIE_MSK          UINT32_C(0x00000001)   /** @brief Command CRC fail interrupt enable set and cleared by software to enable/disable interrupt caused by command CRC failure.. */
  #define SDMMC2_MASKR_DCRCFAILIE_MSK          UINT32_C(0x00000002)   /** @brief Data CRC fail interrupt enable set and cleared by software to enable/disable interrupt caused by data CRC failure.. */
  #define SDMMC2_MASKR_CTIMEOUTIE_MSK          UINT32_C(0x00000004)   /** @brief Command timeout interrupt enable set and cleared by software to enable/disable interrupt caused by command timeout.. */
  #define SDMMC2_MASKR_DTIMEOUTIE_MSK          UINT32_C(0x00000008)   /** @brief Data timeout interrupt enable set and cleared by software to enable/disable interrupt caused by data timeout.. */
  #define SDMMC2_MASKR_TXUNDERRIE_MSK          UINT32_C(0x00000010)   /** @brief Tx FIFO underrun error interrupt enable set and cleared by software to enable/disable interrupt caused by tx FIFO underrun error.. */
  #define SDMMC2_MASKR_RXOVERRIE_MSK           UINT32_C(0x00000020)   /** @brief Rx FIFO overrun error interrupt enable set and cleared by software to enable/disable interrupt caused by rx FIFO overrun error.. */
  #define SDMMC2_MASKR_CMDRENDIE_MSK           UINT32_C(0x00000040)   /** @brief Command response received interrupt enable set and cleared by software to enable/disable interrupt caused by receiving command response.. */
  #define SDMMC2_MASKR_CMDSENTIE_MSK           UINT32_C(0x00000080)   /** @brief Command sent interrupt enable set and cleared by software to enable/disable interrupt caused by sending command.. */
  #define SDMMC2_MASKR_DATAENDIE_MSK           UINT32_C(0x00000100)   /** @brief Data end interrupt enable set and cleared by software to enable/disable interrupt caused by data end.. */
  #define SDMMC2_MASKR_DHOLDIE_MSK             UINT32_C(0x00000200)   /** @brief Data hold interrupt enable set and cleared by software to enable/disable the interrupt generated when sending new data is hold in the DPSM wait_s state.. */
  #define SDMMC2_MASKR_DBCKENDIE_MSK           UINT32_C(0x00000400)   /** @brief Data block end interrupt enable set and cleared by software to enable/disable interrupt caused by data block end.. */
  #define SDMMC2_MASKR_DABORTIE_MSK            UINT32_C(0x00000800)   /** @brief Data transfer aborted interrupt enable set and cleared by software to enable/disable interrupt caused by a data transfer being aborted.. */
  #define SDMMC2_MASKR_TXFIFOHEIE_MSK          UINT32_C(0x00004000)   /** @brief Tx FIFO half empty interrupt enable set and cleared by software to enable/disable interrupt caused by tx FIFO half empty.. */
  #define SDMMC2_MASKR_RXFIFOHFIE_MSK          UINT32_C(0x00008000)   /** @brief Rx FIFO half full interrupt enable set and cleared by software to enable/disable interrupt caused by rx FIFO half full.. */
  #define SDMMC2_MASKR_RXFIFOFIE_MSK           UINT32_C(0x00020000)   /** @brief Rx FIFO full interrupt enable set and cleared by software to enable/disable interrupt caused by rx FIFO full.. */
  #define SDMMC2_MASKR_TXFIFOEIE_MSK           UINT32_C(0x00040000)   /** @brief Tx FIFO empty interrupt enable set and cleared by software to enable/disable interrupt caused by tx FIFO empty.. */
  #define SDMMC2_MASKR_BUSYD0ENDIE_MSK         UINT32_C(0x00200000)   /** @brief BUSYD0END interrupt enable set and cleared by software to enable/disable the interrupt generated when SDMMC_D0 signal changes from busy to NOT busy following a CMD response.. */
  #define SDMMC2_MASKR_SDIOITIE_MSK            UINT32_C(0x00400000)   /** @brief SDIO mode interrupt received interrupt enable set and cleared by software to enable/disable the interrupt generated when receiving the SDIO mode interrupt.. */
  #define SDMMC2_MASKR_ACKFAILIE_MSK           UINT32_C(0x00800000)   /** @brief Acknowledgment fail interrupt enable set and cleared by software to enable/disable interrupt caused by acknowledgment fail.. */
  #define SDMMC2_MASKR_ACKTIMEOUTIE_MSK        UINT32_C(0x01000000)   /** @brief Acknowledgment timeout interrupt enable set and cleared by software to enable/disable interrupt caused by acknowledgment timeout.. */
  #define SDMMC2_MASKR_VSWENDIE_MSK            UINT32_C(0x02000000)   /** @brief Voltage switch critical timing section completion interrupt enable set and cleared by software to enable/disable the interrupt generated when voltage switch critical timing section completion.. */
  #define SDMMC2_MASKR_CKSTOPIE_MSK            UINT32_C(0x04000000)   /** @brief Voltage switch clock stopped interrupt enable set and cleared by software to enable/disable interrupt caused by voltage switch clock stopped.. */
  #define SDMMC2_MASKR_IDMABTCIE_MSK           UINT32_C(0x10000000)   /** @brief IDMA buffer transfer complete interrupt enable set and cleared by software to enable/disable the interrupt generated when the IDMA has transferred all data belonging to a memory buffer.. */
  #define SDMMC2_ACKTIMER_ACKTIME_MSK          UINT32_C(0x01FFFFFF)   /** @brief Boot acknowledgment timeout period this bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). Boot acknowledgment timeout period expressed in card bus clock periods.. */
  #define SDMMC2_IDMACTRLR_IDMAEN_MSK          UINT32_C(0x00000001)   /** @brief IDMA enable this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC2_IDMACTRLR_IDMABMODE_MSK       UINT32_C(0x00000002)   /** @brief Buffer mode selection. This bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC2_IDMACTRLR_IDMABACT_MSK        UINT32_C(0x00000004)   /** @brief Double buffer mode active buffer indication this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0). When IDMA is enabled this bit is toggled by hardware.. */
  #define SDMMC2_IDMABSIZER_IDMABNDT_MSK       UINT32_C(0x00001FE0)   /** @brief Number of transfers per buffer. This 8-bit value shall be multiplied by 8 to get the size of the buffer in 32-bit words and by 32 to get the size of the buffer in bytes. Example: IDMABNDT = 0x01: buffer size = 8 words = 32 bytes. These bits can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC2_IDMABASE0R_IDMABASE0_MSK      UINT32_C(0xFFFFFFFF)   /** @brief Buffer 0 memory base address bits [31:2], shall be word aligned (bit [1:0] are always 0 and read only). This register can be written by firmware when DPSM is inactive (DPSMACT = 0), and can dynamically be written by firmware when DPSM active (DPSMACT = 1) and memory buffer 0 is inactive (IDMABACT = 1).. */
  #define SDMMC2_IDMABASE1R_IDMABASE1_MSK      UINT32_C(0xFFFFFFFF)   /** @brief Buffer 1 memory base address, shall be word aligned (bit [1:0] are always 0 and read only). This register can be written by firmware when DPSM is inactive (DPSMACT = 0), and can dynamically be written by firmware when DPSM active (DPSMACT = 1) and memory buffer 1 is inactive (IDMABACT = 0).. */
  #define SDMMC2_FIFOR_FIFODATA_MSK            UINT32_C(0xFFFFFFFF)   /** @brief Receive and transmit FIFO data this register can only be read or written by firmware when the DPSM is active (DPSMACT=1). The FIFO data occupies 16 entries of 32-bit words.. */
  #define SDMMC2_RESPCMDR_RESPCMD_MSK          UINT32_C(0x0000003F)   /** @brief Response command index. */

  /**** @subsection Field Position Definitions ****/

  #define SDMMC2_POWER_PWRCTRL_POS             INT32_C(0)    /** @brief SDMMC state control bits. These bits can only be written when the SDMMC is not in the power-on state (PWRCTRL?11). These bits are used to define the functional state of the SDMMC signals: any further write will be ignored, PWRCTRL value will keep 11.. */
  #define SDMMC2_POWER_VSWITCH_POS             INT32_C(2)    /** @brief Voltage switch sequence start. This bit is used to start the timing critical section of the voltage switch sequence:. */
  #define SDMMC2_POWER_VSWITCHEN_POS           INT32_C(3)    /** @brief Voltage switch procedure enable. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). This bit is used to stop the SDMMC_CK after the voltage switch command response:. */
  #define SDMMC2_POWER_DIRPOL_POS              INT32_C(4)    /** @brief Data and command direction signals polarity selection. This bit can only be written when the SDMMC is in the power-off state (PWRCTRL = 00).. */
  #define SDMMC2_CLKCR_CLKDIV_POS              INT32_C(0)    /** @brief Clock divide factor this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). This field defines the divide factor between the input clock (SDMMCCLK) and the output clock (SDMMC_CK): SDMMC_CK frequency = SDMMCCLK / [2 * CLKDIV]. 0xx: etc.. Xxx: etc... */
  #define SDMMC2_CLKCR_PWRSAV_POS              INT32_C(12)   /** @brief Power saving configuration bit this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0) for power saving, the SDMMC_CK clock output can be disabled when the bus is idle by setting PWRSAV:. */
  #define SDMMC2_CLKCR_WIDBUS_POS              INT32_C(14)   /** @brief Wide bus mode enable bit this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). */
  #define SDMMC2_CLKCR_NEGEDGE_POS             INT32_C(16)   /** @brief SDMMC_CK dephasing selection bit for data and command. This bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). When clock division = 1 (CLKDIV = 0), this bit has no effect. Data and command change on SDMMC_CK falling edge. When clock division &gt;1 (CLKDIV &gt; 0) &amp; DDR = 0: - SDMMC_CK edge occurs on SDMMCCLK rising edge. When clock division >1 (CLKDIV > 0) & DDR = 1: - data changed on the SDMMCCLK falling edge succeeding a SDMMC_CK edge. - SDMMC_CK edge occurs on SDMMCCLK rising edge. - data changed on the SDMMC_CK falling edge succeeding a SDMMC_CK edge. - SDMMC_CK edge occurs on SDMMCCLK rising edge.. */
  #define SDMMC2_CLKCR_HWFC_EN_POS             INT32_C(17)   /** @brief Hardware flow control enable this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0) when hardware flow control is enabled, the meaning of the TXFIFOE and RXFIFOF flags change, please see SDMMC status register definition in section56.8.11.. */
  #define SDMMC2_CLKCR_DDR_POS                 INT32_C(18)   /** @brief Data rate signaling selection this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0) DDR rate shall only be selected with 4-bit or 8-bit wide bus mode. (WIDBUS &gt; 00). DDR = 1 has no effect when WIDBUS = 00 (1-bit wide bus). DDR rate shall only be selected with clock division &gt;1. (CLKDIV &gt; 0). */
  #define SDMMC2_CLKCR_BUSSPEED_POS            INT32_C(19)   /** @brief Bus speed mode selection between DS, HS, SDR12, SDR25 and SDR50, DDR50, SDR104. This bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). */
  #define SDMMC2_CLKCR_SELCLKRX_POS            INT32_C(20)   /** @brief Receive clock selection. These bits can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). */
  #define SDMMC2_ARGR_CMDARG_POS               INT32_C(0)    /** @brief Command argument. These bits can only be written by firmware when CPSM is disabled (CPSMEN = 0). Command argument sent to a card as part of a command message. If a command contains an argument, it must be loaded into this register before writing a command to the command register.. */
  #define SDMMC2_CMDR_CMDINDEX_POS             INT32_C(0)    /** @brief Command index. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). The command index is sent to the card as part of a command message.. */
  #define SDMMC2_CMDR_CMDTRANS_POS             INT32_C(6)    /** @brief The CPSM treats the command as a data transfer command, stops the interrupt period, and signals dataenable to the DPSM this bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). If this bit is set, the CPSM issues an end of interrupt period and issues dataenable signal to the DPSM when the command is sent.. */
  #define SDMMC2_CMDR_CMDSTOP_POS              INT32_C(7)    /** @brief The CPSM treats the command as a stop transmission command and signals abort to the DPSM. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). If this bit is set, the CPSM issues the abort signal to the DPSM when the command is sent.. */
  #define SDMMC2_CMDR_WAITRESP_POS             INT32_C(8)    /** @brief Wait for response bits. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). They are used to configure whether the CPSM is to wait for a response, and if yes, which kind of response.. */
  #define SDMMC2_CMDR_WAITINT_POS              INT32_C(10)   /** @brief CPSM waits for interrupt request. If this bit is set, the CPSM disables command timeout and waits for an card interrupt request (response). If this bit is cleared in the CPSM wait state, will cause the abort of the interrupt mode.. */
  #define SDMMC2_CMDR_WAITPEND_POS             INT32_C(11)   /** @brief CPSM waits for end of data transfer (cmdpend internal signal) from DPSM. This bit when set, the CPSM waits for the end of data transfer trigger before it starts sending a command. WAITPEND is only taken into account when DTMODE = MMC stream data transfer, WIDBUS = 1-bit wide bus mode, DPSMACT = 1 and DTDIR = from host to card.. */
  #define SDMMC2_CMDR_CPSMEN_POS               INT32_C(12)   /** @brief Command path state machine (CPSM) enable bit this bit is written 1 by firmware, and cleared by hardware when the CPSM enters the idle state. If this bit is set, the CPSM is enabled. When DTEN = 1, no command will be transfered nor boot procedure will be started. CPSMEN is cleared to 0.. */
  #define SDMMC2_CMDR_DTHOLD_POS               INT32_C(13)   /** @brief Hold new data block transmission and reception in the DPSM. If this bit is set, the DPSM will not move from the wait_s state to the send state or from the wait_r state to the receive state.. */
  #define SDMMC2_CMDR_BOOTMODE_POS             INT32_C(14)   /** @brief Select the boot mode procedure to be used. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). */
  #define SDMMC2_CMDR_BOOTEN_POS               INT32_C(15)   /** @brief Enable boot mode procedure.. */
  #define SDMMC2_CMDR_CMDSUSPEND_POS           INT32_C(16)   /** @brief The CPSM treats the command as a suspend or resume command and signals interrupt period start/end. This bit can only be written by firmware when CPSM is disabled (CPSMEN = 0). CMDSUSPEND = 1 and CMDTRANS = 0 suspend command, start interrupt period when response bit BS=0. CMDSUSPEND = 1 and CMDTRANS = 1 resume command with data, end interrupt period when response bit DF=1.. */
  #define SDMMC2_RESP1R_CARDSTATUS1_POS        INT32_C(0)    /** @brief See table 432. */
  #define SDMMC2_RESP2R_CARDSTATUS2_POS        INT32_C(0)    /** @brief See table404.. */
  #define SDMMC2_RESP3R_CARDSTATUS3_POS        INT32_C(0)    /** @brief See table404.. */
  #define SDMMC2_RESP4R_CARDSTATUS4_POS        INT32_C(0)    /** @brief See table404.. */
  #define SDMMC2_DTIMER_DATATIME_POS           INT32_C(0)    /** @brief Data and r1b busy timeout period this bit can only be written when the CPSM and DPSM are not active (CPSMACT = 0 and DPSMACT = 0). Data and r1b busy timeout period expressed in card bus clock periods.. */
  #define SDMMC2_DLENR_DATALENGTH_POS          INT32_C(0)    /** @brief Data length value this register can only be written by firmware when DPSM is inactive (DPSMACT = 0). Number of data bytes to be transferred. When DDR = 1 DATALENGTH is truncated to a multiple of 2. (The last odd byte is not transfered) when DATALENGTH = 0 no data will be transfered, when requested by a CPSMEN and CMDTRANS = 1 also no command will be transfered. DTEN and CPSMEN are cleared to 0.. */
  #define SDMMC2_DCTRL_DTEN_POS                INT32_C(0)    /** @brief Data transfer enable bit this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0). This bit is cleared by hardware when data transfer completes. This bit shall only be used to transfer data when no associated data transfer command is used, i.e. Shall not be used with SD or emmc cards.. */
  #define SDMMC2_DCTRL_DTDIR_POS               INT32_C(1)    /** @brief Data transfer direction selection this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC2_DCTRL_DTMODE_POS              INT32_C(2)    /** @brief Data transfer mode selection. This bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC2_DCTRL_DBLOCKSIZE_POS          INT32_C(4)    /** @brief Data block size this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0). Define the data block length when the block data transfer mode is selected: when DATALENGTH is not a multiple of DBLOCKSIZE, the transfered data is truncated at a multiple of DBLOCKSIZE. (Any remain data will not be transfered.) when DDR = 1, DBLOCKSIZE = 0000 shall not be used. (No data will be transfered). */
  #define SDMMC2_DCTRL_RWSTART_POS             INT32_C(8)    /** @brief Read wait start. If this bit is set, read wait operation starts.. */
  #define SDMMC2_DCTRL_RWSTOP_POS              INT32_C(9)    /** @brief Read wait stop this bit is written by firmware and auto cleared by hardware when the DPSM moves from the READ_WAIT state to the WAIT_R or IDLE state.. */
  #define SDMMC2_DCTRL_RWMOD_POS               INT32_C(10)   /** @brief Read wait mode. This bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC2_DCTRL_SDIOEN_POS              INT32_C(11)   /** @brief SD I/O interrupt enable functions this bit can only be written by firmware when DPSM is inactive (DPSMACT = 0). If this bit is set, the DPSM enables the SD I/O card specific interrupt operation.. */
  #define SDMMC2_DCTRL_BOOTACKEN_POS           INT32_C(12)   /** @brief Enable the reception of the boot acknowledgment. This bit can only be written by firmware when DPSM is inactive (DPSMACT = 0).. */
  #define SDMMC2_DCTRL_FIFORST_POS             INT32_C(13)   /** @brief FIFO reset, will flush any remaining data. This bit can only be written by firmware when IDMAEN= 0 and DPSM is active (DPSMACT = 1). This bit will only take effect when a transfer error or transfer hold occurs.. */
  #define SDMMC2_DCNTR_DATACOUNT_POS           INT32_C(0)    /** @brief Data count value when read, the number of remaining data bytes to be transferred is returned. Write has no effect.. */
  #define SDMMC2_STAR_CCRCFAIL_POS             INT32_C(0)    /** @brief Command response received (CRC check failed). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_DCRCFAIL_POS             INT32_C(1)    /** @brief Data block sent/received (CRC check failed). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_CTIMEOUT_POS             INT32_C(2)    /** @brief Command response timeout. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR. The command timeout period has a fixed value of 64 SDMMC_CK clock periods.. */
  #define SDMMC2_STAR_DTIMEOUT_POS             INT32_C(3)    /** @brief Data timeout. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_TXUNDERR_POS             INT32_C(4)    /** @brief Transmit FIFO underrun error or IDMA read transfer error. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_RXOVERR_POS              INT32_C(5)    /** @brief Received FIFO overrun error or IDMA write transfer error. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_CMDREND_POS              INT32_C(6)    /** @brief Command response received (CRC check passed, or no CRC). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_CMDSENT_POS              INT32_C(7)    /** @brief Command sent (no response required). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_DATAEND_POS              INT32_C(8)    /** @brief Data transfer ended correctly. (data counter, DATACOUNT is zero and no errors occur). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_DHOLD_POS                INT32_C(9)    /** @brief Data transfer hold. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_DBCKEND_POS              INT32_C(10)   /** @brief Data block sent/received. (CRC check passed) and DPSM moves to the READWAIT state. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_DABORT_POS               INT32_C(11)   /** @brief Data transfer aborted by CMD12. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_DPSMACT_POS              INT32_C(12)   /** @brief Data path state machine active, i.e. Not in idle state. This is a hardware status flag only, does not generate an interrupt.. */
  #define SDMMC2_STAR_CPSMACT_POS              INT32_C(13)   /** @brief Command path state machine active, i.e. Not in idle state. This is a hardware status flag only, does not generate an interrupt.. */
  #define SDMMC2_STAR_TXFIFOHE_POS             INT32_C(14)   /** @brief Transmit FIFO half empty at least half the number of words can be written into the FIFO. This bit is cleared when the FIFO becomes half+1 full.. */
  #define SDMMC2_STAR_RXFIFOHF_POS             INT32_C(15)   /** @brief Receive FIFO half full there are at least half the number of words in the FIFO. This bit is cleared when the FIFO becomes half+1 empty.. */
  #define SDMMC2_STAR_TXFIFOF_POS              INT32_C(16)   /** @brief Transmit FIFO full this is a hardware status flag only, does not generate an interrupt. This bit is cleared when one FIFO location becomes empty.. */
  #define SDMMC2_STAR_RXFIFOF_POS              INT32_C(17)   /** @brief Receive FIFO full this bit is cleared when one FIFO location becomes empty.. */
  #define SDMMC2_STAR_TXFIFOE_POS              INT32_C(18)   /** @brief Transmit FIFO empty this bit is cleared when one FIFO location becomes full.. */
  #define SDMMC2_STAR_RXFIFOE_POS              INT32_C(19)   /** @brief Receive FIFO empty this is a hardware status flag only, does not generate an interrupt. This bit is cleared when one FIFO location becomes full.. */
  #define SDMMC2_STAR_BUSYD0_POS               INT32_C(20)   /** @brief Inverted value of SDMMC_D0 line (busy), sampled at the end of a CMD response and a second time 2 SDMMC_CK cycles after the CMD response. This bit is reset to not busy when the SDMMCD0 line changes from busy to not busy. This bit does not signal busy due to data transfer. This is a hardware status flag only, it does not generate an interrupt.. */
  #define SDMMC2_STAR_BUSYD0END_POS            INT32_C(21)   /** @brief End of SDMMC_D0 busy following a CMD response detected. This indicates only end of busy following a CMD response. This bit does not signal busy due to data transfer. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_SDIOIT_POS               INT32_C(22)   /** @brief SDIO interrupt received. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_ACKFAIL_POS              INT32_C(23)   /** @brief Boot acknowledgment received (boot acknowledgment check fail). Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_ACKTIMEOUT_POS           INT32_C(24)   /** @brief Boot acknowledgment timeout. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_VSWEND_POS               INT32_C(25)   /** @brief Voltage switch critical timing section completion. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_CKSTOP_POS               INT32_C(26)   /** @brief SDMMC_CK stopped in voltage switch procedure. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_IDMATE_POS               INT32_C(27)   /** @brief IDMA transfer error. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_STAR_IDMABTC_POS              INT32_C(28)   /** @brief IDMA buffer transfer complete. Interrupt flag is cleared by writing corresponding interrupt clear bit in SDMMC_ICR.. */
  #define SDMMC2_ICR_CCRCFAILC_POS             INT32_C(0)    /** @brief CCRCFAIL flag clear bit set by software to clear the CCRCFAIL flag.. */
  #define SDMMC2_ICR_DCRCFAILC_POS             INT32_C(1)    /** @brief DCRCFAIL flag clear bit set by software to clear the DCRCFAIL flag.. */
  #define SDMMC2_ICR_CTIMEOUTC_POS             INT32_C(2)    /** @brief CTIMEOUT flag clear bit set by software to clear the CTIMEOUT flag.. */
  #define SDMMC2_ICR_DTIMEOUTC_POS             INT32_C(3)    /** @brief DTIMEOUT flag clear bit set by software to clear the DTIMEOUT flag.. */
  #define SDMMC2_ICR_TXUNDERRC_POS             INT32_C(4)    /** @brief TXUNDERR flag clear bit set by software to clear TXUNDERR flag.. */
  #define SDMMC2_ICR_RXOVERRC_POS              INT32_C(5)    /** @brief RXOVERR flag clear bit set by software to clear the RXOVERR flag.. */
