  #define SDMMC2_ICR_CMDSENTC_POS              INT32_C(7)    /** @brief CMDSENT flag clear bit set by software to clear the CMDSENT flag.. */
  #define SDMMC2_ICR_DATAENDC_POS              INT32_C(8)    /** @brief DATAEND flag clear bit set by software to clear the DATAEND flag.. */
  #define SDMMC2_ICR_DHOLDC_POS                INT32_C(9)    /** @brief DHOLD flag clear bit set by software to clear the DHOLD flag.. */
  #define SDMMC2_ICR_DBCKENDC_POS              INT32_C(10)   /** @brief DBCKEND flag clear bit set by software to clear the DBCKEND flag.. */
  #define SDMMC2_ICR_DABORTC_POS               INT32_C(11)   /** @brief DABORT flag clear bit set by software to clear the DABORT flag.. */
  #define SDMMC2_ICR_BUSYD0ENDC_POS            INT32_C(21)   /** @brief BUSYD0END flag clear bit set by software to clear the BUSYD0END flag.. */
  #define SDMMC2_ICR_SDIOITC_POS               INT32_C(22)   /** @brief SDIOIT flag clear bit set by software to clear the SDIOIT flag.. */
  #define SDMMC2_ICR_ACKFAILC_POS              INT32_C(23)   /** @brief ACKFAIL flag clear bit set by software to clear the ACKFAIL flag.. */
  #define SDMMC2_ICR_ACKTIMEOUTC_POS           INT32_C(24)   /** @brief ACKTIMEOUT flag clear bit set by software to clear the ACKTIMEOUT flag.. */
