  #define SDMMC2_ICR_IDMABTCC_POS              INT32_C(28)   /** @brief IDMA buffer transfer complete clear bit set by software to clear the IDMABTC flag.. */
  #define SDMMC2_MASKR_CCRCFAILIE_POS          INT32_C(0)    /** @brief Command CRC fail interrupt enable set and cleared by software to enable/disable interrupt caused by command CRC failure.. */
  #define SDMMC2_MASKR_DCRCFAILIE_POS          INT32_C(1)    /** @brief Data CRC fail interrupt enable set and cleared by software to enable/disable interrupt caused by data CRC failure.. */
  #define SDMMC2_MASKR_CTIMEOUTIE_POS          INT32_C(2)    /** @brief Command timeout interrupt enable set and cleared by software to enable/disable interrupt caused by command timeout.. */
