  /**** @subsection Register Definitions ****/

  #define VREFBUF_CSR_PTR   (*(RW_ uint32_t*)UINT32_C(0x58003C00))   /** @brief VREFBUF control and status register. */
  #define VREFBUF_CCR_PTR   (*(RW_ uint32_t*)UINT32_C(0x58003C04))   /** @brief VREFBUF calibration control register. */

  /**** @subsection Field Mask Definitions ****/

  #define VREFBUF_CSR_ENVR_MSK   UINT32_C(0x00000001)   /** @brief Voltage reference buffer mode enable this bit is used to enable the voltage reference buffer mode.. */
  #define VREFBUF_CSR_HIZ_MSK    UINT32_C(0x00000002)   /** @brief High impedance mode this bit controls the analog switch to connect or not the VREF+ pin. Refer to table196: VREF buffer modes for the mode descriptions depending on ENVR bit configuration.. */
  #define VREFBUF_CSR_VRR_MSK    UINT32_C(0x00000008)   /** @brief Voltage reference buffer ready. */
  #define VREFBUF_CSR_VRS_MSK    UINT32_C(0x00000070)   /** @brief Voltage reference scale these bits select the value generated by the voltage reference buffer. Other: reserved. */
  #define VREFBUF_CCR_TRIM_MSK   UINT32_C(0x0000003F)   /** @brief Trimming code these bits are automatically initialized after reset with the trimming value stored in the flash memory during the production test. Writing into these bits allows to tune the internal reference buffer voltage.. */

  /**** @subsection Field Position Definitions ****/

  #define VREFBUF_CSR_ENVR_POS   INT32_C(0)   /** @brief Voltage reference buffer mode enable this bit is used to enable the voltage reference buffer mode.. */
  #define VREFBUF_CSR_HIZ_POS    INT32_C(1)   /** @brief High impedance mode this bit controls the analog switch to connect or not the VREF+ pin. Refer to table196: VREF buffer modes for the mode descriptions depending on ENVR bit configuration.. */
  #define VREFBUF_CSR_VRR_POS    INT32_C(3)   /** @brief Voltage reference buffer ready. */
  #define VREFBUF_CSR_VRS_POS    INT32_C(4)   /** @brief Voltage reference scale these bits select the value generated by the voltage reference buffer. Other: reserved. */
  #define VREFBUF_CCR_TRIM_POS   INT32_C(0)   /** @brief Trimming code these bits are automatically initialized after reset with the trimming value stored in the flash memory during the production test. Writing into these bits allows to tune the internal reference buffer voltage.. */

