  #define WWDG1_SR_PTR    (*(RW_ uint32_t*)UINT32_C(0x50003008))   /** @brief Status register. */

  /**** @subsection Field Mask Definitions ****/

  #define WWDG1_CR_T_MSK        UINT32_C(0x0000007F)   /** @brief 7-bit counter (MSB to LSB) these bits contain the value of the watchdog counter. It is decremented every (4096 x 2WDGTB[1:0]) PCLK cycles. A reset is produced when it is decremented from 0x40 to 0x3f (T6 becomes cleared).. */
  #define WWDG1_CR_WDGA_MSK     UINT32_C(0x00000080)   /** @brief Activation bit this bit is set by software and only cleared by hardware after a reset. When WDGA=1, the watchdog can generate a reset.. */
  #define WWDG1_CFR_W_MSK       UINT32_C(0x0000007F)   /** @brief 7-bit window value these bits contain the window value to be compared to the downcounter.. */
  #define WWDG1_CFR_WDGTB_MSK   UINT32_C(0x00001800)   /** @brief Timer base the time base of the prescaler can be modified as follows:. */
  #define WWDG1_CFR_EWI_MSK     UINT32_C(0x00000200)   /** @brief Early wakeup interrupt when set, an interrupt occurs whenever the counter reaches the value 0x40. This interrupt is only cleared by hardware after a reset.. */
  #define WWDG1_SR_EWIF_MSK     UINT32_C(0x00000001)   /** @brief Early wakeup interrupt flag this bit is set by hardware when the counter has reached the value 0x40. It must be cleared by software by writing 0. A write of 1 has no effect. This bit is also set if the interrupt is not enabled.. */

  /**** @subsection Field Position Definitions ****/

  #define WWDG1_CR_T_POS        INT32_C(0)    /** @brief 7-bit counter (MSB to LSB) these bits contain the value of the watchdog counter. It is decremented every (4096 x 2WDGTB[1:0]) PCLK cycles. A reset is produced when it is decremented from 0x40 to 0x3f (T6 becomes cleared).. */
  #define WWDG1_CR_WDGA_POS     INT32_C(7)    /** @brief Activation bit this bit is set by software and only cleared by hardware after a reset. When WDGA=1, the watchdog can generate a reset.. */
  #define WWDG1_CFR_W_POS       INT32_C(0)    /** @brief 7-bit window value these bits contain the window value to be compared to the downcounter.. */
  #define WWDG1_CFR_WDGTB_POS   INT32_C(11)   /** @brief Timer base the time base of the prescaler can be modified as follows:. */
  #define WWDG1_CFR_EWI_POS     INT32_C(9)    /** @brief Early wakeup interrupt when set, an interrupt occurs whenever the counter reaches the value 0x40. This interrupt is only cleared by hardware after a reset.. */
  #define WWDG1_SR_EWIF_POS     INT32_C(0)    /** @brief Early wakeup interrupt flag this bit is set by hardware when the counter has reached the value 0x40. It must be cleared by software by writing 0. A write of 1 has no effect. This bit is also set if the interrupt is not enabled.. */

