  /**** @subsection Register Definitions ****/

  #define PWR_CR1_PTR       (*(RW_ uint32_t*)UINT32_C(0x58024800))   /** @brief PWR control register 1. */
  #define PWR_CSR1_PTR      (*(RO_ uint32_t*)UINT32_C(0x58024804))   /** @brief PWR control status register 1. */
  #define PWR_CR2_PTR       (*(RW_ uint32_t*)UINT32_C(0x58024808))   /** @brief This register is not reset by wakeup from standby mode, RESET signal and VDD POR. It is only reset by VSW POR and VSWRST reset. This register shall not be accessed when VSWRST bit in RCC_BDCR register resets the VSW domain.after reset, PWR_CR2 register is write-protected. Prior to modifying its content, the DBP bit in PWR_CR1 register must be set to disable the write protection.. */
  #define PWR_CR3_PTR       (*(RW_ uint32_t*)UINT32_C(0x5802480C))   /** @brief Reset only by POR only, not reset by wakeup from standby mode and RESET pad. The lower byte of this register is written once after POR and shall be written before changing VOS level or ck_sys clock frequency. No limitation applies to the upper bytes.programming data corresponding to an invalid combination of SDLEVEL, SDEXTHP, SDEN, LDOEN and BYPASS bits (see table9) will be ignored: data will not be written, the written-once mechanism will lock the register and any further write access will be ignored. The default supply configuration will be kept and the ACTVOSRDY bit in PWR control status register 1 (PWR_CSR1) will go on indicating invalid voltage levels. The system shall be power cycled before writing a new value.. */
  #define PWR_CPUCR_PTR     (*(RW_ uint32_t*)UINT32_C(0x58024810))   /** @brief This register allows controlling CPU1 power.. */
  #define PWR_D3CR_PTR      (*(RW_ uint32_t*)UINT32_C(0x58024818))   /** @brief This register allows controlling D3 domain power.following reset VOSRDY will be read 1 by software. */
  #define PWR_WKUPCR_PTR    (*(RW_ uint32_t*)UINT32_C(0x58024820))   /** @brief Reset only by system reset, not reset by wakeup from standby mode5 wait states are required when writing this register (when clearing a WKUPF bit in PWR_WKUPFR, the AHB write access will complete after the WKUPF has been cleared).. */
  #define PWR_WKUPFR_PTR    (*(RW_ uint32_t*)UINT32_C(0x58024824))   /** @brief Reset only by system reset, not reset by wakeup from standby mode. */
  #define PWR_WKUPEPR_PTR   (*(RW_ uint32_t*)UINT32_C(0x58024828))   /** @brief Reset only by system reset, not reset by wakeup from standby mode. */

  /**** @subsection Field Mask Definitions ****/

  #define PWR_CR1_LPDS_MSK            UINT32_C(0x00000001)   /** @brief Low-power deepsleep with SVOS3 (SVOS4 and SVOS5 always use low-power, regardless of the setting of this bit). */
  #define PWR_CR1_PVDE_MSK            UINT32_C(0x00000010)   /** @brief Programmable voltage detector enable. */
  #define PWR_CR1_PLS_MSK             UINT32_C(0x000000E0)   /** @brief Programmable voltage detector level selection these bits select the voltage threshold detected by the PVD. Note: refer to section electrical characteristics of the product datasheet for more details.. */
  #define PWR_CR1_DBP_MSK             UINT32_C(0x00000100)   /** @brief Disable backup domain write protection in reset state, the RCC_BDCR register, the RTC registers (including the backup registers), BREN and MOEN bits in PWR_CR2 register, are protected against parasitic write access. This bit must be set to enable write access to these registers.. */
  #define PWR_CR1_FLPS_MSK            UINT32_C(0x00000200)   /** @brief Flash low-power mode in dstop mode this bit allows to obtain the best trade-off between low-power consumption and restart time when exiting from dstop mode. When it is set, the flash memory enters low-power mode when D1 domain is in dstop mode.. */
  #define PWR_CR1_SVOS_MSK            UINT32_C(0x0000C000)   /** @brief System stop mode voltage scaling selection these bits control the VCORE voltage level in system stop mode, to obtain the best trade-off between power consumption and performance.. */
  #define PWR_CR1_AVDEN_MSK           UINT32_C(0x00010000)   /** @brief Peripheral voltage monitor on VDDA enable. */
  #define PWR_CR1_ALS_MSK             UINT32_C(0x00060000)   /** @brief Analog voltage detector level selection these bits select the voltage threshold detected by the AVD.. */
  #define PWR_CSR1_PVDO_MSK           UINT32_C(0x00000010)   /** @brief Programmable voltage detect output this bit is set and cleared by hardware. It is valid only if the PVD has been enabled by the PVDE bit. Note: since the PVD is disabled in standby mode, this bit is equal to 0 after standby or reset until the PVDE bit is set.. */
  #define PWR_CSR1_ACTVOSRDY_MSK      UINT32_C(0x00002000)   /** @brief Voltage levels ready bit for currently used VOS and SDLEVEL this bit is set to 1 by hardware when the voltage regulator and the SD converter are both disabled and bypass mode is selected in PWR control register 3 (PWR_CR3).. */
  #define PWR_CSR1_ACTVOS_MSK         UINT32_C(0x0000C000)   /** @brief VOS currently applied for VCORE voltage scaling selection. These bits reflect the last VOS value applied to the PMU.. */
  #define PWR_CSR1_AVDO_MSK           UINT32_C(0x00010000)   /** @brief Analog voltage detector output on VDDA this bit is set and cleared by hardware. It is valid only if AVD on VDDA is enabled by the AVDEN bit. Note: since the AVD is disabled in standby mode, this bit is equal to 0 after standby or reset until the AVDEN bit is set.. */
  #define PWR_CR2_BREN_MSK            UINT32_C(0x00000001)   /** @brief Backup regulator enable when set, the backup regulator (used to maintain the backup RAM content in standby and VBAT modes) is enabled. If BREN is reset, the backup regulator is switched off. The backup RAM can still be used in run and stop modes. However, its content will be lost in standby and VBAT modes. If BREN is set, the application must wait till the backup regulator ready flag (BRRDY) is set to indicate that the data written into the SRAM will be maintained in standby and VBAT modes.. */
  #define PWR_CR2_MONEN_MSK           UINT32_C(0x00000010)   /** @brief VBAT and temperature monitoring enable when set, the VBAT supply and temperature monitoring is enabled.. */
  #define PWR_CR2_BRRDY_MSK           UINT32_C(0x00010000)   /** @brief Backup regulator ready this bit is set by hardware to indicate that the backup regulator is ready.. */
  #define PWR_CR2_VBATL_MSK           UINT32_C(0x00100000)   /** @brief VBAT level monitoring versus low threshold. */
  #define PWR_CR2_VBATH_MSK           UINT32_C(0x00200000)   /** @brief VBAT level monitoring versus high threshold. */
  #define PWR_CR2_TEMPL_MSK           UINT32_C(0x00400000)   /** @brief Temperature level monitoring versus low threshold. */
  #define PWR_CR2_TEMPH_MSK           UINT32_C(0x00800000)   /** @brief Temperature level monitoring versus high threshold. */
  #define PWR_CR3_BYPASS_MSK          UINT32_C(0x00000001)   /** @brief Power management unit bypass. */
  #define PWR_CR3_LDOEN_MSK           UINT32_C(0x00000002)   /** @brief Low drop-out regulator enable. */
  #define PWR_CR3_SDEN_MSK            UINT32_C(0x00000004)   /** @brief SD converter enable. */
  #define PWR_CR3_VBE_MSK             UINT32_C(0x00000100)   /** @brief VBAT charging enable. */
  #define PWR_CR3_VBRS_MSK            UINT32_C(0x00000200)   /** @brief VBAT charging resistor selection. */
  #define PWR_CR3_USB33DEN_MSK        UINT32_C(0x01000000)   /** @brief VDD33USB voltage level detector enable.. */
  #define PWR_CR3_USBREGEN_MSK        UINT32_C(0x02000000)   /** @brief USB regulator enable.. */
  #define PWR_CR3_USB33RDY_MSK        UINT32_C(0x04000000)   /** @brief USB supply ready.. */
  #define PWR_CPUCR_PDDS_D1_MSK       UINT32_C(0x00000001)   /** @brief D1 domain power down deepsleep selection. This bit allows CPU1 to define the deepsleep mode for D1 domain.. */
  #define PWR_CPUCR_PDDS_D2_MSK       UINT32_C(0x00000002)   /** @brief D2 domain power down deepsleep. This bit allows CPU1 to define the deepsleep mode for D2 domain.. */
  #define PWR_CPUCR_PDDS_D3_MSK       UINT32_C(0x00000004)   /** @brief System D3 domain power down deepsleep. This bit allows CPU1 to define the deepsleep mode for system D3 domain.. */
  #define PWR_CPUCR_STOPF_MSK         UINT32_C(0x00000020)   /** @brief STOP flag this bit is set by hardware and cleared only by any reset or by setting the CPU1 CSSF bit.. */
  #define PWR_CPUCR_SBF_MSK           UINT32_C(0x00000040)   /** @brief System standby flag this bit is set by hardware and cleared only by a POR (power-on reset) or by setting the CPU1 CSSF bit. */
  #define PWR_CPUCR_SBF_D1_MSK        UINT32_C(0x00000080)   /** @brief D1 domain dstandby flag this bit is set by hardware and cleared by any system reset or by setting the CPU1 CSSF bit. Once set, this bit can be cleared only when the D1 domain is no longer in dstandby mode.. */
  #define PWR_CPUCR_SBF_D2_MSK        UINT32_C(0x00000100)   /** @brief D2 domain dstandby flag this bit is set by hardware and cleared by any system reset or by setting the CPU1 CSSF bit. Once set, this bit can be cleared only when the D2 domain is no longer in dstandby mode.. */
  #define PWR_CPUCR_CSSF_MSK          UINT32_C(0x00000200)   /** @brief Clear D1 domain CPU1 standby, stop and HOLD flags (always read as 0) this bit is cleared to 0 by hardware.. */
  #define PWR_CPUCR_RUN_D3_MSK        UINT32_C(0x00000800)   /** @brief Keep system D3 domain in run mode regardless of the CPU sub-systems modes. */
  #define PWR_D3CR_VOSRDY_MSK         UINT32_C(0x00002000)   /** @brief VOS ready bit for VCORE voltage scaling output selection. This bit is set to 1 by hardware when bypass mode is selected in PWR control register 3 (PWR_CR3).. */
  #define PWR_D3CR_VOS_MSK            UINT32_C(0x0000C000)   /** @brief Voltage scaling selection according to performance these bits control the VCORE voltage level and allow to obtains the best trade-off between power consumption and performance: when increasing the performance, the voltage scaling shall be changed before increasing the system frequency. When decreasing performance, the system frequency shall first be decreased before changing the voltage scaling.. */
  #define PWR_WKUPCR_WKUPC_MSK        UINT32_C(0x0000003F)   /** @brief Clear wakeup pin flag for WKUP. These bits are always read as 0.. */
  #define PWR_WKUPFR_WKUPF1_MSK       UINT32_C(0x00000001)   /** @brief Wakeup pin WKUPF flag. This bit is set by hardware and cleared only by a reset pin or by setting the wkupcn+1 bit in the PWR wakeup clear register (PWR_WKUPCR).. */
  #define PWR_WKUPFR_WKUPF2_MSK       UINT32_C(0x00000002)   /** @brief Wakeup pin WKUPF flag. This bit is set by hardware and cleared only by a reset pin or by setting the wkupcn+1 bit in the PWR wakeup clear register (PWR_WKUPCR).. */
  #define PWR_WKUPFR_WKUPF3_MSK       UINT32_C(0x00000004)   /** @brief Wakeup pin WKUPF flag. This bit is set by hardware and cleared only by a reset pin or by setting the wkupcn+1 bit in the PWR wakeup clear register (PWR_WKUPCR).. */
  #define PWR_WKUPFR_WKUPF4_MSK       UINT32_C(0x00000008)   /** @brief Wakeup pin WKUPF flag. This bit is set by hardware and cleared only by a reset pin or by setting the wkupcn+1 bit in the PWR wakeup clear register (PWR_WKUPCR).. */
  #define PWR_WKUPFR_WKUPF5_MSK       UINT32_C(0x00000010)   /** @brief Wakeup pin WKUPF flag. This bit is set by hardware and cleared only by a reset pin or by setting the wkupcn+1 bit in the PWR wakeup clear register (PWR_WKUPCR).. */
  #define PWR_WKUPFR_WKUPF6_MSK       UINT32_C(0x00000020)   /** @brief Wakeup pin WKUPF flag. This bit is set by hardware and cleared only by a reset pin or by setting the wkupcn+1 bit in the PWR wakeup clear register (PWR_WKUPCR).. */
  #define PWR_WKUPEPR_WKUPEN1_MSK     UINT32_C(0x00000001)   /** @brief Enable wakeup pin wkupn+1 each bit is set and cleared by software. Note: an additional wakeup event is detected if wkupn+1 pin is enabled (by setting the wkupenn+1 bit) when wkupn+1 pin level is already high when wkuppn+1 selects rising edge, or low when wkuppn+1 selects falling edge.. */
  #define PWR_WKUPEPR_WKUPEN2_MSK     UINT32_C(0x00000002)   /** @brief Enable wakeup pin wkupn+1 each bit is set and cleared by software. Note: an additional wakeup event is detected if wkupn+1 pin is enabled (by setting the wkupenn+1 bit) when wkupn+1 pin level is already high when wkuppn+1 selects rising edge, or low when wkuppn+1 selects falling edge.. */
  #define PWR_WKUPEPR_WKUPEN3_MSK     UINT32_C(0x00000004)   /** @brief Enable wakeup pin wkupn+1 each bit is set and cleared by software. Note: an additional wakeup event is detected if wkupn+1 pin is enabled (by setting the wkupenn+1 bit) when wkupn+1 pin level is already high when wkuppn+1 selects rising edge, or low when wkuppn+1 selects falling edge.. */
  #define PWR_WKUPEPR_WKUPEN4_MSK     UINT32_C(0x00000008)   /** @brief Enable wakeup pin wkupn+1 each bit is set and cleared by software. Note: an additional wakeup event is detected if wkupn+1 pin is enabled (by setting the wkupenn+1 bit) when wkupn+1 pin level is already high when wkuppn+1 selects rising edge, or low when wkuppn+1 selects falling edge.. */
  #define PWR_WKUPEPR_WKUPEN5_MSK     UINT32_C(0x00000010)   /** @brief Enable wakeup pin wkupn+1 each bit is set and cleared by software. Note: an additional wakeup event is detected if wkupn+1 pin is enabled (by setting the wkupenn+1 bit) when wkupn+1 pin level is already high when wkuppn+1 selects rising edge, or low when wkuppn+1 selects falling edge.. */
  #define PWR_WKUPEPR_WKUPEN6_MSK     UINT32_C(0x00000020)   /** @brief Enable wakeup pin wkupn+1 each bit is set and cleared by software. Note: an additional wakeup event is detected if wkupn+1 pin is enabled (by setting the wkupenn+1 bit) when wkupn+1 pin level is already high when wkuppn+1 selects rising edge, or low when wkuppn+1 selects falling edge.. */
  #define PWR_WKUPEPR_WKUPP1_MSK      UINT32_C(0x00000100)   /** @brief Wakeup pin polarity bit for wkupn-7 these bits define the polarity used for event detection on wkupn-7 external wakeup pin.. */
  #define PWR_WKUPEPR_WKUPP2_MSK      UINT32_C(0x00000200)   /** @brief Wakeup pin polarity bit for wkupn-7 these bits define the polarity used for event detection on wkupn-7 external wakeup pin.. */
  #define PWR_WKUPEPR_WKUPP3_MSK      UINT32_C(0x00000400)   /** @brief Wakeup pin polarity bit for wkupn-7 these bits define the polarity used for event detection on wkupn-7 external wakeup pin.. */
  #define PWR_WKUPEPR_WKUPP4_MSK      UINT32_C(0x00000800)   /** @brief Wakeup pin polarity bit for wkupn-7 these bits define the polarity used for event detection on wkupn-7 external wakeup pin.. */
  #define PWR_WKUPEPR_WKUPP5_MSK      UINT32_C(0x00001000)   /** @brief Wakeup pin polarity bit for wkupn-7 these bits define the polarity used for event detection on wkupn-7 external wakeup pin.. */
  #define PWR_WKUPEPR_WKUPP6_MSK      UINT32_C(0x00002000)   /** @brief Wakeup pin polarity bit for wkupn-7 these bits define the polarity used for event detection on wkupn-7 external wakeup pin.. */
  #define PWR_WKUPEPR_WKUPPUPD1_MSK   UINT32_C(0x00030000)   /** @brief Wakeup pin pull configuration. */
  #define PWR_WKUPEPR_WKUPPUPD2_MSK   UINT32_C(0x000C0000)   /** @brief Wakeup pin pull configuration. */
  #define PWR_WKUPEPR_WKUPPUPD3_MSK   UINT32_C(0x00300000)   /** @brief Wakeup pin pull configuration. */
  #define PWR_WKUPEPR_WKUPPUPD4_MSK   UINT32_C(0x00C00000)   /** @brief Wakeup pin pull configuration. */
  #define PWR_WKUPEPR_WKUPPUPD5_MSK   UINT32_C(0x03000000)   /** @brief Wakeup pin pull configuration. */
  #define PWR_WKUPEPR_WKUPPUPD6_MSK   UINT32_C(0x0C000000)   /** @brief Wakeup pin pull configuration for wkup(truncate(n/2)-7) these bits define the I/O pad pull configuration used when wkupen(truncate(n/2)-7) = 1. The associated GPIO port pull configuration shall be set to the same value or to 00. The wakeup pin pull configuration is kept in standby mode.. */

  /**** @subsection Field Position Definitions ****/

  #define PWR_CR1_LPDS_POS            INT32_C(0)    /** @brief Low-power deepsleep with SVOS3 (SVOS4 and SVOS5 always use low-power, regardless of the setting of this bit). */
  #define PWR_CR1_PVDE_POS            INT32_C(4)    /** @brief Programmable voltage detector enable. */
  #define PWR_CR1_PLS_POS             INT32_C(5)    /** @brief Programmable voltage detector level selection these bits select the voltage threshold detected by the PVD. Note: refer to section electrical characteristics of the product datasheet for more details.. */
  #define PWR_CR1_DBP_POS             INT32_C(8)    /** @brief Disable backup domain write protection in reset state, the RCC_BDCR register, the RTC registers (including the backup registers), BREN and MOEN bits in PWR_CR2 register, are protected against parasitic write access. This bit must be set to enable write access to these registers.. */
  #define PWR_CR1_FLPS_POS            INT32_C(9)    /** @brief Flash low-power mode in dstop mode this bit allows to obtain the best trade-off between low-power consumption and restart time when exiting from dstop mode. When it is set, the flash memory enters low-power mode when D1 domain is in dstop mode.. */
  #define PWR_CR1_SVOS_POS            INT32_C(14)   /** @brief System stop mode voltage scaling selection these bits control the VCORE voltage level in system stop mode, to obtain the best trade-off between power consumption and performance.. */
  #define PWR_CR1_AVDEN_POS           INT32_C(16)   /** @brief Peripheral voltage monitor on VDDA enable. */
  #define PWR_CR1_ALS_POS             INT32_C(17)   /** @brief Analog voltage detector level selection these bits select the voltage threshold detected by the AVD.. */
  #define PWR_CSR1_PVDO_POS           INT32_C(4)    /** @brief Programmable voltage detect output this bit is set and cleared by hardware. It is valid only if the PVD has been enabled by the PVDE bit. Note: since the PVD is disabled in standby mode, this bit is equal to 0 after standby or reset until the PVDE bit is set.. */
  #define PWR_CSR1_ACTVOSRDY_POS      INT32_C(13)   /** @brief Voltage levels ready bit for currently used VOS and SDLEVEL this bit is set to 1 by hardware when the voltage regulator and the SD converter are both disabled and bypass mode is selected in PWR control register 3 (PWR_CR3).. */
  #define PWR_CSR1_ACTVOS_POS         INT32_C(14)   /** @brief VOS currently applied for VCORE voltage scaling selection. These bits reflect the last VOS value applied to the PMU.. */
  #define PWR_CSR1_AVDO_POS           INT32_C(16)   /** @brief Analog voltage detector output on VDDA this bit is set and cleared by hardware. It is valid only if AVD on VDDA is enabled by the AVDEN bit. Note: since the AVD is disabled in standby mode, this bit is equal to 0 after standby or reset until the AVDEN bit is set.. */
  #define PWR_CR2_BREN_POS            INT32_C(0)    /** @brief Backup regulator enable when set, the backup regulator (used to maintain the backup RAM content in standby and VBAT modes) is enabled. If BREN is reset, the backup regulator is switched off. The backup RAM can still be used in run and stop modes. However, its content will be lost in standby and VBAT modes. If BREN is set, the application must wait till the backup regulator ready flag (BRRDY) is set to indicate that the data written into the SRAM will be maintained in standby and VBAT modes.. */
  #define PWR_CR2_MONEN_POS           INT32_C(4)    /** @brief VBAT and temperature monitoring enable when set, the VBAT supply and temperature monitoring is enabled.. */
  #define PWR_CR2_BRRDY_POS           INT32_C(16)   /** @brief Backup regulator ready this bit is set by hardware to indicate that the backup regulator is ready.. */
  #define PWR_CR2_VBATL_POS           INT32_C(20)   /** @brief VBAT level monitoring versus low threshold. */
  #define PWR_CR2_VBATH_POS           INT32_C(21)   /** @brief VBAT level monitoring versus high threshold. */
  #define PWR_CR2_TEMPL_POS           INT32_C(22)   /** @brief Temperature level monitoring versus low threshold. */
  #define PWR_CR2_TEMPH_POS           INT32_C(23)   /** @brief Temperature level monitoring versus high threshold. */
  #define PWR_CR3_BYPASS_POS          INT32_C(0)    /** @brief Power management unit bypass. */
  #define PWR_CR3_LDOEN_POS           INT32_C(1)    /** @brief Low drop-out regulator enable. */
  #define PWR_CR3_SDEN_POS            INT32_C(2)    /** @brief SD converter enable. */
  #define PWR_CR3_VBE_POS             INT32_C(8)    /** @brief VBAT charging enable. */
  #define PWR_CR3_VBRS_POS            INT32_C(9)    /** @brief VBAT charging resistor selection. */
  #define PWR_CR3_USB33DEN_POS        INT32_C(24)   /** @brief VDD33USB voltage level detector enable.. */
  #define PWR_CR3_USBREGEN_POS        INT32_C(25)   /** @brief USB regulator enable.. */
  #define PWR_CR3_USB33RDY_POS        INT32_C(26)   /** @brief USB supply ready.. */
  #define PWR_CPUCR_PDDS_D1_POS       INT32_C(0)    /** @brief D1 domain power down deepsleep selection. This bit allows CPU1 to define the deepsleep mode for D1 domain.. */
  #define PWR_CPUCR_PDDS_D2_POS       INT32_C(1)    /** @brief D2 domain power down deepsleep. This bit allows CPU1 to define the deepsleep mode for D2 domain.. */
  #define PWR_CPUCR_PDDS_D3_POS       INT32_C(2)    /** @brief System D3 domain power down deepsleep. This bit allows CPU1 to define the deepsleep mode for system D3 domain.. */
  #define PWR_CPUCR_STOPF_POS         INT32_C(5)    /** @brief STOP flag this bit is set by hardware and cleared only by any reset or by setting the CPU1 CSSF bit.. */
  #define PWR_CPUCR_SBF_POS           INT32_C(6)    /** @brief System standby flag this bit is set by hardware and cleared only by a POR (power-on reset) or by setting the CPU1 CSSF bit. */
  #define PWR_CPUCR_SBF_D1_POS        INT32_C(7)    /** @brief D1 domain dstandby flag this bit is set by hardware and cleared by any system reset or by setting the CPU1 CSSF bit. Once set, this bit can be cleared only when the D1 domain is no longer in dstandby mode.. */
  #define PWR_CPUCR_SBF_D2_POS        INT32_C(8)    /** @brief D2 domain dstandby flag this bit is set by hardware and cleared by any system reset or by setting the CPU1 CSSF bit. Once set, this bit can be cleared only when the D2 domain is no longer in dstandby mode.. */
  #define PWR_CPUCR_CSSF_POS          INT32_C(9)    /** @brief Clear D1 domain CPU1 standby, stop and HOLD flags (always read as 0) this bit is cleared to 0 by hardware.. */
  #define PWR_CPUCR_RUN_D3_POS        INT32_C(11)   /** @brief Keep system D3 domain in run mode regardless of the CPU sub-systems modes. */
  #define PWR_D3CR_VOSRDY_POS         INT32_C(13)   /** @brief VOS ready bit for VCORE voltage scaling output selection. This bit is set to 1 by hardware when bypass mode is selected in PWR control register 3 (PWR_CR3).. */
  #define PWR_D3CR_VOS_POS            INT32_C(14)   /** @brief Voltage scaling selection according to performance these bits control the VCORE voltage level and allow to obtains the best trade-off between power consumption and performance: when increasing the performance, the voltage scaling shall be changed before increasing the system frequency. When decreasing performance, the system frequency shall first be decreased before changing the voltage scaling.. */
  #define PWR_WKUPCR_WKUPC_POS        INT32_C(0)    /** @brief Clear wakeup pin flag for WKUP. These bits are always read as 0.. */
  #define PWR_WKUPFR_WKUPF1_POS       INT32_C(0)    /** @brief Wakeup pin WKUPF flag. This bit is set by hardware and cleared only by a reset pin or by setting the wkupcn+1 bit in the PWR wakeup clear register (PWR_WKUPCR).. */
  #define PWR_WKUPFR_WKUPF2_POS       INT32_C(1)    /** @brief Wakeup pin WKUPF flag. This bit is set by hardware and cleared only by a reset pin or by setting the wkupcn+1 bit in the PWR wakeup clear register (PWR_WKUPCR).. */
  #define PWR_WKUPFR_WKUPF3_POS       INT32_C(2)    /** @brief Wakeup pin WKUPF flag. This bit is set by hardware and cleared only by a reset pin or by setting the wkupcn+1 bit in the PWR wakeup clear register (PWR_WKUPCR).. */
  #define PWR_WKUPFR_WKUPF4_POS       INT32_C(3)    /** @brief Wakeup pin WKUPF flag. This bit is set by hardware and cleared only by a reset pin or by setting the wkupcn+1 bit in the PWR wakeup clear register (PWR_WKUPCR).. */
  #define PWR_WKUPFR_WKUPF5_POS       INT32_C(4)    /** @brief Wakeup pin WKUPF flag. This bit is set by hardware and cleared only by a reset pin or by setting the wkupcn+1 bit in the PWR wakeup clear register (PWR_WKUPCR).. */
  #define PWR_WKUPFR_WKUPF6_POS       INT32_C(5)    /** @brief Wakeup pin WKUPF flag. This bit is set by hardware and cleared only by a reset pin or by setting the wkupcn+1 bit in the PWR wakeup clear register (PWR_WKUPCR).. */
  #define PWR_WKUPEPR_WKUPEN1_POS     INT32_C(0)    /** @brief Enable wakeup pin wkupn+1 each bit is set and cleared by software. Note: an additional wakeup event is detected if wkupn+1 pin is enabled (by setting the wkupenn+1 bit) when wkupn+1 pin level is already high when wkuppn+1 selects rising edge, or low when wkuppn+1 selects falling edge.. */
  #define PWR_WKUPEPR_WKUPEN2_POS     INT32_C(1)    /** @brief Enable wakeup pin wkupn+1 each bit is set and cleared by software. Note: an additional wakeup event is detected if wkupn+1 pin is enabled (by setting the wkupenn+1 bit) when wkupn+1 pin level is already high when wkuppn+1 selects rising edge, or low when wkuppn+1 selects falling edge.. */
  #define PWR_WKUPEPR_WKUPEN3_POS     INT32_C(2)    /** @brief Enable wakeup pin wkupn+1 each bit is set and cleared by software. Note: an additional wakeup event is detected if wkupn+1 pin is enabled (by setting the wkupenn+1 bit) when wkupn+1 pin level is already high when wkuppn+1 selects rising edge, or low when wkuppn+1 selects falling edge.. */
  #define PWR_WKUPEPR_WKUPEN4_POS     INT32_C(3)    /** @brief Enable wakeup pin wkupn+1 each bit is set and cleared by software. Note: an additional wakeup event is detected if wkupn+1 pin is enabled (by setting the wkupenn+1 bit) when wkupn+1 pin level is already high when wkuppn+1 selects rising edge, or low when wkuppn+1 selects falling edge.. */
  #define PWR_WKUPEPR_WKUPEN5_POS     INT32_C(4)    /** @brief Enable wakeup pin wkupn+1 each bit is set and cleared by software. Note: an additional wakeup event is detected if wkupn+1 pin is enabled (by setting the wkupenn+1 bit) when wkupn+1 pin level is already high when wkuppn+1 selects rising edge, or low when wkuppn+1 selects falling edge.. */
  #define PWR_WKUPEPR_WKUPEN6_POS     INT32_C(5)    /** @brief Enable wakeup pin wkupn+1 each bit is set and cleared by software. Note: an additional wakeup event is detected if wkupn+1 pin is enabled (by setting the wkupenn+1 bit) when wkupn+1 pin level is already high when wkuppn+1 selects rising edge, or low when wkuppn+1 selects falling edge.. */
  #define PWR_WKUPEPR_WKUPP1_POS      INT32_C(8)    /** @brief Wakeup pin polarity bit for wkupn-7 these bits define the polarity used for event detection on wkupn-7 external wakeup pin.. */
  #define PWR_WKUPEPR_WKUPP2_POS      INT32_C(9)    /** @brief Wakeup pin polarity bit for wkupn-7 these bits define the polarity used for event detection on wkupn-7 external wakeup pin.. */
  #define PWR_WKUPEPR_WKUPP3_POS      INT32_C(10)   /** @brief Wakeup pin polarity bit for wkupn-7 these bits define the polarity used for event detection on wkupn-7 external wakeup pin.. */
  #define PWR_WKUPEPR_WKUPP4_POS      INT32_C(11)   /** @brief Wakeup pin polarity bit for wkupn-7 these bits define the polarity used for event detection on wkupn-7 external wakeup pin.. */
  #define PWR_WKUPEPR_WKUPP5_POS      INT32_C(12)   /** @brief Wakeup pin polarity bit for wkupn-7 these bits define the polarity used for event detection on wkupn-7 external wakeup pin.. */
  #define PWR_WKUPEPR_WKUPP6_POS      INT32_C(13)   /** @brief Wakeup pin polarity bit for wkupn-7 these bits define the polarity used for event detection on wkupn-7 external wakeup pin.. */
  #define PWR_WKUPEPR_WKUPPUPD1_POS   INT32_C(16)   /** @brief Wakeup pin pull configuration. */
  #define PWR_WKUPEPR_WKUPPUPD2_POS   INT32_C(18)   /** @brief Wakeup pin pull configuration. */
  #define PWR_WKUPEPR_WKUPPUPD3_POS   INT32_C(20)   /** @brief Wakeup pin pull configuration. */
  #define PWR_WKUPEPR_WKUPPUPD4_POS   INT32_C(22)   /** @brief Wakeup pin pull configuration. */
  #define PWR_WKUPEPR_WKUPPUPD5_POS   INT32_C(24)   /** @brief Wakeup pin pull configuration. */
  #define PWR_WKUPEPR_WKUPPUPD6_POS   INT32_C(26)   /** @brief Wakeup pin pull configuration for wkup(truncate(n/2)-7) these bits define the I/O pad pull configuration used when wkupen(truncate(n/2)-7) = 1. The associated GPIO port pull configuration shall be set to the same value or to 00. The wakeup pin pull configuration is kept in standby mode.. */

