  /**** @subsection Register Definitions ****/

  #define DELAY_BLOCK_SDMMC1_CR_PTR     (*(RW_ uint32_t*)UINT32_C(0x52008000))   /** @brief DLYB control register. */
  #define DELAY_BLOCK_SDMMC1_CFGR_PTR   (*(RW_ uint32_t*)UINT32_C(0x52008004))   /** @brief DLYB configuration register. */

  /**** @subsection Field Mask Definitions ****/

  #define DELAY_BLOCK_SDMMC1_CR_DEN_MSK      UINT32_C(0x00000001)   /** @brief Delay block enable bit. */
